insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (432, 78, 1, 40, 'سورة النبأ ١ – ٤٠', 'النبأ: عمّ يتساءلون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 432) = $j$[{"lbl": "الآيات ١ – ١٦", "q": "عَمَّ يَتَسَآءَلُونَ ﴿١﴾ عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ ﴿٢﴾ ٱلَّذِي هُمۡ فِيهِ مُخۡتَلِفُونَ ﴿٣﴾ كَلَّا سَيَعۡلَمُونَ ﴿٤﴾ ثُمَّ كَلَّا سَيَعۡلَمُونَ ﴿٥﴾ أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدٗا ﴿٦﴾ وَٱلۡجِبَالَ أَوۡتَادٗا ﴿٧﴾ وَخَلَقۡنَٰكُمۡ أَزۡوَٰجٗا ﴿٨﴾ وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا ﴿٩﴾ وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسٗا ﴿١٠﴾ وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشٗا ﴿١١﴾ وَبَنَيۡنَا فَوۡقَكُمۡ سَبۡعٗا شِدَادٗا ﴿١٢﴾ وَجَعَلۡنَا سِرَاجٗا وَهَّاجٗا ﴿١٣﴾ وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَٰتِ مَآءٗ ثَجَّاجٗا ﴿١٤﴾ لِّنُخۡرِجَ بِهِۦ حَبّٗا وَنَبَاتٗا ﴿١٥﴾ وَجَنَّـٰتٍ أَلۡفَافًا ﴿١٦﴾", "w": [["عمّ", "عن أي شيء؟"], ["يتساءلون", "يسأل بعض قريش بعضاً."], ["عن النبأ العظيم", "ما جاء به محمد ﷺ من التوحيد والنبوة والبعث الآخر."], ["الذي هم فيه مختلفون", "ما بين مصدّق ومكذّب."], ["كلا سيعلمون", "عاقبة تكذيبهم عند نزع أرواحهم وعند خروجهم من قبورهم."], ["أوتاداً", "تُثبّت بها الأرض كما تُثبّت الخيمة بالأوتاد."], ["سباتاً", "راحة لأبدانكم."], ["لباساً", "ساتراً بظلامه وسواده."], ["وجعلنا النهار معاشاً", "وقتاً للمعاش كسباً وأكلاً."], ["سبعاً شداداً", "قوية محكمة."], ["سراجاً وهّاجاً", "ضوء الشمس الوهّاج الوقّاد."], ["المعصرات", "السحابات التي حان لها أن تمطر."], ["ثجّاجاً", "صبّاباً وابلاً."], ["وجنات ألفافاً", "بساتين ملتفّة."]], "m": "عن أي شيء يتساءل رجال قريش فيسأل بعضهم بعضاً؟ إنهم يتساءلون عن النبأ العظيم الذي هم فيه مختلفون، ما جاء به محمد ﷺ من التوحيد والنبوة والبعث الآخر. كلا، ردعاً لهم وتخويفاً، سيعلمون عند نزع أرواحهم عاقبة تكذيبهم، ثم كلا سيعلمون يوم يُبعثون من قبورهم ويُحشرون إلى جهنم حين لا ينفعهم علم. ثم ذكر تعالى من مظاهر القدرة والعلم والرحمة والحكمة ما يوجب الإيمان به وبتوحيده ورسوله ولقائه لو كانوا يعقلون: ألم نجعل الأرض فراشاً ووطاءً للحياة عليها؟ والجبال أوتاداً تُثبّت الأرض بها فيأمنون على حياتهم، وخلقناكم أزواجاً، والخلق مظهر من مظاهر القدرة والعلم، وكونهم أزواجاً مظهر من مظاهر الحكمة والرحمة، وجعلنا نومكم راحة لأبدانكم، والليل ساتراً بظلامه، والنهار للعيش كسباً، وبنينا فوقكم السماوات السبع الشديدة البناء، وجعلنا الشمس سراجاً مضيئاً وهّاجاً، وأنزلنا من السحابات التي حان لها أن تمطر ماءً صبّاباً، لنخرج به حبّاً كالبُرّ والذرة لطعامكم، ونباتاً كالكلأ والعشب لحيواناتكم، وبساتين ملتفّة الأشجار. كل هذه مفتقرة إلى قدرة لا يعجزها شيء، وعلم أحاط بكل شيء، وحكمة ورحمة، والله وحده ذو ذلك، فكيف يُنكر توحيده ويُكذّب رسوله ويُستبعد بعثه للناس؟ هل من الحكمة أن يظلم الظالمون ويعدل العادلون ويموتون سواء ولا تكون هناك حياة أخرى يُجزى فيها المسيء بإساءته والمحسن بإحسانه؟ لا، إنه لا بد من حياة أخرى.", "h": ["مظاهر القدرة والعلم والحكمة والرحمة الإلهية في الآيات من قوله: «ألم نجعل الأرض مهاداً» إلى قوله: «وجنات ألفافاً».", "تقرير عقيدة البعث والجزاء والنبوة والتوحيد، وهي التي اختلف الناس فيها ما بين مثبت ونافٍ، ومصدّق ومكذّب.", "سيحصل العلم الكامل بهذه المختلف فيها بين الناس عند نزع الروح ساعة الموت، ولكن لا فائدة من العلم ساعتها، إذ قُضي الأمر وانتهى الخلاف."], "k": "«وجعلنا نومكم سباتاً»… حتى نومي نعمة مدبّرة؛ فهل أنام وأستيقظ على ذكره؟"}, {"lbl": "الآيات ١٧ – ٣٠", "q": "إِنَّ يَوۡمَ ٱلۡفَصۡلِ كَانَ مِيقَٰتٗا ﴿١٧﴾ يَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَتَأۡتُونَ أَفۡوَاجٗا ﴿١٨﴾ وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتۡ أَبۡوَٰبٗا ﴿١٩﴾ وَسُيِّرَتِ ٱلۡجِبَالُ فَكَانَتۡ سَرَابًا ﴿٢٠﴾ إِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادٗا ﴿٢١﴾ لِّلطَّـٰغِينَ مَـَٔابٗا ﴿٢٢﴾ لَّـٰبِثِينَ فِيهَآ أَحۡقَابٗا ﴿٢٣﴾ لَّا يَذُوقُونَ فِيهَا بَرۡدٗا وَلَا شَرَابًا ﴿٢٤﴾ إِلَّا حَمِيمٗا وَغَسَّاقٗا ﴿٢٥﴾ جَزَآءٗ وِفَاقًا ﴿٢٦﴾ إِنَّهُمۡ كَانُواْ لَا يَرۡجُونَ حِسَابٗا ﴿٢٧﴾ وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّابٗا ﴿٢٨﴾ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ كِتَٰبٗا ﴿٢٩﴾ فَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا ﴿٣٠﴾", "w": [["إن يوم الفصل", "الفصل بين الخلائق ليُجزى كل امرئ بما كسب."], ["يوم يُنفخ في الصور", "يوم ينفخ إسرافيل في الصور."], ["فتأتون أفواجاً", "جماعات جماعات إلى ساحة فصل القضاء."], ["وفُتحت السماء", "لنزول الملائكة."], ["وسُيّرت الجبال", "ذُهب بها من أماكنها."], ["فكانت سراباً", "مثل السراب، يُتراءى ماءً وليس بماء، فكذلك الجبال."], ["إن جهنم كانت مرصاداً", "مُرصدة للظالمين، مرجعاً يرجعون إليها."], ["لابثين فيها أحقاباً", "دهوراً لا نهاية لها."], ["لا يذوقون فيها برداً", "نوماً، ولا شراباً يُتلذّذ به، إذ شرابهم الحميم."], ["وغسّاقاً", "ما يسيل من صديد أهل النار."], ["جزاءً وفاقاً", "موافقاً لذنوبهم، إذ لا ذنب أعظم من الكفر، ولا عذاب أعظم من النار."], ["كذّاباً", "تكذيباً."], ["فلن نزيدكم إلا عذاباً", "فوق عذابكم الذي أنتم فيه."]], "m": "بعد أن ذكر تعالى آيات قدرته على البعث، ذكر عرضاً وافياً للبعث الآخر وما يجري فيه: إن يوم الفصل بين الخلائق كان ميقاتاً لما أعدّ الله للمكذّبين، يجزيهم فيه الجزاء الأوفى. ثم ذكر أحداثاً تسبقه: يوم ينفخ إسرافيل نفخة البعث فتأتون أيها الناس جماعات، وانشقّت السماء فكانت أبواباً لنزول الملائكة، وسُيّرت الجبال فكانت هباءً كالسراب في نظر الرائي. إن جهنم بعد الحساب قد أُرصدت وأُعدّت للطاغين، المتجاوزين الحد الذي حُدّ لهم، وهو أن يؤمنوا بربهم ويعبدوه وحده، فتجاوزوا ذلك إلى الكفر والشرك وتكذيب رسوله، هؤلاء أُرصدت لهم جهنم مرجعاً ومآباً، ماكثين فيها دهوراً، لا يذوقون فيها نوماً، إذ النوم يُسمّى البرد في لغة بعض العرب، ولا شراباً ذا لذّة إلا الماء الحار، وما يسيل من صديد أهل النار، جزاءً موافقاً لذنوبهم. ثم ذكر مقتضى هذا العذاب: إنهم كانوا لا يؤمنون بالحساب ولا يخافونه، وكذّبوا بآياتنا تكذيباً زائداً، وكل شيء أحصيناه كتاباً، إذ كانت الملائكة تكتب أعمالهم، فهم يتلقّون جزاءهم العادل، ويقال لهم توبيخاً وهم في أشد العذاب: فذوقوا فلن نزيدكم إلا عذاباً، فيعظم عندهم الكرب ويستحكم اليأس، وهذا جزاء من تنكّر لعقله فكفر بربه وعبد الهوى.", "h": ["التنديد بالطغيان، وبيان جزاء الظالمين.", "التنديد بالتكذيب بالبعث والمكذّبين به.", "أعمال العباد، مؤمنهم وكافرهم، كلها محصاة عليهم ويُجزون بها.", "تقرير عقيدة البعث والجزاء بذكر آثارها.", "أبدية العذاب في الدار الآخرة وعدم إمكان نهايته."], "k": "«وكل شيء أحصيناه كتاباً»… لم يسقط من صحيفتي شيء؛ فماذا أضيف إليها اليوم؟"}, {"lbl": "الآيات ٣١ – ٤٠", "q": "إِنَّ لِلۡمُتَّقِينَ مَفَازًا ﴿٣١﴾ حَدَآئِقَ وَأَعۡنَٰبٗا ﴿٣٢﴾ وَكَوَاعِبَ أَتۡرَابٗا ﴿٣٣﴾ وَكَأۡسٗا دِهَاقٗا ﴿٣٤﴾ لَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّـٰبٗا ﴿٣٥﴾ جَزَآءٗ مِّن رَّبِّكَ عَطَآءً حِسَابٗا ﴿٣٦﴾ رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلرَّحۡمَٰنِۖ لَا يَمۡلِكُونَ مِنۡهُ خِطَابٗا ﴿٣٧﴾ يَوۡمَ يَقُومُ ٱلرُّوحُ وَٱلۡمَلَـٰٓئِكَةُ صَفّٗاۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَقَالَ صَوَابٗا ﴿٣٨﴾ ذَٰلِكَ ٱلۡيَوۡمُ ٱلۡحَقُّۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا ﴿٣٩﴾ إِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا ﴿٤٠﴾", "w": [["إن للمتقين", "الذين اتقوا الشرك والمعاصي خوفاً من ربهم وعذابه."], ["مفازاً", "مكان فوز ونجاة، وهو الجنة."], ["حدائق وأعناباً", "بساتين وأعناباً."], ["وكواعب", "شابّات، الواحدة كاعب."], ["أتراباً", "في سن واحدة."], ["وكأساً دهاقاً", "خمراً كأسها ملأى بها."], ["لا يسمعون فيها لغواً ولا كذّاباً", "لا يسمعون في الجنة باطلاً ولا كذباً من القول."], ["عطاءً حساباً", "عطاءً كثيراً كافياً."], ["يوم يقوم الروح", "ملك عظيم يقوم وحده صفّاً، والملائكة صفّاً وحدهم."], ["مآباً", "مرجعاً سليماً، وذلك بالإيمان والتقوى إذ بهما تكون النجاة."], ["ما قدّمت يداه", "ما أسلفه في الدنيا من خير وشر."], ["يا ليتني كنت تراباً", "حتى لا أُعذّب، وذلك يوم يقول الله للبهائم: كوني تراباً، بعد الاقتصاص لها من بعضها."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء؛ بعد أن ذكر حال الطغاة ومصيرهم ثنّى بذكر المتقين: إن للمتقين مكان فوز ونجاح، حدائق وأعناباً، وكواعب أتراباً في سن واحدة، وكأس خمر ملأى، لا يسمعون في الجنة قولاً باطلاً ولا كذباً، جزاءً من ربك جعله عطاءً كافياً، رب السماوات والأرض وما بينهما، مالكهما والمتصرّف فيهما، الرحمن، لا يملكون منه خطاباً يوم يقوم الروح، ملك عظيم لا يُقادر قدره، صفّاً والملائكة صفّاً، لا يتكلّمون بين يديه إلا من أذن له الرحمن وقال صواباً، وفي الصحيح أن النبي محمداً ﷺ هو أول من يكلّم الله عز وجل في الموقف، حيث يأتي تحت العرش فيخرّ ساجداً يحمد الله بمحامد يُلهمها ساعتئذ، فيقول له الرب: ارفع رأسك وسل تُعطَ واشفع تُشفّع. ذلك اليوم الحق الذي لا مرية فيه، فمن شاء اتّخذ إلى ربه مرجعاً بالإيمان والطاعة. إنا أنذرناكم عذاباً قريباً جداً يبتدئ بالموت ولا ينتهي أبداً، يوم ينظر المرء ما قدّمت يداه من خير أو شر فيرى جزاء عمله عياناً، ويقول الكافر: يا ليتني كنت تراباً، إنه لما يرى البهائم بعد القصاص لها صارت تراباً يتمنّى أن لو كان مثلها، ولولا العذاب وشدّته ودوامه لما تمنّى ذلك أبداً.", "h": ["بيان كرامة المتقين وفضل التقوى.", "وصف جميل لنعيم الجنة.", "ذمّ الكذب واللغو وأهلهما.", "بيان شدة الموقف وصعوبة المقام فيه.", "تقرير عقيدة البعث والجزاء.", "الترغيب في العمل الصالح، واجتناب العمل السيئ الفاسد."], "k": "«يوم ينظر المرء ما قدّمت يداه»… يداي اليوم تكتبان ما سأنظر إليه غداً؛ فماذا تكتبان؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 432;
insert into public.tdb_cards(topic, i, body) select 432, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٦", "q": "عَمَّ يَتَسَآءَلُونَ ﴿١﴾ عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ ﴿٢﴾ ٱلَّذِي هُمۡ فِيهِ مُخۡتَلِفُونَ ﴿٣﴾ كَلَّا سَيَعۡلَمُونَ ﴿٤﴾ ثُمَّ كَلَّا سَيَعۡلَمُونَ ﴿٥﴾ أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدٗا ﴿٦﴾ وَٱلۡجِبَالَ أَوۡتَادٗا ﴿٧﴾ وَخَلَقۡنَٰكُمۡ أَزۡوَٰجٗا ﴿٨﴾ وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا ﴿٩﴾ وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسٗا ﴿١٠﴾ وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشٗا ﴿١١﴾ وَبَنَيۡنَا فَوۡقَكُمۡ سَبۡعٗا شِدَادٗا ﴿١٢﴾ وَجَعَلۡنَا سِرَاجٗا وَهَّاجٗا ﴿١٣﴾ وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَٰتِ مَآءٗ ثَجَّاجٗا ﴿١٤﴾ لِّنُخۡرِجَ بِهِۦ حَبّٗا وَنَبَاتٗا ﴿١٥﴾ وَجَنَّـٰتٍ أَلۡفَافًا ﴿١٦﴾", "w": [["عمّ", "عن أي شيء؟"], ["يتساءلون", "يسأل بعض قريش بعضاً."], ["عن النبأ العظيم", "ما جاء به محمد ﷺ من التوحيد والنبوة والبعث الآخر."], ["الذي هم فيه مختلفون", "ما بين مصدّق ومكذّب."], ["كلا سيعلمون", "عاقبة تكذيبهم عند نزع أرواحهم وعند خروجهم من قبورهم."], ["أوتاداً", "تُثبّت بها الأرض كما تُثبّت الخيمة بالأوتاد."], ["سباتاً", "راحة لأبدانكم."], ["لباساً", "ساتراً بظلامه وسواده."], ["وجعلنا النهار معاشاً", "وقتاً للمعاش كسباً وأكلاً."], ["سبعاً شداداً", "قوية محكمة."], ["سراجاً وهّاجاً", "ضوء الشمس الوهّاج الوقّاد."], ["المعصرات", "السحابات التي حان لها أن تمطر."], ["ثجّاجاً", "صبّاباً وابلاً."], ["وجنات ألفافاً", "بساتين ملتفّة."]], "m": "عن أي شيء يتساءل رجال قريش فيسأل بعضهم بعضاً؟ إنهم يتساءلون عن النبأ العظيم الذي هم فيه مختلفون، ما جاء به محمد ﷺ من التوحيد والنبوة والبعث الآخر. كلا، ردعاً لهم وتخويفاً، سيعلمون عند نزع أرواحهم عاقبة تكذيبهم، ثم كلا سيعلمون يوم يُبعثون من قبورهم ويُحشرون إلى جهنم حين لا ينفعهم علم. ثم ذكر تعالى من مظاهر القدرة والعلم والرحمة والحكمة ما يوجب الإيمان به وبتوحيده ورسوله ولقائه لو كانوا يعقلون: ألم نجعل الأرض فراشاً ووطاءً للحياة عليها؟ والجبال أوتاداً تُثبّت الأرض بها فيأمنون على حياتهم، وخلقناكم أزواجاً، والخلق مظهر من مظاهر القدرة والعلم، وكونهم أزواجاً مظهر من مظاهر الحكمة والرحمة، وجعلنا نومكم راحة لأبدانكم، والليل ساتراً بظلامه، والنهار للعيش كسباً، وبنينا فوقكم السماوات السبع الشديدة البناء، وجعلنا الشمس سراجاً مضيئاً وهّاجاً، وأنزلنا من السحابات التي حان لها أن تمطر ماءً صبّاباً، لنخرج به حبّاً كالبُرّ والذرة لطعامكم، ونباتاً كالكلأ والعشب لحيواناتكم، وبساتين ملتفّة الأشجار. كل هذه مفتقرة إلى قدرة لا يعجزها شيء، وعلم أحاط بكل شيء، وحكمة ورحمة، والله وحده ذو ذلك، فكيف يُنكر توحيده ويُكذّب رسوله ويُستبعد بعثه للناس؟ هل من الحكمة أن يظلم الظالمون ويعدل العادلون ويموتون سواء ولا تكون هناك حياة أخرى يُجزى فيها المسيء بإساءته والمحسن بإحسانه؟ لا، إنه لا بد من حياة أخرى.", "h": ["مظاهر القدرة والعلم والحكمة والرحمة الإلهية في الآيات من قوله: «ألم نجعل الأرض مهاداً» إلى قوله: «وجنات ألفافاً».", "تقرير عقيدة البعث والجزاء والنبوة والتوحيد، وهي التي اختلف الناس فيها ما بين مثبت ونافٍ، ومصدّق ومكذّب.", "سيحصل العلم الكامل بهذه المختلف فيها بين الناس عند نزع الروح ساعة الموت، ولكن لا فائدة من العلم ساعتها، إذ قُضي الأمر وانتهى الخلاف."], "k": "«وجعلنا نومكم سباتاً»… حتى نومي نعمة مدبّرة؛ فهل أنام وأستيقظ على ذكره؟"}, {"lbl": "الآيات ١٧ – ٣٠", "q": "إِنَّ يَوۡمَ ٱلۡفَصۡلِ كَانَ مِيقَٰتٗا ﴿١٧﴾ يَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَتَأۡتُونَ أَفۡوَاجٗا ﴿١٨﴾ وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتۡ أَبۡوَٰبٗا ﴿١٩﴾ وَسُيِّرَتِ ٱلۡجِبَالُ فَكَانَتۡ سَرَابًا ﴿٢٠﴾ إِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادٗا ﴿٢١﴾ لِّلطَّـٰغِينَ مَـَٔابٗا ﴿٢٢﴾ لَّـٰبِثِينَ فِيهَآ أَحۡقَابٗا ﴿٢٣﴾ لَّا يَذُوقُونَ فِيهَا بَرۡدٗا وَلَا شَرَابًا ﴿٢٤﴾ إِلَّا حَمِيمٗا وَغَسَّاقٗا ﴿٢٥﴾ جَزَآءٗ وِفَاقًا ﴿٢٦﴾ إِنَّهُمۡ كَانُواْ لَا يَرۡجُونَ حِسَابٗا ﴿٢٧﴾ وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّابٗا ﴿٢٨﴾ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ كِتَٰبٗا ﴿٢٩﴾ فَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا ﴿٣٠﴾", "w": [["إن يوم الفصل", "الفصل بين الخلائق ليُجزى كل امرئ بما كسب."], ["يوم يُنفخ في الصور", "يوم ينفخ إسرافيل في الصور."], ["فتأتون أفواجاً", "جماعات جماعات إلى ساحة فصل القضاء."], ["وفُتحت السماء", "لنزول الملائكة."], ["وسُيّرت الجبال", "ذُهب بها من أماكنها."], ["فكانت سراباً", "مثل السراب، يُتراءى ماءً وليس بماء، فكذلك الجبال."], ["إن جهنم كانت مرصاداً", "مُرصدة للظالمين، مرجعاً يرجعون إليها."], ["لابثين فيها أحقاباً", "دهوراً لا نهاية لها."], ["لا يذوقون فيها برداً", "نوماً، ولا شراباً يُتلذّذ به، إذ شرابهم الحميم."], ["وغسّاقاً", "ما يسيل من صديد أهل النار."], ["جزاءً وفاقاً", "موافقاً لذنوبهم، إذ لا ذنب أعظم من الكفر، ولا عذاب أعظم من النار."], ["كذّاباً", "تكذيباً."], ["فلن نزيدكم إلا عذاباً", "فوق عذابكم الذي أنتم فيه."]], "m": "بعد أن ذكر تعالى آيات قدرته على البعث، ذكر عرضاً وافياً للبعث الآخر وما يجري فيه: إن يوم الفصل بين الخلائق كان ميقاتاً لما أعدّ الله للمكذّبين، يجزيهم فيه الجزاء الأوفى. ثم ذكر أحداثاً تسبقه: يوم ينفخ إسرافيل نفخة البعث فتأتون أيها الناس جماعات، وانشقّت السماء فكانت أبواباً لنزول الملائكة، وسُيّرت الجبال فكانت هباءً كالسراب في نظر الرائي. إن جهنم بعد الحساب قد أُرصدت وأُعدّت للطاغين، المتجاوزين الحد الذي حُدّ لهم، وهو أن يؤمنوا بربهم ويعبدوه وحده، فتجاوزوا ذلك إلى الكفر والشرك وتكذيب رسوله، هؤلاء أُرصدت لهم جهنم مرجعاً ومآباً، ماكثين فيها دهوراً، لا يذوقون فيها نوماً، إذ النوم يُسمّى البرد في لغة بعض العرب، ولا شراباً ذا لذّة إلا الماء الحار، وما يسيل من صديد أهل النار، جزاءً موافقاً لذنوبهم. ثم ذكر مقتضى هذا العذاب: إنهم كانوا لا يؤمنون بالحساب ولا يخافونه، وكذّبوا بآياتنا تكذيباً زائداً، وكل شيء أحصيناه كتاباً، إذ كانت الملائكة تكتب أعمالهم، فهم يتلقّون جزاءهم العادل، ويقال لهم توبيخاً وهم في أشد العذاب: فذوقوا فلن نزيدكم إلا عذاباً، فيعظم عندهم الكرب ويستحكم اليأس، وهذا جزاء من تنكّر لعقله فكفر بربه وعبد الهوى.", "h": ["التنديد بالطغيان، وبيان جزاء الظالمين.", "التنديد بالتكذيب بالبعث والمكذّبين به.", "أعمال العباد، مؤمنهم وكافرهم، كلها محصاة عليهم ويُجزون بها.", "تقرير عقيدة البعث والجزاء بذكر آثارها.", "أبدية العذاب في الدار الآخرة وعدم إمكان نهايته."], "k": "«وكل شيء أحصيناه كتاباً»… لم يسقط من صحيفتي شيء؛ فماذا أضيف إليها اليوم؟"}, {"lbl": "الآيات ٣١ – ٤٠", "q": "إِنَّ لِلۡمُتَّقِينَ مَفَازًا ﴿٣١﴾ حَدَآئِقَ وَأَعۡنَٰبٗا ﴿٣٢﴾ وَكَوَاعِبَ أَتۡرَابٗا ﴿٣٣﴾ وَكَأۡسٗا دِهَاقٗا ﴿٣٤﴾ لَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّـٰبٗا ﴿٣٥﴾ جَزَآءٗ مِّن رَّبِّكَ عَطَآءً حِسَابٗا ﴿٣٦﴾ رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلرَّحۡمَٰنِۖ لَا يَمۡلِكُونَ مِنۡهُ خِطَابٗا ﴿٣٧﴾ يَوۡمَ يَقُومُ ٱلرُّوحُ وَٱلۡمَلَـٰٓئِكَةُ صَفّٗاۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَقَالَ صَوَابٗا ﴿٣٨﴾ ذَٰلِكَ ٱلۡيَوۡمُ ٱلۡحَقُّۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا ﴿٣٩﴾ إِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا ﴿٤٠﴾", "w": [["إن للمتقين", "الذين اتقوا الشرك والمعاصي خوفاً من ربهم وعذابه."], ["مفازاً", "مكان فوز ونجاة، وهو الجنة."], ["حدائق وأعناباً", "بساتين وأعناباً."], ["وكواعب", "شابّات، الواحدة كاعب."], ["أتراباً", "في سن واحدة."], ["وكأساً دهاقاً", "خمراً كأسها ملأى بها."], ["لا يسمعون فيها لغواً ولا كذّاباً", "لا يسمعون في الجنة باطلاً ولا كذباً من القول."], ["عطاءً حساباً", "عطاءً كثيراً كافياً."], ["يوم يقوم الروح", "ملك عظيم يقوم وحده صفّاً، والملائكة صفّاً وحدهم."], ["مآباً", "مرجعاً سليماً، وذلك بالإيمان والتقوى إذ بهما تكون النجاة."], ["ما قدّمت يداه", "ما أسلفه في الدنيا من خير وشر."], ["يا ليتني كنت تراباً", "حتى لا أُعذّب، وذلك يوم يقول الله للبهائم: كوني تراباً، بعد الاقتصاص لها من بعضها."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء؛ بعد أن ذكر حال الطغاة ومصيرهم ثنّى بذكر المتقين: إن للمتقين مكان فوز ونجاح، حدائق وأعناباً، وكواعب أتراباً في سن واحدة، وكأس خمر ملأى، لا يسمعون في الجنة قولاً باطلاً ولا كذباً، جزاءً من ربك جعله عطاءً كافياً، رب السماوات والأرض وما بينهما، مالكهما والمتصرّف فيهما، الرحمن، لا يملكون منه خطاباً يوم يقوم الروح، ملك عظيم لا يُقادر قدره، صفّاً والملائكة صفّاً، لا يتكلّمون بين يديه إلا من أذن له الرحمن وقال صواباً، وفي الصحيح أن النبي محمداً ﷺ هو أول من يكلّم الله عز وجل في الموقف، حيث يأتي تحت العرش فيخرّ ساجداً يحمد الله بمحامد يُلهمها ساعتئذ، فيقول له الرب: ارفع رأسك وسل تُعطَ واشفع تُشفّع. ذلك اليوم الحق الذي لا مرية فيه، فمن شاء اتّخذ إلى ربه مرجعاً بالإيمان والطاعة. إنا أنذرناكم عذاباً قريباً جداً يبتدئ بالموت ولا ينتهي أبداً، يوم ينظر المرء ما قدّمت يداه من خير أو شر فيرى جزاء عمله عياناً، ويقول الكافر: يا ليتني كنت تراباً، إنه لما يرى البهائم بعد القصاص لها صارت تراباً يتمنّى أن لو كان مثلها، ولولا العذاب وشدّته ودوامه لما تمنّى ذلك أبداً.", "h": ["بيان كرامة المتقين وفضل التقوى.", "وصف جميل لنعيم الجنة.", "ذمّ الكذب واللغو وأهلهما.", "بيان شدة الموقف وصعوبة المقام فيه.", "تقرير عقيدة البعث والجزاء.", "الترغيب في العمل الصالح، واجتناب العمل السيئ الفاسد."], "k": "«يوم ينظر المرء ما قدّمت يداه»… يداي اليوم تكتبان ما سأنظر إليه غداً؛ فماذا تكتبان؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (433, 79, 1, 46, 'سورة النازعات ١ – ٤٦', 'النازعات: وأما من خاف مقام ربه', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 433) = $j$[{"lbl": "الآيات ١ – ١٤", "q": "وَٱلنَّـٰزِعَٰتِ غَرۡقٗا ﴿١﴾ وَٱلنَّـٰشِطَٰتِ نَشۡطٗا ﴿٢﴾ وَٱلسَّـٰبِحَٰتِ سَبۡحٗا ﴿٣﴾ فَٱلسَّـٰبِقَٰتِ سَبۡقٗا ﴿٤﴾ فَٱلۡمُدَبِّرَٰتِ أَمۡرٗا ﴿٥﴾ يَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ ﴿٦﴾ تَتۡبَعُهَا ٱلرَّادِفَةُ ﴿٧﴾ قُلُوبٞ يَوۡمَئِذٖ وَاجِفَةٌ ﴿٨﴾ أَبۡصَٰرُهَا خَٰشِعَةٞ ﴿٩﴾ يَقُولُونَ أَءِنَّا لَمَرۡدُودُونَ فِي ٱلۡحَافِرَةِ ﴿١٠﴾ أَءِذَا كُنَّا عِظَٰمٗا نَّخِرَةٗ ﴿١١﴾ قَالُواْ تِلۡكَ إِذٗا كَرَّةٌ خَاسِرَةٞ ﴿١٢﴾ فَإِنَّمَا هِيَ زَجۡرَةٞ وَٰحِدَةٞ ﴿١٣﴾ فَإِذَا هُم بِٱلسَّاهِرَةِ ﴿١٤﴾", "w": [["والنازعات غرقاً", "الملائكة تنزع أرواح الفجّار والكفار عند الموت بشدة."], ["والناشطات نشطاً", "الملائكة تنشط أرواح المؤمنين الصالحين، أي تسلّها برفق."], ["والسابحات سبحاً", "الملائكة تسبح من السماء بأمر الله، أي تنزل به إلى الأرض."], ["فالسابقات سبقاً", "الملائكة تسبق بأرواح المؤمنين إلى الجنة."], ["فالمدبّرات أمراً", "الملائكة تنزل بتدبير أمر الدنيا من لدن الله المدبّر الحكيم."], ["يوم ترجف الراجفة", "النفخة الأولى، نفخة الفناء التي يتزلزل كل شيء معها."], ["تتبعها الرادفة", "النفخة الثانية."], ["واجفة", "خائفة قلقة."], ["أئنا لمردودون في الحافرة", "أنُردّ إلى أول الحياة؟ إذ الحافرة اسم لأول الأمر."], ["فإنما هي زجرة واحدة", "نفخة واحدة."], ["فإذا هم بالساهرة", "بوجه الأرض أحياء، سُمّيت ساهرة لأن من عليها يسهر ولا ينام."]], "m": "هذا قسم عظيم أقسم تعالى به على أنه لا بد من البعث والجزاء، حيث كان المشركون ينكرونه حتى لا يقفوا عند حد في سلوكهم، فيواصلوا كفرهم وفسادهم جرياً وراء شهواتهم، فأقسم تعالى بخمسة أشياء: النازعات والناشطات والسابحات والسابقات والمدبّرات، ورُجّح أنهم أصناف من الملائكة، وجائز غير ذلك، إذ العبرة أنه تعالى قد أقسم ببعض مخلوقاته على أن البعث حق واقع لا محالة، وتقدير الجواب: لتُبعثنّ ثم لتُنبّؤنّ بما عملتم. وسيتمّ ذلك يوم ترجف الراجفة، النفخة الأولى التي ترجف فيها العوالم كلها ويفنى فيها كل شيء، ثم تتبعها الرادفة، وهي نفخة البعث من القبور، وبين النفختين أربعون سنة كما في الحديث الصحيح. قلوب يومئذ خائفة قلقة، أبصار أصحابها ذليلة خائفة. يقول منكرو البعث: أئنا لمردودون بعد الموت إلى الحياة من جديد كما كنا أول مرة؟ أئذا كنا عظاماً بالية مفتّتة؟ استبعاداً منهم وإنكاراً، وقالوا: تلك إذاً رجعة خاسرة، وهي كذلك بالنسبة إليهم، إذ سيخسرون فيها كل شيء حتى أنفسهم. فإنما هي صيحة واحدة، نفخة إسرافيل الثانية، فإذا هم وسائر الخلق بوجه الأرض لا ينامون. فردّ تعالى بهذا على منكري البعث وقرّره بما لا مزيد عليه إعذاراً وإنذاراً.", "h": ["بيان أن الله تعالى يقسم بما يشاء من مخلوقاته، بخلاف العبد لا يجوز له أن يقسم بغير ربه.", "بيان أن روح المؤمن تُنزع عند الموت نزعاً سريعاً، لا يجد من الألم ما يجده الكافر.", "تقرير عقيدة البعث والجزاء بالإقسام عليها وذكر كيفية وقوعها."], "k": "«والناشطات نشطاً»… خروج الروح برفق كرامة للمؤمن؛ فهل أعيش حياة من يرجو هذا الرفق؟"}, {"lbl": "الآيات ١٥ – ٢٦", "q": "هَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ ﴿١٥﴾ إِذۡ نَادَىٰهُ رَبُّهُۥ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوًى ﴿١٦﴾ ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ﴿١٧﴾ فَقُلۡ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ ﴿١٨﴾ وَأَهۡدِيَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ ﴿١٩﴾ فَأَرَىٰهُ ٱلۡأٓيَةَ ٱلۡكُبۡرَىٰ ﴿٢٠﴾ فَكَذَّبَ وَعَصَىٰ ﴿٢١﴾ ثُمَّ أَدۡبَرَ يَسۡعَىٰ ﴿٢٢﴾ فَحَشَرَ فَنَادَىٰ ﴿٢٣﴾ فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ ﴿٢٤﴾ فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلۡأٓخِرَةِ وَٱلۡأُولَىٰٓ ﴿٢٥﴾ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّمَن يَخۡشَىٰٓ ﴿٢٦﴾", "w": [["موسى", "موسى بن عمران ﵇."], ["بالوادِ المقدّس طوى", "بالوادي الطاهر المبارك المسمّى طوى."], ["اذهب إلى فرعون", "أن اذهب إلى فرعون."], ["إنه طغى", "تجاوز حدّه كعبد إلى ادّعاء الربوبية والألوهية."], ["إلى أن تزكّى", "أن تُسلم فتطهر من رجس الشرك والكفر."], ["وأهديك إلى ربك", "أرشدك إلى معرفة ربك الحق فتخشاه وتطيعه فتنجو من عذابه."], ["فأراه الآية الكبرى", "العصا واليد، إذ هي من أكبر الآيات الدالة على صدق موسى."], ["ثم أدبر يسعى", "بعد ما كذّب وعصى رجع يجمع جموعه ويحشر جنوده لحرب موسى."], ["فأخذه الله نكال الآخرة والأولى", "عذّبه على الكلمة الآخرة: «أنا ربكم الأعلى»، والكلمة الأولى: «ما علمت لكم من إله غيري»."]], "m": "المقصود من هذه الآيات تسلية الرسول ﷺ وهو يعاني من تكذيب قومه، فقصّ عليه طرفاً من قصة موسى مع فرعون تخفيفاً عليه، وتهديداً لقومه بعقوبة كعقوبة فرعون الذي كان أشد منهم بطشاً وقد أهلكه الله فأغرقه وجنده. هل أتاك يا رسولنا حديث موسى بن عمران إذ ناداه ربه بالوادي المطهّر المبارك المسمّى طوى، فأعلمه أولاً أنه لا إله إلا هو وأمره بعبادته، ثم أمره أن يذهب إلى فرعون ملك القبط بمصر: اذهب إلى فرعون إنه طغى، أي عتا وتكبّر وأفحش في الظلم، وعلّمه ما يقول له: هل لك إلى أن تُسلم فتزكو روحك وتطهر، وأرشدك إلى ربك وأعرّفك به فتخشى عقابه فتترك الظلم والطغيان؟ فأراه الآية الكبرى، اليد والعصا، فكذّب فرعون موسى وعصى ربه، ثم أدبر عن دعوة الحق يسعى في الباطل والشر، فحشر رجاله وجنده فناداهم ليعدّهم لحرب موسى، فقال: أنا ربكم الأعلى، يعني أنه لا رب فوقه، فأخذه الله فعذّبه على كلمته الآخرة: «أنا ربكم الأعلى»، وكلمته الأولى: «ما علمت لكم من إله غيري»، وبين الكلمتين الخبيثتين أربعون سنة. إن في ذلك لعظة لمن يخشى الله وعذاب الآخرة فيزداد إيماناً وتقوى.", "h": ["تسلية الداعي إلى الله تعالى وحمله على الصبر في دعوته حتى ينتهي بها إلى غاياتها.", "تقرير أن لا تزكية للنفس البشرية إلا بالإسلام، أي بالعمل بشرائعه.", "لا تحصل الخشية من الله للعبد إلا بعد معرفة الله تعالى: «إنما يخشى الله من عباده العلماء».", "وجود المعجزات لا يستلزم الإيمان، فقد رأى فرعون أعظم الآيات كالعصا واليد وما آمن.", "التنديد والوعيد الشديد لمن يدّعي الربوبية والألوهية فيأمر الناس بعبادته."], "k": "«هل لك إلى أن تزكّى وأهديك إلى ربك فتخشى»… حتى لفرعون قال قولاً ليّناً؛ فكيف أدعو أنا من حولي؟"}, {"lbl": "الآيات ٢٧ – ٣٣", "q": "ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ بَنَىٰهَا ﴿٢٧﴾ رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا ﴿٢٨﴾ وَأَغۡطَشَ لَيۡلَهَا وَأَخۡرَجَ ضُحَىٰهَا ﴿٢٩﴾ وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ ﴿٣٠﴾ أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا ﴿٣١﴾ وَٱلۡجِبَالَ أَرۡسَىٰهَا ﴿٣٢﴾ مَتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ ﴿٣٣﴾", "w": [["أأنتم أشد خلقاً أم السماء", "أيّهما أشد خلقاً؟"], ["رفع سمكها", "غلظها وارتفاعها."], ["فسوّاها", "جعلها مستوية ما فيها نتوء ولا انخفاض."], ["وأغطش ليلها", "أظلمه."], ["وأخرج ضحاها", "ضوءها ونهارها."], ["والأرض بعد ذلك دحاها", "خلق الأرض ثم خلق السماء ثم دحا الأرض، أي بسطها."], ["أخرج منها ماءها ومرعاها", "فجّر فيها عيونها وأنبت ما يُرعى."], ["والجبال أرساها", "أثبتها على سطح الأرض لتثبت ولا تميد بأهلها."], ["متاعاً لكم ولأنعامكم", "أخرج الماء والمرعى وأرسى الجبال متاعاً لكم ولمواشيكم."]], "m": "سيقت هذه الآيات لتقرير عقيدة البعث والجزاء بإيراد أكبر دليل عقلي لا يردّه العاقل: أن السماء والأرض في خلقهما وما فيهما أشد خلقاً وأعظم من خلق الإنسان بعد موته، فالبشرية كلها لا يساوي حجمها حجم كوكب واحد من كواكب السماء، ولا سلسلة واحدة من سلاسل الجبال، فالذي قدر على خلقهما قادر قطعاً ومن باب أولى على خلق الإنسان مرة أخرى، وإعادته أيسر من خلقه أولاً على غير مثال سبق، ولكن أكثر الناس لا يعلمون لأنهم لا يفكّرون. أأنتم أيها المنكرون للبعث أشد خلقاً أم السماء؟ والجواب: السماء أشد خلقاً، وبيان ذلك: بناها فهي سقف للأرض مرفوعة مسوّاة لا انفطار فيها، ورفع غلظها وارتفاعها، وأظلم ليلها، وأخرج نهارها مضيئاً. والأرض بعد ذلك دحاها، بسطها للأنام، وأخرج منها ماءها ففجّر فيها عيونها، ومرعاها من سائر الحبوب والثمار والنبات منفعة للإنسان ولحيوانه، والجبال أثبتها، متاعاً لكم ولأنعامكم. فكيف إذاً ينكر الإنسان على ربه أن يعيده حيّاً بعد إماتته ليحاسبه ويجزيه؟ إنه بدل أن ينكر يجب عليه أن يشكر.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان إفضال الله تعالى على الإنسان وإنعامه عليه.", "مشروعية الاستدلال بالكبير على الصغير وبالكثير على القليل، وهو مما يُعلم بداهة وبالضرورة، إلا أن الغفلة أكبر صارف وأقوى حائل، فلا بد من إزالتها أولاً."], "k": "«أأنتم أشد خلقاً أم السماء»… من رفع السماء يرفعني من قبري؛ فلماذا يثقل عليّ اليقين بذلك؟"}, {"lbl": "الآيات ٣٤ – ٤٦", "q": "فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلۡكُبۡرَىٰ ﴿٣٤﴾ يَوۡمَ يَتَذَكَّرُ ٱلۡإِنسَٰنُ مَا سَعَىٰ ﴿٣٥﴾ وَبُرِّزَتِ ٱلۡجَحِيمُ لِمَن يَرَىٰ ﴿٣٦﴾ فَأَمَّا مَن طَغَىٰ ﴿٣٧﴾ وَءَاثَرَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ﴿٣٨﴾ فَإِنَّ ٱلۡجَحِيمَ هِيَ ٱلۡمَأۡوَىٰ ﴿٣٩﴾ وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ ﴿٤٠﴾ فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ ﴿٤١﴾ يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَا ﴿٤٢﴾ فِيمَ أَنتَ مِن ذِكۡرَىٰهَآ ﴿٤٣﴾ إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ ﴿٤٤﴾ إِنَّمَآ أَنتَ مُنذِرُ مَن يَخۡشَىٰهَا ﴿٤٥﴾ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَهَا لَمۡ يَلۡبَثُوٓاْ إِلَّا عَشِيَّةً أَوۡ ضُحَىٰهَا ﴿٤٦﴾", "w": [["فإذا جاءت الطامّة الكبرى", "النفخة الثانية، وأصل الطامّة الداهية التي تعلو على كل داهية."], ["ما سعى", "ما عمل في الدنيا من خير وشر."], ["فأما من طغى", "كفر وظلم."], ["وآثر الحياة الدنيا", "باتّباع الشهوات."], ["فإن الجحيم هي المأوى", "النار مأواه."], ["مقام ربه", "قيامه بين يديه ليسأله عما قدّم وأخّر."], ["ونهى النفس عن الهوى", "عن الهوى المردي المهلك باتّباع الشهوات."], ["فإن الجنة هي المأوى", "مأواه الذي يأوي إليه بعد الحساب."], ["عن الساعة", "القيامة للحساب والجزاء."], ["أيّان مرساها", "متى وقوعها وقيامها؟"], ["فيمَ أنت من ذكراها", "في أي شيء أنت من ذكراها؟ أي ليس عندك علمها حتى تذكرها."], ["إلى ربك منتهاها", "منتهى علمها إلى الله وحده فلا يعلمها سواه."], ["لم يلبثوا", "في قبورهم."], ["إلا عشية أو ضحاها", "عشية يوم أو ضحى تلك العشية."]], "m": "بعد أن بيّن تعالى مظاهر قدرته في حياة الناس، ذكر مظاهر قدرته في معادهم: فإذا جاءت القيامة، وسُمّيت الطامة الكبرى لأنها تطمّ على كل شيء، لا ريح عاد ولا صيحة ثمود، يوم يتذكّر الإنسان ما سعى من خير أو شر لأنه أيقن أنه محاسب، وأُبرزت الجحيم لمن يرى لا يخفيها شيء. والناس بعد ذلك مؤمن وكافر، والطريق طريقان: فأما من عتا عن أمر ربه فعصاه، وآثر الحياة الدنيا على الآخرة فعمل لها وصرف كل جهده فيها، فما صام ولا صلّى ولا زكّى، فإن الجحيم هي مأواه ومستقرّه. وأما من خاف الوقوف بين يدي ربه لمساءلته فأدّى الفرائض واجتنب النواهي، ونهى نفسه عن هواها فلم يجبها في هوى يبغضه الله، فإن الجنة هي مأواه، ولنعم المأوى. يسألك يا رسولنا المنكرون للبعث عن الساعة متى قيامها ورسوّها، فيمَ أنت من ذكراها؟ ليس عندك علمها، إلى ربك وحده منتهى علم وقت مجيئها. إنما أنت منذر من يخشاها ويخاف حلولها لإيمانه بها، أما من لا يؤمن بها فسؤاله عنها سؤال استهزاء فلا تحفل بهم، فإنهم يوم يرونها كأن لم يلبثوا في دنياهم وقبورهم إلا عشية يوم أو ضحاها، لما يستقبلون من أهوال الموقف.", "h": ["تقرير عقيدة البعث والجزاء بذكر أحوالها وصفاتها.", "الناس يوم القيامة مؤمن تقيّ في الجنة، وكافر وفاجر في النار.", "بيان استئثار الله تعالى بعلم الغيب والساعة.", "بيان أن الشدائد ينسي بعضها بعضاً، فإن عذاب القبر يهون أمام عذاب النار."], "k": "«ونهى النفس عن الهوى»… أي هوى أنهى نفسي عنه اليوم لأقترب من «هي المأوى»؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 433;
insert into public.tdb_cards(topic, i, body) select 433, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٤", "q": "وَٱلنَّـٰزِعَٰتِ غَرۡقٗا ﴿١﴾ وَٱلنَّـٰشِطَٰتِ نَشۡطٗا ﴿٢﴾ وَٱلسَّـٰبِحَٰتِ سَبۡحٗا ﴿٣﴾ فَٱلسَّـٰبِقَٰتِ سَبۡقٗا ﴿٤﴾ فَٱلۡمُدَبِّرَٰتِ أَمۡرٗا ﴿٥﴾ يَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ ﴿٦﴾ تَتۡبَعُهَا ٱلرَّادِفَةُ ﴿٧﴾ قُلُوبٞ يَوۡمَئِذٖ وَاجِفَةٌ ﴿٨﴾ أَبۡصَٰرُهَا خَٰشِعَةٞ ﴿٩﴾ يَقُولُونَ أَءِنَّا لَمَرۡدُودُونَ فِي ٱلۡحَافِرَةِ ﴿١٠﴾ أَءِذَا كُنَّا عِظَٰمٗا نَّخِرَةٗ ﴿١١﴾ قَالُواْ تِلۡكَ إِذٗا كَرَّةٌ خَاسِرَةٞ ﴿١٢﴾ فَإِنَّمَا هِيَ زَجۡرَةٞ وَٰحِدَةٞ ﴿١٣﴾ فَإِذَا هُم بِٱلسَّاهِرَةِ ﴿١٤﴾", "w": [["والنازعات غرقاً", "الملائكة تنزع أرواح الفجّار والكفار عند الموت بشدة."], ["والناشطات نشطاً", "الملائكة تنشط أرواح المؤمنين الصالحين، أي تسلّها برفق."], ["والسابحات سبحاً", "الملائكة تسبح من السماء بأمر الله، أي تنزل به إلى الأرض."], ["فالسابقات سبقاً", "الملائكة تسبق بأرواح المؤمنين إلى الجنة."], ["فالمدبّرات أمراً", "الملائكة تنزل بتدبير أمر الدنيا من لدن الله المدبّر الحكيم."], ["يوم ترجف الراجفة", "النفخة الأولى، نفخة الفناء التي يتزلزل كل شيء معها."], ["تتبعها الرادفة", "النفخة الثانية."], ["واجفة", "خائفة قلقة."], ["أئنا لمردودون في الحافرة", "أنُردّ إلى أول الحياة؟ إذ الحافرة اسم لأول الأمر."], ["فإنما هي زجرة واحدة", "نفخة واحدة."], ["فإذا هم بالساهرة", "بوجه الأرض أحياء، سُمّيت ساهرة لأن من عليها يسهر ولا ينام."]], "m": "هذا قسم عظيم أقسم تعالى به على أنه لا بد من البعث والجزاء، حيث كان المشركون ينكرونه حتى لا يقفوا عند حد في سلوكهم، فيواصلوا كفرهم وفسادهم جرياً وراء شهواتهم، فأقسم تعالى بخمسة أشياء: النازعات والناشطات والسابحات والسابقات والمدبّرات، ورُجّح أنهم أصناف من الملائكة، وجائز غير ذلك، إذ العبرة أنه تعالى قد أقسم ببعض مخلوقاته على أن البعث حق واقع لا محالة، وتقدير الجواب: لتُبعثنّ ثم لتُنبّؤنّ بما عملتم. وسيتمّ ذلك يوم ترجف الراجفة، النفخة الأولى التي ترجف فيها العوالم كلها ويفنى فيها كل شيء، ثم تتبعها الرادفة، وهي نفخة البعث من القبور، وبين النفختين أربعون سنة كما في الحديث الصحيح. قلوب يومئذ خائفة قلقة، أبصار أصحابها ذليلة خائفة. يقول منكرو البعث: أئنا لمردودون بعد الموت إلى الحياة من جديد كما كنا أول مرة؟ أئذا كنا عظاماً بالية مفتّتة؟ استبعاداً منهم وإنكاراً، وقالوا: تلك إذاً رجعة خاسرة، وهي كذلك بالنسبة إليهم، إذ سيخسرون فيها كل شيء حتى أنفسهم. فإنما هي صيحة واحدة، نفخة إسرافيل الثانية، فإذا هم وسائر الخلق بوجه الأرض لا ينامون. فردّ تعالى بهذا على منكري البعث وقرّره بما لا مزيد عليه إعذاراً وإنذاراً.", "h": ["بيان أن الله تعالى يقسم بما يشاء من مخلوقاته، بخلاف العبد لا يجوز له أن يقسم بغير ربه.", "بيان أن روح المؤمن تُنزع عند الموت نزعاً سريعاً، لا يجد من الألم ما يجده الكافر.", "تقرير عقيدة البعث والجزاء بالإقسام عليها وذكر كيفية وقوعها."], "k": "«والناشطات نشطاً»… خروج الروح برفق كرامة للمؤمن؛ فهل أعيش حياة من يرجو هذا الرفق؟"}, {"lbl": "الآيات ١٥ – ٢٦", "q": "هَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ ﴿١٥﴾ إِذۡ نَادَىٰهُ رَبُّهُۥ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوًى ﴿١٦﴾ ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ﴿١٧﴾ فَقُلۡ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ ﴿١٨﴾ وَأَهۡدِيَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ ﴿١٩﴾ فَأَرَىٰهُ ٱلۡأٓيَةَ ٱلۡكُبۡرَىٰ ﴿٢٠﴾ فَكَذَّبَ وَعَصَىٰ ﴿٢١﴾ ثُمَّ أَدۡبَرَ يَسۡعَىٰ ﴿٢٢﴾ فَحَشَرَ فَنَادَىٰ ﴿٢٣﴾ فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ ﴿٢٤﴾ فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلۡأٓخِرَةِ وَٱلۡأُولَىٰٓ ﴿٢٥﴾ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّمَن يَخۡشَىٰٓ ﴿٢٦﴾", "w": [["موسى", "موسى بن عمران ﵇."], ["بالوادِ المقدّس طوى", "بالوادي الطاهر المبارك المسمّى طوى."], ["اذهب إلى فرعون", "أن اذهب إلى فرعون."], ["إنه طغى", "تجاوز حدّه كعبد إلى ادّعاء الربوبية والألوهية."], ["إلى أن تزكّى", "أن تُسلم فتطهر من رجس الشرك والكفر."], ["وأهديك إلى ربك", "أرشدك إلى معرفة ربك الحق فتخشاه وتطيعه فتنجو من عذابه."], ["فأراه الآية الكبرى", "العصا واليد، إذ هي من أكبر الآيات الدالة على صدق موسى."], ["ثم أدبر يسعى", "بعد ما كذّب وعصى رجع يجمع جموعه ويحشر جنوده لحرب موسى."], ["فأخذه الله نكال الآخرة والأولى", "عذّبه على الكلمة الآخرة: «أنا ربكم الأعلى»، والكلمة الأولى: «ما علمت لكم من إله غيري»."]], "m": "المقصود من هذه الآيات تسلية الرسول ﷺ وهو يعاني من تكذيب قومه، فقصّ عليه طرفاً من قصة موسى مع فرعون تخفيفاً عليه، وتهديداً لقومه بعقوبة كعقوبة فرعون الذي كان أشد منهم بطشاً وقد أهلكه الله فأغرقه وجنده. هل أتاك يا رسولنا حديث موسى بن عمران إذ ناداه ربه بالوادي المطهّر المبارك المسمّى طوى، فأعلمه أولاً أنه لا إله إلا هو وأمره بعبادته، ثم أمره أن يذهب إلى فرعون ملك القبط بمصر: اذهب إلى فرعون إنه طغى، أي عتا وتكبّر وأفحش في الظلم، وعلّمه ما يقول له: هل لك إلى أن تُسلم فتزكو روحك وتطهر، وأرشدك إلى ربك وأعرّفك به فتخشى عقابه فتترك الظلم والطغيان؟ فأراه الآية الكبرى، اليد والعصا، فكذّب فرعون موسى وعصى ربه، ثم أدبر عن دعوة الحق يسعى في الباطل والشر، فحشر رجاله وجنده فناداهم ليعدّهم لحرب موسى، فقال: أنا ربكم الأعلى، يعني أنه لا رب فوقه، فأخذه الله فعذّبه على كلمته الآخرة: «أنا ربكم الأعلى»، وكلمته الأولى: «ما علمت لكم من إله غيري»، وبين الكلمتين الخبيثتين أربعون سنة. إن في ذلك لعظة لمن يخشى الله وعذاب الآخرة فيزداد إيماناً وتقوى.", "h": ["تسلية الداعي إلى الله تعالى وحمله على الصبر في دعوته حتى ينتهي بها إلى غاياتها.", "تقرير أن لا تزكية للنفس البشرية إلا بالإسلام، أي بالعمل بشرائعه.", "لا تحصل الخشية من الله للعبد إلا بعد معرفة الله تعالى: «إنما يخشى الله من عباده العلماء».", "وجود المعجزات لا يستلزم الإيمان، فقد رأى فرعون أعظم الآيات كالعصا واليد وما آمن.", "التنديد والوعيد الشديد لمن يدّعي الربوبية والألوهية فيأمر الناس بعبادته."], "k": "«هل لك إلى أن تزكّى وأهديك إلى ربك فتخشى»… حتى لفرعون قال قولاً ليّناً؛ فكيف أدعو أنا من حولي؟"}, {"lbl": "الآيات ٢٧ – ٣٣", "q": "ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ بَنَىٰهَا ﴿٢٧﴾ رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا ﴿٢٨﴾ وَأَغۡطَشَ لَيۡلَهَا وَأَخۡرَجَ ضُحَىٰهَا ﴿٢٩﴾ وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ ﴿٣٠﴾ أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا ﴿٣١﴾ وَٱلۡجِبَالَ أَرۡسَىٰهَا ﴿٣٢﴾ مَتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ ﴿٣٣﴾", "w": [["أأنتم أشد خلقاً أم السماء", "أيّهما أشد خلقاً؟"], ["رفع سمكها", "غلظها وارتفاعها."], ["فسوّاها", "جعلها مستوية ما فيها نتوء ولا انخفاض."], ["وأغطش ليلها", "أظلمه."], ["وأخرج ضحاها", "ضوءها ونهارها."], ["والأرض بعد ذلك دحاها", "خلق الأرض ثم خلق السماء ثم دحا الأرض، أي بسطها."], ["أخرج منها ماءها ومرعاها", "فجّر فيها عيونها وأنبت ما يُرعى."], ["والجبال أرساها", "أثبتها على سطح الأرض لتثبت ولا تميد بأهلها."], ["متاعاً لكم ولأنعامكم", "أخرج الماء والمرعى وأرسى الجبال متاعاً لكم ولمواشيكم."]], "m": "سيقت هذه الآيات لتقرير عقيدة البعث والجزاء بإيراد أكبر دليل عقلي لا يردّه العاقل: أن السماء والأرض في خلقهما وما فيهما أشد خلقاً وأعظم من خلق الإنسان بعد موته، فالبشرية كلها لا يساوي حجمها حجم كوكب واحد من كواكب السماء، ولا سلسلة واحدة من سلاسل الجبال، فالذي قدر على خلقهما قادر قطعاً ومن باب أولى على خلق الإنسان مرة أخرى، وإعادته أيسر من خلقه أولاً على غير مثال سبق، ولكن أكثر الناس لا يعلمون لأنهم لا يفكّرون. أأنتم أيها المنكرون للبعث أشد خلقاً أم السماء؟ والجواب: السماء أشد خلقاً، وبيان ذلك: بناها فهي سقف للأرض مرفوعة مسوّاة لا انفطار فيها، ورفع غلظها وارتفاعها، وأظلم ليلها، وأخرج نهارها مضيئاً. والأرض بعد ذلك دحاها، بسطها للأنام، وأخرج منها ماءها ففجّر فيها عيونها، ومرعاها من سائر الحبوب والثمار والنبات منفعة للإنسان ولحيوانه، والجبال أثبتها، متاعاً لكم ولأنعامكم. فكيف إذاً ينكر الإنسان على ربه أن يعيده حيّاً بعد إماتته ليحاسبه ويجزيه؟ إنه بدل أن ينكر يجب عليه أن يشكر.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان إفضال الله تعالى على الإنسان وإنعامه عليه.", "مشروعية الاستدلال بالكبير على الصغير وبالكثير على القليل، وهو مما يُعلم بداهة وبالضرورة، إلا أن الغفلة أكبر صارف وأقوى حائل، فلا بد من إزالتها أولاً."], "k": "«أأنتم أشد خلقاً أم السماء»… من رفع السماء يرفعني من قبري؛ فلماذا يثقل عليّ اليقين بذلك؟"}, {"lbl": "الآيات ٣٤ – ٤٦", "q": "فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلۡكُبۡرَىٰ ﴿٣٤﴾ يَوۡمَ يَتَذَكَّرُ ٱلۡإِنسَٰنُ مَا سَعَىٰ ﴿٣٥﴾ وَبُرِّزَتِ ٱلۡجَحِيمُ لِمَن يَرَىٰ ﴿٣٦﴾ فَأَمَّا مَن طَغَىٰ ﴿٣٧﴾ وَءَاثَرَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ﴿٣٨﴾ فَإِنَّ ٱلۡجَحِيمَ هِيَ ٱلۡمَأۡوَىٰ ﴿٣٩﴾ وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ ﴿٤٠﴾ فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ ﴿٤١﴾ يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَا ﴿٤٢﴾ فِيمَ أَنتَ مِن ذِكۡرَىٰهَآ ﴿٤٣﴾ إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ ﴿٤٤﴾ إِنَّمَآ أَنتَ مُنذِرُ مَن يَخۡشَىٰهَا ﴿٤٥﴾ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَهَا لَمۡ يَلۡبَثُوٓاْ إِلَّا عَشِيَّةً أَوۡ ضُحَىٰهَا ﴿٤٦﴾", "w": [["فإذا جاءت الطامّة الكبرى", "النفخة الثانية، وأصل الطامّة الداهية التي تعلو على كل داهية."], ["ما سعى", "ما عمل في الدنيا من خير وشر."], ["فأما من طغى", "كفر وظلم."], ["وآثر الحياة الدنيا", "باتّباع الشهوات."], ["فإن الجحيم هي المأوى", "النار مأواه."], ["مقام ربه", "قيامه بين يديه ليسأله عما قدّم وأخّر."], ["ونهى النفس عن الهوى", "عن الهوى المردي المهلك باتّباع الشهوات."], ["فإن الجنة هي المأوى", "مأواه الذي يأوي إليه بعد الحساب."], ["عن الساعة", "القيامة للحساب والجزاء."], ["أيّان مرساها", "متى وقوعها وقيامها؟"], ["فيمَ أنت من ذكراها", "في أي شيء أنت من ذكراها؟ أي ليس عندك علمها حتى تذكرها."], ["إلى ربك منتهاها", "منتهى علمها إلى الله وحده فلا يعلمها سواه."], ["لم يلبثوا", "في قبورهم."], ["إلا عشية أو ضحاها", "عشية يوم أو ضحى تلك العشية."]], "m": "بعد أن بيّن تعالى مظاهر قدرته في حياة الناس، ذكر مظاهر قدرته في معادهم: فإذا جاءت القيامة، وسُمّيت الطامة الكبرى لأنها تطمّ على كل شيء، لا ريح عاد ولا صيحة ثمود، يوم يتذكّر الإنسان ما سعى من خير أو شر لأنه أيقن أنه محاسب، وأُبرزت الجحيم لمن يرى لا يخفيها شيء. والناس بعد ذلك مؤمن وكافر، والطريق طريقان: فأما من عتا عن أمر ربه فعصاه، وآثر الحياة الدنيا على الآخرة فعمل لها وصرف كل جهده فيها، فما صام ولا صلّى ولا زكّى، فإن الجحيم هي مأواه ومستقرّه. وأما من خاف الوقوف بين يدي ربه لمساءلته فأدّى الفرائض واجتنب النواهي، ونهى نفسه عن هواها فلم يجبها في هوى يبغضه الله، فإن الجنة هي مأواه، ولنعم المأوى. يسألك يا رسولنا المنكرون للبعث عن الساعة متى قيامها ورسوّها، فيمَ أنت من ذكراها؟ ليس عندك علمها، إلى ربك وحده منتهى علم وقت مجيئها. إنما أنت منذر من يخشاها ويخاف حلولها لإيمانه بها، أما من لا يؤمن بها فسؤاله عنها سؤال استهزاء فلا تحفل بهم، فإنهم يوم يرونها كأن لم يلبثوا في دنياهم وقبورهم إلا عشية يوم أو ضحاها، لما يستقبلون من أهوال الموقف.", "h": ["تقرير عقيدة البعث والجزاء بذكر أحوالها وصفاتها.", "الناس يوم القيامة مؤمن تقيّ في الجنة، وكافر وفاجر في النار.", "بيان استئثار الله تعالى بعلم الغيب والساعة.", "بيان أن الشدائد ينسي بعضها بعضاً، فإن عذاب القبر يهون أمام عذاب النار."], "k": "«ونهى النفس عن الهوى»… أي هوى أنهى نفسي عنه اليوم لأقترب من «هي المأوى»؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (434, 80, 1, 42, 'سورة عبس ١ – ٤٢', 'عبس: عبس وتولّى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 434) = $j$[{"lbl": "الآيات ١ – ١٦", "q": "عَبَسَ وَتَوَلَّىٰٓ ﴿١﴾ أَن جَآءَهُ ٱلۡأَعۡمَىٰ ﴿٢﴾ وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ ﴿٣﴾ أَوۡ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ ﴿٤﴾ أَمَّا مَنِ ٱسۡتَغۡنَىٰ ﴿٥﴾ فَأَنتَ لَهُۥ تَصَدَّىٰ ﴿٦﴾ وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ ﴿٧﴾ وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ ﴿٨﴾ وَهُوَ يَخۡشَىٰ ﴿٩﴾ فَأَنتَ عَنۡهُ تَلَهَّىٰ ﴿١٠﴾ كَلَّآ إِنَّهَا تَذۡكِرَةٞ ﴿١١﴾ فَمَن شَآءَ ذَكَرَهُۥ ﴿١٢﴾ فِي صُحُفٖ مُّكَرَّمَةٖ ﴿١٣﴾ مَّرۡفُوعَةٖ مُّطَهَّرَةِۭ ﴿١٤﴾ بِأَيۡدِي سَفَرَةٖ ﴿١٥﴾ كِرَامِۭ بَرَرَةٖ ﴿١٦﴾", "w": [["عبس", "أي النبي ﷺ، بمعنى كلح وجهه وتغيّر."], ["وتولّى", "أعرض."], ["أن جاءه الأعمى", "لأجل أن جاء عبد الله بن أم مكتوم فقطعه عما هو مشغول به من دعوة بعض أشراف قريش للإسلام."], ["لعله يزّكّى", "يتطهّر من الذنوب."], ["أو يذّكّر", "يتّعظ."], ["فتنفعه الذكرى", "الموعظة."], ["أما من استغنى", "عن الإيمان والعلم والدين بالمال والجاه."], ["فأنت له تصدّى", "تُقبل عليه وتتصدّى له."], ["وما عليك ألّا يزّكّى", "ليس عليك بأس في عدم تزكيته نفسه بالإسلام."], ["وأما من جاءك يسعى", "في طلب الخير من العلم والهدى."], ["فأنت عنه تلهّى", "تتشاغل."], ["إنها تذكرة", "الآيات عظة للخلق."], ["في صحف مكرّمة", "عند الله."], ["مرفوعة", "في السماء."], ["مطهّرة", "منزّهة عن مسّ الشياطين."], ["بأيدي سفرة", "كتبة ينسخونها من اللوح المحفوظ."], ["كرام بررة", "مطيعين لله، وهم الملائكة."]], "m": "هذا عتاب لطيف يعاتب به الله سبحانه رسوله محمداً ﷺ، فالذي عبس وأعرض هو رسول الله ﷺ، والأعمى عبد الله بن أم مكتوم، أحد المهاجرين، ابن خال خديجة أم المؤمنين. وسبب هذا العتاب أن رسول الله ﷺ كان يوماً ومعه صناديد قريش: عتبة وشيبة ابنا ربيعة وأبو جهل والعباس وأمية بن خلف، يدعوهم إلى الإسلام مجتهداً معهم طمعاً في إسلامهم، فجاء عبد الله بن أم مكتوم ينادي: يا رسول الله أقرئني وعلّمني مما علّمك الله، وكرّر ذلك، فكره رسول الله ﷺ قطعه لحديثه مع القوم، فعبس وتولّى عنه، وما إن عاد إلى منزله حتى نزلت هذه الآيات: عبس وتولّى لأجل أن جاءه الأعمى، وما يعلمك لعله يريد زكاة نفسه وتطهير روحه بما يتعلّمه منك، أو يتذكّر فينفعه التذكير؟ أما من استغنى عن الإيمان وما عندك من العلم بماله وشرفه فأنت له تتعرّض مقبلاً عليه، وما يلحقك من بأس إن لم يتزكَّ؟ وأما من جاءك مسرعاً يناديك بأحب الأسماء إليك: يا رسول الله، وهو يخشى الله، يطلب ما يزكّي به نفسه، فأنت عنه تتشاغل بغيره؟ كلا، لا تفعل مثل هذا مرة أخرى. إن هذه الآيات وما تحمل من عتاب حبيب لحبيب موعظة، فمن شاء من عباد الله ذكره، في صحف مكرّمة عند الله، مرفوعة في السماء، منزّهة عن مسّ الشياطين، بأيدي ملائكة كتبة كرام بررة؛ وما أقرب هذا الوصف من مؤمن طاهر الروح يحفظ كتاب الله ويعمل به، وقد جاء في الصحيح أن الماهر بالقرآن مع السفرة الكرام البررة.", "h": ["بيان مقام النبي ﷺ وأنه أشرف مقام وأسماه، دلّ على ذلك أسلوب عتاب الله تعالى له، حيث خاطبه في أسلوب شخص غائب حتى لا يواجهه بالخطاب فيؤلمه، ثم أقبل عليه بعد أن أزال الوحشة يخاطبه: «وما يدريك».", "إثبات ما جاء في الخبر: «أدّبني ربي فأحسن تأديبي»، فقد دلّت الآيات عليه.", "بلغ رسول الله ﷺ بتأديب ربه له مستوى لم يبلغه سواه، فقد كان إذا جاءه ابن أم مكتوم يوسّع له في المجلس ويجلسه إلى جنبه ويقول: «مرحباً بالذي عاتبني ربي من أجله»، وولّاه على المدينة مرات، وكان مؤذّناً له في رمضان.", "استحالة كتمان الرسول ﷺ لشيء من الوحي، فقد قالت عائشة رضي الله عنها: لو كان للرسول أن يكتم شيئاً من وحي الله لكتم عتاب الله تعالى له في «عبس وتولّى»."], "k": "«وما يدريك لعله يزّكّى»… الضعيف الذي لا ألتفت إليه قد يكون أقرب إلى الله مني؛ فبمن أنشغل؟"}, {"lbl": "الآيات ١٧ – ٣٢", "q": "قُتِلَ ٱلۡإِنسَٰنُ مَآ أَكۡفَرَهُۥ ﴿١٧﴾ مِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ ﴿١٨﴾ مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ ﴿١٩﴾ ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ ﴿٢٠﴾ ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ ﴿٢١﴾ ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ ﴿٢٢﴾ كَلَّا لَمَّا يَقۡضِ مَآ أَمَرَهُۥ ﴿٢٣﴾ فَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ ﴿٢٤﴾ أَنَّا صَبَبۡنَا ٱلۡمَآءَ صَبّٗا ﴿٢٥﴾ ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ شَقّٗا ﴿٢٦﴾ فَأَنۢبَتۡنَا فِيهَا حَبّٗا ﴿٢٧﴾ وَعِنَبٗا وَقَضۡبٗا ﴿٢٨﴾ وَزَيۡتُونٗا وَنَخۡلٗا ﴿٢٩﴾ وَحَدَآئِقَ غُلۡبٗا ﴿٣٠﴾ وَفَٰكِهَةٗ وَأَبّٗا ﴿٣١﴾ مَّتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ ﴿٣٢﴾", "w": [["قُتل الإنسان", "لُعن الإنسان الكافر."], ["ما أكفره", "ما حمله على الكفر؟"], ["من أي شيء خلقه", "من نطفة خلقه."], ["فقدّره", "من نطفة إلى علقة إلى مضغة فبشر سويّ."], ["ثم السبيل يسّره", "سبيل الخروج من بطن أمه."], ["فأقبره", "هيّأ له من يقبره."], ["إذا شاء أنشره", "إذا شاء إحياءه أحياه."], ["كلا", "حقاً، ليس الأمر كما يدّعي الإنسان أنه أدّى ما عليه."], ["لما يقضِ ما أمره", "ما كلّفه به من الطاعات والواجبات في نفسه وماله."], ["إلى طعامه", "كيف قدّر ودبّر له."], ["حبّاً وعنباً", "الحب: الحنطة والشعير، والعنب هو المعروف."], ["وقضباً", "القتّ الرطب، يُقضب أي يُقطع مرة بعد مرة."], ["وحدائق غُلباً", "كثيرة الأشجار ملتفّتها."], ["وفاكهة وأبّاً", "ما يُتفكّه به من سائر الفواكه، والأبّ ما ترعاه البهائم."], ["متاعاً لكم ولأنعامكم", "منفعة لكم ولأنعامكم من الإبل والبقر والغنم."]], "m": "بعدما عاتب الرب تبارك وتعالى رسوله على انشغاله بأولئك المشركين وإعراضه عن ابن أم مكتوم، جرّد شخصاً منهم غير معلوم، والمراد كل كافر متكبّر مثلهم، فقال: قُتل الإنسان الكافر، ما الذي حمله على الكفر والكبر؟ فلينظر من أي شيء خلقه ربه الذي يكفر به؟ إنه خلقه من نطفة قذرة، فقدّره أطواراً: نطفة فعلقة فمضغة، أفمن كان هذا حاله يليق به أن يكفر ويتكبّر ويستغني عن الله؟ ثم يسّر له طريق الخروج من بطن أمه، ولولا ذلك ما خرج، ثم أماته بدون استشارته، فهيّأ له من يقبره، ثم إذا شاء أنشره. كلا، أما يصحو هذا المغرور؟ لم يقضِ ما أمره به من الإيمان والطاعة. فلينظر هذا الإنسان إلى طعامه الذي حياته متوقّفة عليه كيف يتم له بتقدير الله وتدبيره، لعله يذكر فيشكر: إنا صببنا الماء صبّاً، ثم شققنا الأرض شقّاً، فأنبتنا فيها حبّاً كالبُرّ والشعير، وعنباً يأكله رطباً ويابساً، وقضباً هو علف البهائم، وزيتوناً يأكله حبّاً ويدّهن به، ونخلاً يأكل ثمره بسراً ورطباً وتمراً، وحدائق ملتفّة الأشجار، وفاكهة لكم، وأبّاً علفاً لدوابّكم، متاعاً لكم ولأنعامكم؛ فبأي وجه تكفر ربك أيها الإنسان؟", "h": ["بيان مظاهر قدرة الله وعلمه وحكمته، وهي مقتضية للإيمان به وبآياته ورسوله ولقائه.", "الاستدلال بالصنعة على الصانع، وأن أثر الشيء يدلّ عليه، ولذا يُتعجّب من كفر الكافر بربه وهو خلقه ورزقه وكلأ حياته وحفظ وجوده إلى أجله.", "بيان أن الإنسان لا يزال مقصّراً في شكر ربه ولو صام الدهر كله وصلّى في كل لحظة من لحظاته."], "k": "«فلينظر الإنسان إلى طعامه»… قبل أن آكل، فلأنظر: كم يداً وكم مطراً حتى وصل إليّ؟"}, {"lbl": "الآيات ٣٣ – ٤٢", "q": "فَإِذَا جَآءَتِ ٱلصَّآخَّةُ ﴿٣٣﴾ يَوۡمَ يَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِيهِ ﴿٣٤﴾ وَأُمِّهِۦ وَأَبِيهِ ﴿٣٥﴾ وَصَٰحِبَتِهِۦ وَبَنِيهِ ﴿٣٦﴾ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُمۡ يَوۡمَئِذٖ شَأۡنٞ يُغۡنِيهِ ﴿٣٧﴾ وُجُوهٞ يَوۡمَئِذٖ مُّسۡفِرَةٞ ﴿٣٨﴾ ضَاحِكَةٞ مُّسۡتَبۡشِرَةٞ ﴿٣٩﴾ وَوُجُوهٞ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةٞ ﴿٤٠﴾ تَرۡهَقُهَا قَتَرَةٌ ﴿٤١﴾ أُوْلَـٰٓئِكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ ﴿٤٢﴾", "w": [["فإذا جاءت الصاخّة", "النفخة الثانية."], ["وصاحبته", "زوجته."], ["شأن يغنيه", "حال وأمر يغنيه عن السؤال عن غيره."], ["مسفرة", "مضيئة مشرقة."], ["عليها غبرة", "غبار."], ["ترهقها قترة", "تغشاها ظلمة من سواد."], ["الكفرة الفجرة", "الجامعون بين الكفر والفجور."]], "m": "بعدما بيّن تعالى بداية أمر الإنسان في حياته ومعاشه، ذكر معاده ومآله: فإذا جاءت الصاخّة، وهي القيامة، ولعل تسميتها بذلك نظراً إلى نفخة الصور التي تصخّ الآذان، أي تصيبها بالصمم لشدتها، يوم يفرّ المرء من أخيه وأمه وأبيه وزوجته وبنيه، وهؤلاء أقرب الناس إليه، ومع هذا يفرّ عنهم خشية أن يطالبوه بحق لهم عليه، لكل امرئ منهم يومئذ حال وأمر يغنيه عن السؤال عن غيره ولو كان أقرب قريب. وقد سألت عائشة رضي الله عنها رسول الله ﷺ: كيف يُحشر الرجال؟ قال: «حفاة عراة»، ثم قالت: كيف يُحشر النساء؟ قال: «كذلك حفاة عراة»، قالت: واسوأتاه من يوم القيامة! قال: «قد نزلت عليّ آية لا يضرّك كان عليك ثياب أم لا»، قالت: أي آية؟ قال: «لكل امرئ منهم يومئذ شأن يغنيه». وجوه يومئذ مضيئة مشرقة، ضاحكة مستبشرة، وهي وجوه المؤمنين والمؤمنات أهل التقوى، مستبشرون بالقدوم على ربهم، ووجوه يومئذ عليها غبار، تغشاها ظلمة وسواد، أولئك هم الكفرة في الدنيا الفجرة فيها، الذين عاشوا على الكفر والفجور وماتوا على ذلك، والفجور هو الخروج عن طاعة الله بترك الواجبات وغشيان المحرّمات كالربا والزنا.", "h": ["بيان شدة الهول يوم القيامة، يدل عليه فرار المرء من أقربائه.", "خطر التبعات على العبد يوم القيامة، وهي الحقوق التي يُطالب بها العبد.", "شدة الهول والفزع تُنسي المرء يوم القيامة أن ينظر إلى عورة أحد من أهل الموقف.", "ثمرة الإيمان والتقوى تظهر في الموقف نوراً على الوجه وإشراقاً، وثمرة الكفر والفجور تظهر ظلمة وسواداً على الوجه وغباراً.", "تقرير عقيدة البعث والجزاء بعرض صورة من صورها."], "k": "«يوم يفرّ المرء من أخيه»… حقوق الناس تلاحقني حتى من أحبّهم؛ فأي حق عليّ أردّه اليوم؟"}]$j$::jsonb then 0 else 1 end;
