insert into public.tdb_cards(topic, i, body) select 434, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٦", "q": "عَبَسَ وَتَوَلَّىٰٓ ﴿١﴾ أَن جَآءَهُ ٱلۡأَعۡمَىٰ ﴿٢﴾ وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ ﴿٣﴾ أَوۡ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ ﴿٤﴾ أَمَّا مَنِ ٱسۡتَغۡنَىٰ ﴿٥﴾ فَأَنتَ لَهُۥ تَصَدَّىٰ ﴿٦﴾ وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ ﴿٧﴾ وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ ﴿٨﴾ وَهُوَ يَخۡشَىٰ ﴿٩﴾ فَأَنتَ عَنۡهُ تَلَهَّىٰ ﴿١٠﴾ كَلَّآ إِنَّهَا تَذۡكِرَةٞ ﴿١١﴾ فَمَن شَآءَ ذَكَرَهُۥ ﴿١٢﴾ فِي صُحُفٖ مُّكَرَّمَةٖ ﴿١٣﴾ مَّرۡفُوعَةٖ مُّطَهَّرَةِۭ ﴿١٤﴾ بِأَيۡدِي سَفَرَةٖ ﴿١٥﴾ كِرَامِۭ بَرَرَةٖ ﴿١٦﴾", "w": [["عبس", "أي النبي ﷺ، بمعنى كلح وجهه وتغيّر."], ["وتولّى", "أعرض."], ["أن جاءه الأعمى", "لأجل أن جاء عبد الله بن أم مكتوم فقطعه عما هو مشغول به من دعوة بعض أشراف قريش للإسلام."], ["لعله يزّكّى", "يتطهّر من الذنوب."], ["أو يذّكّر", "يتّعظ."], ["فتنفعه الذكرى", "الموعظة."], ["أما من استغنى", "عن الإيمان والعلم والدين بالمال والجاه."], ["فأنت له تصدّى", "تُقبل عليه وتتصدّى له."], ["وما عليك ألّا يزّكّى", "ليس عليك بأس في عدم تزكيته نفسه بالإسلام."], ["وأما من جاءك يسعى", "في طلب الخير من العلم والهدى."], ["فأنت عنه تلهّى", "تتشاغل."], ["إنها تذكرة", "الآيات عظة للخلق."], ["في صحف مكرّمة", "عند الله."], ["مرفوعة", "في السماء."], ["مطهّرة", "منزّهة عن مسّ الشياطين."], ["بأيدي سفرة", "كتبة ينسخونها من اللوح المحفوظ."], ["كرام بررة", "مطيعين لله، وهم الملائكة."]], "m": "هذا عتاب لطيف يعاتب به الله سبحانه رسوله محمداً ﷺ، فالذي عبس وأعرض هو رسول الله ﷺ، والأعمى عبد الله بن أم مكتوم، أحد المهاجرين، ابن خال خديجة أم المؤمنين. وسبب هذا العتاب أن رسول الله ﷺ كان يوماً ومعه صناديد قريش: عتبة وشيبة ابنا ربيعة وأبو جهل والعباس وأمية بن خلف، يدعوهم إلى الإسلام مجتهداً معهم طمعاً في إسلامهم، فجاء عبد الله بن أم مكتوم ينادي: يا رسول الله أقرئني وعلّمني مما علّمك الله، وكرّر ذلك، فكره رسول الله ﷺ قطعه لحديثه مع القوم، فعبس وتولّى عنه، وما إن عاد إلى منزله حتى نزلت هذه الآيات: عبس وتولّى لأجل أن جاءه الأعمى، وما يعلمك لعله يريد زكاة نفسه وتطهير روحه بما يتعلّمه منك، أو يتذكّر فينفعه التذكير؟ أما من استغنى عن الإيمان وما عندك من العلم بماله وشرفه فأنت له تتعرّض مقبلاً عليه، وما يلحقك من بأس إن لم يتزكَّ؟ وأما من جاءك مسرعاً يناديك بأحب الأسماء إليك: يا رسول الله، وهو يخشى الله، يطلب ما يزكّي به نفسه، فأنت عنه تتشاغل بغيره؟ كلا، لا تفعل مثل هذا مرة أخرى. إن هذه الآيات وما تحمل من عتاب حبيب لحبيب موعظة، فمن شاء من عباد الله ذكره، في صحف مكرّمة عند الله، مرفوعة في السماء، منزّهة عن مسّ الشياطين، بأيدي ملائكة كتبة كرام بررة؛ وما أقرب هذا الوصف من مؤمن طاهر الروح يحفظ كتاب الله ويعمل به، وقد جاء في الصحيح أن الماهر بالقرآن مع السفرة الكرام البررة.", "h": ["بيان مقام النبي ﷺ وأنه أشرف مقام وأسماه، دلّ على ذلك أسلوب عتاب الله تعالى له، حيث خاطبه في أسلوب شخص غائب حتى لا يواجهه بالخطاب فيؤلمه، ثم أقبل عليه بعد أن أزال الوحشة يخاطبه: «وما يدريك».", "إثبات ما جاء في الخبر: «أدّبني ربي فأحسن تأديبي»، فقد دلّت الآيات عليه.", "بلغ رسول الله ﷺ بتأديب ربه له مستوى لم يبلغه سواه، فقد كان إذا جاءه ابن أم مكتوم يوسّع له في المجلس ويجلسه إلى جنبه ويقول: «مرحباً بالذي عاتبني ربي من أجله»، وولّاه على المدينة مرات، وكان مؤذّناً له في رمضان.", "استحالة كتمان الرسول ﷺ لشيء من الوحي، فقد قالت عائشة رضي الله عنها: لو كان للرسول أن يكتم شيئاً من وحي الله لكتم عتاب الله تعالى له في «عبس وتولّى»."], "k": "«وما يدريك لعله يزّكّى»… الضعيف الذي لا ألتفت إليه قد يكون أقرب إلى الله مني؛ فبمن أنشغل؟"}, {"lbl": "الآيات ١٧ – ٣٢", "q": "قُتِلَ ٱلۡإِنسَٰنُ مَآ أَكۡفَرَهُۥ ﴿١٧﴾ مِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ ﴿١٨﴾ مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ ﴿١٩﴾ ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ ﴿٢٠﴾ ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ ﴿٢١﴾ ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ ﴿٢٢﴾ كَلَّا لَمَّا يَقۡضِ مَآ أَمَرَهُۥ ﴿٢٣﴾ فَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ ﴿٢٤﴾ أَنَّا صَبَبۡنَا ٱلۡمَآءَ صَبّٗا ﴿٢٥﴾ ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ شَقّٗا ﴿٢٦﴾ فَأَنۢبَتۡنَا فِيهَا حَبّٗا ﴿٢٧﴾ وَعِنَبٗا وَقَضۡبٗا ﴿٢٨﴾ وَزَيۡتُونٗا وَنَخۡلٗا ﴿٢٩﴾ وَحَدَآئِقَ غُلۡبٗا ﴿٣٠﴾ وَفَٰكِهَةٗ وَأَبّٗا ﴿٣١﴾ مَّتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ ﴿٣٢﴾", "w": [["قُتل الإنسان", "لُعن الإنسان الكافر."], ["ما أكفره", "ما حمله على الكفر؟"], ["من أي شيء خلقه", "من نطفة خلقه."], ["فقدّره", "من نطفة إلى علقة إلى مضغة فبشر سويّ."], ["ثم السبيل يسّره", "سبيل الخروج من بطن أمه."], ["فأقبره", "هيّأ له من يقبره."], ["إذا شاء أنشره", "إذا شاء إحياءه أحياه."], ["كلا", "حقاً، ليس الأمر كما يدّعي الإنسان أنه أدّى ما عليه."], ["لما يقضِ ما أمره", "ما كلّفه به من الطاعات والواجبات في نفسه وماله."], ["إلى طعامه", "كيف قدّر ودبّر له."], ["حبّاً وعنباً", "الحب: الحنطة والشعير، والعنب هو المعروف."], ["وقضباً", "القتّ الرطب، يُقضب أي يُقطع مرة بعد مرة."], ["وحدائق غُلباً", "كثيرة الأشجار ملتفّتها."], ["وفاكهة وأبّاً", "ما يُتفكّه به من سائر الفواكه، والأبّ ما ترعاه البهائم."], ["متاعاً لكم ولأنعامكم", "منفعة لكم ولأنعامكم من الإبل والبقر والغنم."]], "m": "بعدما عاتب الرب تبارك وتعالى رسوله على انشغاله بأولئك المشركين وإعراضه عن ابن أم مكتوم، جرّد شخصاً منهم غير معلوم، والمراد كل كافر متكبّر مثلهم، فقال: قُتل الإنسان الكافر، ما الذي حمله على الكفر والكبر؟ فلينظر من أي شيء خلقه ربه الذي يكفر به؟ إنه خلقه من نطفة قذرة، فقدّره أطواراً: نطفة فعلقة فمضغة، أفمن كان هذا حاله يليق به أن يكفر ويتكبّر ويستغني عن الله؟ ثم يسّر له طريق الخروج من بطن أمه، ولولا ذلك ما خرج، ثم أماته بدون استشارته، فهيّأ له من يقبره، ثم إذا شاء أنشره. كلا، أما يصحو هذا المغرور؟ لم يقضِ ما أمره به من الإيمان والطاعة. فلينظر هذا الإنسان إلى طعامه الذي حياته متوقّفة عليه كيف يتم له بتقدير الله وتدبيره، لعله يذكر فيشكر: إنا صببنا الماء صبّاً، ثم شققنا الأرض شقّاً، فأنبتنا فيها حبّاً كالبُرّ والشعير، وعنباً يأكله رطباً ويابساً، وقضباً هو علف البهائم، وزيتوناً يأكله حبّاً ويدّهن به، ونخلاً يأكل ثمره بسراً ورطباً وتمراً، وحدائق ملتفّة الأشجار، وفاكهة لكم، وأبّاً علفاً لدوابّكم، متاعاً لكم ولأنعامكم؛ فبأي وجه تكفر ربك أيها الإنسان؟", "h": ["بيان مظاهر قدرة الله وعلمه وحكمته، وهي مقتضية للإيمان به وبآياته ورسوله ولقائه.", "الاستدلال بالصنعة على الصانع، وأن أثر الشيء يدلّ عليه، ولذا يُتعجّب من كفر الكافر بربه وهو خلقه ورزقه وكلأ حياته وحفظ وجوده إلى أجله.", "بيان أن الإنسان لا يزال مقصّراً في شكر ربه ولو صام الدهر كله وصلّى في كل لحظة من لحظاته."], "k": "«فلينظر الإنسان إلى طعامه»… قبل أن آكل، فلأنظر: كم يداً وكم مطراً حتى وصل إليّ؟"}, {"lbl": "الآيات ٣٣ – ٤٢", "q": "فَإِذَا جَآءَتِ ٱلصَّآخَّةُ ﴿٣٣﴾ يَوۡمَ يَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِيهِ ﴿٣٤﴾ وَأُمِّهِۦ وَأَبِيهِ ﴿٣٥﴾ وَصَٰحِبَتِهِۦ وَبَنِيهِ ﴿٣٦﴾ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُمۡ يَوۡمَئِذٖ شَأۡنٞ يُغۡنِيهِ ﴿٣٧﴾ وُجُوهٞ يَوۡمَئِذٖ مُّسۡفِرَةٞ ﴿٣٨﴾ ضَاحِكَةٞ مُّسۡتَبۡشِرَةٞ ﴿٣٩﴾ وَوُجُوهٞ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةٞ ﴿٤٠﴾ تَرۡهَقُهَا قَتَرَةٌ ﴿٤١﴾ أُوْلَـٰٓئِكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ ﴿٤٢﴾", "w": [["فإذا جاءت الصاخّة", "النفخة الثانية."], ["وصاحبته", "زوجته."], ["شأن يغنيه", "حال وأمر يغنيه عن السؤال عن غيره."], ["مسفرة", "مضيئة مشرقة."], ["عليها غبرة", "غبار."], ["ترهقها قترة", "تغشاها ظلمة من سواد."], ["الكفرة الفجرة", "الجامعون بين الكفر والفجور."]], "m": "بعدما بيّن تعالى بداية أمر الإنسان في حياته ومعاشه، ذكر معاده ومآله: فإذا جاءت الصاخّة، وهي القيامة، ولعل تسميتها بذلك نظراً إلى نفخة الصور التي تصخّ الآذان، أي تصيبها بالصمم لشدتها، يوم يفرّ المرء من أخيه وأمه وأبيه وزوجته وبنيه، وهؤلاء أقرب الناس إليه، ومع هذا يفرّ عنهم خشية أن يطالبوه بحق لهم عليه، لكل امرئ منهم يومئذ حال وأمر يغنيه عن السؤال عن غيره ولو كان أقرب قريب. وقد سألت عائشة رضي الله عنها رسول الله ﷺ: كيف يُحشر الرجال؟ قال: «حفاة عراة»، ثم قالت: كيف يُحشر النساء؟ قال: «كذلك حفاة عراة»، قالت: واسوأتاه من يوم القيامة! قال: «قد نزلت عليّ آية لا يضرّك كان عليك ثياب أم لا»، قالت: أي آية؟ قال: «لكل امرئ منهم يومئذ شأن يغنيه». وجوه يومئذ مضيئة مشرقة، ضاحكة مستبشرة، وهي وجوه المؤمنين والمؤمنات أهل التقوى، مستبشرون بالقدوم على ربهم، ووجوه يومئذ عليها غبار، تغشاها ظلمة وسواد، أولئك هم الكفرة في الدنيا الفجرة فيها، الذين عاشوا على الكفر والفجور وماتوا على ذلك، والفجور هو الخروج عن طاعة الله بترك الواجبات وغشيان المحرّمات كالربا والزنا.", "h": ["بيان شدة الهول يوم القيامة، يدل عليه فرار المرء من أقربائه.", "خطر التبعات على العبد يوم القيامة، وهي الحقوق التي يُطالب بها العبد.", "شدة الهول والفزع تُنسي المرء يوم القيامة أن ينظر إلى عورة أحد من أهل الموقف.", "ثمرة الإيمان والتقوى تظهر في الموقف نوراً على الوجه وإشراقاً، وثمرة الكفر والفجور تظهر ظلمة وسواداً على الوجه وغباراً.", "تقرير عقيدة البعث والجزاء بعرض صورة من صورها."], "k": "«يوم يفرّ المرء من أخيه»… حقوق الناس تلاحقني حتى من أحبّهم؛ فأي حق عليّ أردّه اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (435, 81, 1, 29, 'سورة التكوير ١ – ٢٩', 'التكوير: علمت نفس ما أحضرت', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 435) = $j$[{"lbl": "الآيات ١ – ١٤", "q": "إِذَا ٱلشَّمۡسُ كُوِّرَتۡ ﴿١﴾ وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ ﴿٢﴾ وَإِذَا ٱلۡجِبَالُ سُيِّرَتۡ ﴿٣﴾ وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ ﴿٤﴾ وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ ﴿٥﴾ وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ ﴿٦﴾ وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ ﴿٧﴾ وَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ ﴿٨﴾ بِأَيِّ ذَنۢبٖ قُتِلَتۡ ﴿٩﴾ وَإِذَا ٱلصُّحُفُ نُشِرَتۡ ﴿١٠﴾ وَإِذَا ٱلسَّمَآءُ كُشِطَتۡ ﴿١١﴾ وَإِذَا ٱلۡجَحِيمُ سُعِّرَتۡ ﴿١٢﴾ وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ ﴿١٣﴾ عَلِمَتۡ نَفۡسٞ مَّآ أَحۡضَرَتۡ ﴿١٤﴾", "w": [["إذا", "ظرف لما ذُكر بعده من الأحداث الاثني عشر، وجوابها: علمت نفس ما أحضرت."], ["كُوّرت", "لُفّت وذهب نورها."], ["انكدرت", "انقضّت وتساقطت على الأرض."], ["سُيّرت", "ذُهب بها عن وجه الأرض فصارت هباءً منبثّاً."], ["وإذا العشار", "النوق الحوامل."], ["عُطّلت", "تُركت بلا راعٍ ولا حلب لما دهاهم من الأمر."], ["وإذا الوحوش حُشرت", "جُمعت وماتت."], ["وإذا البحار سُجّرت", "أُوقدت فصارت ناراً."], ["وإذا النفوس زُوّجت", "قُرنت بأجسادها، ثم بقرنائها وأمثالها في الخير والشر."], ["وإذا الموءودة", "البنت تُدفن حيّة خوف العار أو الحاجة."], ["سُئلت", "تبكيتاً لقاتلها."], ["بأي ذنب قُتلت", "بلا ذنب."], ["وإذا الصحف نُشرت", "صحف الأعمال فُتحت وبُسطت."], ["وإذا السماء كُشطت", "نُزعت من أماكنها كما يُنزع الجلد عن الشاة."], ["وإذا الجحيم سُعّرت", "أُجّجت وقُوّيت."], ["وإذا الجنة أُزلفت", "قُرّبت لأهلها ليدخلوها."], ["علمت نفس ما أحضرت", "علمت كل نفس وقت هذه المذكورات ما أحضرت من خير وشر."]], "m": "اشتملت هذه الآيات على اثني عشر حدثاً جللاً، ستة منها في الدنيا وستة في الآخرة، وكلها شرط لجواب واحد: علمت نفس ما أحضرت من خير وشر لتُجزى به. والسياق كله في تقرير عقيدة البعث والجزاء التي أنكرها المشركون، ولكونها مدار إصلاح الفرد والجماعة عُني القرآن بها عناية فائقة، ويدل لذلك أن فواتح سور كثيرة بما فيها من أقسام عظيمة هي لتقرير عقيدة البعث. والأحداث الستة التي تقع في الدنيا وهي مبادئ الآخرة: تكوير الشمس بلفّها وذهاب ضوئها، وانكدار النجوم بانقضاضها وسقوطها، وتسيير الجبال بذهابها واستحالتها إلى هباء، وتعطيل العشار، وهي النوق الحوامل، فلا تُحلب ولا تُركب لما أصاب أهلها من الهول، وكانت أفضل أموالهم وأحبّها إليهم، وحشر الوحوش وموتها، وتسجير البحار باشتعالها ناراً. والستة التي تقع في الآخرة: تزويج النفوس بقرنها بأجسادها بعد خلقها لها، ثم بأمثالها في الخير والشر، وسؤال الموءودة عن ذنبها الذي قُتلت به، ونشر صحف الأعمال، وكشط السماء ونزعها من أماكنها، وتسعير النار وتأجيجها، وإزلاف الجنة وتقريبها لأهل الإيمان والتقوى. وجواب ذلك كله: علمت نفس ما أحضرت من حسنات فتصير بها إلى الجنة، أو سيئات فتصير بها إلى النار.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان مفصّل عن مبادئ القيامة وخواتيمها.", "الترغيب في الإيمان والعمل الصالح، إذ بهما المصير إلى الجنة.", "الترهيب من الشرك والمعاصي، إذ بهما المصير إلى النار."], "k": "«علمت نفس ما أحضرت»… كل ما أعمله اليوم يُحضَر هناك؛ فماذا أحضرت حتى الآن؟"}, {"lbl": "الآيات ١٥ – ٢٩", "q": "فَلَآ أُقۡسِمُ بِٱلۡخُنَّسِ ﴿١٥﴾ ٱلۡجَوَارِ ٱلۡكُنَّسِ ﴿١٦﴾ وَٱلَّيۡلِ إِذَا عَسۡعَسَ ﴿١٧﴾ وَٱلصُّبۡحِ إِذَا تَنَفَّسَ ﴿١٨﴾ إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ ﴿١٩﴾ ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينٖ ﴿٢٠﴾ مُّطَاعٖ ثَمَّ أَمِينٖ ﴿٢١﴾ وَمَا صَاحِبُكُم بِمَجۡنُونٖ ﴿٢٢﴾ وَلَقَدۡ رَءَاهُ بِٱلۡأُفُقِ ٱلۡمُبِينِ ﴿٢٣﴾ وَمَا هُوَ عَلَى ٱلۡغَيۡبِ بِضَنِينٖ ﴿٢٤﴾ وَمَا هُوَ بِقَوۡلِ شَيۡطَٰنٖ رَّجِيمٖ ﴿٢٥﴾ فَأَيۡنَ تَذۡهَبُونَ ﴿٢٦﴾ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ﴿٢٧﴾ لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ ﴿٢٨﴾ وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ﴿٢٩﴾", "w": [["بالخُنّس", "التي تخنس بالنهار، أي تختفي وتظهر بالليل."], ["الجوار الكُنّس", "التي تجري أحياناً وتكنس في مكانسها، أي محل إيوائها، أحياناً أخرى، وهي الدراري الخمسة."], ["إذا عسعس", "أقبل أو أدبر، لأن عسعس من أسماء الأضداد."], ["إذا تنفّس", "امتدّ حتى يصير نهاراً بيّناً."], ["إنه", "القرآن."], ["لقول رسول كريم", "جبريل الكريم على الله تعالى، وأُضيف إليه القرآن لنزوله به."], ["ذي قوة", "شديد القوى."], ["عند ذي العرش مكين", "عند الله تعالى ذي مكانة."], ["مطاع ثَمّ أمين", "مطاع في السماء تطيعه الملائكة، أمين على الوحي."], ["وما صاحبكم بمجنون", "محمد ﷺ ليس به جنون."], ["ولقد رآه بالأفق المبين", "رأى النبي ﷺ جبريل على صورته التي خُلق عليها بالأفق."], ["وما هو على الغيب بضنين", "وما محمد ﷺ على ما غاب من الوحي ببخيل، وفي قراءة بالظاء: بمتّهم، فيُنقص منه ولا يعطيه كله."], ["وما هو بقول شيطان رجيم", "ليس القرآن بقول شيطان مسترق للسمع مرجوم."], ["فأين تذهبون", "فأي طريق تسلكون في إنكاركم القرآن وإعراضكم عنه؟"], ["إن هو إلا ذكر للعالمين", "ما القرآن إلا موعظة للإنس والجن."], ["أن يستقيم", "يتحرّى الحق ويعتقده ويعمل بمقتضاه."], ["وما تشاؤون إلا أن يشاء الله", "ومن شاء الاستقامة منكم فإنه لم يشأها إلا بعد أن شاءها الله له."]], "m": "لما قرّر تعالى عقيدة البعث والجزاء بوصف كامل لأحداثها، وكان الوصف من طريق الوحي، افتقر الموضوع إلى صحة الوحي والإيمان به، فإذا صحّ الوحي وآمن به العبد آمن بصحة البعث، ومن هنا أقسم تعالى بأعظم قسم على أن القرآن نزل به جبريل على محمد ﷺ، وأن ما يقوله هو كلام الله ووحيه، وليس هو بمجنون ولا بقول شيطان رجيم. فلا، ليس الأمر كما تدّعون، أقسم بالخنّس الجواري الكنّس، بكل ما يخنس ويجري ويكنس من الكواكب والدراري الخمسة، وبالليل إذا أقبل أو أدبر، وبالصبح إذا امتدّ ضوؤه فصار نهاراً بيّناً، على أن القرآن الذي يصف لكم البعث والجزاء هو قول رسول كريم، جبريل الكريم على ربه، ذي قوة لا يقدر إنس ولا جن على انتزاع ما عنده من الوحي، عند ذي العرش ذي مكانة، مطاع في السماوات، أمين على الوحي. وما صاحبكم محمد ﷺ بمجنون كما تقولون، ولقد رأى جبريل على صورته التي خلقه الله عليها وله ستمائة جناح، رآه بالأفق ناحية الشرق وقد سدّ الأفق كله. وما هو على الغيب بمظنون فيه التهمة بأن يزيد فيه أو ينقص، ولا ببخيل فيكتم منه شيئاً، وما هو بقول شيطان ممن يسترقون السمع ويلقونه إلى أوليائهم. فأين تذهبون؟ إنكار عليهم مسلكهم في تكذيب رسوله واتّهامه بالسحر، والقرآن بالشعر والكهانة. ما القرآن إلا ذكر للعالمين من الإنس والجن، يذكرون به خالقهم وحقّه عليهم، لمن شاء منكم أن يستقيم على منهاج الحق. ولما سمع أبو جهل هذه الآية قال: الأمر إلينا، إن شئنا استقمنا وإن شئنا لم نستقم، فأنزل الله: وما تشاؤون إلا أن يشاء الله رب العالمين، فمن شاء الاستقامة لم يشأها إلا بعد أن شاءها الله له، إذ مشيئة الله سابقة لمشيئة العبد في كل ما يشاؤه.", "h": ["مشروعية الإقسام بالله تعالى وأسمائه وصفاته.", "تقرير الوحي، وإثبات النبوة المحمدية.", "بيان صفات جبريل الكمالية: الأمانة، والقوة، وعلوّ المكانة، والطاعة، والكرم.", "براءة الرسول ﷺ مما اتّهمه به المشركون.", "بيان أن مشيئة الله سابقة لمشيئة العبد، فلا يقع في ملك الله تعالى إلا ما يريد."], "k": "«لمن شاء منكم أن يستقيم وما تشاؤون إلا أن يشاء الله»… أريد الاستقامة؛ فهل أطلبها منه كل يوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 435;
insert into public.tdb_cards(topic, i, body) select 435, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٤", "q": "إِذَا ٱلشَّمۡسُ كُوِّرَتۡ ﴿١﴾ وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ ﴿٢﴾ وَإِذَا ٱلۡجِبَالُ سُيِّرَتۡ ﴿٣﴾ وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ ﴿٤﴾ وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ ﴿٥﴾ وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ ﴿٦﴾ وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ ﴿٧﴾ وَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ ﴿٨﴾ بِأَيِّ ذَنۢبٖ قُتِلَتۡ ﴿٩﴾ وَإِذَا ٱلصُّحُفُ نُشِرَتۡ ﴿١٠﴾ وَإِذَا ٱلسَّمَآءُ كُشِطَتۡ ﴿١١﴾ وَإِذَا ٱلۡجَحِيمُ سُعِّرَتۡ ﴿١٢﴾ وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ ﴿١٣﴾ عَلِمَتۡ نَفۡسٞ مَّآ أَحۡضَرَتۡ ﴿١٤﴾", "w": [["إذا", "ظرف لما ذُكر بعده من الأحداث الاثني عشر، وجوابها: علمت نفس ما أحضرت."], ["كُوّرت", "لُفّت وذهب نورها."], ["انكدرت", "انقضّت وتساقطت على الأرض."], ["سُيّرت", "ذُهب بها عن وجه الأرض فصارت هباءً منبثّاً."], ["وإذا العشار", "النوق الحوامل."], ["عُطّلت", "تُركت بلا راعٍ ولا حلب لما دهاهم من الأمر."], ["وإذا الوحوش حُشرت", "جُمعت وماتت."], ["وإذا البحار سُجّرت", "أُوقدت فصارت ناراً."], ["وإذا النفوس زُوّجت", "قُرنت بأجسادها، ثم بقرنائها وأمثالها في الخير والشر."], ["وإذا الموءودة", "البنت تُدفن حيّة خوف العار أو الحاجة."], ["سُئلت", "تبكيتاً لقاتلها."], ["بأي ذنب قُتلت", "بلا ذنب."], ["وإذا الصحف نُشرت", "صحف الأعمال فُتحت وبُسطت."], ["وإذا السماء كُشطت", "نُزعت من أماكنها كما يُنزع الجلد عن الشاة."], ["وإذا الجحيم سُعّرت", "أُجّجت وقُوّيت."], ["وإذا الجنة أُزلفت", "قُرّبت لأهلها ليدخلوها."], ["علمت نفس ما أحضرت", "علمت كل نفس وقت هذه المذكورات ما أحضرت من خير وشر."]], "m": "اشتملت هذه الآيات على اثني عشر حدثاً جللاً، ستة منها في الدنيا وستة في الآخرة، وكلها شرط لجواب واحد: علمت نفس ما أحضرت من خير وشر لتُجزى به. والسياق كله في تقرير عقيدة البعث والجزاء التي أنكرها المشركون، ولكونها مدار إصلاح الفرد والجماعة عُني القرآن بها عناية فائقة، ويدل لذلك أن فواتح سور كثيرة بما فيها من أقسام عظيمة هي لتقرير عقيدة البعث. والأحداث الستة التي تقع في الدنيا وهي مبادئ الآخرة: تكوير الشمس بلفّها وذهاب ضوئها، وانكدار النجوم بانقضاضها وسقوطها، وتسيير الجبال بذهابها واستحالتها إلى هباء، وتعطيل العشار، وهي النوق الحوامل، فلا تُحلب ولا تُركب لما أصاب أهلها من الهول، وكانت أفضل أموالهم وأحبّها إليهم، وحشر الوحوش وموتها، وتسجير البحار باشتعالها ناراً. والستة التي تقع في الآخرة: تزويج النفوس بقرنها بأجسادها بعد خلقها لها، ثم بأمثالها في الخير والشر، وسؤال الموءودة عن ذنبها الذي قُتلت به، ونشر صحف الأعمال، وكشط السماء ونزعها من أماكنها، وتسعير النار وتأجيجها، وإزلاف الجنة وتقريبها لأهل الإيمان والتقوى. وجواب ذلك كله: علمت نفس ما أحضرت من حسنات فتصير بها إلى الجنة، أو سيئات فتصير بها إلى النار.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان مفصّل عن مبادئ القيامة وخواتيمها.", "الترغيب في الإيمان والعمل الصالح، إذ بهما المصير إلى الجنة.", "الترهيب من الشرك والمعاصي، إذ بهما المصير إلى النار."], "k": "«علمت نفس ما أحضرت»… كل ما أعمله اليوم يُحضَر هناك؛ فماذا أحضرت حتى الآن؟"}, {"lbl": "الآيات ١٥ – ٢٩", "q": "فَلَآ أُقۡسِمُ بِٱلۡخُنَّسِ ﴿١٥﴾ ٱلۡجَوَارِ ٱلۡكُنَّسِ ﴿١٦﴾ وَٱلَّيۡلِ إِذَا عَسۡعَسَ ﴿١٧﴾ وَٱلصُّبۡحِ إِذَا تَنَفَّسَ ﴿١٨﴾ إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ ﴿١٩﴾ ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينٖ ﴿٢٠﴾ مُّطَاعٖ ثَمَّ أَمِينٖ ﴿٢١﴾ وَمَا صَاحِبُكُم بِمَجۡنُونٖ ﴿٢٢﴾ وَلَقَدۡ رَءَاهُ بِٱلۡأُفُقِ ٱلۡمُبِينِ ﴿٢٣﴾ وَمَا هُوَ عَلَى ٱلۡغَيۡبِ بِضَنِينٖ ﴿٢٤﴾ وَمَا هُوَ بِقَوۡلِ شَيۡطَٰنٖ رَّجِيمٖ ﴿٢٥﴾ فَأَيۡنَ تَذۡهَبُونَ ﴿٢٦﴾ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ﴿٢٧﴾ لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ ﴿٢٨﴾ وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ﴿٢٩﴾", "w": [["بالخُنّس", "التي تخنس بالنهار، أي تختفي وتظهر بالليل."], ["الجوار الكُنّس", "التي تجري أحياناً وتكنس في مكانسها، أي محل إيوائها، أحياناً أخرى، وهي الدراري الخمسة."], ["إذا عسعس", "أقبل أو أدبر، لأن عسعس من أسماء الأضداد."], ["إذا تنفّس", "امتدّ حتى يصير نهاراً بيّناً."], ["إنه", "القرآن."], ["لقول رسول كريم", "جبريل الكريم على الله تعالى، وأُضيف إليه القرآن لنزوله به."], ["ذي قوة", "شديد القوى."], ["عند ذي العرش مكين", "عند الله تعالى ذي مكانة."], ["مطاع ثَمّ أمين", "مطاع في السماء تطيعه الملائكة، أمين على الوحي."], ["وما صاحبكم بمجنون", "محمد ﷺ ليس به جنون."], ["ولقد رآه بالأفق المبين", "رأى النبي ﷺ جبريل على صورته التي خُلق عليها بالأفق."], ["وما هو على الغيب بضنين", "وما محمد ﷺ على ما غاب من الوحي ببخيل، وفي قراءة بالظاء: بمتّهم، فيُنقص منه ولا يعطيه كله."], ["وما هو بقول شيطان رجيم", "ليس القرآن بقول شيطان مسترق للسمع مرجوم."], ["فأين تذهبون", "فأي طريق تسلكون في إنكاركم القرآن وإعراضكم عنه؟"], ["إن هو إلا ذكر للعالمين", "ما القرآن إلا موعظة للإنس والجن."], ["أن يستقيم", "يتحرّى الحق ويعتقده ويعمل بمقتضاه."], ["وما تشاؤون إلا أن يشاء الله", "ومن شاء الاستقامة منكم فإنه لم يشأها إلا بعد أن شاءها الله له."]], "m": "لما قرّر تعالى عقيدة البعث والجزاء بوصف كامل لأحداثها، وكان الوصف من طريق الوحي، افتقر الموضوع إلى صحة الوحي والإيمان به، فإذا صحّ الوحي وآمن به العبد آمن بصحة البعث، ومن هنا أقسم تعالى بأعظم قسم على أن القرآن نزل به جبريل على محمد ﷺ، وأن ما يقوله هو كلام الله ووحيه، وليس هو بمجنون ولا بقول شيطان رجيم. فلا، ليس الأمر كما تدّعون، أقسم بالخنّس الجواري الكنّس، بكل ما يخنس ويجري ويكنس من الكواكب والدراري الخمسة، وبالليل إذا أقبل أو أدبر، وبالصبح إذا امتدّ ضوؤه فصار نهاراً بيّناً، على أن القرآن الذي يصف لكم البعث والجزاء هو قول رسول كريم، جبريل الكريم على ربه، ذي قوة لا يقدر إنس ولا جن على انتزاع ما عنده من الوحي، عند ذي العرش ذي مكانة، مطاع في السماوات، أمين على الوحي. وما صاحبكم محمد ﷺ بمجنون كما تقولون، ولقد رأى جبريل على صورته التي خلقه الله عليها وله ستمائة جناح، رآه بالأفق ناحية الشرق وقد سدّ الأفق كله. وما هو على الغيب بمظنون فيه التهمة بأن يزيد فيه أو ينقص، ولا ببخيل فيكتم منه شيئاً، وما هو بقول شيطان ممن يسترقون السمع ويلقونه إلى أوليائهم. فأين تذهبون؟ إنكار عليهم مسلكهم في تكذيب رسوله واتّهامه بالسحر، والقرآن بالشعر والكهانة. ما القرآن إلا ذكر للعالمين من الإنس والجن، يذكرون به خالقهم وحقّه عليهم، لمن شاء منكم أن يستقيم على منهاج الحق. ولما سمع أبو جهل هذه الآية قال: الأمر إلينا، إن شئنا استقمنا وإن شئنا لم نستقم، فأنزل الله: وما تشاؤون إلا أن يشاء الله رب العالمين، فمن شاء الاستقامة لم يشأها إلا بعد أن شاءها الله له، إذ مشيئة الله سابقة لمشيئة العبد في كل ما يشاؤه.", "h": ["مشروعية الإقسام بالله تعالى وأسمائه وصفاته.", "تقرير الوحي، وإثبات النبوة المحمدية.", "بيان صفات جبريل الكمالية: الأمانة، والقوة، وعلوّ المكانة، والطاعة، والكرم.", "براءة الرسول ﷺ مما اتّهمه به المشركون.", "بيان أن مشيئة الله سابقة لمشيئة العبد، فلا يقع في ملك الله تعالى إلا ما يريد."], "k": "«لمن شاء منكم أن يستقيم وما تشاؤون إلا أن يشاء الله»… أريد الاستقامة؛ فهل أطلبها منه كل يوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (436, 82, 1, 19, 'سورة الانفطار ١ – ١٩', 'الانفطار: ما غرّك بربك الكريم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 436) = $j$[{"lbl": "الآيات ١ – ١٢", "q": "إِذَا ٱلسَّمَآءُ ٱنفَطَرَتۡ ﴿١﴾ وَإِذَا ٱلۡكَوَاكِبُ ٱنتَثَرَتۡ ﴿٢﴾ وَإِذَا ٱلۡبِحَارُ فُجِّرَتۡ ﴿٣﴾ وَإِذَا ٱلۡقُبُورُ بُعۡثِرَتۡ ﴿٤﴾ عَلِمَتۡ نَفۡسٞ مَّا قَدَّمَتۡ وَأَخَّرَتۡ ﴿٥﴾ يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ ﴿٦﴾ ٱلَّذِي خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ ﴿٧﴾ فِيٓ أَيِّ صُورَةٖ مَّا شَآءَ رَكَّبَكَ ﴿٨﴾ كَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّينِ ﴿٩﴾ وَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ ﴿١٠﴾ كِرَامٗا كَٰتِبِينَ ﴿١١﴾ يَعۡلَمُونَ مَا تَفۡعَلُونَ ﴿١٢﴾", "w": [["إذا السماء انفطرت", "انشقّت."], ["وإذا الكواكب انتثرت", "تساقطت."], ["وإذا البحار فُجّرت", "اختلطت ببعضها وأصبحت بحراً واحداً، الملح والعذب سواء."], ["وإذا القبور بُعثرت", "قُلب ترابها وبُعث موتاها."], ["علمت نفس ما قدّمت وأخّرت", "من الأعمال، وما أخّرت منها فلم تعمله، وذلك عند قراءتها كتاب أعمالها."], ["ما غرّك بربك", "أي شيء خدعك وجرّأك على عصيانه؟"], ["الذي خلقك", "بعد أن لم تكن."], ["فسوّاك", "جعلك مستوي الخلقة سالم الأعضاء."], ["فعدلك", "جعلك معتدل الخلق متناسب الأعضاء."], ["كلا بل تكذّبون بالدين", "ليس الكرم هو الذي غرّه، وإنما جرّأه على المعاصي تكذيبه بالجزاء بعد البعث."], ["وإن عليكم لحافظين", "ملائكة كراماً على الله، حافظين لأعمالكم."], ["كاتبين", "لأعمالكم، خيرها وشرّها."]], "m": "إذا السماء انشقّت، وإذا الكواكب تساقطت، وإذا البحار اختلط ماؤها ملحها بعذبها لانكسار الحاجز الذي كان يفصلهما بزلزلة الأرض، وإذا القبور قُلبت وأُخرج ما فيها من الأموات؛ إذا حصلت هذه الأحداث الأربعة، ثلاثة منها في الدنيا بالنفخة الأولى، والرابع في الآخرة بعد النفخة الثانية، علمت كل نفس مكلّفة ما قدّمت من أعمال حسنة أو سيئة، وما أخّرت من أعمال لحقتها بعدها مما سنّته من سنن الهدى أو الضلال، لحديث: «من سنّ سنة حسنة فله أجرها وأجر من عمل بها…، ومن سنّ سنة سيئة فعليه وزرها ووزر من عمل بها»، وهذا العلم يحصل للنفس أولاً مجملاً عند ابيضاض الوجوه واسودادها، ومفصّلاً عندما تقرأ كتاب أعمالها. يا أيها الإنسان الكافر والفاجر، أي شيء خدعك وجرّأك على الكفر بربك الكريم وعصيانه، وهو القادر على مؤاخذتك ساعة كفرت به أو عصيته؟ أليس هو الذي خلقك فسوّى خلقك وعدّل أعضاءك وناسب بين أجزائك، في أي صورة ما شاء ركّبك، إن شاء بيّضك أو سوّدك، طوّلك أو قصّرك، جعلك ذكراً أو أنثى؟ هل هناك من يصرفه عما أراد لك؟ لا أحد، إذاً كيف يسوغ لك الكفر به وعصيانه؟ كلا، ما غرّك كرم الله ولا حلمه، بل تكذيبكم بالبعث والجزاء هو الذي جرّأكم على الكفر والظلم والإجرام، وإن عليكم لملائكة حافظين يحفظون عليكم أعمالكم ويكتبونها في صحائفكم، يعلمون ما تفعلون في السر والعلن، وسوف تفاجؤون يوم تعلم نفس ما قدّمت وأخّرت بصحائف أعمالكم وقد حوت كل أعمالكم لم تغادر صغيرة ولا كبيرة.", "h": ["بيان أحداث تسبق يوم البعث، وذلك في نفخة الفناء، وأما النفخة الثانية، نفخة البعث، فتُجمع فيها الخلائق ويجري الحساب، فتُعطى الصحف وتُوزن الأعمال ويُنصب الصراط، ثم إلى جنة أو إلى نار.", "التحذير من السنة السيئة يتركها المرء بعده، فإن أوزارها تُكتب عليه وهو في قبره.", "التحذير من الغرور والانخداع بعامل الشيطان من الإنس أو الجن.", "التحذير من التكذيب بالبعث والجزاء، فإنه أكبر عامل من عوامل الشر والفساد في الدنيا، وأكبر موجب للعذاب يوم القيامة.", "تقرير عقيدة كتابة الأعمال حسنها وسيئها والحساب بمقتضاها يوم القيامة، بواسطة ملكين كريمين على كل إنسان مكلّف، لحديث الصحيح: «يتعاقبون فيكم ملائكة بالليل وملائكة بالنهار»."], "k": "«يا أيها الإنسان ما غرّك بربك الكريم»… كرمه وحلمه عليّ، هل جعلاني أستحيي أم أتجرّأ؟"}, {"lbl": "الآيات ١٣ – ١٩", "q": "إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ ﴿١٣﴾ وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمٖ ﴿١٤﴾ يَصۡلَوۡنَهَا يَوۡمَ ٱلدِّينِ ﴿١٥﴾ وَمَا هُمۡ عَنۡهَا بِغَآئِبِينَ ﴿١٦﴾ وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ ﴿١٧﴾ ثُمَّ مَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ ﴿١٨﴾ يَوۡمَ لَا تَمۡلِكُ نَفۡسٞ لِّنَفۡسٖ شَيۡـٔٗاۖ وَٱلۡأَمۡرُ يَوۡمَئِذٖ لِّلَّهِ ﴿١٩﴾", "w": [["إن الأبرار", "المؤمنين المتقين الصادقين."], ["وإن الفجّار", "الكافرين والخارجين عن طاعة الله ورسوله."], ["يصلونها يوم الدين", "يدخلونها ويقاسون حرّها يوم الجزاء، وهو يوم القيامة."], ["وما هم عنها بغائبين", "بمخرجين."], ["وما أدراك ما يوم الدين", "أي شيء جعلك تدري لولا أنّا علّمناك؟"], ["لا تملك نفس لنفس شيئاً", "من المنفعة وإن قلّت."], ["والأمر يومئذ لله", "لا لغيره، ولا تنفع الشفاعة عنده إلا بإذنه."]], "m": "تقدّم أن العرض على الله حق، وأن المجازاة بحسب الأعمال المحفوظة المحصاة بواسطة الملائكة الكرام، وأن الناس يومئذ كما هم اليوم: مؤمن بارّ وكافر فاجر. فبيّن تعالى جزاء الكل مقروناً بعلّة الحكم: إن الأبرار لفي نعيم في دار السلام لبرّهم، وهو طاعتهم لله في صدق كامل، وإن الفجار لفي نار ذات جحيم لفجورهم، وهو كفرهم وخروجهم عن طاعة ربهم، يدخلونها ويقاسون حرّها يوم الجزاء الذي كفروا به فأدّى بهم إلى الفجور، وما هم عنها بمخرجين إذا دخلوها. وما أدراك يا رسولنا ما يوم الدين؟ إنه يوم عظيم يقوم فيه الناس لرب العالمين، ثم ما أدراك ما يوم الدين؟ تأكيد لعظم شأنه، يوم لا تملك نفس لنفس شيئاً من المنفعة، حيث يكون الأمر كله فيه لله وحده، ولا تنفع فيه الشفاعة إلا بإذنه، وما للظالمين فيه من شفيع ولا حميم.", "h": ["بيان حكم الله في أهل الموقف، إذ هم ما بين بارّ صادق فهو في نعيم، وفاجر كافر فهو في جحيم.", "بيان عظم شأن يوم الدين، وأنه يوم عظيم.", "بيان أن الناس في يوم الدين لا تنفعهم شفاعة ولا خلّة، إذ لا يشفع أحد إلا بإذن الله، والكافرون هم الظالمون، وما للظالمين من حميم ولا شفيع يُطاع."], "k": "«يوم لا تملك نفس لنفس شيئاً»… من أعتمد عليهم اليوم لن يملكوا لي شيئاً؛ فعلى من أعتمد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 436;
insert into public.tdb_cards(topic, i, body) select 436, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٢", "q": "إِذَا ٱلسَّمَآءُ ٱنفَطَرَتۡ ﴿١﴾ وَإِذَا ٱلۡكَوَاكِبُ ٱنتَثَرَتۡ ﴿٢﴾ وَإِذَا ٱلۡبِحَارُ فُجِّرَتۡ ﴿٣﴾ وَإِذَا ٱلۡقُبُورُ بُعۡثِرَتۡ ﴿٤﴾ عَلِمَتۡ نَفۡسٞ مَّا قَدَّمَتۡ وَأَخَّرَتۡ ﴿٥﴾ يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ ﴿٦﴾ ٱلَّذِي خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ ﴿٧﴾ فِيٓ أَيِّ صُورَةٖ مَّا شَآءَ رَكَّبَكَ ﴿٨﴾ كَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّينِ ﴿٩﴾ وَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ ﴿١٠﴾ كِرَامٗا كَٰتِبِينَ ﴿١١﴾ يَعۡلَمُونَ مَا تَفۡعَلُونَ ﴿١٢﴾", "w": [["إذا السماء انفطرت", "انشقّت."], ["وإذا الكواكب انتثرت", "تساقطت."], ["وإذا البحار فُجّرت", "اختلطت ببعضها وأصبحت بحراً واحداً، الملح والعذب سواء."], ["وإذا القبور بُعثرت", "قُلب ترابها وبُعث موتاها."], ["علمت نفس ما قدّمت وأخّرت", "من الأعمال، وما أخّرت منها فلم تعمله، وذلك عند قراءتها كتاب أعمالها."], ["ما غرّك بربك", "أي شيء خدعك وجرّأك على عصيانه؟"], ["الذي خلقك", "بعد أن لم تكن."], ["فسوّاك", "جعلك مستوي الخلقة سالم الأعضاء."], ["فعدلك", "جعلك معتدل الخلق متناسب الأعضاء."], ["كلا بل تكذّبون بالدين", "ليس الكرم هو الذي غرّه، وإنما جرّأه على المعاصي تكذيبه بالجزاء بعد البعث."], ["وإن عليكم لحافظين", "ملائكة كراماً على الله، حافظين لأعمالكم."], ["كاتبين", "لأعمالكم، خيرها وشرّها."]], "m": "إذا السماء انشقّت، وإذا الكواكب تساقطت، وإذا البحار اختلط ماؤها ملحها بعذبها لانكسار الحاجز الذي كان يفصلهما بزلزلة الأرض، وإذا القبور قُلبت وأُخرج ما فيها من الأموات؛ إذا حصلت هذه الأحداث الأربعة، ثلاثة منها في الدنيا بالنفخة الأولى، والرابع في الآخرة بعد النفخة الثانية، علمت كل نفس مكلّفة ما قدّمت من أعمال حسنة أو سيئة، وما أخّرت من أعمال لحقتها بعدها مما سنّته من سنن الهدى أو الضلال، لحديث: «من سنّ سنة حسنة فله أجرها وأجر من عمل بها…، ومن سنّ سنة سيئة فعليه وزرها ووزر من عمل بها»، وهذا العلم يحصل للنفس أولاً مجملاً عند ابيضاض الوجوه واسودادها، ومفصّلاً عندما تقرأ كتاب أعمالها. يا أيها الإنسان الكافر والفاجر، أي شيء خدعك وجرّأك على الكفر بربك الكريم وعصيانه، وهو القادر على مؤاخذتك ساعة كفرت به أو عصيته؟ أليس هو الذي خلقك فسوّى خلقك وعدّل أعضاءك وناسب بين أجزائك، في أي صورة ما شاء ركّبك، إن شاء بيّضك أو سوّدك، طوّلك أو قصّرك، جعلك ذكراً أو أنثى؟ هل هناك من يصرفه عما أراد لك؟ لا أحد، إذاً كيف يسوغ لك الكفر به وعصيانه؟ كلا، ما غرّك كرم الله ولا حلمه، بل تكذيبكم بالبعث والجزاء هو الذي جرّأكم على الكفر والظلم والإجرام، وإن عليكم لملائكة حافظين يحفظون عليكم أعمالكم ويكتبونها في صحائفكم، يعلمون ما تفعلون في السر والعلن، وسوف تفاجؤون يوم تعلم نفس ما قدّمت وأخّرت بصحائف أعمالكم وقد حوت كل أعمالكم لم تغادر صغيرة ولا كبيرة.", "h": ["بيان أحداث تسبق يوم البعث، وذلك في نفخة الفناء، وأما النفخة الثانية، نفخة البعث، فتُجمع فيها الخلائق ويجري الحساب، فتُعطى الصحف وتُوزن الأعمال ويُنصب الصراط، ثم إلى جنة أو إلى نار.", "التحذير من السنة السيئة يتركها المرء بعده، فإن أوزارها تُكتب عليه وهو في قبره.", "التحذير من الغرور والانخداع بعامل الشيطان من الإنس أو الجن.", "التحذير من التكذيب بالبعث والجزاء، فإنه أكبر عامل من عوامل الشر والفساد في الدنيا، وأكبر موجب للعذاب يوم القيامة.", "تقرير عقيدة كتابة الأعمال حسنها وسيئها والحساب بمقتضاها يوم القيامة، بواسطة ملكين كريمين على كل إنسان مكلّف، لحديث الصحيح: «يتعاقبون فيكم ملائكة بالليل وملائكة بالنهار»."], "k": "«يا أيها الإنسان ما غرّك بربك الكريم»… كرمه وحلمه عليّ، هل جعلاني أستحيي أم أتجرّأ؟"}, {"lbl": "الآيات ١٣ – ١٩", "q": "إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ ﴿١٣﴾ وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمٖ ﴿١٤﴾ يَصۡلَوۡنَهَا يَوۡمَ ٱلدِّينِ ﴿١٥﴾ وَمَا هُمۡ عَنۡهَا بِغَآئِبِينَ ﴿١٦﴾ وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ ﴿١٧﴾ ثُمَّ مَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ ﴿١٨﴾ يَوۡمَ لَا تَمۡلِكُ نَفۡسٞ لِّنَفۡسٖ شَيۡـٔٗاۖ وَٱلۡأَمۡرُ يَوۡمَئِذٖ لِّلَّهِ ﴿١٩﴾", "w": [["إن الأبرار", "المؤمنين المتقين الصادقين."], ["وإن الفجّار", "الكافرين والخارجين عن طاعة الله ورسوله."], ["يصلونها يوم الدين", "يدخلونها ويقاسون حرّها يوم الجزاء، وهو يوم القيامة."], ["وما هم عنها بغائبين", "بمخرجين."], ["وما أدراك ما يوم الدين", "أي شيء جعلك تدري لولا أنّا علّمناك؟"], ["لا تملك نفس لنفس شيئاً", "من المنفعة وإن قلّت."], ["والأمر يومئذ لله", "لا لغيره، ولا تنفع الشفاعة عنده إلا بإذنه."]], "m": "تقدّم أن العرض على الله حق، وأن المجازاة بحسب الأعمال المحفوظة المحصاة بواسطة الملائكة الكرام، وأن الناس يومئذ كما هم اليوم: مؤمن بارّ وكافر فاجر. فبيّن تعالى جزاء الكل مقروناً بعلّة الحكم: إن الأبرار لفي نعيم في دار السلام لبرّهم، وهو طاعتهم لله في صدق كامل، وإن الفجار لفي نار ذات جحيم لفجورهم، وهو كفرهم وخروجهم عن طاعة ربهم، يدخلونها ويقاسون حرّها يوم الجزاء الذي كفروا به فأدّى بهم إلى الفجور، وما هم عنها بمخرجين إذا دخلوها. وما أدراك يا رسولنا ما يوم الدين؟ إنه يوم عظيم يقوم فيه الناس لرب العالمين، ثم ما أدراك ما يوم الدين؟ تأكيد لعظم شأنه، يوم لا تملك نفس لنفس شيئاً من المنفعة، حيث يكون الأمر كله فيه لله وحده، ولا تنفع فيه الشفاعة إلا بإذنه، وما للظالمين فيه من شفيع ولا حميم.", "h": ["بيان حكم الله في أهل الموقف، إذ هم ما بين بارّ صادق فهو في نعيم، وفاجر كافر فهو في جحيم.", "بيان عظم شأن يوم الدين، وأنه يوم عظيم.", "بيان أن الناس في يوم الدين لا تنفعهم شفاعة ولا خلّة، إذ لا يشفع أحد إلا بإذن الله، والكافرون هم الظالمون، وما للظالمين من حميم ولا شفيع يُطاع."], "k": "«يوم لا تملك نفس لنفس شيئاً»… من أعتمد عليهم اليوم لن يملكوا لي شيئاً؛ فعلى من أعتمد؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (437, 83, 1, 36, 'سورة المطففين ١ – ٣٦', 'المطففين: وفي ذلك فليتنافس المتنافسون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 437) = $j$[{"lbl": "الآيات ١ – ٦", "q": "وَيۡلٞ لِّلۡمُطَفِّفِينَ ﴿١﴾ ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ ﴿٢﴾ وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ ﴿٣﴾ أَلَا يَظُنُّ أُوْلَـٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ ﴿٤﴾ لِيَوۡمٍ عَظِيمٖ ﴿٥﴾ يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ ﴿٦﴾", "w": [["ويل", "كلمة عذاب، ووادٍ في جهنم."], ["للمطفّفين", "المنقصين في كيل أو وزن، الباخسين فيهما."], ["يستوفون", "الكيل."], ["وإذا كالوهم", "كالوا لهم."], ["أو وزنوهم", "وزنوا لهم."], ["يُخسرون", "ينقصون الكيل أو الوزن."], ["ألا", "استفهام توبيخي إنكاري."], ["يظن", "يتيقّن."], ["ليوم عظيم", "يوم القيامة، لما فيه من أهوال وعظائم الأمور."], ["يوم يقوم الناس", "من قبورهم."], ["لرب العالمين", "يقومون خاشعين ذليلين ينتظرون حكم الله فيهم."]], "m": "هذه الآيات الأولى من سورة المطففين، قال أحد الأنصار رضي الله عنه: كنا أسوأ الناس كيلاً، حتى إنه ليكون لأحدنا مكيالان: مكيال يشتري به وآخر يبيع به، فما إن نزلت فينا «ويل للمطفّفين» حتى أصبحنا أحسن الناس كيلاً ووزناً. يتوعّد سبحانه بوادٍ في جهنم يسيل بصديد أهل النار الذين يبخسون الناس الكيل والميزان، ويبيّنهم تعالى بقوله: الذين إذا اشتروا من الناس يأخذون كيلهم وافياً، وكذا إذا وزنوا، وإذا كالوا لهم أو وزنوا لهم ينقصون. قال تعالى موبّخاً لهم: ألا يتيقّن أولئك المطفّفون أنهم مبعوثون من قبورهم ليوم عظيم، هو يوم الجزاء والحساب، يوم يقوم الناس لرب العالمين خاشعين ذليلين ينتظرون حكمه فيهم، ويطول بهم الموقف حتى إن أحدهم ليلجمه العرق إلجاماً.", "h": ["حرمة التطفيف في الكيل والوزن، وهو أن يأخذ زائداً ولو قلّ، أو ينقص عامداً شيئاً ولو قلّ، وما كان بغير عمد ولا قصد فإنه مما يُعفى عنه.", "التذكير بالبعث والجزاء وتقريرهما.", "عظم يوم القيامة، يوم يقوم الناس لرب العالمين ليحكم بينهم ويجزي كلاً بعمله خيراً أو شراً."], "k": "«ويل للمطفّفين»… قد لا أزن بميزان، لكن هل أطلب حقي كاملاً وأعطي حقوق الناس ناقصة؟"}, {"lbl": "الآيات ٧ – ١٧", "q": "كَلَّآ إِنَّ كِتَٰبَ ٱلۡفُجَّارِ لَفِي سِجِّينٖ ﴿٧﴾ وَمَآ أَدۡرَىٰكَ مَا سِجِّينٞ ﴿٨﴾ كِتَٰبٞ مَّرۡقُومٞ ﴿٩﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿١٠﴾ ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ ٱلدِّينِ ﴿١١﴾ وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعۡتَدٍ أَثِيمٍ ﴿١٢﴾ إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿١٣﴾ كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ ﴿١٤﴾ كَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذٖ لَّمَحۡجُوبُونَ ﴿١٥﴾ ثُمَّ إِنَّهُمۡ لَصَالُواْ ٱلۡجَحِيمِ ﴿١٦﴾ ثُمَّ يُقَالُ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ ﴿١٧﴾", "w": [["كلا", "حقاً، وإن الأمر ليس كما يظن المطفّفون."], ["لفي سجّين", "سجّين ديوان الشر الذي دُوّنت فيه أعمال الشياطين والكفرة، وهو أيضاً موضع في أسفل الأرض السابعة، وبه أرواح الأشقياء عامة."], ["كتاب مرقوم", "مسطور بيّن الكتابة فيه أعمالهم."], ["يوم الدين", "يوم القيامة الذي هو يوم الحساب والجزاء."], ["كل معتدٍ", "ظالم مضيّع حقوق ربه وحقوق غيره."], ["أثيم", "منغمس في الآثام مكثر منها."], ["أساطير الأولين", "ما سطّره الأولون من القصص والأخبار التي لا تصح."], ["ران على قلوبهم", "غطّى قلوبهم وحجبها عن قبول الحق."], ["ما كانوا يكسبون", "من الذنوب والآثام."], ["لمحجوبون", "يُحال بينهم وبين رؤية الرب يوم القيامة."], ["لصالو الجحيم", "لداخلوها، محرقون معذّبون بها."], ["هذا الذي كنتم به تكذّبون", "يقال لهم توبيخاً وخزياً وهم في العذاب."]], "m": "ما زال السياق في التحذير من الظلم والفسق عن أوامر الرب: كلا، ليس الأمر كما يظن المطفّفون والباخسون للحقوق أنه لا دقّة في الحساب، وأن مثل هذا لا يُكتب ولا يُجزى به، حقاً إن كتاب الفجّار الظلمة الخارجين عن الشرع لفي سجّين، موضع في أسفل الخلق فيه أرواح الكافرين والظالمين وكتب أعمالهم، وما أدراك ما سجّين؟ تفخيم لشأنه، كتاب مسطور بيّن الكتابة. ويل يومئذ للمكذّبين بالله وآياته ولقائه، المكذّبين بيوم الدين، وما يكذّب به إلا كل معتدٍ ظالم متجاوز للحد، أثيم مرتكب للذنوب، إذا قُرئت عليه آيات الله تذكيراً له ردّها بقوله: أساطير الأولين، أي حكايات مسطّرة. كلا، ما الأمر كما يدّعون، وإنما غطّى قلوبهم أثر الذنوب والجرائم فحجبها عن معرفة الحق وقبوله. كلا إنهم عن ربهم يومئذ لمحجوبون، فلا يرونه ولا يرون كرامته، ثم إنهم لداخلو الجحيم ومصطلون بحرّها، ثم يقال لهم توبيخاً وخزياً: هذا العذاب الذي كنتم به في الدنيا تكذّبون حتى واصلتم كفركم وإجرامكم.", "h": ["بيان كتاب الفجّار وأنه في سجّين، وسجّين ديوان تُدوّن فيه سائر كتب الفجّار من أهل النار، وموضع أسفل الأرض السابعة مستودع لكتب أعمال الفجّار من كفار وفسّاق ولأرواحهم إلى يوم القيامة، ولفظ سجّين مشتق من السجن الذي هو الحبس.", "الوعيد الشديد للمكذّبين بالله وبآياته ولقائه.", "التحذير من مواصلة الذنوب وعدم التوبة منها، حيث يؤدّي ذلك بالعبد إلى أن يُحرم التوبة؛ ففي حديث أبي هريرة قال رسول الله ﷺ: «إذا أذنب العبد نُكت في قلبه نكتة سوداء، فإن تاب صُقل منها، فإن عاد عادت حتى تعظم في قلبه، فذلك الران الذي قال الله: كلا بل ران على قلوبهم ما كانوا يكسبون».", "تقرير رؤية الله تعالى في الآخرة، بدليل قوله: «إنهم عن ربهم يومئذ لمحجوبون» أي الأشقياء، إذاً فالسعداء غير محجوبين، فهم يرون ربهم.", "تقرير عقيدة البعث والجزاء."], "k": "«كلا بل ران على قلوبهم»… كل ذنب بلا توبة نكتة سوداء؛ فلأمسحها اليوم بالاستغفار قبل أن تتراكم."}, {"lbl": "الآيات ١٨ – ٢٨", "q": "كَلَّآ إِنَّ كِتَٰبَ ٱلۡأَبۡرَارِ لَفِي عِلِّيِّينَ ﴿١٨﴾ وَمَآ أَدۡرَىٰكَ مَا عِلِّيُّونَ ﴿١٩﴾ كِتَٰبٞ مَّرۡقُومٞ ﴿٢٠﴾ يَشۡهَدُهُ ٱلۡمُقَرَّبُونَ ﴿٢١﴾ إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٍ ﴿٢٢﴾ عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ ﴿٢٣﴾ تَعۡرِفُ فِي وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِيمِ ﴿٢٤﴾ يُسۡقَوۡنَ مِن رَّحِيقٖ مَّخۡتُومٍ ﴿٢٥﴾ خِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ ﴿٢٦﴾ وَمِزَاجُهُۥ مِن تَسۡنِيمٍ ﴿٢٧﴾ عَيۡنٗا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ ﴿٢٨﴾", "w": [["كتاب الأبرار", "كتاب أعمالهم، والأبرار المطيعون لله ولرسوله الصادقون."], ["لفي علّيّين", "في موضع يُسمّى علّيّين في أعلى الجنة."], ["كتاب مرقوم", "كتاب مرقوم بأمان من الله لصاحبه من النار يوم القيامة والفوز بالجنة."], ["يشهده المقرّبون", "يحضره المقرّبون من أهل كل سماء ويحفظونه."], ["إن الأبرار لفي نعيم", "إن الذين برّوا ربهم بطاعته بأداء الفرائض واجتناب النواهي لفي نعيم الجنة."], ["على الأرائك", "على الأسرّة ذات الحجال."], ["ينظرون", "ينظرون ما آتاهم ربهم من صنوف النعيم."], ["نضرة النعيم", "حُسنه وبريقه وتلألؤه."], ["من رحيق", "من خمر صرف خالصة لا غش فيها ولا دنس."], ["مختوم", "مختوم على إنائها لا يفكّ ختمه إلا هم."], ["ختامه مسك", "آخر شربها يفوح برائحة المسك."], ["وفي ذلك", "لا في غيره."], ["فليتنافس المتنافسون", "فليطلب بالطاعة والاستقامة الطالبون للنعيم المقيم."], ["ومزاجه من تسنيم", "ومزاج شرابهم من عين تجري من عالٍ تُسمّى التسنيم."], ["عيناً يشرب بها المقرّبون", "يشرب منها المقرّبون صرفاً، وتُمزج لأصحاب اليمين."]], "m": "بعد أن ذكر تعالى كتاب الفجّار وما خُتم له به، ذكر كتاب الأبرار: كلا، حقاً إن كتاب أعمال الأبرار، وهم المؤمنون الذين برّوا ربهم بطاعته وكانوا صادقين في ذلك، لفي علّيّين، وما أدراك يا رسولنا ما علّيّون؟ موضع في أعلى الجنة، كتاب مرقوم بأمان من الله لصاحبه من النار والفوز بالجنة، يحضره مقرّبو كل سماء ويحفظونه ويشهدون بما فيه. إن الأبرار لفي نعيم الجنة يوم القيامة، على الأسرّة ذات الحجال ينظرون باستحسان وإعجاب ملكهم الكبير الذي ملّكهم الله تعالى، تعرف في وجوههم حُسن النعيم وبريقه، يُسقون من خمر صافية لا دنس فيها، مختوم على أوانيها لا يفكّها إلا هم، آخر هذا الشراب يفوح برائحة المسك، وفي مثل هذا النعيم، لا في غيره من حطام الدنيا وشرابها وملكها الزائل، يجب أن يتنافس المتنافسون بالإيمان وصالح الأعمال بعد البعد عن الشرك وسيئ الأقوال وقبيح الأفعال. ومزاج ذلك الرحيق لأصحاب اليمين من عين تُسمّى التسنيم، ويشربها المقرّبون صرفاً خالصاً.", "h": ["الثناء على الأبرار وبيان ما أعدّ الله تعالى لهم، وهم المؤمنون المتقون الصادقون في ذلك.", "تقرير عقيدة البعث والجزاء بذكر ما يجري فيها.", "الترغيب في العمل الصالح للحصول على نعيم الجنة، لقوله تعالى: «وفي ذلك فليتنافس المتنافسون»."], "k": "«وفي ذلك فليتنافس المتنافسون»… فيمَ أنافس الناس اليوم؟ وهل يستحق ذلك التنافس؟"}, {"lbl": "الآيات ٢٩ – ٣٦", "q": "إِنَّ ٱلَّذِينَ أَجۡرَمُواْ كَانُواْ مِنَ ٱلَّذِينَ ءَامَنُواْ يَضۡحَكُونَ ﴿٢٩﴾ وَإِذَا مَرُّواْ بِهِمۡ يَتَغَامَزُونَ ﴿٣٠﴾ وَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ ﴿٣١﴾ وَإِذَا رَأَوۡهُمۡ قَالُوٓاْ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ ﴿٣٢﴾ وَمَآ أُرۡسِلُواْ عَلَيۡهِمۡ حَٰفِظِينَ ﴿٣٣﴾ فَٱلۡيَوۡمَ ٱلَّذِينَ ءَامَنُواْ مِنَ ٱلۡكُفَّارِ يَضۡحَكُونَ ﴿٣٤﴾ عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ ﴿٣٥﴾ هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُواْ يَفۡعَلُونَ ﴿٣٦﴾", "w": [["إن الذين أجرموا", "على أنفسهم بالشرك والمعاصي، كأبي جهل وأمية بن خلف وعقبة بن أبي معيط."], ["من الذين آمنوا", "كبلال وياسر وعمار وصهيب وخبيب."], ["يتغامزون", "يشيرون إلى المؤمنين بالجفن والحاجب استهزاءً بهم."], ["فكهين", "إذا رجعوا إلى ديارهم وأهليهم رجعوا فرحين معجبين بحالهم."], ["وإذا رأوهم", "وإذا رأى أولئك المؤمنين."], ["قالوا إن هؤلاء لضالّون", "يعنون أصحاب محمد ﷺ، بتركهم دينهم واتّخاذهم دين محمد الجديد."], ["وما أُرسلوا عليهم حافظين", "لم يكلّفهم الله بحفظ أعمالهم ورعاية أحوالهم، وإنما هم متطفّلون."], ["فاليوم", "يوم القيامة."], ["من الكفار يضحكون", "مما هم فيه من العذاب، حيث يرونهم وهم على أرائكهم."], ["هل ثُوّب الكفار ما كانوا يفعلون", "هل جُوزي الكفار بما كانوا يفعلون من الكفر والشر والفساد؟ والجواب: نعم."]], "m": "بعدما بيّن تعالى حال الأبرار في دار الأبرار، وحال المجرمين في دار العذاب، ذكر في خاتمة السورة ما أوجب للمجرمين النار وللمؤمنين الجنة، فذكر طرفاً من سلوك الفريقين: إن الذين أفسدوا أنفسهم بالشرك والشر، كأبي جهل والوليد بن المغيرة والعاص وغيرهم، كانوا من الذين آمنوا، كبلال وعمار وصهيب وخبيب وأضرابهم من فقراء المؤمنين، يضحكون استهزاءً بهم وسخرية، وإذا مرّوا بهم في شوارع مكة وحول المسجد الحرام يتغامزون، يشيرون إليهم بالجفن والحاجب على عادة المتكبّرين، وإذا رجعوا إلى أهلهم رجعوا ناعمين معجبين بحالهم، وإذا رأوا المؤمنين قالوا: إن هؤلاء لضالّون بتركهم دينهم واعتناق دين محمد. قال تعالى: وما أُرسلوا عليهم حافظين لأعمالهم وأحوالهم حتى يقولوا ما قالوا، وإنما هم متطفّلون. فاليوم، يوم القيامة، الذين آمنوا من الكفار يضحكون، على الأسرّة ذات الحجال ينظرون إلى الكفار وهم في النار ويضحكون منهم وهم يُعذّبون، ولا عجب في كيفية رؤيتهم لهم وهم في أسفل سافلين والمؤمنون في أعلى علّيّين، إذ البث التلفزيوني اليوم قطع العجب وأبطله. هل جُوزي الكفار على أفعالهم الإجرامية؟ والجواب معلوم مما تقدّم.", "h": ["التنديد بالإجرام والمجرمين.", "بيان ما كان عليه المشركون في مكة إبّان الدعوة، وما لقيه المؤمنون منهم.", "بيان أن المؤمنين سيرون المشركين في الجحيم ويضحكون منهم وهم في نعيمهم، والمشركون في جحيمهم.", "بيان إكرام الله لأوليائه، وإهانته تعالى لأعدائه."], "k": "«إن الذين أجرموا كانوا من الذين آمنوا يضحكون»… قد يُسخر مني لتمسّكي بديني؛ فهل أثبت وأتذكّر أين ينتهي الضحك؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 437;
insert into public.tdb_cards(topic, i, body) select 437, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "وَيۡلٞ لِّلۡمُطَفِّفِينَ ﴿١﴾ ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ ﴿٢﴾ وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ ﴿٣﴾ أَلَا يَظُنُّ أُوْلَـٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ ﴿٤﴾ لِيَوۡمٍ عَظِيمٖ ﴿٥﴾ يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ ﴿٦﴾", "w": [["ويل", "كلمة عذاب، ووادٍ في جهنم."], ["للمطفّفين", "المنقصين في كيل أو وزن، الباخسين فيهما."], ["يستوفون", "الكيل."], ["وإذا كالوهم", "كالوا لهم."], ["أو وزنوهم", "وزنوا لهم."], ["يُخسرون", "ينقصون الكيل أو الوزن."], ["ألا", "استفهام توبيخي إنكاري."], ["يظن", "يتيقّن."], ["ليوم عظيم", "يوم القيامة، لما فيه من أهوال وعظائم الأمور."], ["يوم يقوم الناس", "من قبورهم."], ["لرب العالمين", "يقومون خاشعين ذليلين ينتظرون حكم الله فيهم."]], "m": "هذه الآيات الأولى من سورة المطففين، قال أحد الأنصار رضي الله عنه: كنا أسوأ الناس كيلاً، حتى إنه ليكون لأحدنا مكيالان: مكيال يشتري به وآخر يبيع به، فما إن نزلت فينا «ويل للمطفّفين» حتى أصبحنا أحسن الناس كيلاً ووزناً. يتوعّد سبحانه بوادٍ في جهنم يسيل بصديد أهل النار الذين يبخسون الناس الكيل والميزان، ويبيّنهم تعالى بقوله: الذين إذا اشتروا من الناس يأخذون كيلهم وافياً، وكذا إذا وزنوا، وإذا كالوا لهم أو وزنوا لهم ينقصون. قال تعالى موبّخاً لهم: ألا يتيقّن أولئك المطفّفون أنهم مبعوثون من قبورهم ليوم عظيم، هو يوم الجزاء والحساب، يوم يقوم الناس لرب العالمين خاشعين ذليلين ينتظرون حكمه فيهم، ويطول بهم الموقف حتى إن أحدهم ليلجمه العرق إلجاماً.", "h": ["حرمة التطفيف في الكيل والوزن، وهو أن يأخذ زائداً ولو قلّ، أو ينقص عامداً شيئاً ولو قلّ، وما كان بغير عمد ولا قصد فإنه مما يُعفى عنه.", "التذكير بالبعث والجزاء وتقريرهما.", "عظم يوم القيامة، يوم يقوم الناس لرب العالمين ليحكم بينهم ويجزي كلاً بعمله خيراً أو شراً."], "k": "«ويل للمطفّفين»… قد لا أزن بميزان، لكن هل أطلب حقي كاملاً وأعطي حقوق الناس ناقصة؟"}, {"lbl": "الآيات ٧ – ١٧", "q": "كَلَّآ إِنَّ كِتَٰبَ ٱلۡفُجَّارِ لَفِي سِجِّينٖ ﴿٧﴾ وَمَآ أَدۡرَىٰكَ مَا سِجِّينٞ ﴿٨﴾ كِتَٰبٞ مَّرۡقُومٞ ﴿٩﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿١٠﴾ ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ ٱلدِّينِ ﴿١١﴾ وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعۡتَدٍ أَثِيمٍ ﴿١٢﴾ إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿١٣﴾ كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ ﴿١٤﴾ كَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذٖ لَّمَحۡجُوبُونَ ﴿١٥﴾ ثُمَّ إِنَّهُمۡ لَصَالُواْ ٱلۡجَحِيمِ ﴿١٦﴾ ثُمَّ يُقَالُ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ ﴿١٧﴾", "w": [["كلا", "حقاً، وإن الأمر ليس كما يظن المطفّفون."], ["لفي سجّين", "سجّين ديوان الشر الذي دُوّنت فيه أعمال الشياطين والكفرة، وهو أيضاً موضع في أسفل الأرض السابعة، وبه أرواح الأشقياء عامة."], ["كتاب مرقوم", "مسطور بيّن الكتابة فيه أعمالهم."], ["يوم الدين", "يوم القيامة الذي هو يوم الحساب والجزاء."], ["كل معتدٍ", "ظالم مضيّع حقوق ربه وحقوق غيره."], ["أثيم", "منغمس في الآثام مكثر منها."], ["أساطير الأولين", "ما سطّره الأولون من القصص والأخبار التي لا تصح."], ["ران على قلوبهم", "غطّى قلوبهم وحجبها عن قبول الحق."], ["ما كانوا يكسبون", "من الذنوب والآثام."], ["لمحجوبون", "يُحال بينهم وبين رؤية الرب يوم القيامة."], ["لصالو الجحيم", "لداخلوها، محرقون معذّبون بها."], ["هذا الذي كنتم به تكذّبون", "يقال لهم توبيخاً وخزياً وهم في العذاب."]], "m": "ما زال السياق في التحذير من الظلم والفسق عن أوامر الرب: كلا، ليس الأمر كما يظن المطفّفون والباخسون للحقوق أنه لا دقّة في الحساب، وأن مثل هذا لا يُكتب ولا يُجزى به، حقاً إن كتاب الفجّار الظلمة الخارجين عن الشرع لفي سجّين، موضع في أسفل الخلق فيه أرواح الكافرين والظالمين وكتب أعمالهم، وما أدراك ما سجّين؟ تفخيم لشأنه، كتاب مسطور بيّن الكتابة. ويل يومئذ للمكذّبين بالله وآياته ولقائه، المكذّبين بيوم الدين، وما يكذّب به إلا كل معتدٍ ظالم متجاوز للحد، أثيم مرتكب للذنوب، إذا قُرئت عليه آيات الله تذكيراً له ردّها بقوله: أساطير الأولين، أي حكايات مسطّرة. كلا، ما الأمر كما يدّعون، وإنما غطّى قلوبهم أثر الذنوب والجرائم فحجبها عن معرفة الحق وقبوله. كلا إنهم عن ربهم يومئذ لمحجوبون، فلا يرونه ولا يرون كرامته، ثم إنهم لداخلو الجحيم ومصطلون بحرّها، ثم يقال لهم توبيخاً وخزياً: هذا العذاب الذي كنتم به في الدنيا تكذّبون حتى واصلتم كفركم وإجرامكم.", "h": ["بيان كتاب الفجّار وأنه في سجّين، وسجّين ديوان تُدوّن فيه سائر كتب الفجّار من أهل النار، وموضع أسفل الأرض السابعة مستودع لكتب أعمال الفجّار من كفار وفسّاق ولأرواحهم إلى يوم القيامة، ولفظ سجّين مشتق من السجن الذي هو الحبس.", "الوعيد الشديد للمكذّبين بالله وبآياته ولقائه.", "التحذير من مواصلة الذنوب وعدم التوبة منها، حيث يؤدّي ذلك بالعبد إلى أن يُحرم التوبة؛ ففي حديث أبي هريرة قال رسول الله ﷺ: «إذا أذنب العبد نُكت في قلبه نكتة سوداء، فإن تاب صُقل منها، فإن عاد عادت حتى تعظم في قلبه، فذلك الران الذي قال الله: كلا بل ران على قلوبهم ما كانوا يكسبون».", "تقرير رؤية الله تعالى في الآخرة، بدليل قوله: «إنهم عن ربهم يومئذ لمحجوبون» أي الأشقياء، إذاً فالسعداء غير محجوبين، فهم يرون ربهم.", "تقرير عقيدة البعث والجزاء."], "k": "«كلا بل ران على قلوبهم»… كل ذنب بلا توبة نكتة سوداء؛ فلأمسحها اليوم بالاستغفار قبل أن تتراكم."}, {"lbl": "الآيات ١٨ – ٢٨", "q": "كَلَّآ إِنَّ كِتَٰبَ ٱلۡأَبۡرَارِ لَفِي عِلِّيِّينَ ﴿١٨﴾ وَمَآ أَدۡرَىٰكَ مَا عِلِّيُّونَ ﴿١٩﴾ كِتَٰبٞ مَّرۡقُومٞ ﴿٢٠﴾ يَشۡهَدُهُ ٱلۡمُقَرَّبُونَ ﴿٢١﴾ إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٍ ﴿٢٢﴾ عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ ﴿٢٣﴾ تَعۡرِفُ فِي وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِيمِ ﴿٢٤﴾ يُسۡقَوۡنَ مِن رَّحِيقٖ مَّخۡتُومٍ ﴿٢٥﴾ خِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ ﴿٢٦﴾ وَمِزَاجُهُۥ مِن تَسۡنِيمٍ ﴿٢٧﴾ عَيۡنٗا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ ﴿٢٨﴾", "w": [["كتاب الأبرار", "كتاب أعمالهم، والأبرار المطيعون لله ولرسوله الصادقون."], ["لفي علّيّين", "في موضع يُسمّى علّيّين في أعلى الجنة."], ["كتاب مرقوم", "كتاب مرقوم بأمان من الله لصاحبه من النار يوم القيامة والفوز بالجنة."], ["يشهده المقرّبون", "يحضره المقرّبون من أهل كل سماء ويحفظونه."], ["إن الأبرار لفي نعيم", "إن الذين برّوا ربهم بطاعته بأداء الفرائض واجتناب النواهي لفي نعيم الجنة."], ["على الأرائك", "على الأسرّة ذات الحجال."], ["ينظرون", "ينظرون ما آتاهم ربهم من صنوف النعيم."], ["نضرة النعيم", "حُسنه وبريقه وتلألؤه."], ["من رحيق", "من خمر صرف خالصة لا غش فيها ولا دنس."], ["مختوم", "مختوم على إنائها لا يفكّ ختمه إلا هم."], ["ختامه مسك", "آخر شربها يفوح برائحة المسك."], ["وفي ذلك", "لا في غيره."], ["فليتنافس المتنافسون", "فليطلب بالطاعة والاستقامة الطالبون للنعيم المقيم."], ["ومزاجه من تسنيم", "ومزاج شرابهم من عين تجري من عالٍ تُسمّى التسنيم."], ["عيناً يشرب بها المقرّبون", "يشرب منها المقرّبون صرفاً، وتُمزج لأصحاب اليمين."]], "m": "بعد أن ذكر تعالى كتاب الفجّار وما خُتم له به، ذكر كتاب الأبرار: كلا، حقاً إن كتاب أعمال الأبرار، وهم المؤمنون الذين برّوا ربهم بطاعته وكانوا صادقين في ذلك، لفي علّيّين، وما أدراك يا رسولنا ما علّيّون؟ موضع في أعلى الجنة، كتاب مرقوم بأمان من الله لصاحبه من النار والفوز بالجنة، يحضره مقرّبو كل سماء ويحفظونه ويشهدون بما فيه. إن الأبرار لفي نعيم الجنة يوم القيامة، على الأسرّة ذات الحجال ينظرون باستحسان وإعجاب ملكهم الكبير الذي ملّكهم الله تعالى، تعرف في وجوههم حُسن النعيم وبريقه، يُسقون من خمر صافية لا دنس فيها، مختوم على أوانيها لا يفكّها إلا هم، آخر هذا الشراب يفوح برائحة المسك، وفي مثل هذا النعيم، لا في غيره من حطام الدنيا وشرابها وملكها الزائل، يجب أن يتنافس المتنافسون بالإيمان وصالح الأعمال بعد البعد عن الشرك وسيئ الأقوال وقبيح الأفعال. ومزاج ذلك الرحيق لأصحاب اليمين من عين تُسمّى التسنيم، ويشربها المقرّبون صرفاً خالصاً.", "h": ["الثناء على الأبرار وبيان ما أعدّ الله تعالى لهم، وهم المؤمنون المتقون الصادقون في ذلك.", "تقرير عقيدة البعث والجزاء بذكر ما يجري فيها.", "الترغيب في العمل الصالح للحصول على نعيم الجنة، لقوله تعالى: «وفي ذلك فليتنافس المتنافسون»."], "k": "«وفي ذلك فليتنافس المتنافسون»… فيمَ أنافس الناس اليوم؟ وهل يستحق ذلك التنافس؟"}, {"lbl": "الآيات ٢٩ – ٣٦", "q": "إِنَّ ٱلَّذِينَ أَجۡرَمُواْ كَانُواْ مِنَ ٱلَّذِينَ ءَامَنُواْ يَضۡحَكُونَ ﴿٢٩﴾ وَإِذَا مَرُّواْ بِهِمۡ يَتَغَامَزُونَ ﴿٣٠﴾ وَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ ﴿٣١﴾ وَإِذَا رَأَوۡهُمۡ قَالُوٓاْ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ ﴿٣٢﴾ وَمَآ أُرۡسِلُواْ عَلَيۡهِمۡ حَٰفِظِينَ ﴿٣٣﴾ فَٱلۡيَوۡمَ ٱلَّذِينَ ءَامَنُواْ مِنَ ٱلۡكُفَّارِ يَضۡحَكُونَ ﴿٣٤﴾ عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ ﴿٣٥﴾ هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُواْ يَفۡعَلُونَ ﴿٣٦﴾", "w": [["إن الذين أجرموا", "على أنفسهم بالشرك والمعاصي، كأبي جهل وأمية بن خلف وعقبة بن أبي معيط."], ["من الذين آمنوا", "كبلال وياسر وعمار وصهيب وخبيب."], ["يتغامزون", "يشيرون إلى المؤمنين بالجفن والحاجب استهزاءً بهم."], ["فكهين", "إذا رجعوا إلى ديارهم وأهليهم رجعوا فرحين معجبين بحالهم."], ["وإذا رأوهم", "وإذا رأى أولئك المؤمنين."], ["قالوا إن هؤلاء لضالّون", "يعنون أصحاب محمد ﷺ، بتركهم دينهم واتّخاذهم دين محمد الجديد."], ["وما أُرسلوا عليهم حافظين", "لم يكلّفهم الله بحفظ أعمالهم ورعاية أحوالهم، وإنما هم متطفّلون."], ["فاليوم", "يوم القيامة."], ["من الكفار يضحكون", "مما هم فيه من العذاب، حيث يرونهم وهم على أرائكهم."], ["هل ثُوّب الكفار ما كانوا يفعلون", "هل جُوزي الكفار بما كانوا يفعلون من الكفر والشر والفساد؟ والجواب: نعم."]], "m": "بعدما بيّن تعالى حال الأبرار في دار الأبرار، وحال المجرمين في دار العذاب، ذكر في خاتمة السورة ما أوجب للمجرمين النار وللمؤمنين الجنة، فذكر طرفاً من سلوك الفريقين: إن الذين أفسدوا أنفسهم بالشرك والشر، كأبي جهل والوليد بن المغيرة والعاص وغيرهم، كانوا من الذين آمنوا، كبلال وعمار وصهيب وخبيب وأضرابهم من فقراء المؤمنين، يضحكون استهزاءً بهم وسخرية، وإذا مرّوا بهم في شوارع مكة وحول المسجد الحرام يتغامزون، يشيرون إليهم بالجفن والحاجب على عادة المتكبّرين، وإذا رجعوا إلى أهلهم رجعوا ناعمين معجبين بحالهم، وإذا رأوا المؤمنين قالوا: إن هؤلاء لضالّون بتركهم دينهم واعتناق دين محمد. قال تعالى: وما أُرسلوا عليهم حافظين لأعمالهم وأحوالهم حتى يقولوا ما قالوا، وإنما هم متطفّلون. فاليوم، يوم القيامة، الذين آمنوا من الكفار يضحكون، على الأسرّة ذات الحجال ينظرون إلى الكفار وهم في النار ويضحكون منهم وهم يُعذّبون، ولا عجب في كيفية رؤيتهم لهم وهم في أسفل سافلين والمؤمنون في أعلى علّيّين، إذ البث التلفزيوني اليوم قطع العجب وأبطله. هل جُوزي الكفار على أفعالهم الإجرامية؟ والجواب معلوم مما تقدّم.", "h": ["التنديد بالإجرام والمجرمين.", "بيان ما كان عليه المشركون في مكة إبّان الدعوة، وما لقيه المؤمنون منهم.", "بيان أن المؤمنين سيرون المشركين في الجحيم ويضحكون منهم وهم في نعيمهم، والمشركون في جحيمهم.", "بيان إكرام الله لأوليائه، وإهانته تعالى لأعدائه."], "k": "«إن الذين أجرموا كانوا من الذين آمنوا يضحكون»… قد يُسخر مني لتمسّكي بديني؛ فهل أثبت وأتذكّر أين ينتهي الضحك؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (438, 84, 1, 25, 'سورة الانشقاق ١ – ٢٥', 'الانشقاق: إنك كادح إلى ربك كدحاً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 438) = $j$[{"lbl": "الآيات ١ – ١٥", "q": "إِذَا ٱلسَّمَآءُ ٱنشَقَّتۡ ﴿١﴾ وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ ﴿٢﴾ وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ ﴿٣﴾ وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ ﴿٤﴾ وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ ﴿٥﴾ يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحٗا فَمُلَٰقِيهِ ﴿٦﴾ فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ ﴿٧﴾ فَسَوۡفَ يُحَاسَبُ حِسَابٗا يَسِيرٗا ﴿٨﴾ وَيَنقَلِبُ إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورٗا ﴿٩﴾ وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ ﴿١٠﴾ فَسَوۡفَ يَدۡعُواْ ثُبُورٗا ﴿١١﴾ وَيَصۡلَىٰ سَعِيرًا ﴿١٢﴾ إِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا ﴿١٣﴾ إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ ﴿١٤﴾ بَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرٗا ﴿١٥﴾", "w": [["إذا السماء انشقّت", "بالغمام، وهو سحاب أبيض رقيق، وذلك لنزول الملائكة."], ["وأذنت لربها", "سمعت وأطاعت."], ["وحُقّت", "وحُقّ لها أن تسمع أمر ربها وتطيعه."], ["وإذا الأرض مُدّت", "زِيد في سعتها كما يُمدّ الأديم، إذ لم يبقَ عليها بناء ولا جبل."], ["وألقت ما فيها وتخلّت", "ألقت ما فيها من الموتى أحياء إلى ظهرها، وتخلّت عمّا كان في بطنها."], ["إنك كادح", "عامل كاسب للخير أو الشر."], ["إلى ربك كدحاً", "إلى أن تلقى ربك وأنت تعمل وتكسب، فليكن عملك مما يرضيه."], ["فملاقيه", "ملاقٍ ربك بعد موتك وبعملك خيره وشرّه."], ["وينقلب إلى أهله مسروراً", "بعد الحساب اليسير يرجع إلى أهله في الجنة."], ["وراء ظهره", "يأخذه بشماله من وراء ظهره إهانةً له."], ["يدعو ثبوراً", "ينادي هلاكه قائلاً: واثبوراه، أي يا هلاكاه."], ["ويصلى سعيراً", "ويُحرق بالنار تحريقاً."], ["إنه ظنّ أن لن يحور", "كان في الدنيا يظن أنه لا يرجع إلى الحياة بعد الموت، فلذا لم يعمل خيراً ولم يتورّع عن شر."]], "m": "يخبر تعالى أنه إذا انشقّت السماء وتصدّعت، وسمعت لأمر ربها واستجابت، وحُقّ لها ذلك، وإذا الأرض مُدّت واتّسعت رقعتها حيث زالت منها الجبال والمباني وأصبحت قاعاً صفصفاً، وألقت ما في بطنها من أموات وتخلّت عنه، وسمعت وأجابت، وحُقّ لها أن تطيع، والجواب: علمت نفس ما قدّمت وأخّرت كما تقدّم نظيره في التكوير والانفطار. يا أيها الإنسان إنك عامل ليل نهار إلى أن تموت وتلقى ربك، تكسب بجوارحك الخير والشر، يشهد له قول الرسول ﷺ في الصحيح: «كل الناس يغدو فبائع نفسه فمعتقها أو موبقها»، فأنصح لك أن يكون عملك صالحاً تلاقي به ربك. فأما من أوتي كتابه بيمينه، لأنه حوى الخير، فسوف يُحاسب حساباً يسيراً، يُنظر في كتابه ويقرّر: هل فعلت كذا؟ فيعترف ويُتجاوز عنه، وينقلب إلى أهله في الجنة مسروراً، يجمعهم الله كرامة لهم. وأما من أوتي كتابه وراء ظهره، حيث تُغلّ اليمنى مع عنقه وتخرج الشمال وراء ظهره، فسوف ينادي هلاكه: يا هلاكاه احضر، ويدخل ناراً مستعرة شديدة الالتهاب، وعلّة ذلك أنه كان في أهله في الدنيا مسروراً لا يخاف الله ولا يرجو الدار الآخرة، يعمل ما يشاء ويترك ما يشاء، إنه ظنّ أنه لا يرجع حيّاً بعد موته ولا يُحاسب، فاحذروا ذلك أيها الناس. بلى ليبعثنّ وليحاسبنّ، إن ربه كان به وبعمله بصيراً، لا يخفى عليه من أمره شيء.", "h": ["تقرير عقيدة البعث والجزاء ببيان مقدّماته في انقلاب الكون.", "بيان حتمية لقاء الإنسان ربه.", "كل إنسان مكلّف بالعقل والبلوغ فهو عامل وكاسب لا محالة إلى أن يموت ويلقى ربه.", "أهل الإيمان والتقوى يُحاسبون حساباً يسيراً، وهو مجرد عرض لا غير ويفوزون، أما من نوقش الحساب فقد هلك وعُذّب لأنه لا يملك حجة ولا عذراً.", "التنعّم في الدنيا والانكباب على شهواتها مع ترك الطاعات ثمرة عدم الإيمان أو اليقين بالبعث والجزاء."], "k": "«إنك كادح إلى ربك كدحاً فملاقيه»… كل تعبي اليوم ينتهي عنده؛ فهل أكدح فيما يسرّني لقاؤه؟"}, {"lbl": "الآيات ١٦ – ٢٥", "q": "فَلَآ أُقۡسِمُ بِٱلشَّفَقِ ﴿١٦﴾ وَٱلَّيۡلِ وَمَا وَسَقَ ﴿١٧﴾ وَٱلۡقَمَرِ إِذَا ٱتَّسَقَ ﴿١٨﴾ لَتَرۡكَبُنَّ طَبَقًا عَن طَبَقٖ ﴿١٩﴾ فَمَا لَهُمۡ لَا يُؤۡمِنُونَ ﴿٢٠﴾ وَإِذَا قُرِئَ عَلَيۡهِمُ ٱلۡقُرۡءَانُ لَا يَسۡجُدُونَۤ۩ ﴿٢١﴾ بَلِ ٱلَّذِينَ كَفَرُواْ يُكَذِّبُونَ ﴿٢٢﴾ وَٱللَّهُ أَعۡلَمُ بِمَا يُوعُونَ ﴿٢٣﴾ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ ﴿٢٤﴾ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونِۭ ﴿٢٥﴾", "w": [["بالشفق", "الحمرة في الأفق بعد غروب الشمس."], ["وما وسق", "ما دخل عليه من الدواب وغيرها."], ["إذا اتّسق", "اجتمع وتمّ نوره، وذلك في الليالي البيض."], ["طبقاً عن طبق", "حالاً بعد حال: الموت، ثم الحياة، ثم ما بعدها من أحوال القيامة."], ["فما لهم لا يؤمنون", "أي مانع لهم من الإيمان بالله ورسوله ولقاء ربهم والحجج كثيرة تُتلى؟"], ["وإذا قُرئ عليهم القرآن", "تُلي عليهم وسمعوه."], ["لا يسجدون", "لا يخضعون فيؤمنوا ويسلموا."], ["بما يوعون", "يجمعون في صحفهم من الكفر والتكذيب."], ["لهم أجر غير ممنون", "غير مقطوع."]], "m": "فليس الأمر كما تدّعون من أنه لا بعث ولا جزاء، أقسم بالشفق، وهو الحمرة في الأفق بعد غروب الشمس، والليل وما جمع من كل ذي روح من سابح في الماء وطائر في السماء وسارح في الغبراء، والقمر إذا اجتمع وتمّ نوره في الليالي البيض. وجواب القسم: لتركبنّ طبقاً عن طبق، حالاً بعد حال: الموت ثم الحياة ثم العرض ثم الحساب ثم الجزاء، فهي أحوال وأهوال، فليس الأمر كما تتصوّرون من أنه موت ولا غير. فما للناس لا يؤمنون، أي شيء منعهم من الإيمان بالله ورسوله والدار الآخرة مع كثرة الآيات وقوة الحجج؟ وما لهم إذا تُلي عليهم القرآن وسمعوه لا يخضعون ولا يخشعون ولا يخرّون ساجدين؟ بل الذين كفروا بدل أن يؤمنوا يكذّبون، والله أعلم بما يجمعون في صدورهم من الكفر والتكذيب والبغض، فبشّرهم يا رسولنا بعذاب أليم عاجلاً وآجلاً، إلا الذين آمنوا بالله ورسوله ولقائه وعملوا الصالحات فأدّوا الفرائض واجتنبوا المحارم، فهؤلاء لهم ثواب عند الله يوم يلقونه غير منقوص ولا مقطوع في الجنة دار السلام.", "h": ["بيان أن الإنسان مقبل على أحوال وأهوال، حالاً بعد حال وهولاً بعد هول، إلى أن ينتهي إلى جنة أو نار.", "بيان أن عدم إيمان الإنسان بربه أمر يستدعي العجب، إذ لا مانع للعبد من الإيمان بخالقه وهو يعلم أنه مخلوق، وقد تعرّف إليه فأنزل كتبه وبعث رسله وأقام الأدلة على ذلك.", "مشروعية السجود عند تلاوة هذه الآية، وهي: «وإذا قُرئ عليهم القرآن لا يسجدون».", "علم الله تعالى بما يعي الإنسان في قلبه وما يحمل في نفسه، فليراقب العبد ربه فلا يعي في قلبه إلا الإيمان، ولا يحمل في نفسه إلا الخير، فلا غلّ ولا حسد ولا شك."], "k": "«وإذا قُرئ عليهم القرآن لا يسجدون»… حين أمرّ بآية سجدة، هل يسجد قلبي قبل جبهتي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 438;
insert into public.tdb_cards(topic, i, body) select 438, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٥", "q": "إِذَا ٱلسَّمَآءُ ٱنشَقَّتۡ ﴿١﴾ وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ ﴿٢﴾ وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ ﴿٣﴾ وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ ﴿٤﴾ وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ ﴿٥﴾ يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحٗا فَمُلَٰقِيهِ ﴿٦﴾ فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ ﴿٧﴾ فَسَوۡفَ يُحَاسَبُ حِسَابٗا يَسِيرٗا ﴿٨﴾ وَيَنقَلِبُ إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورٗا ﴿٩﴾ وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ ﴿١٠﴾ فَسَوۡفَ يَدۡعُواْ ثُبُورٗا ﴿١١﴾ وَيَصۡلَىٰ سَعِيرًا ﴿١٢﴾ إِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا ﴿١٣﴾ إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ ﴿١٤﴾ بَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرٗا ﴿١٥﴾", "w": [["إذا السماء انشقّت", "بالغمام، وهو سحاب أبيض رقيق، وذلك لنزول الملائكة."], ["وأذنت لربها", "سمعت وأطاعت."], ["وحُقّت", "وحُقّ لها أن تسمع أمر ربها وتطيعه."], ["وإذا الأرض مُدّت", "زِيد في سعتها كما يُمدّ الأديم، إذ لم يبقَ عليها بناء ولا جبل."], ["وألقت ما فيها وتخلّت", "ألقت ما فيها من الموتى أحياء إلى ظهرها، وتخلّت عمّا كان في بطنها."], ["إنك كادح", "عامل كاسب للخير أو الشر."], ["إلى ربك كدحاً", "إلى أن تلقى ربك وأنت تعمل وتكسب، فليكن عملك مما يرضيه."], ["فملاقيه", "ملاقٍ ربك بعد موتك وبعملك خيره وشرّه."], ["وينقلب إلى أهله مسروراً", "بعد الحساب اليسير يرجع إلى أهله في الجنة."], ["وراء ظهره", "يأخذه بشماله من وراء ظهره إهانةً له."], ["يدعو ثبوراً", "ينادي هلاكه قائلاً: واثبوراه، أي يا هلاكاه."], ["ويصلى سعيراً", "ويُحرق بالنار تحريقاً."], ["إنه ظنّ أن لن يحور", "كان في الدنيا يظن أنه لا يرجع إلى الحياة بعد الموت، فلذا لم يعمل خيراً ولم يتورّع عن شر."]], "m": "يخبر تعالى أنه إذا انشقّت السماء وتصدّعت، وسمعت لأمر ربها واستجابت، وحُقّ لها ذلك، وإذا الأرض مُدّت واتّسعت رقعتها حيث زالت منها الجبال والمباني وأصبحت قاعاً صفصفاً، وألقت ما في بطنها من أموات وتخلّت عنه، وسمعت وأجابت، وحُقّ لها أن تطيع، والجواب: علمت نفس ما قدّمت وأخّرت كما تقدّم نظيره في التكوير والانفطار. يا أيها الإنسان إنك عامل ليل نهار إلى أن تموت وتلقى ربك، تكسب بجوارحك الخير والشر، يشهد له قول الرسول ﷺ في الصحيح: «كل الناس يغدو فبائع نفسه فمعتقها أو موبقها»، فأنصح لك أن يكون عملك صالحاً تلاقي به ربك. فأما من أوتي كتابه بيمينه، لأنه حوى الخير، فسوف يُحاسب حساباً يسيراً، يُنظر في كتابه ويقرّر: هل فعلت كذا؟ فيعترف ويُتجاوز عنه، وينقلب إلى أهله في الجنة مسروراً، يجمعهم الله كرامة لهم. وأما من أوتي كتابه وراء ظهره، حيث تُغلّ اليمنى مع عنقه وتخرج الشمال وراء ظهره، فسوف ينادي هلاكه: يا هلاكاه احضر، ويدخل ناراً مستعرة شديدة الالتهاب، وعلّة ذلك أنه كان في أهله في الدنيا مسروراً لا يخاف الله ولا يرجو الدار الآخرة، يعمل ما يشاء ويترك ما يشاء، إنه ظنّ أنه لا يرجع حيّاً بعد موته ولا يُحاسب، فاحذروا ذلك أيها الناس. بلى ليبعثنّ وليحاسبنّ، إن ربه كان به وبعمله بصيراً، لا يخفى عليه من أمره شيء.", "h": ["تقرير عقيدة البعث والجزاء ببيان مقدّماته في انقلاب الكون.", "بيان حتمية لقاء الإنسان ربه.", "كل إنسان مكلّف بالعقل والبلوغ فهو عامل وكاسب لا محالة إلى أن يموت ويلقى ربه.", "أهل الإيمان والتقوى يُحاسبون حساباً يسيراً، وهو مجرد عرض لا غير ويفوزون، أما من نوقش الحساب فقد هلك وعُذّب لأنه لا يملك حجة ولا عذراً.", "التنعّم في الدنيا والانكباب على شهواتها مع ترك الطاعات ثمرة عدم الإيمان أو اليقين بالبعث والجزاء."], "k": "«إنك كادح إلى ربك كدحاً فملاقيه»… كل تعبي اليوم ينتهي عنده؛ فهل أكدح فيما يسرّني لقاؤه؟"}, {"lbl": "الآيات ١٦ – ٢٥", "q": "فَلَآ أُقۡسِمُ بِٱلشَّفَقِ ﴿١٦﴾ وَٱلَّيۡلِ وَمَا وَسَقَ ﴿١٧﴾ وَٱلۡقَمَرِ إِذَا ٱتَّسَقَ ﴿١٨﴾ لَتَرۡكَبُنَّ طَبَقًا عَن طَبَقٖ ﴿١٩﴾ فَمَا لَهُمۡ لَا يُؤۡمِنُونَ ﴿٢٠﴾ وَإِذَا قُرِئَ عَلَيۡهِمُ ٱلۡقُرۡءَانُ لَا يَسۡجُدُونَۤ۩ ﴿٢١﴾ بَلِ ٱلَّذِينَ كَفَرُواْ يُكَذِّبُونَ ﴿٢٢﴾ وَٱللَّهُ أَعۡلَمُ بِمَا يُوعُونَ ﴿٢٣﴾ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ ﴿٢٤﴾ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونِۭ ﴿٢٥﴾", "w": [["بالشفق", "الحمرة في الأفق بعد غروب الشمس."], ["وما وسق", "ما دخل عليه من الدواب وغيرها."], ["إذا اتّسق", "اجتمع وتمّ نوره، وذلك في الليالي البيض."], ["طبقاً عن طبق", "حالاً بعد حال: الموت، ثم الحياة، ثم ما بعدها من أحوال القيامة."], ["فما لهم لا يؤمنون", "أي مانع لهم من الإيمان بالله ورسوله ولقاء ربهم والحجج كثيرة تُتلى؟"], ["وإذا قُرئ عليهم القرآن", "تُلي عليهم وسمعوه."], ["لا يسجدون", "لا يخضعون فيؤمنوا ويسلموا."], ["بما يوعون", "يجمعون في صحفهم من الكفر والتكذيب."], ["لهم أجر غير ممنون", "غير مقطوع."]], "m": "فليس الأمر كما تدّعون من أنه لا بعث ولا جزاء، أقسم بالشفق، وهو الحمرة في الأفق بعد غروب الشمس، والليل وما جمع من كل ذي روح من سابح في الماء وطائر في السماء وسارح في الغبراء، والقمر إذا اجتمع وتمّ نوره في الليالي البيض. وجواب القسم: لتركبنّ طبقاً عن طبق، حالاً بعد حال: الموت ثم الحياة ثم العرض ثم الحساب ثم الجزاء، فهي أحوال وأهوال، فليس الأمر كما تتصوّرون من أنه موت ولا غير. فما للناس لا يؤمنون، أي شيء منعهم من الإيمان بالله ورسوله والدار الآخرة مع كثرة الآيات وقوة الحجج؟ وما لهم إذا تُلي عليهم القرآن وسمعوه لا يخضعون ولا يخشعون ولا يخرّون ساجدين؟ بل الذين كفروا بدل أن يؤمنوا يكذّبون، والله أعلم بما يجمعون في صدورهم من الكفر والتكذيب والبغض، فبشّرهم يا رسولنا بعذاب أليم عاجلاً وآجلاً، إلا الذين آمنوا بالله ورسوله ولقائه وعملوا الصالحات فأدّوا الفرائض واجتنبوا المحارم، فهؤلاء لهم ثواب عند الله يوم يلقونه غير منقوص ولا مقطوع في الجنة دار السلام.", "h": ["بيان أن الإنسان مقبل على أحوال وأهوال، حالاً بعد حال وهولاً بعد هول، إلى أن ينتهي إلى جنة أو نار.", "بيان أن عدم إيمان الإنسان بربه أمر يستدعي العجب، إذ لا مانع للعبد من الإيمان بخالقه وهو يعلم أنه مخلوق، وقد تعرّف إليه فأنزل كتبه وبعث رسله وأقام الأدلة على ذلك.", "مشروعية السجود عند تلاوة هذه الآية، وهي: «وإذا قُرئ عليهم القرآن لا يسجدون».", "علم الله تعالى بما يعي الإنسان في قلبه وما يحمل في نفسه، فليراقب العبد ربه فلا يعي في قلبه إلا الإيمان، ولا يحمل في نفسه إلا الخير، فلا غلّ ولا حسد ولا شك."], "k": "«وإذا قُرئ عليهم القرآن لا يسجدون»… حين أمرّ بآية سجدة، هل يسجد قلبي قبل جبهتي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (439, 85, 1, 22, 'سورة البروج ١ – ٢٢', 'البروج: أصحاب الأخدود', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 439) = $j$[{"lbl": "الآيات ١ – ١١", "q": "وَٱلسَّمَآءِ ذَاتِ ٱلۡبُرُوجِ ﴿١﴾ وَٱلۡيَوۡمِ ٱلۡمَوۡعُودِ ﴿٢﴾ وَشَاهِدٖ وَمَشۡهُودٖ ﴿٣﴾ قُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ ﴿٤﴾ ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ ﴿٥﴾ إِذۡ هُمۡ عَلَيۡهَا قُعُودٞ ﴿٦﴾ وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِٱلۡمُؤۡمِنِينَ شُهُودٞ ﴿٧﴾ وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ ﴿٨﴾ ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿٩﴾ إِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ ﴿١٠﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِيرُ ﴿١١﴾", "w": [["ذات البروج", "منازل الشمس والقمر الاثنا عشر برجاً."], ["واليوم الموعود", "يوم القيامة، إذ وعد الله عباده أن يجمعهم فيه لفصل القضاء."], ["وشاهد", "يوم الجمعة."], ["ومشهود", "يوم عرفة."], ["قُتل أصحاب الأخدود", "لُعن أصحاب الأخدود."], ["الأخدود", "الحفرة تُحفر في الأرض، وجمعه أخاديد."], ["إذ هم عليها قعود", "على حافتها وشفيرها."], ["وما نقموا منهم", "ما عابوا عليهم شيئاً سوى إيمانهم بالله تعالى."]], "m": "أقسم تعالى بالسماء ذات البروج، وهي منازل الشمس والقمر، وباليوم الموعود وهو يوم القيامة، إذ وعد عباده أن يجمعهم فيه ليحكم بينهم فيما كانوا فيه يختلفون، وبالشاهد وهو يوم الجمعة، وبالمشهود وهو يوم عرفة. وجواب القسم قد يكون محذوفاً تقديره: لتُبعثُنّ ثم لتُنبّؤنّ، لأن السورة مكية والسور المكية تعالج العقيدة: التوحيد والنبوة والبعث والجزاء، وجائز أن يكون الجواب: لقد قُتل، أي لُعن أصحاب الأخدود، وهي حفر حفرها الكفار وأجّجوا فيها ناراً، وأتوا بالمؤمنين المخالفين لدينهم وعرضوا عليهم الكفر أو الإلقاء في النار، فاختاروا الإلقاء في النار مع بقاء إيمانهم، حتى إن امرأة كانت ترضع صبياً فأحجمت عن إلقاء نفسها مع طفلها في النار، فأنطق الله الصبي فقال لها: يا أمّاه امضي فإنك على الحق، فاقتحمت النار. إذ هم على حافة النار قاعدون، وهم على ما يفعلون بالمؤمنين من الإلقاء في النار حضور، لم يغيّروا منكراً ولم يأمروا بمعروف. وما عابوا عليهم شيئاً سوى إيمانهم بالله العزيز في انتقامه لأوليائه، الحميد لآلائه ونعمه على سائر خلقه، الذي له ملك السموات والأرض، وهو على كل شيء شهيد؛ فكيف يُنكر على المؤمن إيمانه بربه ذي الصفات العلا؟ إن الذين فتنوا المؤمنين والمؤمنات عن دينهم فأحرقوهم بالنار ثم لم يتوبوا، فلهم عذاب جهنم في الآخرة ولهم عذاب الحريق في الدنيا؛ فقد روي أن المؤمنين كانت تفيض أرواحهم قبل وصولهم إلى النار فلم يحسّوا بعذابها، وأن النار خرجت من الأخاديد فأحرقت الكافرين. إن الذين آمنوا بالله وعملوا الصالحات لهم جنات تجري من تحت أشجارها وقصورها الأنهار، ذلك الفوز الكبير، لأنه نجاة من النار أولاً ودخول الجنة ثانياً.", "h": ["تقرير عقيدة البعث والجزاء.", "فضل يومي الجمعة وعرفة.", "بيان ما يُبتلى به المؤمنون في هذه الحياة ويصبرون، فيكون جزاؤهم الجنة.", "الترهيب والترغيب في ذكر جزاء الكافرين والمؤمنين الصالحين."], "k": "«وما نقموا منهم إلا أن يؤمنوا بالله»… ثبتوا على إيمانهم أمام النار؛ فهل أثبت على ديني أمام كلمة سخرية؟"}, {"lbl": "الآيات ١٢ – ٢٢", "q": "إِنَّ بَطۡشَ رَبِّكَ لَشَدِيدٌ ﴿١٢﴾ إِنَّهُۥ هُوَ يُبۡدِئُ وَيُعِيدُ ﴿١٣﴾ وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ ﴿١٤﴾ ذُو ٱلۡعَرۡشِ ٱلۡمَجِيدُ ﴿١٥﴾ فَعَّالٞ لِّمَا يُرِيدُ ﴿١٦﴾ هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ ﴿١٧﴾ فِرۡعَوۡنَ وَثَمُودَ ﴿١٨﴾ بَلِ ٱلَّذِينَ كَفَرُواْ فِي تَكۡذِيبٖ ﴿١٩﴾ وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطُۢ ﴿٢٠﴾ بَلۡ هُوَ قُرۡءَانٞ مَّجِيدٞ ﴿٢١﴾ فِي لَوۡحٖ مَّحۡفُوظِۭ ﴿٢٢﴾", "w": [["يُبدئ ويُعيد", "يبدئ الخلق ويعيده بعد فنائه، ويبدئ العذاب ويعيده."], ["الغفور الودود", "الغفور لذنوب عباده المؤمنين، المتودّد لأوليائه."], ["ذو العرش المجيد", "صاحب العرش إذ هو خالقه ومالكه، والمجيد المستحق لكمال صفات العظمة."], ["في تكذيب", "بما ذُكر في سياق الآيات السابقة."], ["من ورائهم محيط", "هم في قبضته وتحت سلطانه وقهره."], ["قرآن مجيد", "كريم عظيم."], ["في لوح محفوظ", "محفوظ من الشياطين، والمراد به اللوح المحفوظ."]], "m": "لما ذكر تعالى ما توعّد به الذين فتنوا المؤمنين والمؤمنات من أجل إيمانهم، أخبر رسوله ﷺ، معرّضاً بمشركي قومه وطغاتهم الذين آذوا المؤمنين في مكة، فقال: إن بطش ربك لشديد، أي إن أخذه إذا أخذ أليم شديد، ودلّل على ذلك بقوله: إنه هو يبدئ ويعيد، فالقادر على البدء والإعادة بطشه شديد؛ يبدئ الخلق ثم يعيده، ويبدئ العذاب أيضاً ثم يعيده. وهو الغفور الودود، فهو قادر على البطش بأعدائه، وهو الغفور لذنوب أوليائه المتودّد إليهم، ذو العرش خلقاً وملكاً، المجيد العظيم الكريم، فعّال لما يريد، إذ لا يُكره تعالى على شيء. هل أتاك حديث الجنود فرعون وثمود، كيف أهلكهم الله لما طغوا وبغوا وكفروا وعصوا؟ نعم قد أتاك وقرأته على قومك الكافرين ولم ينتفعوا به، لأنهم يعيشون في تكذيب لك يحيط بهم من الكبر والحسد والجهل. والله من ورائهم محيط، فهم في قبضته وتحت قهره وسلطانه، لا يخفى عليه منهم شيء، ولا يحول بينه وبينهم متى أراد أخذهم شيء. بل هو قرآن مجيد في لوح محفوظ، ردٌّ على المشركين الذين قالوا في القرآن إنه سحر وشعر وأساطير الأولين، فليس هو كما ادّعوا، وإنما هو قرآن كريم في لوح محفوظ من الشياطين فلا تمسّه ولا تقربه، ومن غير الشياطين من سائر الخلق أجمعين.", "h": ["تهديد الظلمة بالعذاب عقوبة في الدنيا وفي الآخرة.", "إن الله تعالى لكرمه يتودّد لأوليائه من عباده.", "فائدة القصص هي الموعظة تحصل للعبد، فلا يترك واجباً ولا يغشى محرّماً.", "بيان إحاطة الله تعالى بعباده وأنهم في قبضته وتحت سلطانه.", "شرف القرآن الكريم، وإثبات اللوح المحفوظ وتقريره."], "k": "«وهو الغفور الودود»… ربي يتودّد إليّ بنعمه وهو غني عني؛ فهل أتودّد إليه بطاعة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 439;
insert into public.tdb_cards(topic, i, body) select 439, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١١", "q": "وَٱلسَّمَآءِ ذَاتِ ٱلۡبُرُوجِ ﴿١﴾ وَٱلۡيَوۡمِ ٱلۡمَوۡعُودِ ﴿٢﴾ وَشَاهِدٖ وَمَشۡهُودٖ ﴿٣﴾ قُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ ﴿٤﴾ ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ ﴿٥﴾ إِذۡ هُمۡ عَلَيۡهَا قُعُودٞ ﴿٦﴾ وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِٱلۡمُؤۡمِنِينَ شُهُودٞ ﴿٧﴾ وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ ﴿٨﴾ ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿٩﴾ إِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ ﴿١٠﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِيرُ ﴿١١﴾", "w": [["ذات البروج", "منازل الشمس والقمر الاثنا عشر برجاً."], ["واليوم الموعود", "يوم القيامة، إذ وعد الله عباده أن يجمعهم فيه لفصل القضاء."], ["وشاهد", "يوم الجمعة."], ["ومشهود", "يوم عرفة."], ["قُتل أصحاب الأخدود", "لُعن أصحاب الأخدود."], ["الأخدود", "الحفرة تُحفر في الأرض، وجمعه أخاديد."], ["إذ هم عليها قعود", "على حافتها وشفيرها."], ["وما نقموا منهم", "ما عابوا عليهم شيئاً سوى إيمانهم بالله تعالى."]], "m": "أقسم تعالى بالسماء ذات البروج، وهي منازل الشمس والقمر، وباليوم الموعود وهو يوم القيامة، إذ وعد عباده أن يجمعهم فيه ليحكم بينهم فيما كانوا فيه يختلفون، وبالشاهد وهو يوم الجمعة، وبالمشهود وهو يوم عرفة. وجواب القسم قد يكون محذوفاً تقديره: لتُبعثُنّ ثم لتُنبّؤنّ، لأن السورة مكية والسور المكية تعالج العقيدة: التوحيد والنبوة والبعث والجزاء، وجائز أن يكون الجواب: لقد قُتل، أي لُعن أصحاب الأخدود، وهي حفر حفرها الكفار وأجّجوا فيها ناراً، وأتوا بالمؤمنين المخالفين لدينهم وعرضوا عليهم الكفر أو الإلقاء في النار، فاختاروا الإلقاء في النار مع بقاء إيمانهم، حتى إن امرأة كانت ترضع صبياً فأحجمت عن إلقاء نفسها مع طفلها في النار، فأنطق الله الصبي فقال لها: يا أمّاه امضي فإنك على الحق، فاقتحمت النار. إذ هم على حافة النار قاعدون، وهم على ما يفعلون بالمؤمنين من الإلقاء في النار حضور، لم يغيّروا منكراً ولم يأمروا بمعروف. وما عابوا عليهم شيئاً سوى إيمانهم بالله العزيز في انتقامه لأوليائه، الحميد لآلائه ونعمه على سائر خلقه، الذي له ملك السموات والأرض، وهو على كل شيء شهيد؛ فكيف يُنكر على المؤمن إيمانه بربه ذي الصفات العلا؟ إن الذين فتنوا المؤمنين والمؤمنات عن دينهم فأحرقوهم بالنار ثم لم يتوبوا، فلهم عذاب جهنم في الآخرة ولهم عذاب الحريق في الدنيا؛ فقد روي أن المؤمنين كانت تفيض أرواحهم قبل وصولهم إلى النار فلم يحسّوا بعذابها، وأن النار خرجت من الأخاديد فأحرقت الكافرين. إن الذين آمنوا بالله وعملوا الصالحات لهم جنات تجري من تحت أشجارها وقصورها الأنهار، ذلك الفوز الكبير، لأنه نجاة من النار أولاً ودخول الجنة ثانياً.", "h": ["تقرير عقيدة البعث والجزاء.", "فضل يومي الجمعة وعرفة.", "بيان ما يُبتلى به المؤمنون في هذه الحياة ويصبرون، فيكون جزاؤهم الجنة.", "الترهيب والترغيب في ذكر جزاء الكافرين والمؤمنين الصالحين."], "k": "«وما نقموا منهم إلا أن يؤمنوا بالله»… ثبتوا على إيمانهم أمام النار؛ فهل أثبت على ديني أمام كلمة سخرية؟"}, {"lbl": "الآيات ١٢ – ٢٢", "q": "إِنَّ بَطۡشَ رَبِّكَ لَشَدِيدٌ ﴿١٢﴾ إِنَّهُۥ هُوَ يُبۡدِئُ وَيُعِيدُ ﴿١٣﴾ وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ ﴿١٤﴾ ذُو ٱلۡعَرۡشِ ٱلۡمَجِيدُ ﴿١٥﴾ فَعَّالٞ لِّمَا يُرِيدُ ﴿١٦﴾ هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ ﴿١٧﴾ فِرۡعَوۡنَ وَثَمُودَ ﴿١٨﴾ بَلِ ٱلَّذِينَ كَفَرُواْ فِي تَكۡذِيبٖ ﴿١٩﴾ وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطُۢ ﴿٢٠﴾ بَلۡ هُوَ قُرۡءَانٞ مَّجِيدٞ ﴿٢١﴾ فِي لَوۡحٖ مَّحۡفُوظِۭ ﴿٢٢﴾", "w": [["يُبدئ ويُعيد", "يبدئ الخلق ويعيده بعد فنائه، ويبدئ العذاب ويعيده."], ["الغفور الودود", "الغفور لذنوب عباده المؤمنين، المتودّد لأوليائه."], ["ذو العرش المجيد", "صاحب العرش إذ هو خالقه ومالكه، والمجيد المستحق لكمال صفات العظمة."], ["في تكذيب", "بما ذُكر في سياق الآيات السابقة."], ["من ورائهم محيط", "هم في قبضته وتحت سلطانه وقهره."], ["قرآن مجيد", "كريم عظيم."], ["في لوح محفوظ", "محفوظ من الشياطين، والمراد به اللوح المحفوظ."]], "m": "لما ذكر تعالى ما توعّد به الذين فتنوا المؤمنين والمؤمنات من أجل إيمانهم، أخبر رسوله ﷺ، معرّضاً بمشركي قومه وطغاتهم الذين آذوا المؤمنين في مكة، فقال: إن بطش ربك لشديد، أي إن أخذه إذا أخذ أليم شديد، ودلّل على ذلك بقوله: إنه هو يبدئ ويعيد، فالقادر على البدء والإعادة بطشه شديد؛ يبدئ الخلق ثم يعيده، ويبدئ العذاب أيضاً ثم يعيده. وهو الغفور الودود، فهو قادر على البطش بأعدائه، وهو الغفور لذنوب أوليائه المتودّد إليهم، ذو العرش خلقاً وملكاً، المجيد العظيم الكريم، فعّال لما يريد، إذ لا يُكره تعالى على شيء. هل أتاك حديث الجنود فرعون وثمود، كيف أهلكهم الله لما طغوا وبغوا وكفروا وعصوا؟ نعم قد أتاك وقرأته على قومك الكافرين ولم ينتفعوا به، لأنهم يعيشون في تكذيب لك يحيط بهم من الكبر والحسد والجهل. والله من ورائهم محيط، فهم في قبضته وتحت قهره وسلطانه، لا يخفى عليه منهم شيء، ولا يحول بينه وبينهم متى أراد أخذهم شيء. بل هو قرآن مجيد في لوح محفوظ، ردٌّ على المشركين الذين قالوا في القرآن إنه سحر وشعر وأساطير الأولين، فليس هو كما ادّعوا، وإنما هو قرآن كريم في لوح محفوظ من الشياطين فلا تمسّه ولا تقربه، ومن غير الشياطين من سائر الخلق أجمعين.", "h": ["تهديد الظلمة بالعذاب عقوبة في الدنيا وفي الآخرة.", "إن الله تعالى لكرمه يتودّد لأوليائه من عباده.", "فائدة القصص هي الموعظة تحصل للعبد، فلا يترك واجباً ولا يغشى محرّماً.", "بيان إحاطة الله تعالى بعباده وأنهم في قبضته وتحت سلطانه.", "شرف القرآن الكريم، وإثبات اللوح المحفوظ وتقريره."], "k": "«وهو الغفور الودود»… ربي يتودّد إليّ بنعمه وهو غني عني؛ فهل أتودّد إليه بطاعة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (440, 86, 1, 17, 'سورة الطارق ١ – ١٧', 'الطارق: إن كل نفس لما عليها حافظ', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 440) = $j$[{"lbl": "الآيات ١ – ١٧", "q": "وَٱلسَّمَآءِ وَٱلطَّارِقِ ﴿١﴾ وَمَآ أَدۡرَىٰكَ مَا ٱلطَّارِقُ ﴿٢﴾ ٱلنَّجۡمُ ٱلثَّاقِبُ ﴿٣﴾ إِن كُلُّ نَفۡسٖ لَّمَّا عَلَيۡهَا حَافِظٞ ﴿٤﴾ فَلۡيَنظُرِ ٱلۡإِنسَٰنُ مِمَّ خُلِقَ ﴿٥﴾ خُلِقَ مِن مَّآءٖ دَافِقٖ ﴿٦﴾ يَخۡرُجُ مِنۢ بَيۡنِ ٱلصُّلۡبِ وَٱلتَّرَآئِبِ ﴿٧﴾ إِنَّهُۥ عَلَىٰ رَجۡعِهِۦ لَقَادِرٞ ﴿٨﴾ يَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ ﴿٩﴾ فَمَا لَهُۥ مِن قُوَّةٖ وَلَا نَاصِرٖ ﴿١٠﴾ وَٱلسَّمَآءِ ذَاتِ ٱلرَّجۡعِ ﴿١١﴾ وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ ﴿١٢﴾ إِنَّهُۥ لَقَوۡلٞ فَصۡلٞ ﴿١٣﴾ وَمَا هُوَ بِٱلۡهَزۡلِ ﴿١٤﴾ إِنَّهُمۡ يَكِيدُونَ كَيۡدٗا ﴿١٥﴾ وَأَكِيدُ كَيۡدٗا ﴿١٦﴾ فَمَهِّلِ ٱلۡكَٰفِرِينَ أَمۡهِلۡهُمۡ رُوَيۡدَۢا ﴿١٧﴾", "w": [["والطارق", "كل ما يطرق ويأتي ليلاً، وسُمّي النجم طارقاً لطلوعه ليلاً."], ["النجم الثاقب", "الثريا، والثاقب المضيء الذي يثقب الظلام بنوره."], ["لما عليها حافظ", "إلا عليها حافظ من الملائكة يحفظ عملها."], ["من ماء دافق", "ماء ذي اندفاق، بمعنى مدفوق مصبوب في الرحم."], ["من بين الصلب والترائب", "الصلب عظم الظهر من الرجل، والترائب عظام الصدر."], ["يوم تُبلى السرائر", "تُختبر ضمائر القلوب في العقائد والنيات، والسرائر جمع سريرة."], ["ذات الرجع", "ذات المطر لرجوعه كل حين، والرجع من أسماء المطر."], ["ذات الصدع", "التصدّع والتشقّق بالنبات."], ["لقول فصل", "يفصل بين الحق والباطل، وفي الخصومات يقطعها بالحكم الجازم."], ["وما هو بالهزل", "ليس باللعب والباطل، بل هو الجد كل الجد."], ["يكيدون كيداً", "يعملون المكائد للنبي ﷺ."], ["وأكيد كيداً", "أستدرجهم من حيث لا يعلمون لأوقعهم في المكروه."], ["رويداً", "زمناً قليلاً، وقد أخذهم في بدر."]], "m": "أقسم تعالى بالسماء والطارق، ولما كان لفظ الطارق يشمل كل آتٍ بليل وأراد طارقاً معيّناً، فخّم من شأنه بالاستفهام عنه فقال: وما أدراك ما الطارق؟ ثم بيّنه بقوله: النجم الثاقب، والمراد به الثريا. والمقسم عليه: إن كل نفس لما عليها حافظ، أي ما كل نفس إلا عليها حافظ من ربها يحفظ عملها ويحصي عليها ما كسبت من خير وشر. فلينظر الإنسان الكافر المكذّب بالبعث: من أي شيء خُلق؟ خُلق من ماء دافق، وهو المني يُصبّ في الرحم، يخرج من بين صلب الرجل، وهو عظام ظهره، وترائب المرأة، وهي محل القلادة من صدرها، وقد جاء العلم الحديث فأثبت أن ماء الرجل وماء المرأة يخرجان مما ذكر الله تعالى، وصدق الله العظيم. إن الذي خلقه من ماء دافق فجعله بشراً سوياً ثم أماته، قادر على إرجاعه حياً كما كان، وذلك يوم تُختبر الضمائر وتُكشف الأسرار وتُعرف العقائد والنيات الصالحة من الفاسدة، ويومها ليس لهذا المكذّب قوة يدفع بها عن نفسه عذاب ربه، ولا ناصر ينصره فيخلّصه. وأقسم تعالى بالسماء ذات السحب والأمطار، والأرض ذات التشقّق عن النباتات والزروع، على أن القرآن الكريم قول فصل وحكم عدل في كل مختلف فيه من الحق والباطل، فما أخبر به من أنه لا إله إلا الله وأن محمداً رسول الله وأن الساعة آتية لا ريب فيها هو الحق الذي لا مرية فيه، وليس القرآن باللعب الباطل. إن كفار قريش يمكرون بالنبي ﷺ وبدعوته ويكيدون لهما كيداً، وأنا أكيد لهم كيداً، فمن يغلب: كيد الخالق المالك أم المخلوق المملوك؟ فمهّل الكافرين يا رسولنا، أمهلهم قليلاً، وقد أنجز الله وعده لرسوله والمؤمنين، فلم تمضِ إلا سنيّات قلائل حتى لم يبقَ في مكة سلطان إلا لله، ولا معبود يُعبد إلا الله.", "h": ["تقرير المعاد والبعث والجزاء.", "تقرير أن أعمال العباد محصاة محفوظة، وأن الحساب يجري بحسبها.", "بيان مادة تكوين الإنسان ومصدر تكوين تلك المادة.", "التحذير من إسرار الشر وإخفاء الباطل وإظهار خلاف ما في الضمائر، فإن الله تعالى عليم بذلك، وسيختبر عباده في كل ما يُسرّون ويُخفون.", "إثبات أن القرآن قول فصل ليس فيه من الباطل شيء، وقد تأكّد هذا بمرور الزمان، فقد صدقت أنباؤه ونجحت أحكامه في تحقيق الأمن والاستقرار."], "k": "«يوم تُبلى السرائر»… ما في قلبي الآن سيُكشف يوماً؛ فهل أرضى أن يُرى؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 440;
insert into public.tdb_cards(topic, i, body) select 440, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٧", "q": "وَٱلسَّمَآءِ وَٱلطَّارِقِ ﴿١﴾ وَمَآ أَدۡرَىٰكَ مَا ٱلطَّارِقُ ﴿٢﴾ ٱلنَّجۡمُ ٱلثَّاقِبُ ﴿٣﴾ إِن كُلُّ نَفۡسٖ لَّمَّا عَلَيۡهَا حَافِظٞ ﴿٤﴾ فَلۡيَنظُرِ ٱلۡإِنسَٰنُ مِمَّ خُلِقَ ﴿٥﴾ خُلِقَ مِن مَّآءٖ دَافِقٖ ﴿٦﴾ يَخۡرُجُ مِنۢ بَيۡنِ ٱلصُّلۡبِ وَٱلتَّرَآئِبِ ﴿٧﴾ إِنَّهُۥ عَلَىٰ رَجۡعِهِۦ لَقَادِرٞ ﴿٨﴾ يَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ ﴿٩﴾ فَمَا لَهُۥ مِن قُوَّةٖ وَلَا نَاصِرٖ ﴿١٠﴾ وَٱلسَّمَآءِ ذَاتِ ٱلرَّجۡعِ ﴿١١﴾ وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ ﴿١٢﴾ إِنَّهُۥ لَقَوۡلٞ فَصۡلٞ ﴿١٣﴾ وَمَا هُوَ بِٱلۡهَزۡلِ ﴿١٤﴾ إِنَّهُمۡ يَكِيدُونَ كَيۡدٗا ﴿١٥﴾ وَأَكِيدُ كَيۡدٗا ﴿١٦﴾ فَمَهِّلِ ٱلۡكَٰفِرِينَ أَمۡهِلۡهُمۡ رُوَيۡدَۢا ﴿١٧﴾", "w": [["والطارق", "كل ما يطرق ويأتي ليلاً، وسُمّي النجم طارقاً لطلوعه ليلاً."], ["النجم الثاقب", "الثريا، والثاقب المضيء الذي يثقب الظلام بنوره."], ["لما عليها حافظ", "إلا عليها حافظ من الملائكة يحفظ عملها."], ["من ماء دافق", "ماء ذي اندفاق، بمعنى مدفوق مصبوب في الرحم."], ["من بين الصلب والترائب", "الصلب عظم الظهر من الرجل، والترائب عظام الصدر."], ["يوم تُبلى السرائر", "تُختبر ضمائر القلوب في العقائد والنيات، والسرائر جمع سريرة."], ["ذات الرجع", "ذات المطر لرجوعه كل حين، والرجع من أسماء المطر."], ["ذات الصدع", "التصدّع والتشقّق بالنبات."], ["لقول فصل", "يفصل بين الحق والباطل، وفي الخصومات يقطعها بالحكم الجازم."], ["وما هو بالهزل", "ليس باللعب والباطل، بل هو الجد كل الجد."], ["يكيدون كيداً", "يعملون المكائد للنبي ﷺ."], ["وأكيد كيداً", "أستدرجهم من حيث لا يعلمون لأوقعهم في المكروه."], ["رويداً", "زمناً قليلاً، وقد أخذهم في بدر."]], "m": "أقسم تعالى بالسماء والطارق، ولما كان لفظ الطارق يشمل كل آتٍ بليل وأراد طارقاً معيّناً، فخّم من شأنه بالاستفهام عنه فقال: وما أدراك ما الطارق؟ ثم بيّنه بقوله: النجم الثاقب، والمراد به الثريا. والمقسم عليه: إن كل نفس لما عليها حافظ، أي ما كل نفس إلا عليها حافظ من ربها يحفظ عملها ويحصي عليها ما كسبت من خير وشر. فلينظر الإنسان الكافر المكذّب بالبعث: من أي شيء خُلق؟ خُلق من ماء دافق، وهو المني يُصبّ في الرحم، يخرج من بين صلب الرجل، وهو عظام ظهره، وترائب المرأة، وهي محل القلادة من صدرها، وقد جاء العلم الحديث فأثبت أن ماء الرجل وماء المرأة يخرجان مما ذكر الله تعالى، وصدق الله العظيم. إن الذي خلقه من ماء دافق فجعله بشراً سوياً ثم أماته، قادر على إرجاعه حياً كما كان، وذلك يوم تُختبر الضمائر وتُكشف الأسرار وتُعرف العقائد والنيات الصالحة من الفاسدة، ويومها ليس لهذا المكذّب قوة يدفع بها عن نفسه عذاب ربه، ولا ناصر ينصره فيخلّصه. وأقسم تعالى بالسماء ذات السحب والأمطار، والأرض ذات التشقّق عن النباتات والزروع، على أن القرآن الكريم قول فصل وحكم عدل في كل مختلف فيه من الحق والباطل، فما أخبر به من أنه لا إله إلا الله وأن محمداً رسول الله وأن الساعة آتية لا ريب فيها هو الحق الذي لا مرية فيه، وليس القرآن باللعب الباطل. إن كفار قريش يمكرون بالنبي ﷺ وبدعوته ويكيدون لهما كيداً، وأنا أكيد لهم كيداً، فمن يغلب: كيد الخالق المالك أم المخلوق المملوك؟ فمهّل الكافرين يا رسولنا، أمهلهم قليلاً، وقد أنجز الله وعده لرسوله والمؤمنين، فلم تمضِ إلا سنيّات قلائل حتى لم يبقَ في مكة سلطان إلا لله، ولا معبود يُعبد إلا الله.", "h": ["تقرير المعاد والبعث والجزاء.", "تقرير أن أعمال العباد محصاة محفوظة، وأن الحساب يجري بحسبها.", "بيان مادة تكوين الإنسان ومصدر تكوين تلك المادة.", "التحذير من إسرار الشر وإخفاء الباطل وإظهار خلاف ما في الضمائر، فإن الله تعالى عليم بذلك، وسيختبر عباده في كل ما يُسرّون ويُخفون.", "إثبات أن القرآن قول فصل ليس فيه من الباطل شيء، وقد تأكّد هذا بمرور الزمان، فقد صدقت أنباؤه ونجحت أحكامه في تحقيق الأمن والاستقرار."], "k": "«يوم تُبلى السرائر»… ما في قلبي الآن سيُكشف يوماً؛ فهل أرضى أن يُرى؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (441, 87, 1, 19, 'سورة الأعلى ١ – ١٩', 'الأعلى: سبح اسم ربك الأعلى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 441) = $j$[{"lbl": "الآيات ١ – ١٣", "q": "سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى ﴿١﴾ ٱلَّذِي خَلَقَ فَسَوَّىٰ ﴿٢﴾ وَٱلَّذِي قَدَّرَ فَهَدَىٰ ﴿٣﴾ وَٱلَّذِيٓ أَخۡرَجَ ٱلۡمَرۡعَىٰ ﴿٤﴾ فَجَعَلَهُۥ غُثَآءً أَحۡوَىٰ ﴿٥﴾ سَنُقۡرِئُكَ فَلَا تَنسَىٰٓ ﴿٦﴾ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ وَمَا يَخۡفَىٰ ﴿٧﴾ وَنُيَسِّرُكَ لِلۡيُسۡرَىٰ ﴿٨﴾ فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ ﴿٩﴾ سَيَذَّكَّرُ مَن يَخۡشَىٰ ﴿١٠﴾ وَيَتَجَنَّبُهَا ٱلۡأَشۡقَى ﴿١١﴾ ٱلَّذِي يَصۡلَى ٱلنَّارَ ٱلۡكُبۡرَىٰ ﴿١٢﴾ ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ ﴿١٣﴾", "w": [["سبّح اسم ربك", "نزّه اسم ربك أن يُسمّى به غيره، وأن يُذكر بسخرية أو لعب، فلا يُذكر إلا بإجلال وإكبار، ونزّه ربك عما لا يليق به من الشرك والصاحبة والولد والشبيه والنظير."], ["الأعلى", "فوق كل شيء والقاهر لكل شيء."], ["الذي خلق فسوّى", "خلق الإنسان فسوّى أعضاءه بأن جعلها متناسبة غير متفاوتة."], ["والذي قدّر فهدى", "قدّر ما شاء لمن شاء، وهداه إلى إتيان ما قدّره له وعليه."], ["والذي أخرج المرعى", "أنبت العشب والكلأ."], ["فجعله غثاءً أحوى", "بعد الخضرة والنضرة هشيماً يابساً أسود."], ["سنقرئك فلا تنسى", "القرآن، فلا تنساه بإذننا."], ["إلا ما شاء الله", "إلا ما شئنا أن ننسيكه، وذلك إذا أراد الله نسخ شيء من القرآن بلفظه."], ["ونيسّرك لليسرى", "للشريعة السهلة، وهي الإسلام."], ["فذكّر إن نفعت الذكرى", "عِظ بالقرآن، نفعت الذكرى أو لم تنفع."], ["ويتجنّبها", "يترك الذكرى جانباً فلا يلتفت إليها."], ["الأشقى", "الكافر الذي كُتبت شقاوته أزلاً."], ["النار الكبرى", "نار الدار الآخرة."], ["لا يموت فيها ولا يحيا", "لا يموت فيستريح، ولا يحيا فيهنأ."]], "m": "هذا أمر من الله تعالى لرسوله ﷺ، وأمته تابعة له، بأن ينزّه اسم ربه عن أن يُسمّى به غيره، أو أن يُذكر في مكان قذر، أو أن يُذكر بعدم إجلال واحترام. والأعلى صفة للرب تعالى دالة على علوّه على خلقه، فالخلق كله تحته وهو قاهر له وحاكم فيه، الذي أوجد المخلوقات من العدم وسوّى خلق كل مخلوق بحسب ذاته فعدّل أجزاءه فلا تفاوت فيها، والذي قدّر الأشياء في كتاب المقادير وهدى كل مخلوق إلى ما قُدّر له أو عليه، فهو طالب له حتى يدركه في زمانه ومكانه وعلى الصورة التي قُدّر عليها، والذي أخرج ما ترعاه البهائم من الحشيش والعشب، فجعله بعد الخضرة والنضرة هشيماً يابساً بين سواد وبياض. فالآية الأولى أمرٌ بتنزيه اسم الله، والأربع بعدها في التعريف به سبحانه حتى يُعظّم اسمه وذاته. ثم قال: سنقرئك فلا تنسى، وهذه عِدَة من الله لرسوله؛ إذ كان ﷺ إذا جاءه جبريل بالآيات يخاف نسيانها فيستعجل قراءتها قبل فراغ جبريل ﵇، فطمأنه ربه أنه لا ينسى ما يقرئه جبريل، إلا ما شاء الله أن ينسيه لما أراد نسخه. إنه يعلم الجهر وما يخفى، وهذا تعليل لقدرته على أن يحفظ على رسوله القرآن، فهو يعلم ما يجهر به المرء وما يخفيه. ونيسّرك للطريقة السهلة الخالية من الحرج، وهي الشريعة الإسلامية. فذكّر نفعت الذكرى أو لم تنفع، لأنه ﷺ مأمور بالبلاغ، فيبلّغ الكافر والمؤمن ويذكّرهما، والأمر بعدُ لله. سيذّكّر ويتّعظ من يخشى عقاب الله لإيمانه به ومعرفته له، ويتجنّب الذكرى أشقى الفريقين، الذي يدخل النار الكبرى يوم القيامة، ثم لا يموت فيها فيستريح، ولا يحيا فيهنأ ويسعد، إذ الشقاء لازمه.", "h": ["وجوب تسبيح اسم الله وتنزيهه عما لا يليق به، كوجوب تنزيه ذات الله تعالى عن كل ما لا يليق بجلاله وكماله.", "مشروعية قول «سبحان ربي الأعلى» عند قراءة هذه الآية: «سبّح اسم ربك الأعلى».", "وجوب التسبيح في السجود: سبحان ربي الأعلى ثلاثاً فأكثر.", "مشروعية قراءة هذه السورة في الوتر: يقرأ في الركعة الأولى بالفاتحة والأعلى، وفي الثانية بالفاتحة والكافرون، وفي ركعة الوتر بالفاتحة والصمد أو الصمد والمعوّذتين.", "أحبّ الرسول ﷺ سورة الأعلى لأن ربه بشّره فيها بشارتين عظيمتين: الأولى أنه ييسّره لليسرى، ومن ثَمّ ما خُيّر بين شيئين إلا اختار أيسرهما، والثانية أنه حفظه من النسيان، ولذا كان يصلّي بهذه السورة في الجمع والأعياد والوتر."], "k": "«سبّح اسم ربك الأعلى»… أقولها في سجودي كل يوم؛ فهل يحضر قلبي معناها؟"}, {"lbl": "الآيات ١٤ – ١٩", "q": "قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ ﴿١٤﴾ وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ ﴿١٥﴾ بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ﴿١٦﴾ وَٱلۡأٓخِرَةُ خَيۡرٞ وَأَبۡقَىٰٓ ﴿١٧﴾ إِنَّ هَٰذَا لَفِي ٱلصُّحُفِ ٱلۡأُولَىٰ ﴿١٨﴾ صُحُفِ إِبۡرَٰهِيمَ وَمُوسَىٰ ﴿١٩﴾", "w": [["أفلح", "فاز بأن نجا من النار ودخل الجنة."], ["من تزكّى", "تطهّر بالإيمان وصالح الأعمال بعد التخلّي عن الشرك."], ["وذكر اسم ربه", "في كل أحيانه: عند الأكل والشرب والنوم والقيام منه، وفي الصلاة وخارجها، من تسبيح وتحميد وتهليل."], ["فصلّى", "الصلوات الخمس والنوافل من رواتب وغيرها."], ["تؤثرون", "تقدّمون وتفضّلون الدنيا على الآخرة."], ["إن هذا لفي الصحف الأولى", "من قوله «قد أفلح» إلى قوله «وأبقى»."], ["صحف إبراهيم", "وكانت عشر صحف."], ["وموسى", "توراته."]], "m": "يخبر تعالى بفلاح عبد مؤمن زكّى نفسه، أي طهّرها بالإيمان وصالح الأعمال، وذكر اسم ربه في كل أحيانه: عند القيام من النوم، وعند الوضوء وبعده، وفي الصلاة وبعدها، وعند الأكل والشرب واللباس، فلا يخلو من ذكر الله ساعة، فصلّى الصلوات الخمس وصلّى النوافل. والفلاح الفوز، وهو النجاة من المرهوب والظفر بالمرغوب المحبوب، والمراد به هنا النجاة من النار ودخول الجنة. بل تؤثرون الحياة الدنيا أيها الناس، أي تفضّلونها على الآخرة، فتعملون لها وتنسون الآخرة فلا تقدّمون لها شيئاً، هذا هو طبعكم إلا من ذكر الله فصلّى بعد أن آمن واهتدى، في حين أن الآخرة خير من الدنيا نوعاً وأبقى؛ قال بعض الحكماء: لو كانت الدنيا من ذهب والآخرة من خزف لاختار العاقل ما يبقى على ما يفنى. إن هذا، من قوله «قد أفلح» إلى قوله «خير وأبقى»، مذكور في صحف إبراهيم، وكانت عشر صحف، وفي توراة موسى.", "h": ["الترغيب في الزكاة والذكر والصلاة، ويحصل هذا للمسلم كل عيد فطر، إذ يُخرج زكاة الفطر أولاً، ثم يأتي المسجد يكبّر، ثم يصلّي، حتى إن بعضهم يرى أن هذه الآية نزلت في ذلك.", "التزهيد في الدنيا والترغيب في الآخرة، لفناء الدنيا وبقاء الآخرة.", "توافق الكتب السماوية دليل أنها وحي الله وكتبه أنزلها على رسله ﵈."], "k": "«بل تؤثرون الحياة الدنيا والآخرة خير وأبقى»… في قراراتي اليومية الصغيرة، أيّهما أقدّم فعلاً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 441;
insert into public.tdb_cards(topic, i, body) select 441, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٣", "q": "سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى ﴿١﴾ ٱلَّذِي خَلَقَ فَسَوَّىٰ ﴿٢﴾ وَٱلَّذِي قَدَّرَ فَهَدَىٰ ﴿٣﴾ وَٱلَّذِيٓ أَخۡرَجَ ٱلۡمَرۡعَىٰ ﴿٤﴾ فَجَعَلَهُۥ غُثَآءً أَحۡوَىٰ ﴿٥﴾ سَنُقۡرِئُكَ فَلَا تَنسَىٰٓ ﴿٦﴾ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ وَمَا يَخۡفَىٰ ﴿٧﴾ وَنُيَسِّرُكَ لِلۡيُسۡرَىٰ ﴿٨﴾ فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ ﴿٩﴾ سَيَذَّكَّرُ مَن يَخۡشَىٰ ﴿١٠﴾ وَيَتَجَنَّبُهَا ٱلۡأَشۡقَى ﴿١١﴾ ٱلَّذِي يَصۡلَى ٱلنَّارَ ٱلۡكُبۡرَىٰ ﴿١٢﴾ ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ ﴿١٣﴾", "w": [["سبّح اسم ربك", "نزّه اسم ربك أن يُسمّى به غيره، وأن يُذكر بسخرية أو لعب، فلا يُذكر إلا بإجلال وإكبار، ونزّه ربك عما لا يليق به من الشرك والصاحبة والولد والشبيه والنظير."], ["الأعلى", "فوق كل شيء والقاهر لكل شيء."], ["الذي خلق فسوّى", "خلق الإنسان فسوّى أعضاءه بأن جعلها متناسبة غير متفاوتة."], ["والذي قدّر فهدى", "قدّر ما شاء لمن شاء، وهداه إلى إتيان ما قدّره له وعليه."], ["والذي أخرج المرعى", "أنبت العشب والكلأ."], ["فجعله غثاءً أحوى", "بعد الخضرة والنضرة هشيماً يابساً أسود."], ["سنقرئك فلا تنسى", "القرآن، فلا تنساه بإذننا."], ["إلا ما شاء الله", "إلا ما شئنا أن ننسيكه، وذلك إذا أراد الله نسخ شيء من القرآن بلفظه."], ["ونيسّرك لليسرى", "للشريعة السهلة، وهي الإسلام."], ["فذكّر إن نفعت الذكرى", "عِظ بالقرآن، نفعت الذكرى أو لم تنفع."], ["ويتجنّبها", "يترك الذكرى جانباً فلا يلتفت إليها."], ["الأشقى", "الكافر الذي كُتبت شقاوته أزلاً."], ["النار الكبرى", "نار الدار الآخرة."], ["لا يموت فيها ولا يحيا", "لا يموت فيستريح، ولا يحيا فيهنأ."]], "m": "هذا أمر من الله تعالى لرسوله ﷺ، وأمته تابعة له، بأن ينزّه اسم ربه عن أن يُسمّى به غيره، أو أن يُذكر في مكان قذر، أو أن يُذكر بعدم إجلال واحترام. والأعلى صفة للرب تعالى دالة على علوّه على خلقه، فالخلق كله تحته وهو قاهر له وحاكم فيه، الذي أوجد المخلوقات من العدم وسوّى خلق كل مخلوق بحسب ذاته فعدّل أجزاءه فلا تفاوت فيها، والذي قدّر الأشياء في كتاب المقادير وهدى كل مخلوق إلى ما قُدّر له أو عليه، فهو طالب له حتى يدركه في زمانه ومكانه وعلى الصورة التي قُدّر عليها، والذي أخرج ما ترعاه البهائم من الحشيش والعشب، فجعله بعد الخضرة والنضرة هشيماً يابساً بين سواد وبياض. فالآية الأولى أمرٌ بتنزيه اسم الله، والأربع بعدها في التعريف به سبحانه حتى يُعظّم اسمه وذاته. ثم قال: سنقرئك فلا تنسى، وهذه عِدَة من الله لرسوله؛ إذ كان ﷺ إذا جاءه جبريل بالآيات يخاف نسيانها فيستعجل قراءتها قبل فراغ جبريل ﵇، فطمأنه ربه أنه لا ينسى ما يقرئه جبريل، إلا ما شاء الله أن ينسيه لما أراد نسخه. إنه يعلم الجهر وما يخفى، وهذا تعليل لقدرته على أن يحفظ على رسوله القرآن، فهو يعلم ما يجهر به المرء وما يخفيه. ونيسّرك للطريقة السهلة الخالية من الحرج، وهي الشريعة الإسلامية. فذكّر نفعت الذكرى أو لم تنفع، لأنه ﷺ مأمور بالبلاغ، فيبلّغ الكافر والمؤمن ويذكّرهما، والأمر بعدُ لله. سيذّكّر ويتّعظ من يخشى عقاب الله لإيمانه به ومعرفته له، ويتجنّب الذكرى أشقى الفريقين، الذي يدخل النار الكبرى يوم القيامة، ثم لا يموت فيها فيستريح، ولا يحيا فيهنأ ويسعد، إذ الشقاء لازمه.", "h": ["وجوب تسبيح اسم الله وتنزيهه عما لا يليق به، كوجوب تنزيه ذات الله تعالى عن كل ما لا يليق بجلاله وكماله.", "مشروعية قول «سبحان ربي الأعلى» عند قراءة هذه الآية: «سبّح اسم ربك الأعلى».", "وجوب التسبيح في السجود: سبحان ربي الأعلى ثلاثاً فأكثر.", "مشروعية قراءة هذه السورة في الوتر: يقرأ في الركعة الأولى بالفاتحة والأعلى، وفي الثانية بالفاتحة والكافرون، وفي ركعة الوتر بالفاتحة والصمد أو الصمد والمعوّذتين.", "أحبّ الرسول ﷺ سورة الأعلى لأن ربه بشّره فيها بشارتين عظيمتين: الأولى أنه ييسّره لليسرى، ومن ثَمّ ما خُيّر بين شيئين إلا اختار أيسرهما، والثانية أنه حفظه من النسيان، ولذا كان يصلّي بهذه السورة في الجمع والأعياد والوتر."], "k": "«سبّح اسم ربك الأعلى»… أقولها في سجودي كل يوم؛ فهل يحضر قلبي معناها؟"}, {"lbl": "الآيات ١٤ – ١٩", "q": "قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ ﴿١٤﴾ وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ ﴿١٥﴾ بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ﴿١٦﴾ وَٱلۡأٓخِرَةُ خَيۡرٞ وَأَبۡقَىٰٓ ﴿١٧﴾ إِنَّ هَٰذَا لَفِي ٱلصُّحُفِ ٱلۡأُولَىٰ ﴿١٨﴾ صُحُفِ إِبۡرَٰهِيمَ وَمُوسَىٰ ﴿١٩﴾", "w": [["أفلح", "فاز بأن نجا من النار ودخل الجنة."], ["من تزكّى", "تطهّر بالإيمان وصالح الأعمال بعد التخلّي عن الشرك."], ["وذكر اسم ربه", "في كل أحيانه: عند الأكل والشرب والنوم والقيام منه، وفي الصلاة وخارجها، من تسبيح وتحميد وتهليل."], ["فصلّى", "الصلوات الخمس والنوافل من رواتب وغيرها."], ["تؤثرون", "تقدّمون وتفضّلون الدنيا على الآخرة."], ["إن هذا لفي الصحف الأولى", "من قوله «قد أفلح» إلى قوله «وأبقى»."], ["صحف إبراهيم", "وكانت عشر صحف."], ["وموسى", "توراته."]], "m": "يخبر تعالى بفلاح عبد مؤمن زكّى نفسه، أي طهّرها بالإيمان وصالح الأعمال، وذكر اسم ربه في كل أحيانه: عند القيام من النوم، وعند الوضوء وبعده، وفي الصلاة وبعدها، وعند الأكل والشرب واللباس، فلا يخلو من ذكر الله ساعة، فصلّى الصلوات الخمس وصلّى النوافل. والفلاح الفوز، وهو النجاة من المرهوب والظفر بالمرغوب المحبوب، والمراد به هنا النجاة من النار ودخول الجنة. بل تؤثرون الحياة الدنيا أيها الناس، أي تفضّلونها على الآخرة، فتعملون لها وتنسون الآخرة فلا تقدّمون لها شيئاً، هذا هو طبعكم إلا من ذكر الله فصلّى بعد أن آمن واهتدى، في حين أن الآخرة خير من الدنيا نوعاً وأبقى؛ قال بعض الحكماء: لو كانت الدنيا من ذهب والآخرة من خزف لاختار العاقل ما يبقى على ما يفنى. إن هذا، من قوله «قد أفلح» إلى قوله «خير وأبقى»، مذكور في صحف إبراهيم، وكانت عشر صحف، وفي توراة موسى.", "h": ["الترغيب في الزكاة والذكر والصلاة، ويحصل هذا للمسلم كل عيد فطر، إذ يُخرج زكاة الفطر أولاً، ثم يأتي المسجد يكبّر، ثم يصلّي، حتى إن بعضهم يرى أن هذه الآية نزلت في ذلك.", "التزهيد في الدنيا والترغيب في الآخرة، لفناء الدنيا وبقاء الآخرة.", "توافق الكتب السماوية دليل أنها وحي الله وكتبه أنزلها على رسله ﵈."], "k": "«بل تؤثرون الحياة الدنيا والآخرة خير وأبقى»… في قراراتي اليومية الصغيرة، أيّهما أقدّم فعلاً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (442, 88, 1, 26, 'سورة الغاشية ١ – ٢٦', 'الغاشية: أفلا ينظرون إلى الإبل كيف خلقت', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 442) = $j$[{"lbl": "الآيات ١ – ١٦", "q": "هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡغَٰشِيَةِ ﴿١﴾ وُجُوهٞ يَوۡمَئِذٍ خَٰشِعَةٌ ﴿٢﴾ عَامِلَةٞ نَّاصِبَةٞ ﴿٣﴾ تَصۡلَىٰ نَارًا حَامِيَةٗ ﴿٤﴾ تُسۡقَىٰ مِنۡ عَيۡنٍ ءَانِيَةٖ ﴿٥﴾ لَّيۡسَ لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِيعٖ ﴿٦﴾ لَّا يُسۡمِنُ وَلَا يُغۡنِي مِن جُوعٖ ﴿٧﴾ وُجُوهٞ يَوۡمَئِذٖ نَّاعِمَةٞ ﴿٨﴾ لِّسَعۡيِهَا رَاضِيَةٞ ﴿٩﴾ فِي جَنَّةٍ عَالِيَةٖ ﴿١٠﴾ لَّا تَسۡمَعُ فِيهَا لَٰغِيَةٗ ﴿١١﴾ فِيهَا عَيۡنٞ جَارِيَةٞ ﴿١٢﴾ فِيهَا سُرُرٞ مَّرۡفُوعَةٞ ﴿١٣﴾ وَأَكۡوَابٞ مَّوۡضُوعَةٞ ﴿١٤﴾ وَنَمَارِقُ مَصۡفُوفَةٞ ﴿١٥﴾ وَزَرَابِيُّ مَبۡثُوثَةٌ ﴿١٦﴾", "w": [["هل أتاك", "قد جاءك."], ["الغاشية", "القيامة، وسُمّيت الغاشية لأنها تغشى الناس بأهوالها."], ["خاشعة", "ذليلة، أُطلقت الوجوه وأُريد أصحابها."], ["عاملة ناصبة", "ذات نصب وتعب بالسلاسل والأغلال وتكليف شاقّ الأعمال."], ["تصلى ناراً حامية", "ترد ناراً قد اشتدّت حرارتها."], ["من عين آنية", "بلغت أناها من الحرارة، أي منتهاها."], ["إلا من ضريع", "أخبث طعام وأنتنه، وضريع الدنيا نبت يقال له الشبرق لا ترعاه الدواب."], ["ناعمة", "حسنة نضرة."], ["لسعيها راضية", "لعملها الصالحات في الدنيا راضية في الآخرة لما رأت من ثوابها."], ["لاغية", "كلمة لاغية من اللغو والباطل."], ["وأكواب", "أقداح لا عُرى لها، موضوعة على حافة العين للشرب."], ["ونمارق مصفوفة", "مساند مصفوفة، الواحدة إلى جنب الأخرى للاستناد إليها."], ["وزرابيّ مبثوثة", "بُسط وطنافس مفروشة هنا وهناك مبسوطة."]], "m": "هذا خطاب من الله تعالى لرسوله ﷺ: هل أتاك نبأ الغاشية وخبرها العظيم؟ إن لم يكن أتاك فقد أتاك الآن، إنه حديث القيامة التي تغشى الناس بأهوالها وصعوبة مواقفها، وإليك عرضاً سريعاً لبعض ما يجري فيها: وجوه يومئذ ذليلة، ذات نصب وتعب من جرّ السلاسل والأغلال وتكليف أشقّ الأعمال، ترد ناراً حامية، وتُسقى فيها من عين قد بلغت غايتها في حرارتها، هذا هو الشراب، أما الطعام فليس لهم طعام إلا من ضريع قبيح اللون خبيث الطعم منتن الريح، لا يُسمن آكله ولا يغنيه من جوع. هذه حال من كفر بالله وآياته ولقائه ورسوله، أو فجر عن طاعة الله ورسوله فترك الفرائض وغشي المحارم. ووجوه يومئذ ناعمة نضرة حسنة، راضية لسعيها في الدنيا، وهو إيمانها وصبرها وجهادها وتقواها وعملها الصالح، رضي أصحابها بأعمالهم لما رأوا من ثوابها، في جنة عالية، لا تسمع فيها كلمة باطلة تنغّص سعادتهم ولا كلمة نابية تقلق راحتهم، فيها عين جارية من غير أخدود حُفر لها، فيها سرر مرفوعة قدراً وحالاً ومكاناً، وأكواب من ذهب وفضة موضوعة لشربهم، إن شاءوا شربوا بأيديهم أو ناولتهم غلمانهم، ووسائد قد صُفّت للراحة والاتّكاء الواحدة إلى جنب الأخرى، وطنافس مفروشة هنا وهناك مبسوطة. هذه لمحة خاطفة عن الدار الآخرة، ذكرى للذاكرين.", "h": ["تقرير عقيدة البعث والجزاء بذكر عرض سريع لها.", "من أسماء القيامة الغاشية، لأنها تغشى الناس بأهوالها.", "بيان أن في النار نصباً وتعباً، على عكس الجنة فإنها لا نصب فيها ولا تعب.", "من مؤلمات النفس البشرية لغو الكلام وكذبه وباطله، وهو ما ينزّه عنه المؤمنون أنفسهم."], "k": "«لا تسمع فيها لاغية»… الجنة خالية من اللغو؛ فهل أنزّه لساني ومجالسي عنه من الآن؟"}, {"lbl": "الآيات ١٧ – ٢٦", "q": "أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ ﴿١٧﴾ وَإِلَى ٱلسَّمَآءِ كَيۡفَ رُفِعَتۡ ﴿١٨﴾ وَإِلَى ٱلۡجِبَالِ كَيۡفَ نُصِبَتۡ ﴿١٩﴾ وَإِلَى ٱلۡأَرۡضِ كَيۡفَ سُطِحَتۡ ﴿٢٠﴾ فَذَكِّرۡ إِنَّمَآ أَنتَ مُذَكِّرٞ ﴿٢١﴾ لَّسۡتَ عَلَيۡهِم بِمُصَيۡطِرٍ ﴿٢٢﴾ إِلَّا مَن تَوَلَّىٰ وَكَفَرَ ﴿٢٣﴾ فَيُعَذِّبُهُ ٱللَّهُ ٱلۡعَذَابَ ٱلۡأَكۡبَرَ ﴿٢٤﴾ إِنَّ إِلَيۡنَآ إِيَابَهُمۡ ﴿٢٥﴾ ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم ﴿٢٦﴾", "w": [["أفلا ينظرون", "أينكرون البعث فلا ينظرون نظر اعتبار؟"], ["إلى الإبل كيف خُلقت", "خلقاً بديعاً معدولاً به عن سنن سائر المخلوقات."], ["وإلى السماء كيف رُفعت", "فوق الأرض بلا عمد ولا مستند."], ["وإلى الجبال كيف نُصبت", "على وجه الأرض نصباً ثابتاً لا يتزلزل."], ["وإلى الأرض كيف سُطحت", "بُسطت."], ["فذكّر", "ذكّرهم بنعم الله ودلائل توحيده."], ["بمسيطر", "بمسلّط."]], "m": "أينكرون البعث والجزاء وما أعدّ الله لأوليائه من النعيم المقيم ولأعدائه من عذاب الجحيم؟ أفلا ينظرون نظرة اعتبار إلى الإبل كيف خُلقت على تلك الصورة العجيبة، وذاك التسخير لها وما فيها من منافع، إذ يُشرب لبنها ويُركب ظهرها ويُؤكل لحمها؟ وإلى السماء بكواكبها وشمسها وقمرها كيف رُفعت بغير عمد يدعمها ولا سند يسندها؟ وإلى الجبال كيف نُصبت بعد خلق ترابها وإيجاد صخورها؟ وإلى الأرض بكل ما فيها كيف بُسطت للحياة عليها والسير فوقها وتعميرها؟ أفلا يدل ذلك كله على قدرة الخالق على إحياء الموتى وبعثهم ليحاسبهم ويجزيهم؟ فما للقوم لا ينظرون ولا يفكّرون! وبعد لفت أنظار المشركين إلى ما لو نظروا فيه لاهتدوا، أمر رسوله أن يقوم بالمهمة التي أُنيطت به، وهي التذكير دون الهداية التي هي لله وحده، فقال: فذكّر بمظاهر قدرتنا وآياتنا في الآفاق وآلائنا على العباد، إنما أنت مذكّر ليس غير، لست عليهم بمتسلّط تجبرهم على الإيمان والاستقامة، لكن من تولّى عن الإيمان فكفر بآياتنا ورسولنا ولقائنا فيعذّبه الله العذاب الأكبر، وهو عذاب الآخرة. إن إلينا لا إلى غيرنا رجوعهم، ثم إن علينا لا على غيرنا حسابهم، ومن ثَمّ نجزيهم الجزاء اللائق بهم؛ فلا يضرّك يا رسولنا إعراضهم، وحسبك تذكيرهم، فمن اهتدى نجا ونجاته لنفسه، ومن ضلّ فعاقبة ضلاله، وهي الخسران التام، عائدة عليه.", "h": ["تقرير البعث والجزاء بالدعوة إلى النظر إلى الأدلة الموجبة للإيمان به.", "بيان أن الداعي إلى الله تعالى مهمته الدعوة دون هداية القلوب، فإنها إلى الله تعالى وحده.", "بيان أن مصير البشرية إلى الله تعالى، وهي حال تقتضي الإيمان به وطاعته طلباً للنجاة من عذابه والفوز برحمته، وهو مطلب كل عاقل لو أن الناس يفكّرون."], "k": "«إنما أنت مذكّر لست عليهم بمسيطر»… حين أنصح أحداً، هل أكتفي بالتذكير بلطف وأترك الهداية لله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 442;
insert into public.tdb_cards(topic, i, body) select 442, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٦", "q": "هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡغَٰشِيَةِ ﴿١﴾ وُجُوهٞ يَوۡمَئِذٍ خَٰشِعَةٌ ﴿٢﴾ عَامِلَةٞ نَّاصِبَةٞ ﴿٣﴾ تَصۡلَىٰ نَارًا حَامِيَةٗ ﴿٤﴾ تُسۡقَىٰ مِنۡ عَيۡنٍ ءَانِيَةٖ ﴿٥﴾ لَّيۡسَ لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِيعٖ ﴿٦﴾ لَّا يُسۡمِنُ وَلَا يُغۡنِي مِن جُوعٖ ﴿٧﴾ وُجُوهٞ يَوۡمَئِذٖ نَّاعِمَةٞ ﴿٨﴾ لِّسَعۡيِهَا رَاضِيَةٞ ﴿٩﴾ فِي جَنَّةٍ عَالِيَةٖ ﴿١٠﴾ لَّا تَسۡمَعُ فِيهَا لَٰغِيَةٗ ﴿١١﴾ فِيهَا عَيۡنٞ جَارِيَةٞ ﴿١٢﴾ فِيهَا سُرُرٞ مَّرۡفُوعَةٞ ﴿١٣﴾ وَأَكۡوَابٞ مَّوۡضُوعَةٞ ﴿١٤﴾ وَنَمَارِقُ مَصۡفُوفَةٞ ﴿١٥﴾ وَزَرَابِيُّ مَبۡثُوثَةٌ ﴿١٦﴾", "w": [["هل أتاك", "قد جاءك."], ["الغاشية", "القيامة، وسُمّيت الغاشية لأنها تغشى الناس بأهوالها."], ["خاشعة", "ذليلة، أُطلقت الوجوه وأُريد أصحابها."], ["عاملة ناصبة", "ذات نصب وتعب بالسلاسل والأغلال وتكليف شاقّ الأعمال."], ["تصلى ناراً حامية", "ترد ناراً قد اشتدّت حرارتها."], ["من عين آنية", "بلغت أناها من الحرارة، أي منتهاها."], ["إلا من ضريع", "أخبث طعام وأنتنه، وضريع الدنيا نبت يقال له الشبرق لا ترعاه الدواب."], ["ناعمة", "حسنة نضرة."], ["لسعيها راضية", "لعملها الصالحات في الدنيا راضية في الآخرة لما رأت من ثوابها."], ["لاغية", "كلمة لاغية من اللغو والباطل."], ["وأكواب", "أقداح لا عُرى لها، موضوعة على حافة العين للشرب."], ["ونمارق مصفوفة", "مساند مصفوفة، الواحدة إلى جنب الأخرى للاستناد إليها."], ["وزرابيّ مبثوثة", "بُسط وطنافس مفروشة هنا وهناك مبسوطة."]], "m": "هذا خطاب من الله تعالى لرسوله ﷺ: هل أتاك نبأ الغاشية وخبرها العظيم؟ إن لم يكن أتاك فقد أتاك الآن، إنه حديث القيامة التي تغشى الناس بأهوالها وصعوبة مواقفها، وإليك عرضاً سريعاً لبعض ما يجري فيها: وجوه يومئذ ذليلة، ذات نصب وتعب من جرّ السلاسل والأغلال وتكليف أشقّ الأعمال، ترد ناراً حامية، وتُسقى فيها من عين قد بلغت غايتها في حرارتها، هذا هو الشراب، أما الطعام فليس لهم طعام إلا من ضريع قبيح اللون خبيث الطعم منتن الريح، لا يُسمن آكله ولا يغنيه من جوع. هذه حال من كفر بالله وآياته ولقائه ورسوله، أو فجر عن طاعة الله ورسوله فترك الفرائض وغشي المحارم. ووجوه يومئذ ناعمة نضرة حسنة، راضية لسعيها في الدنيا، وهو إيمانها وصبرها وجهادها وتقواها وعملها الصالح، رضي أصحابها بأعمالهم لما رأوا من ثوابها، في جنة عالية، لا تسمع فيها كلمة باطلة تنغّص سعادتهم ولا كلمة نابية تقلق راحتهم، فيها عين جارية من غير أخدود حُفر لها، فيها سرر مرفوعة قدراً وحالاً ومكاناً، وأكواب من ذهب وفضة موضوعة لشربهم، إن شاءوا شربوا بأيديهم أو ناولتهم غلمانهم، ووسائد قد صُفّت للراحة والاتّكاء الواحدة إلى جنب الأخرى، وطنافس مفروشة هنا وهناك مبسوطة. هذه لمحة خاطفة عن الدار الآخرة، ذكرى للذاكرين.", "h": ["تقرير عقيدة البعث والجزاء بذكر عرض سريع لها.", "من أسماء القيامة الغاشية، لأنها تغشى الناس بأهوالها.", "بيان أن في النار نصباً وتعباً، على عكس الجنة فإنها لا نصب فيها ولا تعب.", "من مؤلمات النفس البشرية لغو الكلام وكذبه وباطله، وهو ما ينزّه عنه المؤمنون أنفسهم."], "k": "«لا تسمع فيها لاغية»… الجنة خالية من اللغو؛ فهل أنزّه لساني ومجالسي عنه من الآن؟"}, {"lbl": "الآيات ١٧ – ٢٦", "q": "أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ ﴿١٧﴾ وَإِلَى ٱلسَّمَآءِ كَيۡفَ رُفِعَتۡ ﴿١٨﴾ وَإِلَى ٱلۡجِبَالِ كَيۡفَ نُصِبَتۡ ﴿١٩﴾ وَإِلَى ٱلۡأَرۡضِ كَيۡفَ سُطِحَتۡ ﴿٢٠﴾ فَذَكِّرۡ إِنَّمَآ أَنتَ مُذَكِّرٞ ﴿٢١﴾ لَّسۡتَ عَلَيۡهِم بِمُصَيۡطِرٍ ﴿٢٢﴾ إِلَّا مَن تَوَلَّىٰ وَكَفَرَ ﴿٢٣﴾ فَيُعَذِّبُهُ ٱللَّهُ ٱلۡعَذَابَ ٱلۡأَكۡبَرَ ﴿٢٤﴾ إِنَّ إِلَيۡنَآ إِيَابَهُمۡ ﴿٢٥﴾ ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم ﴿٢٦﴾", "w": [["أفلا ينظرون", "أينكرون البعث فلا ينظرون نظر اعتبار؟"], ["إلى الإبل كيف خُلقت", "خلقاً بديعاً معدولاً به عن سنن سائر المخلوقات."], ["وإلى السماء كيف رُفعت", "فوق الأرض بلا عمد ولا مستند."], ["وإلى الجبال كيف نُصبت", "على وجه الأرض نصباً ثابتاً لا يتزلزل."], ["وإلى الأرض كيف سُطحت", "بُسطت."], ["فذكّر", "ذكّرهم بنعم الله ودلائل توحيده."], ["بمسيطر", "بمسلّط."]], "m": "أينكرون البعث والجزاء وما أعدّ الله لأوليائه من النعيم المقيم ولأعدائه من عذاب الجحيم؟ أفلا ينظرون نظرة اعتبار إلى الإبل كيف خُلقت على تلك الصورة العجيبة، وذاك التسخير لها وما فيها من منافع، إذ يُشرب لبنها ويُركب ظهرها ويُؤكل لحمها؟ وإلى السماء بكواكبها وشمسها وقمرها كيف رُفعت بغير عمد يدعمها ولا سند يسندها؟ وإلى الجبال كيف نُصبت بعد خلق ترابها وإيجاد صخورها؟ وإلى الأرض بكل ما فيها كيف بُسطت للحياة عليها والسير فوقها وتعميرها؟ أفلا يدل ذلك كله على قدرة الخالق على إحياء الموتى وبعثهم ليحاسبهم ويجزيهم؟ فما للقوم لا ينظرون ولا يفكّرون! وبعد لفت أنظار المشركين إلى ما لو نظروا فيه لاهتدوا، أمر رسوله أن يقوم بالمهمة التي أُنيطت به، وهي التذكير دون الهداية التي هي لله وحده، فقال: فذكّر بمظاهر قدرتنا وآياتنا في الآفاق وآلائنا على العباد، إنما أنت مذكّر ليس غير، لست عليهم بمتسلّط تجبرهم على الإيمان والاستقامة، لكن من تولّى عن الإيمان فكفر بآياتنا ورسولنا ولقائنا فيعذّبه الله العذاب الأكبر، وهو عذاب الآخرة. إن إلينا لا إلى غيرنا رجوعهم، ثم إن علينا لا على غيرنا حسابهم، ومن ثَمّ نجزيهم الجزاء اللائق بهم؛ فلا يضرّك يا رسولنا إعراضهم، وحسبك تذكيرهم، فمن اهتدى نجا ونجاته لنفسه، ومن ضلّ فعاقبة ضلاله، وهي الخسران التام، عائدة عليه.", "h": ["تقرير البعث والجزاء بالدعوة إلى النظر إلى الأدلة الموجبة للإيمان به.", "بيان أن الداعي إلى الله تعالى مهمته الدعوة دون هداية القلوب، فإنها إلى الله تعالى وحده.", "بيان أن مصير البشرية إلى الله تعالى، وهي حال تقتضي الإيمان به وطاعته طلباً للنجاة من عذابه والفوز برحمته، وهو مطلب كل عاقل لو أن الناس يفكّرون."], "k": "«إنما أنت مذكّر لست عليهم بمسيطر»… حين أنصح أحداً، هل أكتفي بالتذكير بلطف وأترك الهداية لله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (443, 89, 1, 30, 'سورة الفجر ١ – ٣٠', 'الفجر: يا أيتها النفس المطمئنة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 443) = $j$[{"lbl": "الآيات ١ – ١٤", "q": "وَٱلۡفَجۡرِ ﴿١﴾ وَلَيَالٍ عَشۡرٖ ﴿٢﴾ وَٱلشَّفۡعِ وَٱلۡوَتۡرِ ﴿٣﴾ وَٱلَّيۡلِ إِذَا يَسۡرِ ﴿٤﴾ هَلۡ فِي ذَٰلِكَ قَسَمٞ لِّذِي حِجۡرٍ ﴿٥﴾ أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ ﴿٦﴾ إِرَمَ ذَاتِ ٱلۡعِمَادِ ﴿٧﴾ ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ ﴿٨﴾ وَثَمُودَ ٱلَّذِينَ جَابُواْ ٱلصَّخۡرَ بِٱلۡوَادِ ﴿٩﴾ وَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ ﴿١٠﴾ ٱلَّذِينَ طَغَوۡاْ فِي ٱلۡبِلَٰدِ ﴿١١﴾ فَأَكۡثَرُواْ فِيهَا ٱلۡفَسَادَ ﴿١٢﴾ فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ ﴿١٣﴾ إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ ﴿١٤﴾", "w": [["والفجر", "فجر كل يوم."], ["وليالٍ عشر", "عشر ذي الحجة."], ["والشفع والوتر", "الزوج والفرد."], ["والليل إذا يسر", "مقبلاً أو مدبراً."], ["لذي حِجر", "لذي حِجى وعقل."], ["بعاد إرم", "هي عاد الأولى."], ["التي لم يُخلق مثلها في البلاد", "إذ كان طول الرجل منهم اثني عشر ذراعاً."], ["جابوا الصخر بالواد", "قطعوا الصخر فجعلوا من الصخور بيوتاً بواديهم."], ["ذي الأوتاد", "صاحب الأوتاد، وهي أربعة أوتاد يشدّ إليها يدي ورجلي من يعذّبه."], ["طغوا في البلاد", "تجبّروا فيها وظلموا العباد."], ["سوط عذاب", "نوع عذاب."], ["لبالمرصاد", "يرصد أعمال العباد ليجزيهم عليها."]], "m": "أقسم الله تعالى بأربعة أشياء: الفجر، وفي كل يوم فجر، وليالٍ عشر، وهي العشر الأُوَل من ذي الحجة وفيها عرفة والأضحى، وقد أشاد بها رسول الله ﷺ فقال: «ما من أيام العمل الصالح فيها أحب إلى الله تعالى من عشر ذي الحجة»، والشفع وهو كل زوج، والوتر وهو كل فرد، فهو إقسام بالخلق كله، والليل إذا يسري مقبلاً أو مدبراً. هل في ذلك قسم لذي لبّ وعقل؟ نعم فيه قسم عظيم. وجواب القسم جائز أن يكون قوله: «إن ربك لبالمرصاد»، وجائز أن يكون مقدّراً مثل: لتُبعثُنّ ثم لتُنبّؤنّ بما عملتم، لأن السورة مكية تعالج العقيدة، ومن أكبر ما أنكره المشركون البعث والجزاء، ويدل عليه ما ذكر تعالى بعدُ من مظاهر قدرته: ألم تنظر بعين قلبك كيف فعل ربك بعاد إرم ذات العماد التي لم يُخلق مثلها في البلاد؟ وهي عاد الأولى قوم هود، الذين قالوا: من أشدّ منا قوة؟ وكان طول الرجل منهم اثني عشر ذراعاً، ولازم طول الأجسام أن تكون أعمدة المنازل طويلة تناسب سكانها، ومع هذه القوة أهلكهم الله الذي هو أشدّ منهم قوة. وانظر كيف فعل ربك بثمود، أصحاب الحجر شمال المدينة النبوية، قوم صالح، الذين قطعوا الصخور بواديهم نحتاً وجعلوا منها مساكن تقيهم برد الشتاء وحرّ الصيف، ومع هذا أهلكهم الله ذو القوة المتين. وانظر كيف فعل ربك بفرعون صاحب الأوتاد، إذ كان إذا أراد قتل من كفر به وخرج عن طاعته قيّد كل يد ورجل بوتد ثم قتله. الذين طغوا في البلاد فأكثروا فيها الفساد بالشرك والمعاصي، فصبّ عليهم ربك نوع عذاب من أنواع عذابه: أهلك عاداً بالريح الصرصر، وثمود بالصيحة، وفرعون بالغرق. إن ربك لبالمرصاد لكل جبار عاتٍ وطاغية ظالم، يرصد أعمال العباد ليجزيهم بها في الدنيا والآخرة؛ والمرصاد مكان تُرصد فيه تحركات الصيد أو العدو كبرج المراقبة، والرب تعالى فوق عرشه والخليقة كلها تحته، يعلم ظواهرها وبواطنها ويراقب أعمالها ويجزيها بحسبها.", "h": ["فضل الليالي العشر من أول ذي الحجة إلى العاشر منه.", "بيان مظاهر قدرة الله في إهلاك الأمم العاتية والشعوب الظالمة، مستلزم لقدرته تعالى على البعث والجزاء، وللتوحيد والنبوة، وهو ما أنكره أهل مكة.", "التحذير من عذاب الله ونقمه، فإنه تعالى بالمرصاد، فليحذر المنحرفون عن سبيل الله، والحاكمون بغير شرعه، والعاملون بغير هداه، أن يصبّ عليهم سوط عذاب."], "k": "«إن ربك لبالمرصاد»… أعمالي كلها تحت نظره؛ فهل أعمل الليلة ما أحب أن يراه مني؟"}, {"lbl": "الآيات ١٥ – ٢٠", "q": "فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ ﴿١٥﴾ وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ ﴿١٦﴾ كَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ ﴿١٧﴾ وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ﴿١٨﴾ وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلٗا لَّمّٗا ﴿١٩﴾ وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا ﴿٢٠﴾", "w": [["فأما الإنسان", "الكافر المشرك."], ["ابتلاه", "اختبره."], ["فأكرمه ونعّمه", "بالمال والجاه، ونعّمه بالخيرات."], ["أكرمن", "فضّلني لما لي من مزايا على غيري."], ["فقدر عليه رزقه", "ضيّقه ولم يوسّعه عليه."], ["أهانن", "أذلّني بالفقر، ولم يشكر الله على ما وهبه من سلامة جوارحه والعافية."], ["كلا", "ليس الأمر كما يرى هذا الكافر ويعتقد ويقول."], ["التراث", "الميراث."], ["أكلاً لمّاً", "أكلاً شديداً، إذ يلمّون نصيب النساء والأطفال إلى مالهم فلا يورّثونهم من التركة."], ["حباً جمّاً", "حباً شديداً كثيراً."]], "m": "تقدّم قوله تعالى: «إن ربك لبالمرصاد»، وهو دالّ على أن الله تعالى يحب من عبده أن يعبده ويشكره ليكرمه في دار كرامته، ويخوّفه من معاصيه ويرغّبه في طاعته؛ فالله لا يرضى لعباده الكفر ويحب لهم الشكر. فأما الإنسان المشرك إذا ما اختبره ربه فأكرمه بالمال والولد والجاه، ونعّمه بالأرزاق والخيرات لينظر أيشكر أم يكفر، فيقول مفاخراً: ربي أكرمني، أي فضّلني على غيري لما لي من فضائل ومزايا لم تكن لهؤلاء الفقراء. وأما إذا ما اختبره فضيّق عليه رزقه لينظر أيصبر أم يجزع، فيقول: ربي أذلّني فأفقرني. كلا، فارتدعوا أيها الماديون الذين تقيسون الأمور كلها بمقاييس المادة؛ فالله يوسّع الرزق اختباراً للعبد: هل يذكر نعم الله ويشكرها بالإيمان والطاعة؟ ويضيّق الرزق امتحاناً: هل يصبر العبد لقضاء ربه أو يجزع؟ وإنما أنتم ترون أن في التوسعة إكراماً وفي التضييق إهانة، ونظريتكم المادية هذه أتتكم من حبكم الدنيا واغتراركم بها، ويشهد بذلك إهانتكم لليتامى وعدم إكرامكم لهم لضعفهم وعجزهم، وأنكم لا تحضّون أنفسكم ولا غيركم على إطعام المساكين وهم جياع أمامكم، وأنكم تأكلون الميراث أكلاً شديداً، تضمّون مال الورثة من الأطفال والنساء إلى أموالكم وتحرمونهم، وأنكم تحبون المال حباً قوياً شديداً. كلا، ارتدعوا واخرجوا من دائرة هذه النظرية المادية قبل حلول العذاب.", "h": ["النظرية المادية لم تكن حديثة عهد، إذ عرفها الماديون في مكة من مشركي قريش قبل أربعة عشر قرناً.", "وجوب إكرام اليتامى، والحضّ على إطعام الجياع من فقراء ومساكين.", "وجوب إعطاء المواريث لمستحقيها، ذكوراً أو إناثاً، صغاراً أو كباراً.", "التنديد بحب المال الذي يحمل على منع الحقوق، ويزن الأمور بميزانه قوة وضعفاً."], "k": "«فيقول ربي أهانن»… حين يضيق رزقي، هل أراه إهانة أم اختباراً لصبري؟ وحين يتّسع، هل أشكر؟"}, {"lbl": "الآيات ٢١ – ٣٠", "q": "كَلَّآۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكّٗا دَكّٗا ﴿٢١﴾ وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا ﴿٢٢﴾ وَجِاْيٓءَ يَوۡمَئِذِۭ بِجَهَنَّمَۚ يَوۡمَئِذٖ يَتَذَكَّرُ ٱلۡإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ ﴿٢٣﴾ يَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي ﴿٢٤﴾ فَيَوۡمَئِذٖ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٞ ﴿٢٥﴾ وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٞ ﴿٢٦﴾ يَـٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ ﴿٢٧﴾ ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرۡضِيَّةٗ ﴿٢٨﴾ فَٱدۡخُلِي فِي عِبَٰدِي ﴿٢٩﴾ وَٱدۡخُلِي جَنَّتِي ﴿٣٠﴾", "w": [["إذا دُكّت الأرض دكاً", "حُرّكت حركة شديدة وزُلزلت زلزالاً قوياً فلم يبقَ عليها شاخص."], ["والملك صفاً صفاً", "والملائكة صفاً بعد صف."], ["وجيء يومئذ بجهنم", "تُجرّ بسبعين ألف زمام، كل زمام بأيدي سبعين ألف ملك."], ["يتذكّر الإنسان", "الكافر ما قالت له الرسل من وعد الله ووعيده يوم لقائه."], ["وأنّى له الذكرى", "لا تنفعه في هذا اليوم الذكرى."], ["قدّمت لحياتي", "الإيمان وصالح الأعمال."], ["لا يعذّب عذابه أحد", "لا يعذّب مثل عذاب الله أحد في قوته وشدته."], ["ولا يوثق وثاقه أحد", "ولا يوثق أحد مثل وثاق الله ﷻ."], ["يا أيتها النفس المطمئنة", "المؤمنة الآمنة اليوم من العذاب لما لاح لها من بشائر النجاة."], ["ارجعي إلى ربك", "إلى جواره في دار كرامته، أي الجنة."], ["فادخلي في عبادي", "في جملة عبادي المؤمنين المتقين."], ["وادخلي جنتي", "دار كرامتي لأوليائي."]], "m": "إذا دُكّت الأرض دكاً دكاً، وجاء ربك لفصل القضاء، والملائكة صفاً بعد صف، وجيء يومئذ بجهنم تُجرّ بسبعين ألف زمام، كل زمام بأيدي سبعين ألف ملك، في هذا اليوم يتذكّر الإنسان المفرّط المعرض عن دعوة الرسل الكافر بلقاء الله والجزاء، وأنّى له الذكرى! وماذا يتذكّر وقد كان كفره عريضاً وشرّه مستطيراً؟ وهل تنفعه الذكرى؟ يقول نادماً متحسّراً: يا ليتني قدّمت لحياتي، أي هذه الحياة الماثلة بين يديه، وهل ينفعه التمنّي؟ ففي هذا اليوم يقضي الله بعذاب أهل الكفر والشرك والفجور، فيُوثقون في السلاسل ويُغلّون في الأغلال، ويذوقون العذاب والنكال، أمرٌ ما عرفه الناس في الدنيا أيام كانوا يعذّبون المؤمنين ويوثقونهم في الحبال؛ فلا يعذّب أحد في الدنيا، مهما بالغ في التعذيب، عذاب الله في الآخرة، ولا يوثق أحد وثاقه. هذه صورة من عذاب الله لأعدائه، وأما أولياؤه الذين آمنوا وكانوا يتقون فها هم يُنادَون: يا أيتها النفس المطمئنة إلى صادق وعد الله ووعيده، فآمنت واتّقت وتخلّت عن الشرك والشر، فكانت مطمئنة بالإيمان وذكر الله، قريرة العين بحب الله ورسوله وما وعدها الرحمن، ارجعي إلى جوار ربك في دار كرامته، راضية بثواب الله لك، مرضيّاً عنك من مولاك، فادخلي في جملة عبادي الصالحين، وادخلي جنتي. يقال لها هذا عندما يُرسل الله الأرواح إلى الأجساد يوم المعاد، فتتلقّاها الملائكة بالسلام، وتُساق إلى ساحة العرض، وتُعطى كتابها بيمينها، ثم يقال لها: ادخلي في عبادي وادخلي جنتي بعد مرورها على الصراط.", "h": ["تقرير المعاد بعرض شبه تفصيلي ليوم القيامة.", "بيان اشتداد حسرة المفرّطين اليوم في طاعة الله تعالى وطاعة رسوله يوم القيامة.", "بشرى النفس المطمئنة بالإيمان وذكر الله ووعده ووعيده، عند الموت، وعند القيام من القبر، وعند تطاير الصحف."], "k": "«يا ليتني قدّمت لحياتي»… ما الذي أقدّمه اليوم حتى لا أقولها غداً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 443;
insert into public.tdb_cards(topic, i, body) select 443, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٤", "q": "وَٱلۡفَجۡرِ ﴿١﴾ وَلَيَالٍ عَشۡرٖ ﴿٢﴾ وَٱلشَّفۡعِ وَٱلۡوَتۡرِ ﴿٣﴾ وَٱلَّيۡلِ إِذَا يَسۡرِ ﴿٤﴾ هَلۡ فِي ذَٰلِكَ قَسَمٞ لِّذِي حِجۡرٍ ﴿٥﴾ أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ ﴿٦﴾ إِرَمَ ذَاتِ ٱلۡعِمَادِ ﴿٧﴾ ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ ﴿٨﴾ وَثَمُودَ ٱلَّذِينَ جَابُواْ ٱلصَّخۡرَ بِٱلۡوَادِ ﴿٩﴾ وَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ ﴿١٠﴾ ٱلَّذِينَ طَغَوۡاْ فِي ٱلۡبِلَٰدِ ﴿١١﴾ فَأَكۡثَرُواْ فِيهَا ٱلۡفَسَادَ ﴿١٢﴾ فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ ﴿١٣﴾ إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ ﴿١٤﴾", "w": [["والفجر", "فجر كل يوم."], ["وليالٍ عشر", "عشر ذي الحجة."], ["والشفع والوتر", "الزوج والفرد."], ["والليل إذا يسر", "مقبلاً أو مدبراً."], ["لذي حِجر", "لذي حِجى وعقل."], ["بعاد إرم", "هي عاد الأولى."], ["التي لم يُخلق مثلها في البلاد", "إذ كان طول الرجل منهم اثني عشر ذراعاً."], ["جابوا الصخر بالواد", "قطعوا الصخر فجعلوا من الصخور بيوتاً بواديهم."], ["ذي الأوتاد", "صاحب الأوتاد، وهي أربعة أوتاد يشدّ إليها يدي ورجلي من يعذّبه."], ["طغوا في البلاد", "تجبّروا فيها وظلموا العباد."], ["سوط عذاب", "نوع عذاب."], ["لبالمرصاد", "يرصد أعمال العباد ليجزيهم عليها."]], "m": "أقسم الله تعالى بأربعة أشياء: الفجر، وفي كل يوم فجر، وليالٍ عشر، وهي العشر الأُوَل من ذي الحجة وفيها عرفة والأضحى، وقد أشاد بها رسول الله ﷺ فقال: «ما من أيام العمل الصالح فيها أحب إلى الله تعالى من عشر ذي الحجة»، والشفع وهو كل زوج، والوتر وهو كل فرد، فهو إقسام بالخلق كله، والليل إذا يسري مقبلاً أو مدبراً. هل في ذلك قسم لذي لبّ وعقل؟ نعم فيه قسم عظيم. وجواب القسم جائز أن يكون قوله: «إن ربك لبالمرصاد»، وجائز أن يكون مقدّراً مثل: لتُبعثُنّ ثم لتُنبّؤنّ بما عملتم، لأن السورة مكية تعالج العقيدة، ومن أكبر ما أنكره المشركون البعث والجزاء، ويدل عليه ما ذكر تعالى بعدُ من مظاهر قدرته: ألم تنظر بعين قلبك كيف فعل ربك بعاد إرم ذات العماد التي لم يُخلق مثلها في البلاد؟ وهي عاد الأولى قوم هود، الذين قالوا: من أشدّ منا قوة؟ وكان طول الرجل منهم اثني عشر ذراعاً، ولازم طول الأجسام أن تكون أعمدة المنازل طويلة تناسب سكانها، ومع هذه القوة أهلكهم الله الذي هو أشدّ منهم قوة. وانظر كيف فعل ربك بثمود، أصحاب الحجر شمال المدينة النبوية، قوم صالح، الذين قطعوا الصخور بواديهم نحتاً وجعلوا منها مساكن تقيهم برد الشتاء وحرّ الصيف، ومع هذا أهلكهم الله ذو القوة المتين. وانظر كيف فعل ربك بفرعون صاحب الأوتاد، إذ كان إذا أراد قتل من كفر به وخرج عن طاعته قيّد كل يد ورجل بوتد ثم قتله. الذين طغوا في البلاد فأكثروا فيها الفساد بالشرك والمعاصي، فصبّ عليهم ربك نوع عذاب من أنواع عذابه: أهلك عاداً بالريح الصرصر، وثمود بالصيحة، وفرعون بالغرق. إن ربك لبالمرصاد لكل جبار عاتٍ وطاغية ظالم، يرصد أعمال العباد ليجزيهم بها في الدنيا والآخرة؛ والمرصاد مكان تُرصد فيه تحركات الصيد أو العدو كبرج المراقبة، والرب تعالى فوق عرشه والخليقة كلها تحته، يعلم ظواهرها وبواطنها ويراقب أعمالها ويجزيها بحسبها.", "h": ["فضل الليالي العشر من أول ذي الحجة إلى العاشر منه.", "بيان مظاهر قدرة الله في إهلاك الأمم العاتية والشعوب الظالمة، مستلزم لقدرته تعالى على البعث والجزاء، وللتوحيد والنبوة، وهو ما أنكره أهل مكة.", "التحذير من عذاب الله ونقمه، فإنه تعالى بالمرصاد، فليحذر المنحرفون عن سبيل الله، والحاكمون بغير شرعه، والعاملون بغير هداه، أن يصبّ عليهم سوط عذاب."], "k": "«إن ربك لبالمرصاد»… أعمالي كلها تحت نظره؛ فهل أعمل الليلة ما أحب أن يراه مني؟"}, {"lbl": "الآيات ١٥ – ٢٠", "q": "فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ ﴿١٥﴾ وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ ﴿١٦﴾ كَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ ﴿١٧﴾ وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ﴿١٨﴾ وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلٗا لَّمّٗا ﴿١٩﴾ وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا ﴿٢٠﴾", "w": [["فأما الإنسان", "الكافر المشرك."], ["ابتلاه", "اختبره."], ["فأكرمه ونعّمه", "بالمال والجاه، ونعّمه بالخيرات."], ["أكرمن", "فضّلني لما لي من مزايا على غيري."], ["فقدر عليه رزقه", "ضيّقه ولم يوسّعه عليه."], ["أهانن", "أذلّني بالفقر، ولم يشكر الله على ما وهبه من سلامة جوارحه والعافية."], ["كلا", "ليس الأمر كما يرى هذا الكافر ويعتقد ويقول."], ["التراث", "الميراث."], ["أكلاً لمّاً", "أكلاً شديداً، إذ يلمّون نصيب النساء والأطفال إلى مالهم فلا يورّثونهم من التركة."], ["حباً جمّاً", "حباً شديداً كثيراً."]], "m": "تقدّم قوله تعالى: «إن ربك لبالمرصاد»، وهو دالّ على أن الله تعالى يحب من عبده أن يعبده ويشكره ليكرمه في دار كرامته، ويخوّفه من معاصيه ويرغّبه في طاعته؛ فالله لا يرضى لعباده الكفر ويحب لهم الشكر. فأما الإنسان المشرك إذا ما اختبره ربه فأكرمه بالمال والولد والجاه، ونعّمه بالأرزاق والخيرات لينظر أيشكر أم يكفر، فيقول مفاخراً: ربي أكرمني، أي فضّلني على غيري لما لي من فضائل ومزايا لم تكن لهؤلاء الفقراء. وأما إذا ما اختبره فضيّق عليه رزقه لينظر أيصبر أم يجزع، فيقول: ربي أذلّني فأفقرني. كلا، فارتدعوا أيها الماديون الذين تقيسون الأمور كلها بمقاييس المادة؛ فالله يوسّع الرزق اختباراً للعبد: هل يذكر نعم الله ويشكرها بالإيمان والطاعة؟ ويضيّق الرزق امتحاناً: هل يصبر العبد لقضاء ربه أو يجزع؟ وإنما أنتم ترون أن في التوسعة إكراماً وفي التضييق إهانة، ونظريتكم المادية هذه أتتكم من حبكم الدنيا واغتراركم بها، ويشهد بذلك إهانتكم لليتامى وعدم إكرامكم لهم لضعفهم وعجزهم، وأنكم لا تحضّون أنفسكم ولا غيركم على إطعام المساكين وهم جياع أمامكم، وأنكم تأكلون الميراث أكلاً شديداً، تضمّون مال الورثة من الأطفال والنساء إلى أموالكم وتحرمونهم، وأنكم تحبون المال حباً قوياً شديداً. كلا، ارتدعوا واخرجوا من دائرة هذه النظرية المادية قبل حلول العذاب.", "h": ["النظرية المادية لم تكن حديثة عهد، إذ عرفها الماديون في مكة من مشركي قريش قبل أربعة عشر قرناً.", "وجوب إكرام اليتامى، والحضّ على إطعام الجياع من فقراء ومساكين.", "وجوب إعطاء المواريث لمستحقيها، ذكوراً أو إناثاً، صغاراً أو كباراً.", "التنديد بحب المال الذي يحمل على منع الحقوق، ويزن الأمور بميزانه قوة وضعفاً."], "k": "«فيقول ربي أهانن»… حين يضيق رزقي، هل أراه إهانة أم اختباراً لصبري؟ وحين يتّسع، هل أشكر؟"}, {"lbl": "الآيات ٢١ – ٣٠", "q": "كَلَّآۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكّٗا دَكّٗا ﴿٢١﴾ وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا ﴿٢٢﴾ وَجِاْيٓءَ يَوۡمَئِذِۭ بِجَهَنَّمَۚ يَوۡمَئِذٖ يَتَذَكَّرُ ٱلۡإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ ﴿٢٣﴾ يَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي ﴿٢٤﴾ فَيَوۡمَئِذٖ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٞ ﴿٢٥﴾ وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٞ ﴿٢٦﴾ يَـٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ ﴿٢٧﴾ ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرۡضِيَّةٗ ﴿٢٨﴾ فَٱدۡخُلِي فِي عِبَٰدِي ﴿٢٩﴾ وَٱدۡخُلِي جَنَّتِي ﴿٣٠﴾", "w": [["إذا دُكّت الأرض دكاً", "حُرّكت حركة شديدة وزُلزلت زلزالاً قوياً فلم يبقَ عليها شاخص."], ["والملك صفاً صفاً", "والملائكة صفاً بعد صف."], ["وجيء يومئذ بجهنم", "تُجرّ بسبعين ألف زمام، كل زمام بأيدي سبعين ألف ملك."], ["يتذكّر الإنسان", "الكافر ما قالت له الرسل من وعد الله ووعيده يوم لقائه."], ["وأنّى له الذكرى", "لا تنفعه في هذا اليوم الذكرى."], ["قدّمت لحياتي", "الإيمان وصالح الأعمال."], ["لا يعذّب عذابه أحد", "لا يعذّب مثل عذاب الله أحد في قوته وشدته."], ["ولا يوثق وثاقه أحد", "ولا يوثق أحد مثل وثاق الله ﷻ."], ["يا أيتها النفس المطمئنة", "المؤمنة الآمنة اليوم من العذاب لما لاح لها من بشائر النجاة."], ["ارجعي إلى ربك", "إلى جواره في دار كرامته، أي الجنة."], ["فادخلي في عبادي", "في جملة عبادي المؤمنين المتقين."], ["وادخلي جنتي", "دار كرامتي لأوليائي."]], "m": "إذا دُكّت الأرض دكاً دكاً، وجاء ربك لفصل القضاء، والملائكة صفاً بعد صف، وجيء يومئذ بجهنم تُجرّ بسبعين ألف زمام، كل زمام بأيدي سبعين ألف ملك، في هذا اليوم يتذكّر الإنسان المفرّط المعرض عن دعوة الرسل الكافر بلقاء الله والجزاء، وأنّى له الذكرى! وماذا يتذكّر وقد كان كفره عريضاً وشرّه مستطيراً؟ وهل تنفعه الذكرى؟ يقول نادماً متحسّراً: يا ليتني قدّمت لحياتي، أي هذه الحياة الماثلة بين يديه، وهل ينفعه التمنّي؟ ففي هذا اليوم يقضي الله بعذاب أهل الكفر والشرك والفجور، فيُوثقون في السلاسل ويُغلّون في الأغلال، ويذوقون العذاب والنكال، أمرٌ ما عرفه الناس في الدنيا أيام كانوا يعذّبون المؤمنين ويوثقونهم في الحبال؛ فلا يعذّب أحد في الدنيا، مهما بالغ في التعذيب، عذاب الله في الآخرة، ولا يوثق أحد وثاقه. هذه صورة من عذاب الله لأعدائه، وأما أولياؤه الذين آمنوا وكانوا يتقون فها هم يُنادَون: يا أيتها النفس المطمئنة إلى صادق وعد الله ووعيده، فآمنت واتّقت وتخلّت عن الشرك والشر، فكانت مطمئنة بالإيمان وذكر الله، قريرة العين بحب الله ورسوله وما وعدها الرحمن، ارجعي إلى جوار ربك في دار كرامته، راضية بثواب الله لك، مرضيّاً عنك من مولاك، فادخلي في جملة عبادي الصالحين، وادخلي جنتي. يقال لها هذا عندما يُرسل الله الأرواح إلى الأجساد يوم المعاد، فتتلقّاها الملائكة بالسلام، وتُساق إلى ساحة العرض، وتُعطى كتابها بيمينها، ثم يقال لها: ادخلي في عبادي وادخلي جنتي بعد مرورها على الصراط.", "h": ["تقرير المعاد بعرض شبه تفصيلي ليوم القيامة.", "بيان اشتداد حسرة المفرّطين اليوم في طاعة الله تعالى وطاعة رسوله يوم القيامة.", "بشرى النفس المطمئنة بالإيمان وذكر الله ووعده ووعيده، عند الموت، وعند القيام من القبر، وعند تطاير الصحف."], "k": "«يا ليتني قدّمت لحياتي»… ما الذي أقدّمه اليوم حتى لا أقولها غداً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (444, 90, 1, 20, 'سورة البلد ١ – ٢٠', 'البلد: فلا اقتحم العقبة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 444) = $j$[{"lbl": "الآيات ١ – ١٠", "q": "لَآ أُقۡسِمُ بِهَٰذَا ٱلۡبَلَدِ ﴿١﴾ وَأَنتَ حِلُّۢ بِهَٰذَا ٱلۡبَلَدِ ﴿٢﴾ وَوَالِدٖ وَمَا وَلَدَ ﴿٣﴾ لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ ﴿٤﴾ أَيَحۡسَبُ أَن لَّن يَقۡدِرَ عَلَيۡهِ أَحَدٞ ﴿٥﴾ يَقُولُ أَهۡلَكۡتُ مَالٗا لُّبَدًا ﴿٦﴾ أَيَحۡسَبُ أَن لَّمۡ يَرَهُۥٓ أَحَدٌ ﴿٧﴾ أَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ ﴿٨﴾ وَلِسَانٗا وَشَفَتَيۡنِ ﴿٩﴾ وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ ﴿١٠﴾", "w": [["لا أقسم بهذا البلد", "أقسم بمكة."], ["وأنت حِلّ بهذا البلد", "وأنت يا نبي الله محمد حلال بمكة."], ["ووالد وما ولد", "آدم وذريته."], ["في كبد", "في نصب وشدة، يكابد مصائب الدنيا وشدائد الآخرة."], ["أيحسب أن لن يقدر عليه أحد", "أيظن، وهو أبو الأشدّين بن كلدة، وكان قوياً شديداً؟"], ["أهلكت مالاً لُبداً", "يقول هذا مفاخراً بعداوة الرسول، وأنه أنفق فيها مالاً كثيراً."], ["أيحسب أن لم يره أحد", "أيظن أنه لم يره أحد؟ بل الله رآه وعلم ما أنفقه."], ["وهديناه النجدين", "بيّنّا له طريق الخير وطريق الشر بما فطرناه عليه، وبما أرسلنا به رسلنا وأنزلنا به كتبنا."]], "m": "أقسم الله تعالى بمكة بلده الأمين، والرسول ﷺ حِلٌّ بها يقاتل فيها، وذلك يوم الفتح الموعود، وقد قُتل يومها ابن خطل وهو متعلّق بأستار الكعبة، وأقسم بوالد وما ولد: آدم وذريته، ومنهم الأنبياء والأولياء. والمقسم عليه: لقد خلقنا الإنسان في كبد، أي في نصب وتعب لا يفارقانه منذ تخلّقه في بطن أمه إلى وفاته، ثم يكابد شدائد الآخرة، ثم إما إلى نعيم لا نصب معه ولا تعب، وإما إلى جحيم. وفي هذا الخبر المؤكد بأجلّ قسم ترويح على نفوس المؤمنين بمكة، وهم يعانون من الحاجة والاضطهاد والتعذيب من طغاة قريش، لا سيما المستضعفين كياسر وولده عمار وبلال وصهيب وخبيب، وحتى الرسول ﷺ لم يسلم من أذى المشركين؛ فإذا عرفوا طبيعة الحياة، وأن السعادة فيها أن يعلم المرء ألا سعادة بها، هان عليهم الأمر وخفّت آلامهم، كما هو تنبيه للطغاة لعلهم يصحون من سكرتهم بحب الدنيا. أيحسب هذا الإنسان، وقيل إنه أبو الأشدّين الذي أنفق ماله في عداوة الرسول ﷺ والإسلام، ويتبجّح قائلاً: أهلكت مالاً كثيراً بعضه فوق بعض، أيظن أن لم يره أحد؟ بلى إن الله قد رآه وعلم القدر الذي أنفقه، وسوف يحاسبه عليه ويجزيه به. ثم قرّره بقدرته ونعمه عليه: ألم نجعل له عينين يبصر بهما، ولساناً ينطق به ويفصح عن مراده، وشفتين يستر بهما فمه وأسنانه، وبيّنّا له طريق الخير والشر والسعادة والشقاء بما أودعنا في فطرته وبما أرسلنا به رسلنا؟ أنسي هذا كله ثم هو ينفق ما أعطيناه في حرب رسولنا وديننا؟", "h": ["شرف مكة وحرمتها، وعلو شأن الرسول ﷺ وسموّ مقامه وهو فيها، وقد أحلّها الله تعالى له ولم يحلّها لأحد سواه.", "شرف آدم وذريته الصالحين منهم.", "إعلان حقيقة، وهي أن الإنسان لا يبرح يعاني من أتعاب الحياة حتى الممات، ثم يستقبل شدائد الآخرة إلى أن يقرّ قراره، وينتهي تطوافه باستقراره في الجنة حيث يستريح نهائياً، أو في النار فيعذّب ويتعب أبداً."], "k": "«ألم نجعل له عينين ولساناً وشفتين»… فيمَ أستعمل عينيّ ولساني اليوم؟"}, {"lbl": "الآيات ١١ – ٢٠", "q": "فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ ﴿١١﴾ وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ ﴿١٢﴾ فَكُّ رَقَبَةٍ ﴿١٣﴾ أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ ﴿١٤﴾ يَتِيمٗا ذَا مَقۡرَبَةٍ ﴿١٥﴾ أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ ﴿١٦﴾ ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ ﴿١٧﴾ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ ﴿١٨﴾ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمۡ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ ﴿١٩﴾ عَلَيۡهِمۡ نَارٞ مُّؤۡصَدَةُۢ ﴿٢٠﴾", "w": [["فلا اقتحم", "فهلّا تجاوز."], ["العقبة", "الطريق الصعب في الجبل، والمراد به النجاة من النار."], ["فكّ رقبة", "أعتق رقبة في سبيل الله تعالى."], ["في يوم ذي مسغبة", "في يوم ذي مجاعة وشدة مؤونة."], ["يتيماً ذا مقربة", "أطعم يتيماً من ذوي قرابته."], ["مسكيناً ذا متربة", "أطعم فقيراً لاصقاً بالتراب ليس له شيء."], ["وتواصوا بالصبر", "أوصى بعضهم بعضاً بالصبر على طاعة الله."], ["وتواصوا بالمرحمة", "أوصى بعضهم بعضاً برحمة الفقراء والمساكين."], ["أصحاب الميمنة", "أصحاب اليمين، وهم المؤمنون المتقون."], ["أصحاب المشأمة", "أصحاب الشمال، وهم الكفار الفجار."], ["مؤصدة", "مطبقة لا نافذة لها ولا كوّة فلا يدخلها هواء."]], "m": "فهلّا أنفق أبو الأشدّين ما أنفقه في عداوة محمد ﷺ في سبيل الله، فاقتحم به العقبة فتجاوزها! وما أدراك ما العقبة؟ تفخيم لشأنها وتعظيم له. وبأربعة أمور تُقتحم العقبة ويُنجى من النار: فكّ رقبة، وقد ورد: «من أعتق رقبة مؤمنة فهي فداؤه من النار»، وإطعام في يوم مجاعة يتيماً ذا قرابة، أو مسكيناً لاصقاً بالأرض لحاجته وشدة فقره، وإيمان صادق بالله ورسوله وآيات الله ولقائه يحيا به قلبه، وتواصٍ بالصبر مع المؤمنين المستضعفين على الثبات على الحق ولزوم طريقه، وتواصٍ بالمرحمة مع أهل المال أن يرحموا الفقراء والمساكين فيسدّوا خلّتهم ويقضوا حاجتهم. بهذه الأربعة تُجتاز العقبة وينجو المرء من عذاب الله، وفي مثل هذا تُنفق الأموال، لا في الدسائس والمكر بالصالحين وخداع المؤمنين، أولئك أصحاب اليمين. ولما ذكر الإيمان والعمل الصالح، وهما المنجيان من عذاب الله، ذكر ضدّهما وهما المهلكان: الكفر والمعاصي، فقال: والذين كفروا بآياتنا هم أصحاب الشمال، عليهم نار مغلقة الأبواب مطبقة، هي جزاؤهم لأنهم كفروا بآيات الله وعصوا رسوله.", "h": ["التنديد بمن ينفق ماله في معصية الله ورسوله، والنصح له بالإنفاق في الخير، فإنه أجدى له وأنجى من عذاب الله.", "بيان أن عقبة عذاب الله يوم القيامة تُقتحم وتُجتاز بالإنفاق في سبيل الله، وبالإيمان والعمل الصالح والتواصي به.", "التنديد بالكفر، والوعيد الشديد لأهله."], "k": "«فلا اقتحم العقبة»… العقبة تُجتاز بإطعام ورحمة وتواصٍ بالصبر؛ أيّها أبدأ به هذا الأسبوع؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 444;
insert into public.tdb_cards(topic, i, body) select 444, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٠", "q": "لَآ أُقۡسِمُ بِهَٰذَا ٱلۡبَلَدِ ﴿١﴾ وَأَنتَ حِلُّۢ بِهَٰذَا ٱلۡبَلَدِ ﴿٢﴾ وَوَالِدٖ وَمَا وَلَدَ ﴿٣﴾ لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ ﴿٤﴾ أَيَحۡسَبُ أَن لَّن يَقۡدِرَ عَلَيۡهِ أَحَدٞ ﴿٥﴾ يَقُولُ أَهۡلَكۡتُ مَالٗا لُّبَدًا ﴿٦﴾ أَيَحۡسَبُ أَن لَّمۡ يَرَهُۥٓ أَحَدٌ ﴿٧﴾ أَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ ﴿٨﴾ وَلِسَانٗا وَشَفَتَيۡنِ ﴿٩﴾ وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ ﴿١٠﴾", "w": [["لا أقسم بهذا البلد", "أقسم بمكة."], ["وأنت حِلّ بهذا البلد", "وأنت يا نبي الله محمد حلال بمكة."], ["ووالد وما ولد", "آدم وذريته."], ["في كبد", "في نصب وشدة، يكابد مصائب الدنيا وشدائد الآخرة."], ["أيحسب أن لن يقدر عليه أحد", "أيظن، وهو أبو الأشدّين بن كلدة، وكان قوياً شديداً؟"], ["أهلكت مالاً لُبداً", "يقول هذا مفاخراً بعداوة الرسول، وأنه أنفق فيها مالاً كثيراً."], ["أيحسب أن لم يره أحد", "أيظن أنه لم يره أحد؟ بل الله رآه وعلم ما أنفقه."], ["وهديناه النجدين", "بيّنّا له طريق الخير وطريق الشر بما فطرناه عليه، وبما أرسلنا به رسلنا وأنزلنا به كتبنا."]], "m": "أقسم الله تعالى بمكة بلده الأمين، والرسول ﷺ حِلٌّ بها يقاتل فيها، وذلك يوم الفتح الموعود، وقد قُتل يومها ابن خطل وهو متعلّق بأستار الكعبة، وأقسم بوالد وما ولد: آدم وذريته، ومنهم الأنبياء والأولياء. والمقسم عليه: لقد خلقنا الإنسان في كبد، أي في نصب وتعب لا يفارقانه منذ تخلّقه في بطن أمه إلى وفاته، ثم يكابد شدائد الآخرة، ثم إما إلى نعيم لا نصب معه ولا تعب، وإما إلى جحيم. وفي هذا الخبر المؤكد بأجلّ قسم ترويح على نفوس المؤمنين بمكة، وهم يعانون من الحاجة والاضطهاد والتعذيب من طغاة قريش، لا سيما المستضعفين كياسر وولده عمار وبلال وصهيب وخبيب، وحتى الرسول ﷺ لم يسلم من أذى المشركين؛ فإذا عرفوا طبيعة الحياة، وأن السعادة فيها أن يعلم المرء ألا سعادة بها، هان عليهم الأمر وخفّت آلامهم، كما هو تنبيه للطغاة لعلهم يصحون من سكرتهم بحب الدنيا. أيحسب هذا الإنسان، وقيل إنه أبو الأشدّين الذي أنفق ماله في عداوة الرسول ﷺ والإسلام، ويتبجّح قائلاً: أهلكت مالاً كثيراً بعضه فوق بعض، أيظن أن لم يره أحد؟ بلى إن الله قد رآه وعلم القدر الذي أنفقه، وسوف يحاسبه عليه ويجزيه به. ثم قرّره بقدرته ونعمه عليه: ألم نجعل له عينين يبصر بهما، ولساناً ينطق به ويفصح عن مراده، وشفتين يستر بهما فمه وأسنانه، وبيّنّا له طريق الخير والشر والسعادة والشقاء بما أودعنا في فطرته وبما أرسلنا به رسلنا؟ أنسي هذا كله ثم هو ينفق ما أعطيناه في حرب رسولنا وديننا؟", "h": ["شرف مكة وحرمتها، وعلو شأن الرسول ﷺ وسموّ مقامه وهو فيها، وقد أحلّها الله تعالى له ولم يحلّها لأحد سواه.", "شرف آدم وذريته الصالحين منهم.", "إعلان حقيقة، وهي أن الإنسان لا يبرح يعاني من أتعاب الحياة حتى الممات، ثم يستقبل شدائد الآخرة إلى أن يقرّ قراره، وينتهي تطوافه باستقراره في الجنة حيث يستريح نهائياً، أو في النار فيعذّب ويتعب أبداً."], "k": "«ألم نجعل له عينين ولساناً وشفتين»… فيمَ أستعمل عينيّ ولساني اليوم؟"}, {"lbl": "الآيات ١١ – ٢٠", "q": "فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ ﴿١١﴾ وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ ﴿١٢﴾ فَكُّ رَقَبَةٍ ﴿١٣﴾ أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ ﴿١٤﴾ يَتِيمٗا ذَا مَقۡرَبَةٍ ﴿١٥﴾ أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ ﴿١٦﴾ ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ ﴿١٧﴾ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ ﴿١٨﴾ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمۡ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ ﴿١٩﴾ عَلَيۡهِمۡ نَارٞ مُّؤۡصَدَةُۢ ﴿٢٠﴾", "w": [["فلا اقتحم", "فهلّا تجاوز."], ["العقبة", "الطريق الصعب في الجبل، والمراد به النجاة من النار."], ["فكّ رقبة", "أعتق رقبة في سبيل الله تعالى."], ["في يوم ذي مسغبة", "في يوم ذي مجاعة وشدة مؤونة."], ["يتيماً ذا مقربة", "أطعم يتيماً من ذوي قرابته."], ["مسكيناً ذا متربة", "أطعم فقيراً لاصقاً بالتراب ليس له شيء."], ["وتواصوا بالصبر", "أوصى بعضهم بعضاً بالصبر على طاعة الله."], ["وتواصوا بالمرحمة", "أوصى بعضهم بعضاً برحمة الفقراء والمساكين."], ["أصحاب الميمنة", "أصحاب اليمين، وهم المؤمنون المتقون."], ["أصحاب المشأمة", "أصحاب الشمال، وهم الكفار الفجار."], ["مؤصدة", "مطبقة لا نافذة لها ولا كوّة فلا يدخلها هواء."]], "m": "فهلّا أنفق أبو الأشدّين ما أنفقه في عداوة محمد ﷺ في سبيل الله، فاقتحم به العقبة فتجاوزها! وما أدراك ما العقبة؟ تفخيم لشأنها وتعظيم له. وبأربعة أمور تُقتحم العقبة ويُنجى من النار: فكّ رقبة، وقد ورد: «من أعتق رقبة مؤمنة فهي فداؤه من النار»، وإطعام في يوم مجاعة يتيماً ذا قرابة، أو مسكيناً لاصقاً بالأرض لحاجته وشدة فقره، وإيمان صادق بالله ورسوله وآيات الله ولقائه يحيا به قلبه، وتواصٍ بالصبر مع المؤمنين المستضعفين على الثبات على الحق ولزوم طريقه، وتواصٍ بالمرحمة مع أهل المال أن يرحموا الفقراء والمساكين فيسدّوا خلّتهم ويقضوا حاجتهم. بهذه الأربعة تُجتاز العقبة وينجو المرء من عذاب الله، وفي مثل هذا تُنفق الأموال، لا في الدسائس والمكر بالصالحين وخداع المؤمنين، أولئك أصحاب اليمين. ولما ذكر الإيمان والعمل الصالح، وهما المنجيان من عذاب الله، ذكر ضدّهما وهما المهلكان: الكفر والمعاصي، فقال: والذين كفروا بآياتنا هم أصحاب الشمال، عليهم نار مغلقة الأبواب مطبقة، هي جزاؤهم لأنهم كفروا بآيات الله وعصوا رسوله.", "h": ["التنديد بمن ينفق ماله في معصية الله ورسوله، والنصح له بالإنفاق في الخير، فإنه أجدى له وأنجى من عذاب الله.", "بيان أن عقبة عذاب الله يوم القيامة تُقتحم وتُجتاز بالإنفاق في سبيل الله، وبالإيمان والعمل الصالح والتواصي به.", "التنديد بالكفر، والوعيد الشديد لأهله."], "k": "«فلا اقتحم العقبة»… العقبة تُجتاز بإطعام ورحمة وتواصٍ بالصبر؛ أيّها أبدأ به هذا الأسبوع؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (445, 91, 1, 15, 'سورة الشمس ١ – ١٥', 'الشمس: قد أفلح من زكاها', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 445) = $j$[{"lbl": "الآيات ١ – ١٠", "q": "وَٱلشَّمۡسِ وَضُحَىٰهَا ﴿١﴾ وَٱلۡقَمَرِ إِذَا تَلَىٰهَا ﴿٢﴾ وَٱلنَّهَارِ إِذَا جَلَّىٰهَا ﴿٣﴾ وَٱلَّيۡلِ إِذَا يَغۡشَىٰهَا ﴿٤﴾ وَٱلسَّمَآءِ وَمَا بَنَىٰهَا ﴿٥﴾ وَٱلۡأَرۡضِ وَمَا طَحَىٰهَا ﴿٦﴾ وَنَفۡسٖ وَمَا سَوَّىٰهَا ﴿٧﴾ فَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا ﴿٨﴾ قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا ﴿٩﴾ وَقَدۡ خَابَ مَن دَسَّىٰهَا ﴿١٠﴾", "w": [["وضحاها", "ونهارها."], ["إذا تلاها", "تلا الشمس فطلع بعد غروبها مباشرة، وذلك ليلة النصف من الشهر."], ["إذا جلّاها", "إذا أضاءها."], ["إذا يغشاها", "غطّى الشمس حتى تظلم الآفاق."], ["وما بناها", "ومن بناها، وهو الله ﷻ، حيث جعل السماء كالسقف للأرض."], ["وما طحاها", "ومن بسطها، وهو الله ﷻ."], ["وما سوّاها", "ومن سوّى خلقها وعدّله، وهو الله ﷻ."], ["فألهمها فجورها وتقواها", "بيّن لها ما ينبغي لها أن تأتيه أو تتركه من الخير والشر."], ["قد أفلح من زكّاها", "فاز بالنجاة من النار ودخول الجنة من طهّر نفسه من الذنوب والآثام."], ["وقد خاب", "خسر في الآخرة نفسه وأهله يوم القيامة."], ["من دسّاها", "أخفى نفسه وأخملها بالكفر والمعاصي."]], "m": "تضمّنت هذه الآيات العشر قسماً إلهياً من أعظم الأقسام، ومقسماً عليه وهو جواب القسم، ومقسماً لهم وهم سائر الناس. فأقسم تعالى بالشمس وضحاها، وبالقمر إذا تلاها أي طلع بعد غروبها وذلك ليلة النصف من الشهر، وبالنهار إذا جلّاها أي أضاء فكشف الظلمة، وبالليل إذا يغشى الشمس حتى تظلم الآفاق، وبالسماء ومن بناها وهو الله سبحانه، وبالأرض ومن بسطها وهو الله تعالى، وبالنفس ومن خلقها وعدّل خلقها وهو الله تعالى، فألهمها، أي بيّن لها الخير والشر، ما تعمله من الصالحات وما تتجنّبه من السيئات. أقسم تعالى بأربع من مخلوقاته العظام وبنفسه، وهو العلي العظيم، على قوله: قد أفلح من زكّاها وقد خاب من دسّاها؛ أي أن من وفّقه الله وأعانه فزكّى نفسه، أي طهّرها بالإيمان والعمل الصالح مبعداً لها عما يدنّسها من الشرك والمعاصي، فقد فاز يوم القيامة بالنجاة من النار ودخول الجنة، إذ الفوز لغةً السلامة من المرهوب والظفر بالمرغوب، وأن من خذله الله تعالى لما له من سوابق في الشر والفساد، فلم يزكِّ نفسه بالإيمان والعمل الصالح ودسّاها، أي أخفاها وأخملها بما أفرغ عليها من الذنوب وما غطّاها من آثار الخطايا، فقد خسر في آخرته نفسه وأهله، وهو الخسران المبين.", "h": ["بيان مظاهر القدرة الإلهية في الآيات التي أقسم بها الرب تعالى.", "بيان ما يكون به الفلاح، وما يكون به الخسران.", "الترغيب في الإيمان والعمل الصالح، والترهيب من الشرك والمعاصي."], "k": "«قد أفلح من زكّاها»… ما الذنب الذي يُخمل نفسي أكثر من غيره؟ وكيف أبدأ تطهيرها منه؟"}, {"lbl": "الآيات ١١ – ١٥", "q": "كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ ﴿١١﴾ إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا ﴿١٢﴾ فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا ﴿١٣﴾ فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا ﴿١٤﴾ وَلَا يَخَافُ عُقۡبَٰهَا ﴿١٥﴾", "w": [["ثمود", "أصحاب الحجر، كذّبوا رسولهم صالحاً ﵇."], ["بطغواها", "بسبب طغيانها في الشرك والمعاصي."], ["أشقاها", "أشقى القبيلة، وهو قُدار بن سالف الذي يُضرب به المثل فيقال: أشأم من قُدار."], ["رسول الله", "صالح ﵇."], ["ناقة الله وسقياها", "ذروها وشربها في يومها."], ["فكذّبوه", "فيما أخبرهم به من شأن الناقة."], ["فعقروها", "قتلوها ليخلص لهم ماء شربها في يومها."], ["فدمدم", "أطبق عليهم العذاب فأهلكهم."], ["بذنبهم", "بسبب ذنوبهم التي هي الشرك والتكذيب وقتل الناقة."], ["فسوّاها", "سوّى الدمدمة عليهم فلم يفلت منهم أحد."], ["ولا يخاف عقباها", "لا يخاف الرب تعالى تبعة إهلاكهم كما يخاف الإنسان عاقبة فعله إذا قتل أحداً أو عذّبه."]], "m": "سيقت هذه الآيات للتدليل على أمور: أن الذنوب موجبة لعذاب الله في الدنيا والآخرة، وأن تكذيب الرسول الذي عليه كفار مكة منذرٌ بخطر عظيم إن استمرّوا عليه، فقد يهلكهم الله كما أهلك أصحاب الحجر قوم صالح، وأن محمداً رسول الله حقاً وصدقاً، وأنه لا إله إلا الله، وأن البعث والجزاء ثابتان بأدلة قدرة الله وعلمه. فقوله: كذّبت ثمود بطغواها، إخبار منه تعالى المراد به إنذار قريش من خطر الاستمرار على التكذيب، وتسلية الرسول والمؤمنين، أي كذّبت بسبب ذنوبها التي بلغت فيها حدّ الطغيان، وهو الإسراف ومجاوزة الحد، إذ انبعث أشقى تلك القبيلة قُدار بن سالف، الذي يُضرب به المثل في الشقاوة، فقال لهم رسول الله صالح: احذروا ناقة الله، ذروها تأكل في أرض الله ولا تمسّوها بسوء فيأخذكم عذاب أليم، وذروا سقياها، إذ كان الماء قسمة بينهم: لها يوم ولهم يوم. فكذّبوه في ذلك وفي غيره من رسالته، فذبحوها، فأطبق عليهم ربهم العذاب وعمّهم به فلم ينجُ منهم أحد، وذلك بذنبهم لا بظلم منه تعالى، فسوّاها في النقمة والعذاب، ولا يخاف تبعة تلحقه من هلاكها، إذ هو رب الكل ومالك الكل، وهو القاهر فوق عباده، وهو العزيز الحكيم.", "h": ["بيان أن نجاة العبد من النار ودخوله الجنة متوقّف على زكاة نفسه وتطهيرها من أوضار الذنوب والمعاصي، وأن شقاء العبد وخسرانه سببه تدنيسه نفسه بالشرك والمعاصي، وكل هذا من سنن الله تعالى في الأسباب والمسبّبات.", "التحذير من الطغيان، وهو الإسراف في الشر والفساد، فإنه مهلك ومدمّر، وموجب للهلاك والدمار في الدنيا والعذاب في الآخرة.", "تسلية الرسول ﷺ والتخفيف عنه، إذ كذّبت قبل قريش ثمود وغيرها من الأمم، كأصحاب مدين وقوم لوط وفرعون.", "إنذار كفار قريش عاقبة الشرك والتكذيب والمعاصي من الظلم والاعتداء."], "k": "«فدمدم عليهم ربهم بذنبهم»… واحد عقر الناقة والقوم رضوا فعمّهم العذاب؛ فهل أرضى بمنكر أراه ولا أنكره؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 445;
insert into public.tdb_cards(topic, i, body) select 445, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٠", "q": "وَٱلشَّمۡسِ وَضُحَىٰهَا ﴿١﴾ وَٱلۡقَمَرِ إِذَا تَلَىٰهَا ﴿٢﴾ وَٱلنَّهَارِ إِذَا جَلَّىٰهَا ﴿٣﴾ وَٱلَّيۡلِ إِذَا يَغۡشَىٰهَا ﴿٤﴾ وَٱلسَّمَآءِ وَمَا بَنَىٰهَا ﴿٥﴾ وَٱلۡأَرۡضِ وَمَا طَحَىٰهَا ﴿٦﴾ وَنَفۡسٖ وَمَا سَوَّىٰهَا ﴿٧﴾ فَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا ﴿٨﴾ قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا ﴿٩﴾ وَقَدۡ خَابَ مَن دَسَّىٰهَا ﴿١٠﴾", "w": [["وضحاها", "ونهارها."], ["إذا تلاها", "تلا الشمس فطلع بعد غروبها مباشرة، وذلك ليلة النصف من الشهر."], ["إذا جلّاها", "إذا أضاءها."], ["إذا يغشاها", "غطّى الشمس حتى تظلم الآفاق."], ["وما بناها", "ومن بناها، وهو الله ﷻ، حيث جعل السماء كالسقف للأرض."], ["وما طحاها", "ومن بسطها، وهو الله ﷻ."], ["وما سوّاها", "ومن سوّى خلقها وعدّله، وهو الله ﷻ."], ["فألهمها فجورها وتقواها", "بيّن لها ما ينبغي لها أن تأتيه أو تتركه من الخير والشر."], ["قد أفلح من زكّاها", "فاز بالنجاة من النار ودخول الجنة من طهّر نفسه من الذنوب والآثام."], ["وقد خاب", "خسر في الآخرة نفسه وأهله يوم القيامة."], ["من دسّاها", "أخفى نفسه وأخملها بالكفر والمعاصي."]], "m": "تضمّنت هذه الآيات العشر قسماً إلهياً من أعظم الأقسام، ومقسماً عليه وهو جواب القسم، ومقسماً لهم وهم سائر الناس. فأقسم تعالى بالشمس وضحاها، وبالقمر إذا تلاها أي طلع بعد غروبها وذلك ليلة النصف من الشهر، وبالنهار إذا جلّاها أي أضاء فكشف الظلمة، وبالليل إذا يغشى الشمس حتى تظلم الآفاق، وبالسماء ومن بناها وهو الله سبحانه، وبالأرض ومن بسطها وهو الله تعالى، وبالنفس ومن خلقها وعدّل خلقها وهو الله تعالى، فألهمها، أي بيّن لها الخير والشر، ما تعمله من الصالحات وما تتجنّبه من السيئات. أقسم تعالى بأربع من مخلوقاته العظام وبنفسه، وهو العلي العظيم، على قوله: قد أفلح من زكّاها وقد خاب من دسّاها؛ أي أن من وفّقه الله وأعانه فزكّى نفسه، أي طهّرها بالإيمان والعمل الصالح مبعداً لها عما يدنّسها من الشرك والمعاصي، فقد فاز يوم القيامة بالنجاة من النار ودخول الجنة، إذ الفوز لغةً السلامة من المرهوب والظفر بالمرغوب، وأن من خذله الله تعالى لما له من سوابق في الشر والفساد، فلم يزكِّ نفسه بالإيمان والعمل الصالح ودسّاها، أي أخفاها وأخملها بما أفرغ عليها من الذنوب وما غطّاها من آثار الخطايا، فقد خسر في آخرته نفسه وأهله، وهو الخسران المبين.", "h": ["بيان مظاهر القدرة الإلهية في الآيات التي أقسم بها الرب تعالى.", "بيان ما يكون به الفلاح، وما يكون به الخسران.", "الترغيب في الإيمان والعمل الصالح، والترهيب من الشرك والمعاصي."], "k": "«قد أفلح من زكّاها»… ما الذنب الذي يُخمل نفسي أكثر من غيره؟ وكيف أبدأ تطهيرها منه؟"}, {"lbl": "الآيات ١١ – ١٥", "q": "كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ ﴿١١﴾ إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا ﴿١٢﴾ فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا ﴿١٣﴾ فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا ﴿١٤﴾ وَلَا يَخَافُ عُقۡبَٰهَا ﴿١٥﴾", "w": [["ثمود", "أصحاب الحجر، كذّبوا رسولهم صالحاً ﵇."], ["بطغواها", "بسبب طغيانها في الشرك والمعاصي."], ["أشقاها", "أشقى القبيلة، وهو قُدار بن سالف الذي يُضرب به المثل فيقال: أشأم من قُدار."], ["رسول الله", "صالح ﵇."], ["ناقة الله وسقياها", "ذروها وشربها في يومها."], ["فكذّبوه", "فيما أخبرهم به من شأن الناقة."], ["فعقروها", "قتلوها ليخلص لهم ماء شربها في يومها."], ["فدمدم", "أطبق عليهم العذاب فأهلكهم."], ["بذنبهم", "بسبب ذنوبهم التي هي الشرك والتكذيب وقتل الناقة."], ["فسوّاها", "سوّى الدمدمة عليهم فلم يفلت منهم أحد."], ["ولا يخاف عقباها", "لا يخاف الرب تعالى تبعة إهلاكهم كما يخاف الإنسان عاقبة فعله إذا قتل أحداً أو عذّبه."]], "m": "سيقت هذه الآيات للتدليل على أمور: أن الذنوب موجبة لعذاب الله في الدنيا والآخرة، وأن تكذيب الرسول الذي عليه كفار مكة منذرٌ بخطر عظيم إن استمرّوا عليه، فقد يهلكهم الله كما أهلك أصحاب الحجر قوم صالح، وأن محمداً رسول الله حقاً وصدقاً، وأنه لا إله إلا الله، وأن البعث والجزاء ثابتان بأدلة قدرة الله وعلمه. فقوله: كذّبت ثمود بطغواها، إخبار منه تعالى المراد به إنذار قريش من خطر الاستمرار على التكذيب، وتسلية الرسول والمؤمنين، أي كذّبت بسبب ذنوبها التي بلغت فيها حدّ الطغيان، وهو الإسراف ومجاوزة الحد، إذ انبعث أشقى تلك القبيلة قُدار بن سالف، الذي يُضرب به المثل في الشقاوة، فقال لهم رسول الله صالح: احذروا ناقة الله، ذروها تأكل في أرض الله ولا تمسّوها بسوء فيأخذكم عذاب أليم، وذروا سقياها، إذ كان الماء قسمة بينهم: لها يوم ولهم يوم. فكذّبوه في ذلك وفي غيره من رسالته، فذبحوها، فأطبق عليهم ربهم العذاب وعمّهم به فلم ينجُ منهم أحد، وذلك بذنبهم لا بظلم منه تعالى، فسوّاها في النقمة والعذاب، ولا يخاف تبعة تلحقه من هلاكها، إذ هو رب الكل ومالك الكل، وهو القاهر فوق عباده، وهو العزيز الحكيم.", "h": ["بيان أن نجاة العبد من النار ودخوله الجنة متوقّف على زكاة نفسه وتطهيرها من أوضار الذنوب والمعاصي، وأن شقاء العبد وخسرانه سببه تدنيسه نفسه بالشرك والمعاصي، وكل هذا من سنن الله تعالى في الأسباب والمسبّبات.", "التحذير من الطغيان، وهو الإسراف في الشر والفساد، فإنه مهلك ومدمّر، وموجب للهلاك والدمار في الدنيا والعذاب في الآخرة.", "تسلية الرسول ﷺ والتخفيف عنه، إذ كذّبت قبل قريش ثمود وغيرها من الأمم، كأصحاب مدين وقوم لوط وفرعون.", "إنذار كفار قريش عاقبة الشرك والتكذيب والمعاصي من الظلم والاعتداء."], "k": "«فدمدم عليهم ربهم بذنبهم»… واحد عقر الناقة والقوم رضوا فعمّهم العذاب؛ فهل أرضى بمنكر أراه ولا أنكره؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (446, 92, 1, 21, 'سورة الليل ١ – ٢١', 'الليل: فأما من أعطى واتقى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 446) = $j$[{"lbl": "الآيات ١ – ١١", "q": "وَٱلَّيۡلِ إِذَا يَغۡشَىٰ ﴿١﴾ وَٱلنَّهَارِ إِذَا تَجَلَّىٰ ﴿٢﴾ وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ ﴿٣﴾ إِنَّ سَعۡيَكُمۡ لَشَتَّىٰ ﴿٤﴾ فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ ﴿٥﴾ وَصَدَّقَ بِٱلۡحُسۡنَىٰ ﴿٦﴾ فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ ﴿٧﴾ وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ ﴿٨﴾ وَكَذَّبَ بِٱلۡحُسۡنَىٰ ﴿٩﴾ فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ ﴿١٠﴾ وَمَا يُغۡنِي عَنۡهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ ﴿١١﴾", "w": [["إذا يغشى", "بظلمته كل ما بين السماء والأرض في الإقليم الذي يكون به."], ["إذا تجلّى", "تكشّف وظهر في الإقليم الذي هو به."], ["وما خلق الذكر والأنثى", "ومن خلق الذكر والأنثى: آدم وحواء وكل ذريتهما، وهو الله تعالى."], ["إن سعيكم لشتّى", "إن عملكم أيها الناس لمختلف: منه الحسنة المورثة للجنة، ومنه السيئة الموجبة للنار."], ["من أعطى واتقى", "أعطى حق الله وأنفق في سبيل الله، واتقى ما يسخط الله تعالى من الشرك والمعاصي."], ["وصدّق بالحسنى", "بالخلف، لحديث: «اللهم أعطِ منفقاً خلفاً»."], ["فسنيسّره لليسرى", "فسنهيّئه للخلّة اليسرى، وهي العمل بما يرضاه الله منه في الدنيا ليوجب له به الجنة في الآخرة."], ["وأما من بخل واستغنى", "منع حق الله والإنفاق في سبيل الله، واستغنى بماله عن الله فلم يسأله من فضله ولم يعمل عملاً صالحاً يتقرّب به إليه."], ["وكذّب بالحسنى", "بالخلف وما تثمره الصدقة والإيمان، وهو الجنة."], ["فسنيسّره للعسرى", "فسنهيّئه للخلّة العسرى، وهي العمل بما يكرهه الله ولا يرضاه، ليكون قائده إلى النار."], ["إذا تردّى", "في جهنم فسقط فيها."]], "m": "أقسم تعالى بالليل إذا يغشى بظلامه الكون، وبالنهار إذا تكشّف وظهر، وهما آيتان من آيات الله الدالّتان على ربوبيته الموجبة لألوهيته، وأقسم بنفسه جلّ وعزّ فقال: والذي خلق الذكر والأنثى: آدم وحواء ثم سائر الذكور والإناث من كل الحيوانات، وهو مظهر لا يقل عظمة عن آيتي الليل والنهار. وجواب القسم: إن عملكم أيها الناس لمختلف، منه الحسنات الموجبة للسعادة والكمال في الدارين، ومنه السيئات الموجبة للشقاء فيهما. فأما من أعطى حق الله في المال فأنفق وتصدّق في سبيل الله، واتقى الله فآمن به وعبده ولم يشرك به، وصدّق بالحسنى، أي الخلف والعوض المضاعف الذي وعد به من ينفق في سبيله في قوله: «وما أنفقتم من شيء فهو يخلفه»، وفي قول الرسول ﷺ في الصحيح: «ما من يوم يصبح العباد فيه إلا ملكان ينزلان، فيقول أحدهما: اللهم أعطِ منفقاً خلفاً، ويقول الآخر: اللهم أعطِ ممسكاً تلفاً»، فسنيسّره للخلّة اليسرى، وهي العمل بما يرضاه الله منه في الدنيا ويثيبه عليه في الآخرة بالجنة. وأما من بخل بالمال فلم يعطِ حق الله فيه، واستغنى بماله وولده وجاهه فلم يتقرّب إلى الله بطاعته، وكذّب بالخلف من الله على من ينفق في سبيله، فسنهيّئه للخلّة العسرى، وهي العمل بما يكره الله من الذنوب والآثام، ليكون ذلك قائده إلى النار. وما يغني عنه ماله الذي بخل به شيئاً يوم القيامة إذا أُلقي في نار جهنم فتردّى ساقطاً فيها على أم رأسه.", "h": ["بيان عظمة الله وقدرته وعلمه الموجبة لربوبيته، المقتضية لعبادته وحده دون سواه.", "تقرير القضاء والقدر، وهو أن كل إنسان ميسّر لما خُلق له من سعادة أو شقاء، لحديث: «اعملوا فكلٌّ ميسّر لما خُلق له»، مع تقرير أن من وُفّق للعمل بما يرضي الله كان ذلك دليلاً على أنه مكتوب سعيداً إذا مات على ما وُفّق له من العمل الصالح، وأن من وُفّق للعمل المسخط لله كان دليلاً على أنه مكتوبة شقاوته إن هو مات على ذلك.", "تقرير أن التوفيق للعمل بالطاعة يتوقّف، حسب سنة الله تعالى، على رغبة العبد وطلبه ذلك وحرصه عليه واختياره على غيره وتسخير النفس والجوارح له، كما أن التوفيق للعمل الفاسد قائم على اختيار العبد وطلبه وحرصه وتسخير نفسه وجوارحه لذلك، وهذه سنة من سنن الله تعالى في خلقه."], "k": "«فأما من أعطى واتقى وصدّق بالحسنى فسنيسّره لليسرى»… أريد أن يُيسَّر لي الخير؛ فما الذي سأعطيه اليوم واثقاً بالخلف؟"}, {"lbl": "الآيات ١٢ – ٢١", "q": "إِنَّ عَلَيۡنَا لَلۡهُدَىٰ ﴿١٢﴾ وَإِنَّ لَنَا لَلۡأٓخِرَةَ وَٱلۡأُولَىٰ ﴿١٣﴾ فَأَنذَرۡتُكُمۡ نَارٗا تَلَظَّىٰ ﴿١٤﴾ لَا يَصۡلَىٰهَآ إِلَّا ٱلۡأَشۡقَى ﴿١٥﴾ ٱلَّذِي كَذَّبَ وَتَوَلَّىٰ ﴿١٦﴾ وَسَيُجَنَّبُهَا ٱلۡأَتۡقَى ﴿١٧﴾ ٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ ﴿١٨﴾ وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ ﴿١٩﴾ إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ ﴿٢٠﴾ وَلَسَوۡفَ يَرۡضَىٰ ﴿٢١﴾", "w": [["إن علينا للهدى", "إن علينا لبيان الحق من الباطل، والطاعة من المعصية."], ["وإن لنا للآخرة والأولى", "ملك ما في الدنيا والآخرة، نعطي ونحرم من نشاء، لا مالك غيرنا."], ["فأنذرتكم", "خوّفتكم."], ["ناراً تلظّى", "تتوقّد التهاباً."], ["لا يصلاها إلا الأشقى", "لا يدخلها ويصطلي بحرّها خالداً فيها إلا الأكثر شقاوة."], ["الذي كذّب وتولّى", "كذّب النبي ﷺ فيما جاء به، وتولّى: أعرض عن الإيمان به وبما جاء به من التوحيد والطاعة لله ورسوله."], ["وسيجنّبها الأتقى", "يُبعد عنها التقي."], ["يتزكّى", "يتطهّر به من الشح والبخل وآثار الذنوب."], ["وما لأحد عنده من نعمة تُجزى", "ليس لأحد من الناس عليه منّة فهو يكافئه بذلك."], ["إلا ابتغاء وجه ربه الأعلى", "لكن يؤتي ماله في سبيل الله ابتغاء مرضاة الله ﷻ."], ["ولسوف يرضى", "يعطيه الله تعالى من الكرامة ما يرضى به في دار السلام."]], "m": "بعد أن أعلم تعالى عباده أنه ييسّر لليسرى من أعطى واتقى وصدّق بالحسنى، وييسّر للعسرى من بخل واستغنى وكذّب بالحسنى، أعلم بحقيقة أخرى: أن بيان الطريق الموصل إلى اليسرى على الله تعالى، متكفّل به، وقد بيّنه بكتابه ورسوله؛ فمن طلب اليسرى فأولاً يؤمن بالله ورسوله ويوطّن نفسه على طاعتهما ويعمل بها، وثانياً ينفق في سبيل الله ما يطهّر به نفسه من البخل وشح النفس، ويُظهر فقره وحاجته إلى الله بالتقرّب إليه بالنوافل وصالح الأعمال، وبذلك يكون قد يُسّر فعلاً لليسرى. وإن لنا الآخرة والدنيا، فمن طلبهما من غيرنا فقد أخطأ، فطلب الآخرة يكون بالإيمان والتقوى، وطلب الدنيا بالعمل حسب سنتنا في الكسب وحصول المال. فبناءً على ما بيّنّا فقد خوّفتكم ناراً تتوقّد التهاباً، لا يدخلها خالداً فيها إلا الأشقى، وهو المشرك الذي كذّب وتولّى، وقد يدخلها الشقي من أهل التوحيد ويخرج منها بتوحيده، حيث لم يكذّب ولم يتولّ، ولكن فجر وعصى. وسيُبعد عنها الأتقى الذي يعطي ماله في سبيل الله يتزكّى به من مرض الشح والبخل وآثار الذنوب، وليس ما ينفقه من أجل أن لأحد عليه فضلاً أو يداً فهو يكافئه بها، وإنما ينفق ابتغاء وجه ربه الأعلى، يريد رضا ربه لا غير، فسوف نعطيه عطاء يرضى به في الجنة. نزلت هذه الآيات في أبي بكر الصديق رضي الله عنه، فقد كان بمكة يشتري العبيد من مواليهم الذين يعذّبونهم من أجل إسلامهم ويعتقهم لوجه الله، ومنهم بلال رضي الله عنه، فقال المشركون: إنما فعل ذلك ليدٍ لهم عنده يكافئهم بها، فأكذبهم الله وأنزل: «وسيجنّبها الأتقى» الآيات.", "h": ["بيان أن الله تعالى متكفّل بطريق الهدى، فأرسل الرسل وأنزل الكتاب فأبان الطريق وأوضحه.", "أن لله تعالى وحده الدنيا والآخرة، فمن أرادهما أو إحداهما فليطلب ذلك من الله تعالى؛ فالآخرة تُطلب بالإيمان والتقوى، والدنيا تُطلب باتّباع سنن الله تعالى في الحصول عليها.", "بيان فضل أبي بكر الصديق، وأنه مبشّر بالجنة في هذه الآية الكريمة."], "k": "«إلا ابتغاء وجه ربه الأعلى»… حين أعطي، هل أنتظر شكراً أو ردّاً للجميل؟ أم وجه ربي وحده؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 446;
insert into public.tdb_cards(topic, i, body) select 446, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١١", "q": "وَٱلَّيۡلِ إِذَا يَغۡشَىٰ ﴿١﴾ وَٱلنَّهَارِ إِذَا تَجَلَّىٰ ﴿٢﴾ وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ ﴿٣﴾ إِنَّ سَعۡيَكُمۡ لَشَتَّىٰ ﴿٤﴾ فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ ﴿٥﴾ وَصَدَّقَ بِٱلۡحُسۡنَىٰ ﴿٦﴾ فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ ﴿٧﴾ وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ ﴿٨﴾ وَكَذَّبَ بِٱلۡحُسۡنَىٰ ﴿٩﴾ فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ ﴿١٠﴾ وَمَا يُغۡنِي عَنۡهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ ﴿١١﴾", "w": [["إذا يغشى", "بظلمته كل ما بين السماء والأرض في الإقليم الذي يكون به."], ["إذا تجلّى", "تكشّف وظهر في الإقليم الذي هو به."], ["وما خلق الذكر والأنثى", "ومن خلق الذكر والأنثى: آدم وحواء وكل ذريتهما، وهو الله تعالى."], ["إن سعيكم لشتّى", "إن عملكم أيها الناس لمختلف: منه الحسنة المورثة للجنة، ومنه السيئة الموجبة للنار."], ["من أعطى واتقى", "أعطى حق الله وأنفق في سبيل الله، واتقى ما يسخط الله تعالى من الشرك والمعاصي."], ["وصدّق بالحسنى", "بالخلف، لحديث: «اللهم أعطِ منفقاً خلفاً»."], ["فسنيسّره لليسرى", "فسنهيّئه للخلّة اليسرى، وهي العمل بما يرضاه الله منه في الدنيا ليوجب له به الجنة في الآخرة."], ["وأما من بخل واستغنى", "منع حق الله والإنفاق في سبيل الله، واستغنى بماله عن الله فلم يسأله من فضله ولم يعمل عملاً صالحاً يتقرّب به إليه."], ["وكذّب بالحسنى", "بالخلف وما تثمره الصدقة والإيمان، وهو الجنة."], ["فسنيسّره للعسرى", "فسنهيّئه للخلّة العسرى، وهي العمل بما يكرهه الله ولا يرضاه، ليكون قائده إلى النار."], ["إذا تردّى", "في جهنم فسقط فيها."]], "m": "أقسم تعالى بالليل إذا يغشى بظلامه الكون، وبالنهار إذا تكشّف وظهر، وهما آيتان من آيات الله الدالّتان على ربوبيته الموجبة لألوهيته، وأقسم بنفسه جلّ وعزّ فقال: والذي خلق الذكر والأنثى: آدم وحواء ثم سائر الذكور والإناث من كل الحيوانات، وهو مظهر لا يقل عظمة عن آيتي الليل والنهار. وجواب القسم: إن عملكم أيها الناس لمختلف، منه الحسنات الموجبة للسعادة والكمال في الدارين، ومنه السيئات الموجبة للشقاء فيهما. فأما من أعطى حق الله في المال فأنفق وتصدّق في سبيل الله، واتقى الله فآمن به وعبده ولم يشرك به، وصدّق بالحسنى، أي الخلف والعوض المضاعف الذي وعد به من ينفق في سبيله في قوله: «وما أنفقتم من شيء فهو يخلفه»، وفي قول الرسول ﷺ في الصحيح: «ما من يوم يصبح العباد فيه إلا ملكان ينزلان، فيقول أحدهما: اللهم أعطِ منفقاً خلفاً، ويقول الآخر: اللهم أعطِ ممسكاً تلفاً»، فسنيسّره للخلّة اليسرى، وهي العمل بما يرضاه الله منه في الدنيا ويثيبه عليه في الآخرة بالجنة. وأما من بخل بالمال فلم يعطِ حق الله فيه، واستغنى بماله وولده وجاهه فلم يتقرّب إلى الله بطاعته، وكذّب بالخلف من الله على من ينفق في سبيله، فسنهيّئه للخلّة العسرى، وهي العمل بما يكره الله من الذنوب والآثام، ليكون ذلك قائده إلى النار. وما يغني عنه ماله الذي بخل به شيئاً يوم القيامة إذا أُلقي في نار جهنم فتردّى ساقطاً فيها على أم رأسه.", "h": ["بيان عظمة الله وقدرته وعلمه الموجبة لربوبيته، المقتضية لعبادته وحده دون سواه.", "تقرير القضاء والقدر، وهو أن كل إنسان ميسّر لما خُلق له من سعادة أو شقاء، لحديث: «اعملوا فكلٌّ ميسّر لما خُلق له»، مع تقرير أن من وُفّق للعمل بما يرضي الله كان ذلك دليلاً على أنه مكتوب سعيداً إذا مات على ما وُفّق له من العمل الصالح، وأن من وُفّق للعمل المسخط لله كان دليلاً على أنه مكتوبة شقاوته إن هو مات على ذلك.", "تقرير أن التوفيق للعمل بالطاعة يتوقّف، حسب سنة الله تعالى، على رغبة العبد وطلبه ذلك وحرصه عليه واختياره على غيره وتسخير النفس والجوارح له، كما أن التوفيق للعمل الفاسد قائم على اختيار العبد وطلبه وحرصه وتسخير نفسه وجوارحه لذلك، وهذه سنة من سنن الله تعالى في خلقه."], "k": "«فأما من أعطى واتقى وصدّق بالحسنى فسنيسّره لليسرى»… أريد أن يُيسَّر لي الخير؛ فما الذي سأعطيه اليوم واثقاً بالخلف؟"}, {"lbl": "الآيات ١٢ – ٢١", "q": "إِنَّ عَلَيۡنَا لَلۡهُدَىٰ ﴿١٢﴾ وَإِنَّ لَنَا لَلۡأٓخِرَةَ وَٱلۡأُولَىٰ ﴿١٣﴾ فَأَنذَرۡتُكُمۡ نَارٗا تَلَظَّىٰ ﴿١٤﴾ لَا يَصۡلَىٰهَآ إِلَّا ٱلۡأَشۡقَى ﴿١٥﴾ ٱلَّذِي كَذَّبَ وَتَوَلَّىٰ ﴿١٦﴾ وَسَيُجَنَّبُهَا ٱلۡأَتۡقَى ﴿١٧﴾ ٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ ﴿١٨﴾ وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ ﴿١٩﴾ إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ ﴿٢٠﴾ وَلَسَوۡفَ يَرۡضَىٰ ﴿٢١﴾", "w": [["إن علينا للهدى", "إن علينا لبيان الحق من الباطل، والطاعة من المعصية."], ["وإن لنا للآخرة والأولى", "ملك ما في الدنيا والآخرة، نعطي ونحرم من نشاء، لا مالك غيرنا."], ["فأنذرتكم", "خوّفتكم."], ["ناراً تلظّى", "تتوقّد التهاباً."], ["لا يصلاها إلا الأشقى", "لا يدخلها ويصطلي بحرّها خالداً فيها إلا الأكثر شقاوة."], ["الذي كذّب وتولّى", "كذّب النبي ﷺ فيما جاء به، وتولّى: أعرض عن الإيمان به وبما جاء به من التوحيد والطاعة لله ورسوله."], ["وسيجنّبها الأتقى", "يُبعد عنها التقي."], ["يتزكّى", "يتطهّر به من الشح والبخل وآثار الذنوب."], ["وما لأحد عنده من نعمة تُجزى", "ليس لأحد من الناس عليه منّة فهو يكافئه بذلك."], ["إلا ابتغاء وجه ربه الأعلى", "لكن يؤتي ماله في سبيل الله ابتغاء مرضاة الله ﷻ."], ["ولسوف يرضى", "يعطيه الله تعالى من الكرامة ما يرضى به في دار السلام."]], "m": "بعد أن أعلم تعالى عباده أنه ييسّر لليسرى من أعطى واتقى وصدّق بالحسنى، وييسّر للعسرى من بخل واستغنى وكذّب بالحسنى، أعلم بحقيقة أخرى: أن بيان الطريق الموصل إلى اليسرى على الله تعالى، متكفّل به، وقد بيّنه بكتابه ورسوله؛ فمن طلب اليسرى فأولاً يؤمن بالله ورسوله ويوطّن نفسه على طاعتهما ويعمل بها، وثانياً ينفق في سبيل الله ما يطهّر به نفسه من البخل وشح النفس، ويُظهر فقره وحاجته إلى الله بالتقرّب إليه بالنوافل وصالح الأعمال، وبذلك يكون قد يُسّر فعلاً لليسرى. وإن لنا الآخرة والدنيا، فمن طلبهما من غيرنا فقد أخطأ، فطلب الآخرة يكون بالإيمان والتقوى، وطلب الدنيا بالعمل حسب سنتنا في الكسب وحصول المال. فبناءً على ما بيّنّا فقد خوّفتكم ناراً تتوقّد التهاباً، لا يدخلها خالداً فيها إلا الأشقى، وهو المشرك الذي كذّب وتولّى، وقد يدخلها الشقي من أهل التوحيد ويخرج منها بتوحيده، حيث لم يكذّب ولم يتولّ، ولكن فجر وعصى. وسيُبعد عنها الأتقى الذي يعطي ماله في سبيل الله يتزكّى به من مرض الشح والبخل وآثار الذنوب، وليس ما ينفقه من أجل أن لأحد عليه فضلاً أو يداً فهو يكافئه بها، وإنما ينفق ابتغاء وجه ربه الأعلى، يريد رضا ربه لا غير، فسوف نعطيه عطاء يرضى به في الجنة. نزلت هذه الآيات في أبي بكر الصديق رضي الله عنه، فقد كان بمكة يشتري العبيد من مواليهم الذين يعذّبونهم من أجل إسلامهم ويعتقهم لوجه الله، ومنهم بلال رضي الله عنه، فقال المشركون: إنما فعل ذلك ليدٍ لهم عنده يكافئهم بها، فأكذبهم الله وأنزل: «وسيجنّبها الأتقى» الآيات.", "h": ["بيان أن الله تعالى متكفّل بطريق الهدى، فأرسل الرسل وأنزل الكتاب فأبان الطريق وأوضحه.", "أن لله تعالى وحده الدنيا والآخرة، فمن أرادهما أو إحداهما فليطلب ذلك من الله تعالى؛ فالآخرة تُطلب بالإيمان والتقوى، والدنيا تُطلب باتّباع سنن الله تعالى في الحصول عليها.", "بيان فضل أبي بكر الصديق، وأنه مبشّر بالجنة في هذه الآية الكريمة."], "k": "«إلا ابتغاء وجه ربه الأعلى»… حين أعطي، هل أنتظر شكراً أو ردّاً للجميل؟ أم وجه ربي وحده؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (447, 93, 1, 11, 'سورة الضحى ١ – ١١', 'الضحى: ولسوف يعطيك ربك فترضى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 447) = $j$[{"lbl": "الآيات ١ – ١١", "q": "وَٱلضُّحَىٰ ﴿١﴾ وَٱلَّيۡلِ إِذَا سَجَىٰ ﴿٢﴾ مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ ﴿٣﴾ وَلَلۡأٓخِرَةُ خَيۡرٞ لَّكَ مِنَ ٱلۡأُولَىٰ ﴿٤﴾ وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ ﴿٥﴾ أَلَمۡ يَجِدۡكَ يَتِيمٗا فَـَٔاوَىٰ ﴿٦﴾ وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ ﴿٧﴾ وَوَجَدَكَ عَآئِلٗا فَأَغۡنَىٰ ﴿٨﴾ فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ ﴿٩﴾ وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ ﴿١٠﴾ وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ ﴿١١﴾", "w": [["والضحى", "أول النهار، ما بين طلوع الشمس وارتفاعها قيد رمح إلى الزوال."], ["والليل إذا سجى", "غطّى بظلامه المعمورة وسكن، فسكن الناس وخلدوا إلى الراحة."], ["ما ودّعك", "ما تركك."], ["وما قلى", "وما أبغضك."], ["ألم يجدك يتيماً", "فاقد الأب، إذ مات والده قبل ولادته."], ["فآوى", "فآواك بأن ضمّك إلى عمك أبي طالب."], ["ووجدك ضالاً", "لا تعرف ديناً ولا هدى."], ["فأغنى", "بالقناعة، وبما يسّر لك من مال خديجة وأبي بكر الصديق."], ["فلا تقهر", "لا تذلّه ولا تأخذ ماله."], ["فلا تنهر", "لا تنهره بزجر ونحوه."], ["وأما بنعمة ربك فحدّث", "اذكر ما أنعم الله تعالى به عليك شكراً له على ذلك."]], "m": "هذا قسم من الله تعالى لرسوله ﷺ على أنه ما تركه ولا أبغضه؛ وذلك أنه أبطأ عنه الوحي أياماً، فلما رأى ذلك المشركون فرحوا به وعيّروه، فأنزل الله سورة الضحى، يقسم له فيها بالضحى، وهو أول النهار، وبالليل إذا غطّى بظلامه المعمورة وسكن: ما تركك ربك يا محمد وما أبغضك، وللآخرة خير لك من الدنيا لما أعدّ الله لك فيها من الملك الكبير والنعيم العظيم المقيم، ولسوف يعطيك ربك من فواضل نعمه حتى ترضى: في الدنيا من كمال الدين وظهور الأمر، وفي الآخرة الشفاعة، وألا يبقى أحد من أمته أهل التوحيد في النار، والوسيلة والدرجة الرفيعة التي لا تكون لأحد سواه. ثم ذكّره بثلاث منن ليوقن أن الله معه وأنه ما تركه ولن يتركه، وحتى تنتهي فرحة المشركين ببطء الوحي: الأولى أن والده مات قبل ولادته وأمه ماتت بُعيد فطامه، فآواه ربه بأن ضمّه إلى عمه أبي طالب، فكان أباً رحيماً وعماً كريماً وحصناً منيعاً له، لم يتخلّ عن نصرته حتى وفاته. والثانية منّة العلم والهداية، فقد كان ﷺ يعيش في مكة لا يعرف علماً ولا شرعاً، وإن كان معصوماً من مقارفة أي ذنب، كما قال تعالى: «ما كنت تدري ما الكتاب ولا الإيمان». والثالثة الغنى بعد الحاجة، فقد مات والده ولم يخلّف أكثر من جارية هي بركة أم أيمن وبضعة جمال، فأغناه الله بغنى القناعة فلم يمدّ يده لأحد قط، وكان يقول: «ليس الغنى عن كثرة العَرَض، ولكن الغنى غنى النفس». والمنّة تتطلّب شكراً، والله يزيد على الشكر، فأرشده إلى شكرها: فأما اليتيم فلا تقهره بأخذ ماله أو إذلاله أو أذاه، ذاكراً رعاية الله لك أيام يتمك، وأما السائل ذو الحاجة فأعطه ما وجدت، أو ردّه بكلمة طيبة تشرح صدره، ولا تنهره بزجر عنيف ولا بقول غير لطيف، ذاكراً ما كنت عليه من حاجة، وأما بنعمة ربك من الإيمان والوحي والعلم فحدّث بها إبلاغاً وتعليماً وتربية وهداية، فذاك شكرها، والله يحب الشاكرين.", "h": ["الدنيا لا تخلو من كدر، وصدق الله العظيم: «لقد خلقنا الإنسان في كبد».", "بيان علوّ المقام المحمدي وشرف مكانته.", "مشروعية التذكير بالنعم والنقم حملاً للعبد على الصبر والشكر.", "وجوب شكر النعم بصرفها في مرضاة المنعم ﷻ.", "تقرير معنى الحديث: «إن الله تعالى إذا أنعم على عبد نعمة أحب أن يرى أثرها عليه»."], "k": "«وأما السائل فلا تنهر»… حين لا أستطيع أن أعطي، هل أردّ بكلمة طيبة على الأقل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 447;
insert into public.tdb_cards(topic, i, body) select 447, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١١", "q": "وَٱلضُّحَىٰ ﴿١﴾ وَٱلَّيۡلِ إِذَا سَجَىٰ ﴿٢﴾ مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ ﴿٣﴾ وَلَلۡأٓخِرَةُ خَيۡرٞ لَّكَ مِنَ ٱلۡأُولَىٰ ﴿٤﴾ وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ ﴿٥﴾ أَلَمۡ يَجِدۡكَ يَتِيمٗا فَـَٔاوَىٰ ﴿٦﴾ وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ ﴿٧﴾ وَوَجَدَكَ عَآئِلٗا فَأَغۡنَىٰ ﴿٨﴾ فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ ﴿٩﴾ وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ ﴿١٠﴾ وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ ﴿١١﴾", "w": [["والضحى", "أول النهار، ما بين طلوع الشمس وارتفاعها قيد رمح إلى الزوال."], ["والليل إذا سجى", "غطّى بظلامه المعمورة وسكن، فسكن الناس وخلدوا إلى الراحة."], ["ما ودّعك", "ما تركك."], ["وما قلى", "وما أبغضك."], ["ألم يجدك يتيماً", "فاقد الأب، إذ مات والده قبل ولادته."], ["فآوى", "فآواك بأن ضمّك إلى عمك أبي طالب."], ["ووجدك ضالاً", "لا تعرف ديناً ولا هدى."], ["فأغنى", "بالقناعة، وبما يسّر لك من مال خديجة وأبي بكر الصديق."], ["فلا تقهر", "لا تذلّه ولا تأخذ ماله."], ["فلا تنهر", "لا تنهره بزجر ونحوه."], ["وأما بنعمة ربك فحدّث", "اذكر ما أنعم الله تعالى به عليك شكراً له على ذلك."]], "m": "هذا قسم من الله تعالى لرسوله ﷺ على أنه ما تركه ولا أبغضه؛ وذلك أنه أبطأ عنه الوحي أياماً، فلما رأى ذلك المشركون فرحوا به وعيّروه، فأنزل الله سورة الضحى، يقسم له فيها بالضحى، وهو أول النهار، وبالليل إذا غطّى بظلامه المعمورة وسكن: ما تركك ربك يا محمد وما أبغضك، وللآخرة خير لك من الدنيا لما أعدّ الله لك فيها من الملك الكبير والنعيم العظيم المقيم، ولسوف يعطيك ربك من فواضل نعمه حتى ترضى: في الدنيا من كمال الدين وظهور الأمر، وفي الآخرة الشفاعة، وألا يبقى أحد من أمته أهل التوحيد في النار، والوسيلة والدرجة الرفيعة التي لا تكون لأحد سواه. ثم ذكّره بثلاث منن ليوقن أن الله معه وأنه ما تركه ولن يتركه، وحتى تنتهي فرحة المشركين ببطء الوحي: الأولى أن والده مات قبل ولادته وأمه ماتت بُعيد فطامه، فآواه ربه بأن ضمّه إلى عمه أبي طالب، فكان أباً رحيماً وعماً كريماً وحصناً منيعاً له، لم يتخلّ عن نصرته حتى وفاته. والثانية منّة العلم والهداية، فقد كان ﷺ يعيش في مكة لا يعرف علماً ولا شرعاً، وإن كان معصوماً من مقارفة أي ذنب، كما قال تعالى: «ما كنت تدري ما الكتاب ولا الإيمان». والثالثة الغنى بعد الحاجة، فقد مات والده ولم يخلّف أكثر من جارية هي بركة أم أيمن وبضعة جمال، فأغناه الله بغنى القناعة فلم يمدّ يده لأحد قط، وكان يقول: «ليس الغنى عن كثرة العَرَض، ولكن الغنى غنى النفس». والمنّة تتطلّب شكراً، والله يزيد على الشكر، فأرشده إلى شكرها: فأما اليتيم فلا تقهره بأخذ ماله أو إذلاله أو أذاه، ذاكراً رعاية الله لك أيام يتمك، وأما السائل ذو الحاجة فأعطه ما وجدت، أو ردّه بكلمة طيبة تشرح صدره، ولا تنهره بزجر عنيف ولا بقول غير لطيف، ذاكراً ما كنت عليه من حاجة، وأما بنعمة ربك من الإيمان والوحي والعلم فحدّث بها إبلاغاً وتعليماً وتربية وهداية، فذاك شكرها، والله يحب الشاكرين.", "h": ["الدنيا لا تخلو من كدر، وصدق الله العظيم: «لقد خلقنا الإنسان في كبد».", "بيان علوّ المقام المحمدي وشرف مكانته.", "مشروعية التذكير بالنعم والنقم حملاً للعبد على الصبر والشكر.", "وجوب شكر النعم بصرفها في مرضاة المنعم ﷻ.", "تقرير معنى الحديث: «إن الله تعالى إذا أنعم على عبد نعمة أحب أن يرى أثرها عليه»."], "k": "«وأما السائل فلا تنهر»… حين لا أستطيع أن أعطي، هل أردّ بكلمة طيبة على الأقل؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (448, 94, 1, 8, 'سورة الشرح ١ – ٨', 'الشرح: إن مع العسر يسراً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 448) = $j$[{"lbl": "الآيات ١ – ٨", "q": "أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ ﴿١﴾ وَوَضَعۡنَا عَنكَ وِزۡرَكَ ﴿٢﴾ ٱلَّذِيٓ أَنقَضَ ظَهۡرَكَ ﴿٣﴾ وَرَفَعۡنَا لَكَ ذِكۡرَكَ ﴿٤﴾ فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا ﴿٥﴾ إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا ﴿٦﴾ فَإِذَا فَرَغۡتَ فَٱنصَبۡ ﴿٧﴾ وَإِلَىٰ رَبِّكَ فَٱرۡغَب ﴿٨﴾", "w": [["ألم", "الاستفهام للتقرير، أي إن الله تعالى يقرّر رسوله بنعمه عليه."], ["نشرح لك صدرك", "بالنبوة، وبشقّه وتطهيره وملئه إيماناً وحكمة."], ["ووضعنا عنك وزرك", "حططنا عنك ما سلف من تبعات أيام الجاهلية قبل نبوتك."], ["الذي أنقض ظهرك", "الذي أثقل ظهرك، حيث كان ﷺ يشعر بثقل السنين التي عاشها قبل النبوة لم يعبد فيها الله تعالى بفعل محابّه وترك مكارهه لعدم علمه بذلك."], ["ورفعنا لك ذكرك", "أعليناه، فأصبحت تُذكر معي في الأذان والإقامة والتشهد."], ["فإن مع العسر يسراً", "مع الشدة سهولة."], ["فإذا فرغت", "من الصلاة."], ["فانصب", "اتعب في الدعاء."], ["وإلى ربك فارغب", "فاضرع إليه راغباً فيما عنده من الخيرات والبركات."]], "m": "هذه ثلاث منن أخرى بعد المنن الثلاث التي جاءت في السورة قبلها، منّ الله تعالى بها على رسوله: الأولى شرح صدره ليتّسع للوحي ولما سيلقاه من قومه من سيئ القول وباطل الكلام الذي يضيق به الإنسان. والثانية وضع الوزر عنه، فإنه ﷺ وإن لم يكن له وزر حقيقة، فقد كان يشعر بحمل ثقيل من جرّاء ترك العبادة والتقرّب إلى الله فيما قبل النبوة، إذ عاش أربعين سنة لم يعرف فيها عبادة ولا طاعة لله، أما مقارفة الخطايا فقد كان محفوظاً بحفظ الله له، فلم يسجد لصنم ولم يشرب خمراً ولم يقل أو يفعل إثماً قط، فقد شُقّ صدره وهو طفل في الرابعة من عمره، وأُخرجت منه العلقة التي هي محطة الشيطان التي ينزل بها من صدر الإنسان ويوسوس بالشر. والثالثة رفع الذكر، إذ قرن اسمه باسمه تعالى في التشهد وفي الأذان والإقامة، وذلك الدهر كله ما بقيت الحياة. فإن مع العسر يسراً، إن مع العسر يسراً، بشرى بقرب الفرج له ولأصحابه بعد ذلك العناء والشدة التي يقاسون، ومن ثَمّ بشّر ﷺ أصحابه وهو يقول: «لن يغلب عسرٌ يسرين». فإذا فرغت فانصب وإلى ربك فارغب، خطة لحياة المسلم وُضعت لنبي الإسلام ﷺ ليطبّقها أمام المسلمين ويطبّقوها معه: فإذا فرغت من عمل ديني فانصب لعمل دنيوي، وإذا فرغت من عمل دنيوي فانصب لعمل ديني أخروي؛ فرغت من الصلاة فانصب نفسك للذكر والدعاء بعدها، فرغت من الصلاة والدعاء فانصب نفسك لدنياك، فرغت من الجهاد فانصب نفسك للحج؛ ومعنى هذا أن المسلم يحيا حياة الجد والتعب، فلا يعرف وقتاً للهو واللعب أو للكسل والبطالة قط. وارغب بعد كل عمل تقوم به في مثوبة ربك وما عنده من الفضل والخير، إذ هو الذي تعمل له وتنصب من أجله، فلا ترغب في غيره ولا تطلب سواه.", "h": ["بيان ما أكرم الله تعالى به رسوله محمداً ﷺ من شرح صدره ومغفرة ذنوبه ورفع ذكره.", "بيان أن انشراح صدر المؤمن للدين واتّساعه لتحمّل الأذى في سبيل الله نعمة عظيمة.", "بيان أن مع العسر يسراً دائماً وأبداً، ولن يغلب عسرٌ يسرين، فرجاء المؤمن في الفرج دائم.", "بيان أن حياة المؤمن ليس فيها لهو ولا باطل، ولا فراغ لا عمل فيه أبداً ولا ساعة من الدهر قط."], "k": "«فإن مع العسر يسراً»… ما العسر الذي أعيشه الآن؟ وهل أنتظر يسرَه بيقين؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 448;
