insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (449, 95, 1, 8, 'سورة التين ١ – ٨', 'التين: لقد خلقنا الإنسان في أحسن تقويم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 449) = $j$[{"lbl": "الآيات ١ – ٨", "q": "وَٱلتِّينِ وَٱلزَّيۡتُونِ ﴿١﴾ وَطُورِ سِينِينَ ﴿٢﴾ وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ ﴿٣﴾ لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ ﴿٤﴾ ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ ﴿٥﴾ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ ﴿٦﴾ فَمَا يُكَذِّبُكَ بَعۡدُ بِٱلدِّينِ ﴿٧﴾ أَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ ﴿٨﴾", "w": [["والتين والزيتون", "هما المعروفان: التين فاكهة، والزيتون ما يُستخرج منه الزيت."], ["وطور سينين", "جبل الطور الذي ناجى الرب تعالى فيه موسى ﵇."], ["وهذا البلد الأمين", "مكة المكرمة، لأنها بلد حرام لا يُقاتل فيها، فمن دخلها أمن."], ["لقد خلقنا الإنسان", "جنس الإنسان: آدم ﵇ وذريته."], ["في أحسن تقويم", "في أجمل صورة، في اعتدال الخلق وحسن التركيب."], ["أسفل سافلين", "إلى أرذل العمر حتى يخرف ويصبح لا يعلم بعد أن كان يعلم."], ["أجر غير ممنون", "غير منقطع؛ فالشيخ الهرم الخرف المسلم يُكتب له ما كان يفعله أيام قدرته على العمل، فأجره لا ينقطع إلا بموته."]], "m": "هذا قسم جليل من أقسام الرب تعالى، أقسم فيه بأربعة أشياء: التين المعروف، وهو أشبه شيء بفاكهة الجنة لخلوّه من العَجَم، أي النوى، والزيتون وهو ذو منافع، يؤكل ويُدهن به ويُستصبح ويُتداوى به، وطور سينين وهو جبل سيناء، إذ تمّ عليه أكبر حدث في تاريخ الحياة، وهو أن الله تعالى كلّم موسى بن عمران نبي بني إسرائيل ﵇ وأسمعه كلامه، وتجلّى للجبل فصار دكاً، وبمكة أم القرى وفيها بيت الله وحولها حرمه. وجوابه: لقد خلقنا الإنسان في أحسن تقويم، ثم رددناه أسفل سافلين، إلا الذين آمنوا وعملوا الصالحات فلهم أجر غير ممنون. وقد تضمّن هذا الجواب أكبر مظاهر القدرة والعلم والرحمة، وهي موجبة للإيمان بالله وتوحيده ولقائه، وهو ما كذّب به أهل مكة؛ فالإنسان كائن حي مخلوق، فخالقه ذو قدرة قطعاً، وتعديل خلقه بنصب قامته وتسوية أعضائه وحسن سمته وجمال منظره دالّ على علم وقدرة، إذ القادر على خلق الإنسان اليوم قادر على خلقه غداً كما شاء متى شاء. ثم رددناه أسفل سافلين، وذلك بهرم بعض أفراده والنزول بهم إلى ما هو أسفل من سنّ الطفولة، حيث يفقد قواه العقلية والبدنية، إلا الذين آمنوا وعملوا الصالحات، فإن ما كانوا يقومون به من الفرائض والنوافل وسائر الطاعات لا ينقطع أجرهم منها بكبرهم وعجزهم عنها في سنّ الشيخوخة، بخلاف الكافر والفاجر، فليس لهم أعمال لا تنقطع، إلا من سنّ منهم سنة سيئة فإن ذنبه لا ينقطع ما بقي من يعمل بها. فمن يقدر على تكذيبك يا رسولنا بعد هذه الحجج الدالة على قدرة الله وعلمه ورحمته؟ فمن كذّب بالدين، وهو الجزاء الأخروي على عمل المكلّفين، فإن تكذيبه قائم على العناد والمكابرة. أليس الله بأحكم الحاكمين؟ بلى، فليس أعدل من الله ولا أحسن حكماً، فكيف يُظن أن الناس يعملون متفاوتين في أعمالهم ثم يموتون سواء ولا جزاء بالثواب ولا بالعقاب؟ هذا ظلم وباطل ينزّه الرب عنه سبحانه، فقضية البعث لا تقبل الجدل بحال من الأحوال.", "h": ["بيان منافع التين والزيتون، واستحباب غرس هاتين الشجرتين والعناية بهما.", "بيان شرف مكة وحرمها.", "بيان فضل الله على الإنسان في خلقه في أحسن صورة وأقوم تعديل.", "تقرير فضل الله على الإنسان المسلم، وهو أنه يطيل عمره، فإذا هرم وخرف كُتب له كل ما كان يعمله من الخير ويجانبه من الشر.", "مشروعية قول: «بلى وأنا على ذلك من الشاهدين» بعد قراءة «والتين»، إذ كان النبي ﷺ يقول ذلك."], "k": "«إلا الذين آمنوا وعملوا الصالحات فلهم أجر غير ممنون»… ما أعمله اليوم وأنا قادر قد يُكتب لي يوم أعجز؛ فلأغتنم قوّتي."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 449;
insert into public.tdb_cards(topic, i, body) select 449, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٨", "q": "وَٱلتِّينِ وَٱلزَّيۡتُونِ ﴿١﴾ وَطُورِ سِينِينَ ﴿٢﴾ وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ ﴿٣﴾ لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ ﴿٤﴾ ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ ﴿٥﴾ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ ﴿٦﴾ فَمَا يُكَذِّبُكَ بَعۡدُ بِٱلدِّينِ ﴿٧﴾ أَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ ﴿٨﴾", "w": [["والتين والزيتون", "هما المعروفان: التين فاكهة، والزيتون ما يُستخرج منه الزيت."], ["وطور سينين", "جبل الطور الذي ناجى الرب تعالى فيه موسى ﵇."], ["وهذا البلد الأمين", "مكة المكرمة، لأنها بلد حرام لا يُقاتل فيها، فمن دخلها أمن."], ["لقد خلقنا الإنسان", "جنس الإنسان: آدم ﵇ وذريته."], ["في أحسن تقويم", "في أجمل صورة، في اعتدال الخلق وحسن التركيب."], ["أسفل سافلين", "إلى أرذل العمر حتى يخرف ويصبح لا يعلم بعد أن كان يعلم."], ["أجر غير ممنون", "غير منقطع؛ فالشيخ الهرم الخرف المسلم يُكتب له ما كان يفعله أيام قدرته على العمل، فأجره لا ينقطع إلا بموته."]], "m": "هذا قسم جليل من أقسام الرب تعالى، أقسم فيه بأربعة أشياء: التين المعروف، وهو أشبه شيء بفاكهة الجنة لخلوّه من العَجَم، أي النوى، والزيتون وهو ذو منافع، يؤكل ويُدهن به ويُستصبح ويُتداوى به، وطور سينين وهو جبل سيناء، إذ تمّ عليه أكبر حدث في تاريخ الحياة، وهو أن الله تعالى كلّم موسى بن عمران نبي بني إسرائيل ﵇ وأسمعه كلامه، وتجلّى للجبل فصار دكاً، وبمكة أم القرى وفيها بيت الله وحولها حرمه. وجوابه: لقد خلقنا الإنسان في أحسن تقويم، ثم رددناه أسفل سافلين، إلا الذين آمنوا وعملوا الصالحات فلهم أجر غير ممنون. وقد تضمّن هذا الجواب أكبر مظاهر القدرة والعلم والرحمة، وهي موجبة للإيمان بالله وتوحيده ولقائه، وهو ما كذّب به أهل مكة؛ فالإنسان كائن حي مخلوق، فخالقه ذو قدرة قطعاً، وتعديل خلقه بنصب قامته وتسوية أعضائه وحسن سمته وجمال منظره دالّ على علم وقدرة، إذ القادر على خلق الإنسان اليوم قادر على خلقه غداً كما شاء متى شاء. ثم رددناه أسفل سافلين، وذلك بهرم بعض أفراده والنزول بهم إلى ما هو أسفل من سنّ الطفولة، حيث يفقد قواه العقلية والبدنية، إلا الذين آمنوا وعملوا الصالحات، فإن ما كانوا يقومون به من الفرائض والنوافل وسائر الطاعات لا ينقطع أجرهم منها بكبرهم وعجزهم عنها في سنّ الشيخوخة، بخلاف الكافر والفاجر، فليس لهم أعمال لا تنقطع، إلا من سنّ منهم سنة سيئة فإن ذنبه لا ينقطع ما بقي من يعمل بها. فمن يقدر على تكذيبك يا رسولنا بعد هذه الحجج الدالة على قدرة الله وعلمه ورحمته؟ فمن كذّب بالدين، وهو الجزاء الأخروي على عمل المكلّفين، فإن تكذيبه قائم على العناد والمكابرة. أليس الله بأحكم الحاكمين؟ بلى، فليس أعدل من الله ولا أحسن حكماً، فكيف يُظن أن الناس يعملون متفاوتين في أعمالهم ثم يموتون سواء ولا جزاء بالثواب ولا بالعقاب؟ هذا ظلم وباطل ينزّه الرب عنه سبحانه، فقضية البعث لا تقبل الجدل بحال من الأحوال.", "h": ["بيان منافع التين والزيتون، واستحباب غرس هاتين الشجرتين والعناية بهما.", "بيان شرف مكة وحرمها.", "بيان فضل الله على الإنسان في خلقه في أحسن صورة وأقوم تعديل.", "تقرير فضل الله على الإنسان المسلم، وهو أنه يطيل عمره، فإذا هرم وخرف كُتب له كل ما كان يعمله من الخير ويجانبه من الشر.", "مشروعية قول: «بلى وأنا على ذلك من الشاهدين» بعد قراءة «والتين»، إذ كان النبي ﷺ يقول ذلك."], "k": "«إلا الذين آمنوا وعملوا الصالحات فلهم أجر غير ممنون»… ما أعمله اليوم وأنا قادر قد يُكتب لي يوم أعجز؛ فلأغتنم قوّتي."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (450, 96, 1, 19, 'سورة العلق ١ – ١٩', 'العلق: اقرأ باسم ربك الذي خلق', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 450) = $j$[{"lbl": "الآيات ١ – ٥", "q": "ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ ﴿١﴾ خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ ﴿٢﴾ ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ﴿٣﴾ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ ﴿٤﴾ عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ ﴿٥﴾", "w": [["اقرأ", "أوجد القراءة، وهي جمع الكلمات ذات الحروف باللسان."], ["باسم ربك", "بذكر اسم ربك."], ["الذي خلق", "خلق آدم من سلالة من طين."], ["خلق الإنسان", "الإنسان الذي هو ذرية آدم."], ["من علق", "جمع علقة، وهي النطفة في الطور الثاني حيث تصير قطعة من دم."], ["وربك الأكرم", "الذي لا يوازيه كريم ولا يعادله ولا يساويه."], ["الذي علّم بالقلم", "علّم العباد الكتابة والخط بالقلم."], ["علّم الإنسان", "جنس الإنسان."], ["ما لم يعلم", "ما لم يكن يعلمه من سائر العلوم والمعارف."]], "m": "هذه الآيات الخمس أول ما نزل من القرآن الكريم، ومما اشتهر في ذلك أن النبي ﷺ كان يأتي حراء يتحنّث فيه، فراراً مما عليه قومه من الشرك والباطل، حتى فاجأه الحق وهو في غار حراء، فقال: يا محمد، أنا جبريل وأنت رسول الله، ثم قال: اقرأ، قال: «ما أنا بقارئ»، قال: «فأخذني فغطّني ثلاث مرات حتى بلغ مني الجهد، ثم قال: اقرأ باسم ربك الذي خلق، فقرأت». يأمر الله تعالى رسوله أن يقرأ بادئاً قراءته بذكر اسم ربه، الذي خلق الخلق كله، وخلق آدم من طين، وخلق الإنسان من أولاد آدم من علق، والعلق اسم جمع واحده علقة، وهي قطعة من الدم غليظة كانت في الأربعين يوماً الأولى في الرحم نطفة، ثم تطوّرت إلى علقة تعلق بجدار الرحم، ثم تتطوّر في أربعين يوماً إلى مضغة لحم، ثم إما أن يُؤذن بتخلّقها فتُخلّق، وإما لا فيطرحها الرحم قطعة لحم. اقرأ، تأكيد للأمر الأول لصعوبة الأمر واندهاش الرسول ﷺ للمفاجأة، وربك الأكرم هو الذي علّم عباده بالقلم الكتابة والخط، ومن كرمه الذي أفاض منه على عباده نعمه التي لا تُحصى أنه علّم الإنسان بواسطة القلم ما لم يكن يعلم من العلوم والمعارف. وهذه إشادة بالقلم، وأنه واسطة العلوم والمعارف، والواسطة تشرف بشرف الغاية؛ فلذا لا أشرف في الدنيا من عباد الله الصالحين والعلوم الإلهية في الكتاب والسنة، وما دعوا إليه وحضّا عليه من العلوم النافعة.", "h": ["تقرير الوحي الإلهي وإثبات النبوة المحمدية.", "مشروعية ابتداء القراءة بذكر اسم الله، ولذا افتُتحت سور القرآن، ما عدا التوبة، ببسم الله الرحمن الرحيم.", "بيان تطوّر النطفة في الرحم إلى علقة، ومنها يتخلّق الإنسان.", "إعظام شأن الله تعالى وعظم كرمه، فلا أحد يعادله في الكرم.", "التنويه بشأن الكتابة والخط بالقلم، إذ المعارف والعلوم لم تُدوّن إلا بالكتابة والقلم.", "بيان فضل الله تعالى على الإنسان في تعليمه ما لم يكن يعلم بواسطة الكتابة والخط."], "k": "«اقرأ»… أول كلمة نزلت أمرٌ بالقراءة؛ فماذا أقرأ اليوم مما ينفعني عند ربي؟"}, {"lbl": "الآيات ٦ – ١٩", "q": "كَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ ﴿٦﴾ أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ ﴿٧﴾ إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ ﴿٨﴾ أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ ﴿٩﴾ عَبۡدًا إِذَا صَلَّىٰٓ ﴿١٠﴾ أَرَءَيۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰٓ ﴿١١﴾ أَوۡ أَمَرَ بِٱلتَّقۡوَىٰٓ ﴿١٢﴾ أَرَءَيۡتَ إِن كَذَّبَ وَتَوَلَّىٰٓ ﴿١٣﴾ أَلَمۡ يَعۡلَم بِأَنَّ ٱللَّهَ يَرَىٰ ﴿١٤﴾ كَلَّا لَئِن لَّمۡ يَنتَهِ لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ ﴿١٥﴾ نَاصِيَةٖ كَٰذِبَةٍ خَاطِئَةٖ ﴿١٦﴾ فَلۡيَدۡعُ نَادِيَهُۥ ﴿١٧﴾ سَنَدۡعُ ٱلزَّبَانِيَةَ ﴿١٨﴾ كَلَّا لَا تُطِعۡهُ وَٱسۡجُدۡۤ وَٱقۡتَرِب۩ ﴿١٩﴾", "w": [["إن الإنسان", "ابن آدم قبل أن تتهذّب مشاعره وأخلاقه بالإيمان والآداب الشرعية."], ["ليطغى", "يتجاوز الحدّ المفروض له في سلوكه ومعاملاته."], ["إن إلى ربك الرجعى", "إن إلى ربك أيها الرسول الرجوع والمصير."], ["الذي ينهى عبداً إذا صلّى", "أبو جهل عمرو بن هشام المخزومي."], ["إن كان على الهدى", "هو رسول الله محمد بن عبد الله بن عبد المطلب بن هاشم."], ["إن كذّب وتولّى", "هو أبو جهل."], ["لئن لم ينتهِ", "من أذية رسولنا محمد ﷺ ومنعه من الصلاة خلف المقام."], ["لنسفعاً بالناصية", "لنأخذنّ بناصيته ونسحبه إلى نار جهنم."], ["فليدعُ ناديه", "رجال مجلسه ومنتداه."], ["سندعُ الزبانية", "خزّان جهنم."], ["كلا", "ارتدع أيها الكاذب الكافر."], ["واقترب", "منه تعالى، وذلك بطاعته."]], "m": "يخبر تعالى عن طبيعة الإنسان قبل أن يهذّبه الإيمان والمعارف الإلهية المشتملة على معرفة محابّ الله تعالى ومساخطه، أنه إذا رأى نفسه قد استغنى بماله أو ولده أو سلطانه، وما أصبح في حاجة إلى غيره، يطغى فيتجاوز حدّ الآداب والعدل والحق، فيتكبّر ويظلم ويمنع الحقوق ويحتقر الضعفاء ويسخر بغيره. وكان أبو جهل مضرب المثل في الطغيان حتى قيل إنه فرعون هذه الأمة؛ فقد كان رسول الله ﷺ يصلّي في المسجد الحرام خلف المقام، فيأتيه هذا الطاغية ويهدّده ويقول: لقد نهيتك عن الصلاة هنا فلا تعد، وإن وجدتك مرة أخرى آخذ بناصيتك وأسحبك على الأرض، فأنزل الله هذه الآيات يقف برسوله على علّة ما يجده من أبي جهل وأضرابه، ويسلّيه: وإن طغوا وتجبّروا فإن مرجعهم إلينا، فاصبر على أذاهم. ثم قال قولاً يحمل العقلاء على التعجّب: أرأيت الذي ينهى عبداً إذا صلّى؟ وهل الصلاة جريمة؟ وهل فيها ضرر على أحد؟ أرأيت إن كان المصلّي على الهدى الموصل إلى سعادة الدارين، أو أمر بالتقوى؟ هل الآمر بأسباب النجاة يُعادى ويُضرب ويُهدّد؟ إن هذا لعجب العجاب. أرأيت إن كذّب هذا الناهي بالحق وتولّى عن الإيمان، كيف يكون حاله يوم يلقى ربه؟ ألم يعلم أن الله يرى أفعاله وتطاوله على رسول الله وتهديده؟ وبعد هذه الدعوة للطاغية لعله يرجع، إذا به يزداد طغياناً ويقول في مجلس قريش: واللات والعزّى لئن رأيت محمداً يصلّي لأطأنّ على رقبته، وفعلاً أتى إلى النبي ﷺ وهو يصلّي ليطأ على رقبته، فإذا به ينكص على عقبيه ويتّقي بيديه، فقيل له: ما لك؟ فقال: إن بيني وبينه خندقاً من نار وهولاً وأجنحة، فقال رسول الله ﷺ: «لو دنا مني لاختطفته الملائكة عضواً عضواً». وأنزل الله: كلا لئن لم ينتهِ عن أذية رسولنا لنأخذنّ بناصيته الكاذبة الخاطئة ونجرّه إلى جهنم، فليدعُ حينئذ رجال ناديه، فإنّا ندعو الزبانية خزنة النار من الملائكة. كلا، فليرتدع هذا الطاغية، فإنه لن يقدر أن يصل إلى رسولنا بعد اليوم بأذى، وقد ارتدع فعلاً ولم يجرؤ بعد ذلك أن يمدّ لسانه ولا يده بسوء لرسول الله ﷺ. لا تطعه فيما يطلب منك من ترك الصلاة في المسجد الحرام فقد كفيناك شرّه، واسجد واقترب إلينا بالطاعات، ومن أهمّها الصلاة.", "h": ["بيان سبب نزول الآيات من «كلا إن الإنسان ليطغى» إلى آخر السورة.", "بيان طبع الإنسان إذا لم يُهذّب بالإيمان والتقوى.", "نصرة الله لرسوله ﷺ بالملائكة عياناً في المسجد الحرام.", "بيان أن أبا جهل فرعون هذه الأمة، وأنه كان أظلم قريش لرسول الله ﷺ وأصحابه.", "مشروعية السجود عند تلاوة هذه السورة إذا قرأ: «واسجد واقترب»، شُرع له السجود، إلا أن يكون يصلّي بجماعة في الصلاة السرية فلا يسجد لئلا يفتنهم."], "k": "«واسجد واقترب»… أقرب ما أكون من ربي وأنا ساجد؛ فهل أطيل سجودي وأحضر قلبي فيه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 450;
insert into public.tdb_cards(topic, i, body) select 450, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ ﴿١﴾ خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ ﴿٢﴾ ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ﴿٣﴾ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ ﴿٤﴾ عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ ﴿٥﴾", "w": [["اقرأ", "أوجد القراءة، وهي جمع الكلمات ذات الحروف باللسان."], ["باسم ربك", "بذكر اسم ربك."], ["الذي خلق", "خلق آدم من سلالة من طين."], ["خلق الإنسان", "الإنسان الذي هو ذرية آدم."], ["من علق", "جمع علقة، وهي النطفة في الطور الثاني حيث تصير قطعة من دم."], ["وربك الأكرم", "الذي لا يوازيه كريم ولا يعادله ولا يساويه."], ["الذي علّم بالقلم", "علّم العباد الكتابة والخط بالقلم."], ["علّم الإنسان", "جنس الإنسان."], ["ما لم يعلم", "ما لم يكن يعلمه من سائر العلوم والمعارف."]], "m": "هذه الآيات الخمس أول ما نزل من القرآن الكريم، ومما اشتهر في ذلك أن النبي ﷺ كان يأتي حراء يتحنّث فيه، فراراً مما عليه قومه من الشرك والباطل، حتى فاجأه الحق وهو في غار حراء، فقال: يا محمد، أنا جبريل وأنت رسول الله، ثم قال: اقرأ، قال: «ما أنا بقارئ»، قال: «فأخذني فغطّني ثلاث مرات حتى بلغ مني الجهد، ثم قال: اقرأ باسم ربك الذي خلق، فقرأت». يأمر الله تعالى رسوله أن يقرأ بادئاً قراءته بذكر اسم ربه، الذي خلق الخلق كله، وخلق آدم من طين، وخلق الإنسان من أولاد آدم من علق، والعلق اسم جمع واحده علقة، وهي قطعة من الدم غليظة كانت في الأربعين يوماً الأولى في الرحم نطفة، ثم تطوّرت إلى علقة تعلق بجدار الرحم، ثم تتطوّر في أربعين يوماً إلى مضغة لحم، ثم إما أن يُؤذن بتخلّقها فتُخلّق، وإما لا فيطرحها الرحم قطعة لحم. اقرأ، تأكيد للأمر الأول لصعوبة الأمر واندهاش الرسول ﷺ للمفاجأة، وربك الأكرم هو الذي علّم عباده بالقلم الكتابة والخط، ومن كرمه الذي أفاض منه على عباده نعمه التي لا تُحصى أنه علّم الإنسان بواسطة القلم ما لم يكن يعلم من العلوم والمعارف. وهذه إشادة بالقلم، وأنه واسطة العلوم والمعارف، والواسطة تشرف بشرف الغاية؛ فلذا لا أشرف في الدنيا من عباد الله الصالحين والعلوم الإلهية في الكتاب والسنة، وما دعوا إليه وحضّا عليه من العلوم النافعة.", "h": ["تقرير الوحي الإلهي وإثبات النبوة المحمدية.", "مشروعية ابتداء القراءة بذكر اسم الله، ولذا افتُتحت سور القرآن، ما عدا التوبة، ببسم الله الرحمن الرحيم.", "بيان تطوّر النطفة في الرحم إلى علقة، ومنها يتخلّق الإنسان.", "إعظام شأن الله تعالى وعظم كرمه، فلا أحد يعادله في الكرم.", "التنويه بشأن الكتابة والخط بالقلم، إذ المعارف والعلوم لم تُدوّن إلا بالكتابة والقلم.", "بيان فضل الله تعالى على الإنسان في تعليمه ما لم يكن يعلم بواسطة الكتابة والخط."], "k": "«اقرأ»… أول كلمة نزلت أمرٌ بالقراءة؛ فماذا أقرأ اليوم مما ينفعني عند ربي؟"}, {"lbl": "الآيات ٦ – ١٩", "q": "كَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ ﴿٦﴾ أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ ﴿٧﴾ إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ ﴿٨﴾ أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ ﴿٩﴾ عَبۡدًا إِذَا صَلَّىٰٓ ﴿١٠﴾ أَرَءَيۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰٓ ﴿١١﴾ أَوۡ أَمَرَ بِٱلتَّقۡوَىٰٓ ﴿١٢﴾ أَرَءَيۡتَ إِن كَذَّبَ وَتَوَلَّىٰٓ ﴿١٣﴾ أَلَمۡ يَعۡلَم بِأَنَّ ٱللَّهَ يَرَىٰ ﴿١٤﴾ كَلَّا لَئِن لَّمۡ يَنتَهِ لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ ﴿١٥﴾ نَاصِيَةٖ كَٰذِبَةٍ خَاطِئَةٖ ﴿١٦﴾ فَلۡيَدۡعُ نَادِيَهُۥ ﴿١٧﴾ سَنَدۡعُ ٱلزَّبَانِيَةَ ﴿١٨﴾ كَلَّا لَا تُطِعۡهُ وَٱسۡجُدۡۤ وَٱقۡتَرِب۩ ﴿١٩﴾", "w": [["إن الإنسان", "ابن آدم قبل أن تتهذّب مشاعره وأخلاقه بالإيمان والآداب الشرعية."], ["ليطغى", "يتجاوز الحدّ المفروض له في سلوكه ومعاملاته."], ["إن إلى ربك الرجعى", "إن إلى ربك أيها الرسول الرجوع والمصير."], ["الذي ينهى عبداً إذا صلّى", "أبو جهل عمرو بن هشام المخزومي."], ["إن كان على الهدى", "هو رسول الله محمد بن عبد الله بن عبد المطلب بن هاشم."], ["إن كذّب وتولّى", "هو أبو جهل."], ["لئن لم ينتهِ", "من أذية رسولنا محمد ﷺ ومنعه من الصلاة خلف المقام."], ["لنسفعاً بالناصية", "لنأخذنّ بناصيته ونسحبه إلى نار جهنم."], ["فليدعُ ناديه", "رجال مجلسه ومنتداه."], ["سندعُ الزبانية", "خزّان جهنم."], ["كلا", "ارتدع أيها الكاذب الكافر."], ["واقترب", "منه تعالى، وذلك بطاعته."]], "m": "يخبر تعالى عن طبيعة الإنسان قبل أن يهذّبه الإيمان والمعارف الإلهية المشتملة على معرفة محابّ الله تعالى ومساخطه، أنه إذا رأى نفسه قد استغنى بماله أو ولده أو سلطانه، وما أصبح في حاجة إلى غيره، يطغى فيتجاوز حدّ الآداب والعدل والحق، فيتكبّر ويظلم ويمنع الحقوق ويحتقر الضعفاء ويسخر بغيره. وكان أبو جهل مضرب المثل في الطغيان حتى قيل إنه فرعون هذه الأمة؛ فقد كان رسول الله ﷺ يصلّي في المسجد الحرام خلف المقام، فيأتيه هذا الطاغية ويهدّده ويقول: لقد نهيتك عن الصلاة هنا فلا تعد، وإن وجدتك مرة أخرى آخذ بناصيتك وأسحبك على الأرض، فأنزل الله هذه الآيات يقف برسوله على علّة ما يجده من أبي جهل وأضرابه، ويسلّيه: وإن طغوا وتجبّروا فإن مرجعهم إلينا، فاصبر على أذاهم. ثم قال قولاً يحمل العقلاء على التعجّب: أرأيت الذي ينهى عبداً إذا صلّى؟ وهل الصلاة جريمة؟ وهل فيها ضرر على أحد؟ أرأيت إن كان المصلّي على الهدى الموصل إلى سعادة الدارين، أو أمر بالتقوى؟ هل الآمر بأسباب النجاة يُعادى ويُضرب ويُهدّد؟ إن هذا لعجب العجاب. أرأيت إن كذّب هذا الناهي بالحق وتولّى عن الإيمان، كيف يكون حاله يوم يلقى ربه؟ ألم يعلم أن الله يرى أفعاله وتطاوله على رسول الله وتهديده؟ وبعد هذه الدعوة للطاغية لعله يرجع، إذا به يزداد طغياناً ويقول في مجلس قريش: واللات والعزّى لئن رأيت محمداً يصلّي لأطأنّ على رقبته، وفعلاً أتى إلى النبي ﷺ وهو يصلّي ليطأ على رقبته، فإذا به ينكص على عقبيه ويتّقي بيديه، فقيل له: ما لك؟ فقال: إن بيني وبينه خندقاً من نار وهولاً وأجنحة، فقال رسول الله ﷺ: «لو دنا مني لاختطفته الملائكة عضواً عضواً». وأنزل الله: كلا لئن لم ينتهِ عن أذية رسولنا لنأخذنّ بناصيته الكاذبة الخاطئة ونجرّه إلى جهنم، فليدعُ حينئذ رجال ناديه، فإنّا ندعو الزبانية خزنة النار من الملائكة. كلا، فليرتدع هذا الطاغية، فإنه لن يقدر أن يصل إلى رسولنا بعد اليوم بأذى، وقد ارتدع فعلاً ولم يجرؤ بعد ذلك أن يمدّ لسانه ولا يده بسوء لرسول الله ﷺ. لا تطعه فيما يطلب منك من ترك الصلاة في المسجد الحرام فقد كفيناك شرّه، واسجد واقترب إلينا بالطاعات، ومن أهمّها الصلاة.", "h": ["بيان سبب نزول الآيات من «كلا إن الإنسان ليطغى» إلى آخر السورة.", "بيان طبع الإنسان إذا لم يُهذّب بالإيمان والتقوى.", "نصرة الله لرسوله ﷺ بالملائكة عياناً في المسجد الحرام.", "بيان أن أبا جهل فرعون هذه الأمة، وأنه كان أظلم قريش لرسول الله ﷺ وأصحابه.", "مشروعية السجود عند تلاوة هذه السورة إذا قرأ: «واسجد واقترب»، شُرع له السجود، إلا أن يكون يصلّي بجماعة في الصلاة السرية فلا يسجد لئلا يفتنهم."], "k": "«واسجد واقترب»… أقرب ما أكون من ربي وأنا ساجد؛ فهل أطيل سجودي وأحضر قلبي فيه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (451, 97, 1, 5, 'سورة القدر ١ – ٥', 'القدر: ليلة القدر خير من ألف شهر', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 451) = $j$[{"lbl": "الآيات ١ – ٥", "q": "إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ ﴿١﴾ وَمَآ أَدۡرَىٰكَ مَا لَيۡلَةُ ٱلۡقَدۡرِ ﴿٢﴾ لَيۡلَةُ ٱلۡقَدۡرِ خَيۡرٞ مِّنۡ أَلۡفِ شَهۡرٖ ﴿٣﴾ تَنَزَّلُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرٖ ﴿٤﴾ سَلَٰمٌ هِيَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ ﴿٥﴾", "w": [["إنا أنزلناه", "القرآن جملة واحدة من اللوح المحفوظ إلى سماء الدنيا."], ["في ليلة القدر", "ليلة الحكم والتقدير التي يُقضى فيها قضاء السنة كلها."], ["وما أدراك ما ليلة القدر", "إن شأنها عظيم."], ["خير من ألف شهر", "العمل الصالح فيها من صلاة وتلاوة قرآن ودعاء خير من عبادة ألف شهر ليس فيها ليلة القدر، وهي ثلاث وثمانون سنة وأربعة أشهر."], ["والروح فيها", "جبريل في ليلة القدر."], ["بإذن ربهم", "ينزلون بأمره تعالى لهم بالتنزّل فيها."], ["من كل أمر", "من كل أمر قضاه الله تعالى في تلك السنة من رزق وأجل وغيرهما."], ["سلام هي حتى مطلع الفجر", "هي سلام من الشر كله، من غروب الشمس إلى طلوع الفجر."]], "m": "يخبر تعالى أن ما يتلوه عبده ورسوله محمد ﷺ هو حق وحي الله وكتابه، أنزله جملة واحدة من اللوح المحفوظ إلى السماء الدنيا، في ليلة الحكم والقضاء التي يقضي الله فيها ما يشاء من أحداث العالم من رزق وأجل وغيرهما إلى بداية السنة الآتية، وذلك كل سنة، كقوله: «إنا أنزلناه في ليلة مباركة إنا كنا منذرين، فيها يُفرق كل أمر حكيم»؛ إذ ما قضاه الله وحكم بوجوده قد كُتب في اللوح المحفوظ، ثم في ليلة القدر تُؤخذ نسخة من أحداث السنة فتُعطى الملائكة وتُنفّذ في تلك السنة. ولذلك كان لليلة القدر، بمعنى التقدير، شأن عظيم، ففضّلها الله على ألف شهر، وأخبر عن سبب فضلها أن الملائكة تتنزّل فيها وجبريل معهم بإذن ربهم وأمره إياهم بالنزول، مصحوبين بكل أمر قضاه الله وحكم به في تلك السنة من خير وشر ومن رزق وأجل. ولفضل هذه الليلة كانت العبادة فيها تفضل غيرها أضعافاً مضاعفة، إذ عمل تلك الليلة يُحسب لصاحبه عمل ألف شهر، أي ثلاث وثمانين سنة وأربعة أشهر. وهي سلام من كل شر، إذ هي كلها خير من غروب الشمس إلى طلوع فجرها، سلام الملائكة على العابدين من المؤمنين والمؤمنات، وسلامة من كل شر.", "h": ["تقرير الوحي وإثبات النبوة المحمدية.", "تقرير عقيدة القضاء والقدر.", "فضل ليلة القدر وفضل العبادة فيها.", "بيان أن القرآن نزل في رمضان جملة واحدة من اللوح المحفوظ إلى السماء الدنيا، وأن ابتداء نزوله على رسول الله ﷺ في رمضان أيضاً.", "الندب إلى طلب ليلة القدر للفوز بفضلها، وذلك في العشر الأواخر من شهر رمضان، وأرجى ليلة في العشر الأواخر هي الوتر، كالواحدة والعشرين إلى التاسعة والعشرين، لحديث الصحيح: «التمسوها في العشر الأواخر».", "استحباب الإكثار من قراءة القرآن وسماعه فيها، لمعارضة جبريل الرسولَ ﷺ القرآن في رمضان مرتين."], "k": "«ليلة القدر خير من ألف شهر»… ليلة واحدة تعدل عمراً؛ فكيف أستعدّ للعشر الأواخر من الآن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 451;
insert into public.tdb_cards(topic, i, body) select 451, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ ﴿١﴾ وَمَآ أَدۡرَىٰكَ مَا لَيۡلَةُ ٱلۡقَدۡرِ ﴿٢﴾ لَيۡلَةُ ٱلۡقَدۡرِ خَيۡرٞ مِّنۡ أَلۡفِ شَهۡرٖ ﴿٣﴾ تَنَزَّلُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرٖ ﴿٤﴾ سَلَٰمٌ هِيَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ ﴿٥﴾", "w": [["إنا أنزلناه", "القرآن جملة واحدة من اللوح المحفوظ إلى سماء الدنيا."], ["في ليلة القدر", "ليلة الحكم والتقدير التي يُقضى فيها قضاء السنة كلها."], ["وما أدراك ما ليلة القدر", "إن شأنها عظيم."], ["خير من ألف شهر", "العمل الصالح فيها من صلاة وتلاوة قرآن ودعاء خير من عبادة ألف شهر ليس فيها ليلة القدر، وهي ثلاث وثمانون سنة وأربعة أشهر."], ["والروح فيها", "جبريل في ليلة القدر."], ["بإذن ربهم", "ينزلون بأمره تعالى لهم بالتنزّل فيها."], ["من كل أمر", "من كل أمر قضاه الله تعالى في تلك السنة من رزق وأجل وغيرهما."], ["سلام هي حتى مطلع الفجر", "هي سلام من الشر كله، من غروب الشمس إلى طلوع الفجر."]], "m": "يخبر تعالى أن ما يتلوه عبده ورسوله محمد ﷺ هو حق وحي الله وكتابه، أنزله جملة واحدة من اللوح المحفوظ إلى السماء الدنيا، في ليلة الحكم والقضاء التي يقضي الله فيها ما يشاء من أحداث العالم من رزق وأجل وغيرهما إلى بداية السنة الآتية، وذلك كل سنة، كقوله: «إنا أنزلناه في ليلة مباركة إنا كنا منذرين، فيها يُفرق كل أمر حكيم»؛ إذ ما قضاه الله وحكم بوجوده قد كُتب في اللوح المحفوظ، ثم في ليلة القدر تُؤخذ نسخة من أحداث السنة فتُعطى الملائكة وتُنفّذ في تلك السنة. ولذلك كان لليلة القدر، بمعنى التقدير، شأن عظيم، ففضّلها الله على ألف شهر، وأخبر عن سبب فضلها أن الملائكة تتنزّل فيها وجبريل معهم بإذن ربهم وأمره إياهم بالنزول، مصحوبين بكل أمر قضاه الله وحكم به في تلك السنة من خير وشر ومن رزق وأجل. ولفضل هذه الليلة كانت العبادة فيها تفضل غيرها أضعافاً مضاعفة، إذ عمل تلك الليلة يُحسب لصاحبه عمل ألف شهر، أي ثلاث وثمانين سنة وأربعة أشهر. وهي سلام من كل شر، إذ هي كلها خير من غروب الشمس إلى طلوع فجرها، سلام الملائكة على العابدين من المؤمنين والمؤمنات، وسلامة من كل شر.", "h": ["تقرير الوحي وإثبات النبوة المحمدية.", "تقرير عقيدة القضاء والقدر.", "فضل ليلة القدر وفضل العبادة فيها.", "بيان أن القرآن نزل في رمضان جملة واحدة من اللوح المحفوظ إلى السماء الدنيا، وأن ابتداء نزوله على رسول الله ﷺ في رمضان أيضاً.", "الندب إلى طلب ليلة القدر للفوز بفضلها، وذلك في العشر الأواخر من شهر رمضان، وأرجى ليلة في العشر الأواخر هي الوتر، كالواحدة والعشرين إلى التاسعة والعشرين، لحديث الصحيح: «التمسوها في العشر الأواخر».", "استحباب الإكثار من قراءة القرآن وسماعه فيها، لمعارضة جبريل الرسولَ ﷺ القرآن في رمضان مرتين."], "k": "«ليلة القدر خير من ألف شهر»… ليلة واحدة تعدل عمراً؛ فكيف أستعدّ للعشر الأواخر من الآن؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (452, 98, 1, 8, 'سورة البينة ١ – ٨', 'البينة: وما أُمروا إلا ليعبدوا الله مخلصين له الدين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 452) = $j$[{"lbl": "الآيات ١ – ٥", "q": "لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ ﴿١﴾ رَسُولٞ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفٗا مُّطَهَّرَةٗ ﴿٢﴾ فِيهَا كُتُبٞ قَيِّمَةٞ ﴿٣﴾ وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ ﴿٤﴾ وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ ﴿٥﴾", "w": [["من أهل الكتاب", "اليهود والنصارى."], ["والمشركين", "عبدة الأصنام."], ["حتى تأتيهم البينة", "الحجة الواضحة، وهي محمد ﷺ وكتابه القرآن الكريم."], ["رسول من الله", "محمد رسول الله ﷺ."], ["صحفاً مطهّرة", "من الباطل."], ["فيها كتب قيّمة", "في تلك الصحف المطهّرة كتب من الله مستقيمة."], ["إلا من بعد ما جاءتهم البينة", "الرسول محمد ﷺ وكتابه القرآن الكريم."], ["وما أُمروا", "في كتبهم: التوراة والإنجيل."], ["حنفاء", "مائلين عن الأديان كلها إلى دين الإسلام."], ["دين القيّمة", "دين الملة القيّمة، أي المستقيمة."]], "m": "لم يكن الذين كفروا من أهل الكتاب، وهم اليهود والنصارى، والمشركون عبّاد الأصنام، منفصلين عما هم عليه من الديانة تاركين لها إلى غاية مجيء البيّنة لهم، فلما جاءتهم البيّنة، وهي محمد ﷺ وكتابه، انفكّوا، أي انقسموا: فمنهم من آمن بمحمد ﷺ وكتابه والدين الإسلامي، ومنهم من كفر. رسول من الله، هو محمد ﷺ، يقرأ عن ظهر قلب ما تضمّنته تلك الصحف المطهّرة من الباطل، المشتملة على كتب من عند الله مستقيمة لا انحراف فيها عن الحق، والمراد بالصحف المطهّرة القرآن الكريم. وما تفرّق الذين أوتوا الكتاب إلا من بعد ما جاءتهم البيّنة، إذ كانوا قبل البعثة المحمدية متّفقين على انتظار نبي آخر الزمان، وأنه النبي الخاتم للنبوات، فلما جاءهم تفرّقوا، فآمن بعض وكفر بعض، في حين أنهم ما أُمروا في كتبهم وعلى ألسنة رسلهم، وكذا في القرآن وعلى لسان نبيه محمد ﷺ، إلا ليعبدوا الله مخلصين له الدين، مائلين عن الأديان كلها إلى دين الإسلام، ويقيموا الصلاة بأن يؤدّوها في أوقاتها بشروطها وأركانها وآدابها، ويؤتوا الزكاة التي أوجب الله في الأموال لصالح الفقراء والمساكين، وذلك دين الملة القيّمة المستقيمة، الموصلة للعبد إلى رضا الرب وجنات الخلد بعد إنجائه من العذاب والغضب.", "h": ["بيان أن الديانات السابقة للإسلام والتي عاصرته كانت منحرفة، اختلط فيها الحق بالباطل، ولم تُصبح صالحة للإسعاد والهداية البشرية، ولا فرق بين اليهودية والنصرانية والمجوسية.", "أن أهل الكتاب بصورة خاصة كانوا منتظرين البعثة المحمدية بفارغ الصبر لعلمهم بما أصاب دينهم من فساد، ولما بُعث رسول الله ﷺ وجاءتهم البيّنة على صدقه وصحة ما جاء به، تفرّقوا فآمن البعض وكفر البعض.", "مما يُؤخذ على اليهود والنصارى أنهم في كتبهم مأمورون بعبادة الله وحده، مائلين عن كل دين إلى دين الإسلام، وإقامة الصلاة وإيتاء الزكاة، فما بالهم لما جاءهم الإسلام بمثل ما أُمروا به كفروا به وعادوه؟ والجواب أنهم لما انحرفوا عزّ عليهم أن يستقيموا لما ألفوا من الشرك والضلالة والباطل.", "بيان أن الملة القيّمة والدين المنجي من العذاب المحقّق للإسعاد والكمال ما قام على أساس عبادة الله وحده، وإقام الصلاة، وإيتاء الزكاة، والميل عن كل دين إلى هذا الدين الإسلامي."], "k": "«وما أُمروا إلا ليعبدوا الله مخلصين له الدين»… لمن أعمل حين لا يراني أحد؟"}, {"lbl": "الآيات ٦ – ٨", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآۚ أُوْلَـٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ ﴿٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ ﴿٧﴾ جَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ ﴿٨﴾", "w": [["إن الذين كفروا من أهل الكتاب", "بالإسلام ونبيه وكتابه، وهم اليهود والنصارى."], ["شرّ البرية", "شرّ الخليقة."], ["إن الذين آمنوا وعملوا الصالحات", "آمنوا بالإسلام ونبيه وكتابه وعملوا الصالحات."], ["خير البرية", "خير الخليقة."], ["جنات عدن", "بساتين إقامة دائمة."], ["رضي الله عنهم", "بإيمانهم وطاعتهم."], ["ورضوا عنه", "بثوابه."]], "m": "بعد أن بيّن تعالى الدين الحق المنجي من العذاب والموجب للنعيم، وهو الدين الإسلامي، أخبر أن من كفر به من أهل الكتاب ومن المشركين هم في نار جهنم خالدين فيها، هذا حكم الله فيهم لكفرهم بالحق وإعراضهم عنه بعد ما جاءتهم البيّنة وعرفوا الطريق فتنكّبوه، رضاً بالباطل واقتناعاً بالكفر والشرك بدل الإيمان والتوحيد، أولئك هم شرّ الخليقة كلها. كما أخبر أن الذين آمنوا بالله ورسوله وعملوا بالدين الإسلامي، فأدّوا الفرائض واجتنبوا النواهي وسابقوا في الخيرات، هم خير البرية، جزاؤهم عند ربهم يوم يلقونه بعد الموت بساتين إقامة دائمة، خالدين فيها أبداً لا يخرجون منها ولا يموتون، رضي الله عنهم بسبب إيمانهم وطاعتهم، ورضوا عنه بسبب ما وهبهم من النعيم المقيم في دار السلام. ذلك الجزاء العظيم، الذي يُجمع لأهله فيه بين سعادة الروح وسعادة البدن معاً، هو جزاء عبد خاف ربه فلم يعصه حتى لقيه، وإن عصاه يوماً تاب، وإن أخطأ رجع، حتى مات وهو على الطاعة لا على المعصية.", "h": ["بيان جزاء من كفر بالإسلام من سائر الناس، وأنه بئس الجزاء.", "بيان جزاء من آمن بالإسلام ودخل فيه وطبّق قواعده واستقام على الأمر والنهي فيه، وهو نعم الجزاء: رضا الله والخلود في دار السلام.", "فضل الخشية إن حملت صاحبها على طاعة الله ورسوله، فأطاعهما بأداء الفرائض وترك المحرّمات في الاعتقاد والقول والعمل."], "k": "«ذلك لمن خشي ربه»… خشية تعيدني كلما أخطأت؛ فهل أسارع بالرجوع بعد الزلّة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 452;
insert into public.tdb_cards(topic, i, body) select 452, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ ﴿١﴾ رَسُولٞ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفٗا مُّطَهَّرَةٗ ﴿٢﴾ فِيهَا كُتُبٞ قَيِّمَةٞ ﴿٣﴾ وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ ﴿٤﴾ وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ ﴿٥﴾", "w": [["من أهل الكتاب", "اليهود والنصارى."], ["والمشركين", "عبدة الأصنام."], ["حتى تأتيهم البينة", "الحجة الواضحة، وهي محمد ﷺ وكتابه القرآن الكريم."], ["رسول من الله", "محمد رسول الله ﷺ."], ["صحفاً مطهّرة", "من الباطل."], ["فيها كتب قيّمة", "في تلك الصحف المطهّرة كتب من الله مستقيمة."], ["إلا من بعد ما جاءتهم البينة", "الرسول محمد ﷺ وكتابه القرآن الكريم."], ["وما أُمروا", "في كتبهم: التوراة والإنجيل."], ["حنفاء", "مائلين عن الأديان كلها إلى دين الإسلام."], ["دين القيّمة", "دين الملة القيّمة، أي المستقيمة."]], "m": "لم يكن الذين كفروا من أهل الكتاب، وهم اليهود والنصارى، والمشركون عبّاد الأصنام، منفصلين عما هم عليه من الديانة تاركين لها إلى غاية مجيء البيّنة لهم، فلما جاءتهم البيّنة، وهي محمد ﷺ وكتابه، انفكّوا، أي انقسموا: فمنهم من آمن بمحمد ﷺ وكتابه والدين الإسلامي، ومنهم من كفر. رسول من الله، هو محمد ﷺ، يقرأ عن ظهر قلب ما تضمّنته تلك الصحف المطهّرة من الباطل، المشتملة على كتب من عند الله مستقيمة لا انحراف فيها عن الحق، والمراد بالصحف المطهّرة القرآن الكريم. وما تفرّق الذين أوتوا الكتاب إلا من بعد ما جاءتهم البيّنة، إذ كانوا قبل البعثة المحمدية متّفقين على انتظار نبي آخر الزمان، وأنه النبي الخاتم للنبوات، فلما جاءهم تفرّقوا، فآمن بعض وكفر بعض، في حين أنهم ما أُمروا في كتبهم وعلى ألسنة رسلهم، وكذا في القرآن وعلى لسان نبيه محمد ﷺ، إلا ليعبدوا الله مخلصين له الدين، مائلين عن الأديان كلها إلى دين الإسلام، ويقيموا الصلاة بأن يؤدّوها في أوقاتها بشروطها وأركانها وآدابها، ويؤتوا الزكاة التي أوجب الله في الأموال لصالح الفقراء والمساكين، وذلك دين الملة القيّمة المستقيمة، الموصلة للعبد إلى رضا الرب وجنات الخلد بعد إنجائه من العذاب والغضب.", "h": ["بيان أن الديانات السابقة للإسلام والتي عاصرته كانت منحرفة، اختلط فيها الحق بالباطل، ولم تُصبح صالحة للإسعاد والهداية البشرية، ولا فرق بين اليهودية والنصرانية والمجوسية.", "أن أهل الكتاب بصورة خاصة كانوا منتظرين البعثة المحمدية بفارغ الصبر لعلمهم بما أصاب دينهم من فساد، ولما بُعث رسول الله ﷺ وجاءتهم البيّنة على صدقه وصحة ما جاء به، تفرّقوا فآمن البعض وكفر البعض.", "مما يُؤخذ على اليهود والنصارى أنهم في كتبهم مأمورون بعبادة الله وحده، مائلين عن كل دين إلى دين الإسلام، وإقامة الصلاة وإيتاء الزكاة، فما بالهم لما جاءهم الإسلام بمثل ما أُمروا به كفروا به وعادوه؟ والجواب أنهم لما انحرفوا عزّ عليهم أن يستقيموا لما ألفوا من الشرك والضلالة والباطل.", "بيان أن الملة القيّمة والدين المنجي من العذاب المحقّق للإسعاد والكمال ما قام على أساس عبادة الله وحده، وإقام الصلاة، وإيتاء الزكاة، والميل عن كل دين إلى هذا الدين الإسلامي."], "k": "«وما أُمروا إلا ليعبدوا الله مخلصين له الدين»… لمن أعمل حين لا يراني أحد؟"}, {"lbl": "الآيات ٦ – ٨", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآۚ أُوْلَـٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ ﴿٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ ﴿٧﴾ جَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ ﴿٨﴾", "w": [["إن الذين كفروا من أهل الكتاب", "بالإسلام ونبيه وكتابه، وهم اليهود والنصارى."], ["شرّ البرية", "شرّ الخليقة."], ["إن الذين آمنوا وعملوا الصالحات", "آمنوا بالإسلام ونبيه وكتابه وعملوا الصالحات."], ["خير البرية", "خير الخليقة."], ["جنات عدن", "بساتين إقامة دائمة."], ["رضي الله عنهم", "بإيمانهم وطاعتهم."], ["ورضوا عنه", "بثوابه."]], "m": "بعد أن بيّن تعالى الدين الحق المنجي من العذاب والموجب للنعيم، وهو الدين الإسلامي، أخبر أن من كفر به من أهل الكتاب ومن المشركين هم في نار جهنم خالدين فيها، هذا حكم الله فيهم لكفرهم بالحق وإعراضهم عنه بعد ما جاءتهم البيّنة وعرفوا الطريق فتنكّبوه، رضاً بالباطل واقتناعاً بالكفر والشرك بدل الإيمان والتوحيد، أولئك هم شرّ الخليقة كلها. كما أخبر أن الذين آمنوا بالله ورسوله وعملوا بالدين الإسلامي، فأدّوا الفرائض واجتنبوا النواهي وسابقوا في الخيرات، هم خير البرية، جزاؤهم عند ربهم يوم يلقونه بعد الموت بساتين إقامة دائمة، خالدين فيها أبداً لا يخرجون منها ولا يموتون، رضي الله عنهم بسبب إيمانهم وطاعتهم، ورضوا عنه بسبب ما وهبهم من النعيم المقيم في دار السلام. ذلك الجزاء العظيم، الذي يُجمع لأهله فيه بين سعادة الروح وسعادة البدن معاً، هو جزاء عبد خاف ربه فلم يعصه حتى لقيه، وإن عصاه يوماً تاب، وإن أخطأ رجع، حتى مات وهو على الطاعة لا على المعصية.", "h": ["بيان جزاء من كفر بالإسلام من سائر الناس، وأنه بئس الجزاء.", "بيان جزاء من آمن بالإسلام ودخل فيه وطبّق قواعده واستقام على الأمر والنهي فيه، وهو نعم الجزاء: رضا الله والخلود في دار السلام.", "فضل الخشية إن حملت صاحبها على طاعة الله ورسوله، فأطاعهما بأداء الفرائض وترك المحرّمات في الاعتقاد والقول والعمل."], "k": "«ذلك لمن خشي ربه»… خشية تعيدني كلما أخطأت؛ فهل أسارع بالرجوع بعد الزلّة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (453, 99, 1, 8, 'سورة الزلزلة ١ – ٨', 'الزلزلة: فمن يعمل مثقال ذرة خيراً يره', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 453) = $j$[{"lbl": "الآيات ١ – ٨", "q": "إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا ﴿١﴾ وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا ﴿٢﴾ وَقَالَ ٱلۡإِنسَٰنُ مَا لَهَا ﴿٣﴾ يَوۡمَئِذٖ تُحَدِّثُ أَخۡبَارَهَا ﴿٤﴾ بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا ﴿٥﴾ يَوۡمَئِذٖ يَصۡدُرُ ٱلنَّاسُ أَشۡتَاتٗا لِّيُرَوۡاْ أَعۡمَٰلَهُمۡ ﴿٦﴾ فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ ﴿٧﴾ وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ ﴿٨﴾", "w": [["إذا زُلزلت الأرض", "حُرّكت لقيام الساعة."], ["وأخرجت الأرض أثقالها", "كنوزها وموتاها، فألقتها وتخلّت."], ["ما لها", "وقال الكافر: ما لها؟ أي أي شيء جعلها تتحرك هذه الحركة؟"], ["تحدّث أخبارها", "تخبر بما وقع عليها من خير وشر وتشهد به لأهله."], ["أوحى لها", "أن تحدّث أخبارها فحدّثت."], ["يصدر الناس أشتاتاً", "من موقف الحساب."], ["ليُروا أعمالهم", "جزاء أعمالهم، إما إلى الجنة وإما إلى النار."], ["مثقال ذرة", "زنة نملة صغيرة."]], "m": "إذا زُلزلت الأرض، أي تحرّكت حركتها الشديدة لقيام الساعة، وأخرجت أثقالها من كنوز، وذلك في النفخة الأولى، وأموات، وذلك في النفخة الثانية، والمقصود تقرير البعث والجزاء ليعمل الناس بما ينجيهم من النار ويدخلهم الجنة. وقال الإنسان: ما لها؟ ولا شك أن هذا السائل كان كافراً بالساعة، ولذا تساءل، أما المؤمن فهو يعلم ذلك لأنه جزء من عقيدته. يومئذ تخبر الأرض بما جرى عليها من خير وشر بلسان المقال أو الحال، وهي في هذا الإخبار مأمورة، بأن ربك أوحى لها بذلك. يومئذ يصدر الناس من ساحة فصل القضاء أشتاتاً، فمن آخذٍ ذات اليمين ومن آخذٍ ذات الشمال، ليُروا جزاء أعمالهم في الدنيا من حسنة وسيئة، فالحسنة تورث الجنة والسيئة تورث النار. فمن يعمل وزن ذرة من خير في الدنيا يُثب عليه في الآخرة، ومن يعمل وزن ذرة من شر يُجزَ به، إلا أن يعفو الجبار ﷻ. وبما أن الكفر مانع من دخول الجنة، فإن الكافر إذا عمل حسنة في الدنيا يرى جزاءها في الدنيا وليس له في الآخرة منها شيء، لحديث عائشة رضي الله عنها إذ سألت الرسول ﷺ عن عبد الله بن جدعان: هل ينفعه ما كان يفعله في الدنيا من إطعام الحجيج وكسوتهم؟ فقال: «لا، إنه لم يقل يوماً من الدهر: ربِّ اغفر لي خطيئتي يوم الدين». كما أن أبا بكر الصديق رضي الله عنه كان يأكل مع الرسول ﷺ فنزلت هذه الآية، فرفع يده من الطعام وقال: إني لراءٍ ما عملت من خير وشر؟ فقال النبي ﷺ: «إن ما ترى مما تكره فهو مثاقيل ذرّ شرٍّ كثير، ويدّخر الله لك مثاقيل الخير حتى تُعطاه يوم القيامة»، وتصديق ذلك في كتاب الله: «وما أصابكم من مصيبة فبما كسبت أيديكم ويعفو عن كثير».", "h": ["تقرير عقيدة البعث والجزاء.", "الإعلام بالانقلاب الكوني الذي تتبدّل فيه الأرض غير الأرض والسموات غير السموات.", "تكلّم الجمادات من آيات الله تعالى الدالة على قدرته وعلمه وحكمته، وهي موجبات ألوهيته بعبادته وحده دون سواه.", "تقرير حديث الصحيح: «اتقوا النار ولو بشق تمرة».", "الكافر عمله الخيري ينفعه في الدنيا دون الآخرة."], "k": "«فمن يعمل مثقال ذرة خيراً يره»… لا أحقر معروفاً ولو صغيراً؛ فما الذرّة التي أعملها اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 453;
insert into public.tdb_cards(topic, i, body) select 453, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٨", "q": "إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا ﴿١﴾ وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا ﴿٢﴾ وَقَالَ ٱلۡإِنسَٰنُ مَا لَهَا ﴿٣﴾ يَوۡمَئِذٖ تُحَدِّثُ أَخۡبَارَهَا ﴿٤﴾ بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا ﴿٥﴾ يَوۡمَئِذٖ يَصۡدُرُ ٱلنَّاسُ أَشۡتَاتٗا لِّيُرَوۡاْ أَعۡمَٰلَهُمۡ ﴿٦﴾ فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ ﴿٧﴾ وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ ﴿٨﴾", "w": [["إذا زُلزلت الأرض", "حُرّكت لقيام الساعة."], ["وأخرجت الأرض أثقالها", "كنوزها وموتاها، فألقتها وتخلّت."], ["ما لها", "وقال الكافر: ما لها؟ أي أي شيء جعلها تتحرك هذه الحركة؟"], ["تحدّث أخبارها", "تخبر بما وقع عليها من خير وشر وتشهد به لأهله."], ["أوحى لها", "أن تحدّث أخبارها فحدّثت."], ["يصدر الناس أشتاتاً", "من موقف الحساب."], ["ليُروا أعمالهم", "جزاء أعمالهم، إما إلى الجنة وإما إلى النار."], ["مثقال ذرة", "زنة نملة صغيرة."]], "m": "إذا زُلزلت الأرض، أي تحرّكت حركتها الشديدة لقيام الساعة، وأخرجت أثقالها من كنوز، وذلك في النفخة الأولى، وأموات، وذلك في النفخة الثانية، والمقصود تقرير البعث والجزاء ليعمل الناس بما ينجيهم من النار ويدخلهم الجنة. وقال الإنسان: ما لها؟ ولا شك أن هذا السائل كان كافراً بالساعة، ولذا تساءل، أما المؤمن فهو يعلم ذلك لأنه جزء من عقيدته. يومئذ تخبر الأرض بما جرى عليها من خير وشر بلسان المقال أو الحال، وهي في هذا الإخبار مأمورة، بأن ربك أوحى لها بذلك. يومئذ يصدر الناس من ساحة فصل القضاء أشتاتاً، فمن آخذٍ ذات اليمين ومن آخذٍ ذات الشمال، ليُروا جزاء أعمالهم في الدنيا من حسنة وسيئة، فالحسنة تورث الجنة والسيئة تورث النار. فمن يعمل وزن ذرة من خير في الدنيا يُثب عليه في الآخرة، ومن يعمل وزن ذرة من شر يُجزَ به، إلا أن يعفو الجبار ﷻ. وبما أن الكفر مانع من دخول الجنة، فإن الكافر إذا عمل حسنة في الدنيا يرى جزاءها في الدنيا وليس له في الآخرة منها شيء، لحديث عائشة رضي الله عنها إذ سألت الرسول ﷺ عن عبد الله بن جدعان: هل ينفعه ما كان يفعله في الدنيا من إطعام الحجيج وكسوتهم؟ فقال: «لا، إنه لم يقل يوماً من الدهر: ربِّ اغفر لي خطيئتي يوم الدين». كما أن أبا بكر الصديق رضي الله عنه كان يأكل مع الرسول ﷺ فنزلت هذه الآية، فرفع يده من الطعام وقال: إني لراءٍ ما عملت من خير وشر؟ فقال النبي ﷺ: «إن ما ترى مما تكره فهو مثاقيل ذرّ شرٍّ كثير، ويدّخر الله لك مثاقيل الخير حتى تُعطاه يوم القيامة»، وتصديق ذلك في كتاب الله: «وما أصابكم من مصيبة فبما كسبت أيديكم ويعفو عن كثير».", "h": ["تقرير عقيدة البعث والجزاء.", "الإعلام بالانقلاب الكوني الذي تتبدّل فيه الأرض غير الأرض والسموات غير السموات.", "تكلّم الجمادات من آيات الله تعالى الدالة على قدرته وعلمه وحكمته، وهي موجبات ألوهيته بعبادته وحده دون سواه.", "تقرير حديث الصحيح: «اتقوا النار ولو بشق تمرة».", "الكافر عمله الخيري ينفعه في الدنيا دون الآخرة."], "k": "«فمن يعمل مثقال ذرة خيراً يره»… لا أحقر معروفاً ولو صغيراً؛ فما الذرّة التي أعملها اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (454, 100, 1, 11, 'سورة العاديات ١ – ١١', 'العاديات: إن الإنسان لربه لكنود', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 454) = $j$[{"lbl": "الآيات ١ – ١١", "q": "وَٱلۡعَٰدِيَٰتِ ضَبۡحٗا ﴿١﴾ فَٱلۡمُورِيَٰتِ قَدۡحٗا ﴿٢﴾ فَٱلۡمُغِيرَٰتِ صُبۡحٗا ﴿٣﴾ فَأَثَرۡنَ بِهِۦ نَقۡعٗا ﴿٤﴾ فَوَسَطۡنَ بِهِۦ جَمۡعًا ﴿٥﴾ إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ ﴿٦﴾ وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٞ ﴿٧﴾ وَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ ﴿٨﴾ ۞أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ ﴿٩﴾ وَحُصِّلَ مَا فِي ٱلصُّدُورِ ﴿١٠﴾ إِنَّ رَبَّهُم بِهِمۡ يَوۡمَئِذٖ لَّخَبِيرُۢ ﴿١١﴾", "w": [["والعاديات", "الخيل تعدو في الغزو."], ["ضبحاً", "تضبح ضبحاً، والضبح صوت الخيل إذا عدت، أي جرت."], ["فالموريات قدحاً", "الخيل توري النار بحوافرها إذا سارت بالليل."], ["فالمغيرات صبحاً", "الخيل تغير على العدو صباحاً."], ["فأثرن به نقعاً", "هيّجن بمكان عدوها غباراً."], ["فوسطن به جمعاً", "بالنقع جمعَ العدو، أي حيث تجمّعاته."], ["لكنود", "لكفور، يجحد نعمه تعالى عليه."], ["لشهيد", "يشهد على نفسه بعمله."], ["لحب الخير", "لحب المال."], ["إذا بُعثر", "أُثير وأُخرج ما في القبور."], ["وحُصّل ما في الصدور", "بُيّن وأُفرز ما في الصدور من الإيمان والكفر."]], "m": "تضمّنت الآيات قسماً إلهياً عظيماً على حقيقة كبرى يجهلها كثير من الناس، وهي كفر الإنسان لربه ولنعمه عليه، يعدّ المصائب وينسى النعم والفواضل. أقسم تعالى بالعاديات ضبحاً، وهي الخيل تُخرج صوتاً خاصاً غير الصهيل المعروف، فالموريات قدحاً، أي الخيل توري النار بحوافرها إذا مشت فوق الحجارة ليلاً، ويدخل ضمن هذا كل قادحة للنار، فالمغيرات صبحاً، أي جماعات الخيل يركبها فرسانها للإغارة على العدو صباحاً، فأثارت الخيل الغبار والتراب عند سيرها بفرسانها، فتوسّطت جمع العدو وكتائبه لقتال أعداء الله الكافرين المفسدين في الأرض بالشرك والمعاصي. والمقسم عليه: إن الإنسان لربه لكنود، والمراد الإنسان الكافر والجاهل بربه، الذي لم تتهذّب روحه بمعرفة الله ومحابّه ومكارهه، ولم يزكِّ نفسه بفعل المحابّ وترك المكاره، فهو كفور لربه ولنعمه عليه، يذكر المصائب ويشعر بها ويصرخ لها، وينسى النعم والفواضل فلا يذكرها ولا يشكر الله عليها. وإن الله على هذا الوصف في الإنسان لشهيد، كما أن الإنسان شهيد على نفسه بأقواله وأفعاله بالكفر والجحود. وإنه لحب المال لشديد، وسُمّي المال خيراً تسمية عرفية، كما أنه خير من حيث إنه يحصل به الخير الكثير إذا أُنفق في مرضاة الله. أيكفر الإنسان بربه ويجحد نعمه، ويحب المال أشدّ الحب فيمنع حقوق الله فيه ويكتسبه مما حرّم الله عليه؟ أفلا يعلم إذا بُعثرت القبور وأُخرج ما فيها من البشر للحساب والجزاء، ووقفوا بين يدي الله، وأُفرز وبُيّن ما كان خفياً في الصدور من الاعتقادات والنيات الصالحة والفاسدة؟ إن ربهم بهم يومئذ لخبير، كما هو اليوم خبير، فلا يخفى عليه من ذلك شيء، وسيتمّ الجزاء العادل بحسب هذا العلم. فلو علم الكفور المحب للمال هذا وأيقنه لعدّل من سلوكه وأصلح اعتقاده وأقواله وأعماله؛ فالآيات دعوة إلى مراقبة الله تعالى بعد الإيمان والاستقامة على طاعته.", "h": ["الترغيب في الجهاد والإعداد له، كالخيل أمس ونفّاثات الطائرات اليوم.", "بيان حقيقة، وهي أن الإنسان كفور لربه ونعمه عليه، يذكر المصيبة إذا أصابته، وينسى النعم التي غطّته، إلا إذا آمن وعمل صالحاً.", "بيان أن الإنسان يحب المال حباً شديداً، إلا إذا هُذّب بالإيمان وصالح الأعمال.", "تقرير عقيدة البعث والجزاء."], "k": "«إن الإنسان لربه لكنود»… أعدّ مصائبي وأنسى نعمه؛ فلأعدّ اليوم ثلاث نعم وأشكره عليها."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 454;
