بالكفر والجحود. وإنه لحب المال لشديد، وسُمّي المال خيراً تسمية عرفية، كما أنه خير من حيث إنه يحصل به الخير الكثير إذا أُنفق في مرضاة الله. أيكفر الإنسان بربه ويجحد نعمه، ويحب المال أشدّ الحب فيمنع حقوق الله فيه ويكتسبه مما حرّم الله عليه؟ أفلا يعلم إذا بُعثرت القبور وأُخرج ما فيها من البشر للحساب والجزاء، ووقفوا بين يدي الله، وأُفرز وبُيّن ما كان خفياً في الصدور من الاعتقادات والنيات الصالحة والفاسدة؟ إن ربهم بهم يومئذ لخبير، كما هو اليوم خبير، فلا يخفى عليه من ذلك شيء، وسيتمّ الجزاء العادل بحسب هذا العلم. فلو علم الكفور المحب للمال هذا وأيقنه لعدّل من سلوكه وأصلح اعتقاده وأقواله وأعماله؛ فالآيات دعوة إلى مراقبة الله تعالى بعد الإيمان والاستقامة على طاعته.", "h": ["الترغيب في الجهاد والإعداد له، كالخيل أمس ونفّاثات الطائرات اليوم.", "بيان حقيقة، وهي أن الإنسان كفور لربه ونعمه عليه، يذكر المصيبة إذا أصابته، وينسى النعم التي غطّته، إلا إذا آمن وعمل صالحاً.", "بيان أن الإنسان يحب المال حباً شديداً، إلا إذا هُذّب بالإيمان وصالح الأعمال.", "تقرير عقيدة البعث والجزاء."], "k": "«إن الإنسان لربه لكنود»… أعدّ مصائبي وأنسى نعمه؛ فلأعدّ اليوم ثلاث نعم وأشكره عليها."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (455, 101, 1, 11, 'سورة القارعة ١ – ١١', 'القارعة: فأما من ثقلت موازينه', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 455) = $j$[{"lbl": "الآيات ١ – ١١", "q": "ٱلۡقَارِعَةُ ﴿١﴾ مَا ٱلۡقَارِعَةُ ﴿٢﴾ وَمَآ أَدۡرَىٰكَ مَا ٱلۡقَارِعَةُ ﴿٣﴾ يَوۡمَ يَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ ﴿٤﴾ وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٱلۡمَنفُوشِ ﴿٥﴾ فَأَمَّا مَن ثَقُلَتۡ مَوَٰزِينُهُۥ ﴿٦﴾ فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ ﴿٧﴾ وَأَمَّا مَنۡ خَفَّتۡ مَوَٰزِينُهُۥ ﴿٨﴾ فَأُمُّهُۥ هَاوِيَةٞ ﴿٩﴾ وَمَآ أَدۡرَىٰكَ مَا هِيَهۡ ﴿١٠﴾ نَارٌ حَامِيَةُۢ ﴿١١﴾", "w": [["القارعة", "القيامة، وسُمّيت القارعة لأنها تقرع القلوب بأهوالها."], ["ما القارعة", "أي شيء هي؟ فالاستفهام للتهويل من شأنها."], ["وما أدراك ما القارعة", "زيادة في تهويل أمرها وتعظيمه."], ["كالفراش المبثوث", "كغوغاء الجراد المنتشر يموج بعضهم في بعض."], ["كالعهن المنفوش", "كالصوف المندوف، هذه حالها أولاً، ثم تكون كثيباً مهيلاً، ثم تكون هباءً منبثّاً."], ["في عيشة راضية", "يرضاها صاحبها في الجنة، فهي مرضية له."], ["فأمّه هاوية", "مأواه ومسكنه الهاوية التي يهوي فيها على رأسه، وهي النار."], ["نار حامية", "هي نار حامية."]], "m": "تضمّنت آيات السورة الإحدى عشرة وصفاً لعقيدة البعث والجزاء التي كذّب بها المشركون وبالغوا في إنكارها؛ فأخبر تعالى أن القيامة تقرع الناس بأهوالها وعظائم ما يجري فيها، بحيث يكون الناس، وهم أشرف الكائنات الأرضية، في خفّة أحلامهم وحيرة عقولهم كالفراش المبثوث، وهو غوغاء الجراد وتراكمه وانتشاره يموج بعضه فوق بعض، وتكون الجبال على رسوّها وعلوّها وضخامتها كالصوف المندوف يتطاير هنا وهناك، هذا في أول الأمر، ثم تكون كالرمل المتهيّل، ثم كالهباء المنبث. فإذا بُعثوا ووقفوا بين يدي ربهم لحسابهم ومجازاتهم، فمن ثقلت موازينه فهو في عيشة يرضاها صاحبها، وكيف لا وهي الجنة دار النعيم المقيم! ومن خفّت موازينه، أي قلّت حسناته وكثرت سيئاته، أو لم يكن له حسنة بالمرة كأهل الكفر والشرك، فأمّه التي تضمّه إليها وتؤويه هاوية يهوي فيها على أم رأسه. وما أدراك ما هي؟ نار حامية، والاستفهام للتهويل من شأنها، ولا أشدّ هولاً منها، إنها النار دار البوار والخسران.", "h": ["تقرير عقيدة البعث والجزاء بذكر صورة صادقة لها.", "التحذير من أهوال يوم القيامة وعذاب الله تعالى فيها.", "تقرير عقيدة وزن الأعمال صالحها وفاسدها، وترتيب الجزاء عليها.", "تقرير أن الناس يوم القيامة فريقان: فريق في الجنة وفريق في السعير."], "k": "«فأما من ثقلت موازينه»… ما العمل الذي أضعه اليوم في ميزاني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 455;
