 عقيدة وزن الأعمال صالحها وفاسدها، وترتيب الجزاء عليها.", "تقرير أن الناس يوم القيامة فريقان: فريق في الجنة وفريق في السعير."], "k": "«فأما من ثقلت موازينه»… ما العمل الذي أضعه اليوم في ميزاني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (456, 102, 1, 8, 'سورة التكاثر ١ – ٨', 'التكاثر: ثم لتُسألنّ يومئذ عن النعيم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 456) = $j$[{"lbl": "الآيات ١ – ٨", "q": "أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ ﴿١﴾ حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ ﴿٢﴾ كَلَّا سَوۡفَ تَعۡلَمُونَ ﴿٣﴾ ثُمَّ كَلَّا سَوۡفَ تَعۡلَمُونَ ﴿٤﴾ كَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ ﴿٥﴾ لَتَرَوُنَّ ٱلۡجَحِيمَ ﴿٦﴾ ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ ﴿٧﴾ ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ ﴿٨﴾", "w": [["ألهاكم", "شغلكم عن طاعة الله تعالى."], ["التكاثر", "التباهي بكثرة المال."], ["حتى زرتم المقابر", "شغلكم التكاثر بالمال والتباهي بكثرته حتى متّم ونُقلتم إلى المقابر."], ["كلا", "ما هكذا ينبغي أن تفعلوا، فارتدعوا عن هذا التكاثر."], ["سوف تعلمون", "إذا دخلتم قبوركم علمتم خطأكم في التكاثر في الأموال والأولاد."], ["كلا لو تعلمون", "حقاً لو تعلمون."], ["علم اليقين", "علماً يقينياً عاقبة التكاثر لما تفاخرتم بكثرة أموالكم."], ["لترونّ الجحيم", "النار."], ["يومئذ", "يوم ترون الجحيم عين اليقين."], ["عن النعيم", "ما تنعّمتم به وتلذّذتم من الصحة والفراغ والأمن والمطاعم والمشارب."]], "m": "هذا خطاب الله تعالى للمشتغلين بجمع المال وتكثيره للمباهاة به والتفاخر، الأمر الذي ألهاهم عن طاعة الله ورسوله، فماتوا ولم يقدّموا لأنفسهم خيراً؛ فقال: شغلكم التكاثر في الأموال للتفاخر بها حتى زرتم المقابر فدُفنتم فيها إلى أن تخرجوا منها للحساب والجزاء. كلا، ما هكذا ينبغي أن تفعلوا، فارتدعوا عن هذا السلوك المفضي بكم إلى الهلاك والخسران، سوف تعلمون عاقبة تشاغلكم عن طاعة الله ورسوله والتزوّد للدار الآخرة، ثم كلا سوف تعلمون، كرّر الوعيد والتهديد. حقاً لو تعلمون ما تجدونه في قبوركم ويوم بعثكم ونشوركم لما تشاغلتم بالأموال وتكاثرتم فيها. وعزّتنا لترونّ الجحيم يوم القيامة، المشرك يراها ويصلاها، والمؤمن يراها وينجّيه الله منها، ثم لترونها عين اليقين، الأمر الذي لا شك فيه، إذ يُؤتى بجهنم فيراها أهل الموقف أجمعون، ثم لتُسألنّ يومئذ عن النعيم الذي كان لكم في الدنيا من صحة وفراغ وأمن وطعام وشراب، فمن أدّى شكره نجا، ومن لم يؤدِّ شكره أُخذ به. وقد صحّ أن النبي ﷺ قال لأبي بكر وعمر وأبي الهيثم بن التيهان: «هذا من النعيم الذي تُسألون عنه يوم القيامة»، يشير إلى بُسر ورطب وماء بارد، وصحّ أيضاً: «لا تزول قدما عبد يوم القيامة حتى يُسأل عن عمره فيمَ أفناه، وعن شبابه فيمَ أبلاه، وعن علمه ماذا عمل به، وعن ماله من أين اكتسبه وفيمَ أنفقه».", "h": ["التحذير من جمع المال وتكثيره مع عدم شكره، وترك طاعة الله ورسوله من أجله.", "إثبات عذاب القبر وتأكيده بقوله: «حتى زرتم المقابر كلا سوف تعلمون»، أي في القبر.", "تقرير عقيدة البعث وحتمية الجزاء بعد الحساب والاستنطاق والاستجواب.", "حتمية سؤال العبد عن النعم التي أنعم الله تعالى عليه بها في الدنيا، فإن كان شاكراً لها فاز، وإن كان كافراً لها أُخذ."], "k": "«ثم لتُسألنّ يومئذ عن النعيم»… كوب ماء بارد نعمة سأُسأل عنها؛ فهل أشكره عليه الآن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 456;
insert into public.tdb_cards(topic, i, body) select 456, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٨", "q": "أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ ﴿١﴾ حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ ﴿٢﴾ كَلَّا سَوۡفَ تَعۡلَمُونَ ﴿٣﴾ ثُمَّ كَلَّا سَوۡفَ تَعۡلَمُونَ ﴿٤﴾ كَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ ﴿٥﴾ لَتَرَوُنَّ ٱلۡجَحِيمَ ﴿٦﴾ ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ ﴿٧﴾ ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ ﴿٨﴾", "w": [["ألهاكم", "شغلكم عن طاعة الله تعالى."], ["التكاثر", "التباهي بكثرة المال."], ["حتى زرتم المقابر", "شغلكم التكاثر بالمال والتباهي بكثرته حتى متّم ونُقلتم إلى المقابر."], ["كلا", "ما هكذا ينبغي أن تفعلوا، فارتدعوا عن هذا التكاثر."], ["سوف تعلمون", "إذا دخلتم قبوركم علمتم خطأكم في التكاثر في الأموال والأولاد."], ["كلا لو تعلمون", "حقاً لو تعلمون."], ["علم اليقين", "علماً يقينياً عاقبة التكاثر لما تفاخرتم بكثرة أموالكم."], ["لترونّ الجحيم", "النار."], ["يومئذ", "يوم ترون الجحيم عين اليقين."], ["عن النعيم", "ما تنعّمتم به وتلذّذتم من الصحة والفراغ والأمن والمطاعم والمشارب."]], "m": "هذا خطاب الله تعالى للمشتغلين بجمع المال وتكثيره للمباهاة به والتفاخر، الأمر الذي ألهاهم عن طاعة الله ورسوله، فماتوا ولم يقدّموا لأنفسهم خيراً؛ فقال: شغلكم التكاثر في الأموال للتفاخر بها حتى زرتم المقابر فدُفنتم فيها إلى أن تخرجوا منها للحساب والجزاء. كلا، ما هكذا ينبغي أن تفعلوا، فارتدعوا عن هذا السلوك المفضي بكم إلى الهلاك والخسران، سوف تعلمون عاقبة تشاغلكم عن طاعة الله ورسوله والتزوّد للدار الآخرة، ثم كلا سوف تعلمون، كرّر الوعيد والتهديد. حقاً لو تعلمون ما تجدونه في قبوركم ويوم بعثكم ونشوركم لما تشاغلتم بالأموال وتكاثرتم فيها. وعزّتنا لترونّ الجحيم يوم القيامة، المشرك يراها ويصلاها، والمؤمن يراها وينجّيه الله منها، ثم لترونها عين اليقين، الأمر الذي لا شك فيه، إذ يُؤتى بجهنم فيراها أهل الموقف أجمعون، ثم لتُسألنّ يومئذ عن النعيم الذي كان لكم في الدنيا من صحة وفراغ وأمن وطعام وشراب، فمن أدّى شكره نجا، ومن لم يؤدِّ شكره أُخذ به. وقد صحّ أن النبي ﷺ قال لأبي بكر وعمر وأبي الهيثم بن التيهان: «هذا من النعيم الذي تُسألون عنه يوم القيامة»، يشير إلى بُسر ورطب وماء بارد، وصحّ أيضاً: «لا تزول قدما عبد يوم القيامة حتى يُسأل عن عمره فيمَ أفناه، وعن شبابه فيمَ أبلاه، وعن علمه ماذا عمل به، وعن ماله من أين اكتسبه وفيمَ أنفقه».", "h": ["التحذير من جمع المال وتكثيره مع عدم شكره، وترك طاعة الله ورسوله من أجله.", "إثبات عذاب القبر وتأكيده بقوله: «حتى زرتم المقابر كلا سوف تعلمون»، أي في القبر.", "تقرير عقيدة البعث وحتمية الجزاء بعد الحساب والاستنطاق والاستجواب.", "حتمية سؤال العبد عن النعم التي أنعم الله تعالى عليه بها في الدنيا، فإن كان شاكراً لها فاز، وإن كان كافراً لها أُخذ."], "k": "«ثم لتُسألنّ يومئذ عن النعيم»… كوب ماء بارد نعمة سأُسأل عنها؛ فهل أشكره عليه الآن؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (457, 103, 1, 3, 'سورة العصر ١ – ٣', 'العصر: إن الإنسان لفي خسر', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 457) = $j$[{"lbl": "الآيات ١ – ٣", "q": "وَٱلۡعَصۡرِ ﴿١﴾ إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ ﴿٢﴾ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ ﴿٣﴾", "w": [["والعصر", "الدهر كله."], ["إن الإنسان", "جنس الإنسان كله."], ["لفي خسر", "في نقصان وخسران، إذ حياته هي رأس ماله، فإذا مات ولم يؤمن ولم يعمل صالحاً خسر كل الخسران."], ["وتواصوا بالحق", "أوصى بعضهم بعضاً باعتقاد الحق وقوله والعمل به."], ["وتواصوا بالصبر", "أوصى بعضهم بعضاً بالصبر على اعتقاد الحق وقوله والعمل به."]], "m": "تضمّنت هذه الآيات الثلاث حكماً ومحكوماً عليه ومحكوماً به: فالحكم ما حكم به تعالى على الإنسان، كل الإنسان، من النقصان والخسران، والمحكوم عليه الإنسان ابن آدم، والمحكوم به الخسران لمن لم يؤمن ويعمل صالحاً، والربح والنجاة من الخسران لمن آمنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر. أقسم الله بالعصر، وهو الدهر كله، ليله ونهاره وصبحه ومساؤه، وجواب القسم: إن الإنسان لفي نقصان وهلكة وخسران، إذ يعيش في كبد ويموت إلى جهنم، فيخسر كل شيء حتى نفسه التي بين جنبيه، إلا الذين آمنوا وعملوا الصالحات، فهؤلاء استثناهم الله من الخسر، فهم رابحون بدخولهم الجنة دار السعادة؛ والمراد من الإيمان الإيمان بالله ورسوله وما جاء به رسوله من الهدى ودين الحق، والمراد من العمل الصالح الفرائض والسنن والنوافل. وتواصوا بالحق اعتقاداً وقولاً وعملاً، وذلك باتّباع الكتاب والسنة، وتواصوا بالصبر على ذلك حتى يموت أحدهم وهو يعتقد الحق ويقول به ويعمل بما جاء فيه؛ فالإسلام حق، والكتاب حق، والرسول حق، فهم بذلك يؤمنون ويعملون ويتواصون بالثبات على ذلك حتى الموت.", "h": ["فضيلة سورة العصر لاشتمالها على طريق النجاة في ثلاث آيات، حتى قال الإمام الشافعي: لو ما أنزل الله تعالى على خلقه حجة إلا هذه السورة لكفتهم.", "بيان مصير الإنسان الكافر، وأنه الخسران التام.", "بيان فوز أهل الإيمان والعمل الصالح المجتنبين للشرك والمعاصي.", "وجوب التواصي بالحق والتواصي بالصبر بين المسلمين."], "k": "«وتواصوا بالحق وتواصوا بالصبر»… من الذي يذكّرني بالحق وأذكّره؟ وهل أصبر معه عليه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 457;
insert into public.tdb_cards(topic, i, body) select 457, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "وَٱلۡعَصۡرِ ﴿١﴾ إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ ﴿٢﴾ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ ﴿٣﴾", "w": [["والعصر", "الدهر كله."], ["إن الإنسان", "جنس الإنسان كله."], ["لفي خسر", "في نقصان وخسران، إذ حياته هي رأس ماله، فإذا مات ولم يؤمن ولم يعمل صالحاً خسر كل الخسران."], ["وتواصوا بالحق", "أوصى بعضهم بعضاً باعتقاد الحق وقوله والعمل به."], ["وتواصوا بالصبر", "أوصى بعضهم بعضاً بالصبر على اعتقاد الحق وقوله والعمل به."]], "m": "تضمّنت هذه الآيات الثلاث حكماً ومحكوماً عليه ومحكوماً به: فالحكم ما حكم به تعالى على الإنسان، كل الإنسان، من النقصان والخسران، والمحكوم عليه الإنسان ابن آدم، والمحكوم به الخسران لمن لم يؤمن ويعمل صالحاً، والربح والنجاة من الخسران لمن آمنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر. أقسم الله بالعصر، وهو الدهر كله، ليله ونهاره وصبحه ومساؤه، وجواب القسم: إن الإنسان لفي نقصان وهلكة وخسران، إذ يعيش في كبد ويموت إلى جهنم، فيخسر كل شيء حتى نفسه التي بين جنبيه، إلا الذين آمنوا وعملوا الصالحات، فهؤلاء استثناهم الله من الخسر، فهم رابحون بدخولهم الجنة دار السعادة؛ والمراد من الإيمان الإيمان بالله ورسوله وما جاء به رسوله من الهدى ودين الحق، والمراد من العمل الصالح الفرائض والسنن والنوافل. وتواصوا بالحق اعتقاداً وقولاً وعملاً، وذلك باتّباع الكتاب والسنة، وتواصوا بالصبر على ذلك حتى يموت أحدهم وهو يعتقد الحق ويقول به ويعمل بما جاء فيه؛ فالإسلام حق، والكتاب حق، والرسول حق، فهم بذلك يؤمنون ويعملون ويتواصون بالثبات على ذلك حتى الموت.", "h": ["فضيلة سورة العصر لاشتمالها على طريق النجاة في ثلاث آيات، حتى قال الإمام الشافعي: لو ما أنزل الله تعالى على خلقه حجة إلا هذه السورة لكفتهم.", "بيان مصير الإنسان الكافر، وأنه الخسران التام.", "بيان فوز أهل الإيمان والعمل الصالح المجتنبين للشرك والمعاصي.", "وجوب التواصي بالحق والتواصي بالصبر بين المسلمين."], "k": "«وتواصوا بالحق وتواصوا بالصبر»… من الذي يذكّرني بالحق وأذكّره؟ وهل أصبر معه عليه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (458, 104, 1, 9, 'سورة الهمزة ١ – ٩', 'الهمزة: ويل لكل همزة لمزة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 458) = $j$[{"lbl": "الآيات ١ – ٩", "q": "وَيۡلٞ لِّكُلِّ هُمَزَةٖ لُّمَزَةٍ ﴿١﴾ ٱلَّذِي جَمَعَ مَالٗا وَعَدَّدَهُۥ ﴿٢﴾ يَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ ﴿٣﴾ كَلَّاۖ لَيُنۢبَذَنَّ فِي ٱلۡحُطَمَةِ ﴿٤﴾ وَمَآ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ ﴿٥﴾ نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ ﴿٦﴾ ٱلَّتِي تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ ﴿٧﴾ إِنَّهَا عَلَيۡهِم مُّؤۡصَدَةٞ ﴿٨﴾ فِي عَمَدٖ مُّمَدَّدَةِۭ ﴿٩﴾", "w": [["ويل", "كلمة يُطلب بها العذاب، ووادٍ في جهنم."], ["لكل همزة لمزة", "الهمزة كثير الهمز، واللمزة كذلك، وهم الطعّانون المظهرون العيوب للإفساد."], ["جمع مالاً وعدّده", "أحصاه وأعدّه لحوادث الدهر."], ["يحسب أن ماله أخلده", "يجعله خالداً في الحياة لا يموت."], ["كلا", "ليس الأمر كما يزعم ويظن."], ["لينبذنّ", "ليُطرحنّ."], ["في الحُطَمة", "النار التي تحطم كل ما يُلقى فيها."], ["تطّلع على الأفئدة", "تشرف على القلوب فتحرقها."], ["مؤصدة", "مغلقة مطبقة."], ["في عمد ممدّدة", "يُعذّبون في النار بأعمدة ممدّدة."]], "m": "يتوعّد الرب تبارك وتعالى بوادٍ في جهنم يسيل بصديد أهل النار وقيوحهم كلَّ همزة لمزة، أي كل مغتاب عيّاب ممن يمشون بالنميمة ويبغون للبُرآء العيب. ومن وصف هذا الهمّاز اللمّاز أنه جمع مالاً كثيراً من حرام وحلال، وعدّده، أي أحصاه وعرف مقداره وأعدّه لحوادث الدهر كما يزعم، يظن أنه لا يموت لكثرة أمواله، ومتى كان المال ينجي من الموت؟ إنه الغرور في الحياة، لو كان المال يُخلد أحداً لأخلد قارون. كلا، لا يخلّده ماله، بل وعزّتنا وجلالنا ليُطرحنّ في الحطمة، النار المستعرة التي تحطم كل ما يُلقى فيها، وما أدراك ما الحطمة؟ استفهام لتعظيم أمرها وتهويل شأنها، وبيّنها تعالى بقوله: نار الله الموقدة المستعرة المتأجّجة، التي تشرف على القلوب فتحرقها، إنها على أولئك الهمّازين اللمّازين مطبقة مغلقة الأبواب، يُعذّبون فيها بعمد ممدّدة، والله أعلم كيف يكون تعذيبهم بها، إذ لم يطلعنا الله تعالى على ذلك.", "h": ["تقرير عقيدة البعث والجزاء.", "التحذير من الغيبة والنميمة.", "التنديد بالمغترّين بالأموال المعجبين بها."], "k": "«ويل لكل همزة لمزة»… هل أتّبع عيوب الناس بلساني أو بنظرة؟ فلأمسك اليوم عن ذكر أحد بسوء."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 458;
insert into public.tdb_cards(topic, i, body) select 458, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٩", "q": "وَيۡلٞ لِّكُلِّ هُمَزَةٖ لُّمَزَةٍ ﴿١﴾ ٱلَّذِي جَمَعَ مَالٗا وَعَدَّدَهُۥ ﴿٢﴾ يَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ ﴿٣﴾ كَلَّاۖ لَيُنۢبَذَنَّ فِي ٱلۡحُطَمَةِ ﴿٤﴾ وَمَآ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ ﴿٥﴾ نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ ﴿٦﴾ ٱلَّتِي تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ ﴿٧﴾ إِنَّهَا عَلَيۡهِم مُّؤۡصَدَةٞ ﴿٨﴾ فِي عَمَدٖ مُّمَدَّدَةِۭ ﴿٩﴾", "w": [["ويل", "كلمة يُطلب بها العذاب، ووادٍ في جهنم."], ["لكل همزة لمزة", "الهمزة كثير الهمز، واللمزة كذلك، وهم الطعّانون المظهرون العيوب للإفساد."], ["جمع مالاً وعدّده", "أحصاه وأعدّه لحوادث الدهر."], ["يحسب أن ماله أخلده", "يجعله خالداً في الحياة لا يموت."], ["كلا", "ليس الأمر كما يزعم ويظن."], ["لينبذنّ", "ليُطرحنّ."], ["في الحُطَمة", "النار التي تحطم كل ما يُلقى فيها."], ["تطّلع على الأفئدة", "تشرف على القلوب فتحرقها."], ["مؤصدة", "مغلقة مطبقة."], ["في عمد ممدّدة", "يُعذّبون في النار بأعمدة ممدّدة."]], "m": "يتوعّد الرب تبارك وتعالى بوادٍ في جهنم يسيل بصديد أهل النار وقيوحهم كلَّ همزة لمزة، أي كل مغتاب عيّاب ممن يمشون بالنميمة ويبغون للبُرآء العيب. ومن وصف هذا الهمّاز اللمّاز أنه جمع مالاً كثيراً من حرام وحلال، وعدّده، أي أحصاه وعرف مقداره وأعدّه لحوادث الدهر كما يزعم، يظن أنه لا يموت لكثرة أمواله، ومتى كان المال ينجي من الموت؟ إنه الغرور في الحياة، لو كان المال يُخلد أحداً لأخلد قارون. كلا، لا يخلّده ماله، بل وعزّتنا وجلالنا ليُطرحنّ في الحطمة، النار المستعرة التي تحطم كل ما يُلقى فيها، وما أدراك ما الحطمة؟ استفهام لتعظيم أمرها وتهويل شأنها، وبيّنها تعالى بقوله: نار الله الموقدة المستعرة المتأجّجة، التي تشرف على القلوب فتحرقها، إنها على أولئك الهمّازين اللمّازين مطبقة مغلقة الأبواب، يُعذّبون فيها بعمد ممدّدة، والله أعلم كيف يكون تعذيبهم بها، إذ لم يطلعنا الله تعالى على ذلك.", "h": ["تقرير عقيدة البعث والجزاء.", "التحذير من الغيبة والنميمة.", "التنديد بالمغترّين بالأموال المعجبين بها."], "k": "«ويل لكل همزة لمزة»… هل أتّبع عيوب الناس بلساني أو بنظرة؟ فلأمسك اليوم عن ذكر أحد بسوء."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (459, 105, 1, 5, 'سورة الفيل ١ – ٥', 'الفيل: ألم تر كيف فعل ربك بأصحاب الفيل', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 459) = $j$[{"lbl": "الآيات ١ – ٥", "q": "أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ ﴿١﴾ أَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلٖ ﴿٢﴾ وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ ﴿٣﴾ تَرۡمِيهِم بِحِجَارَةٖ مِّن سِجِّيلٖ ﴿٤﴾ فَجَعَلَهُمۡ كَعَصۡفٖ مَّأۡكُولِۭ ﴿٥﴾", "w": [["ألم ترَ كيف فعل ربك", "ألم ينتهِ إلى علمك فعل ربك؟"], ["بأصحاب الفيل", "الفيل محمود، وهو أكبرها، ومعه اثنا عشر فيلاً، وصاحبها أبرهة."], ["ألم يجعل كيدهم", "في هدم الكعبة."], ["في تضليل", "في خسارة وضلال."], ["طيراً أبابيل", "جماعات جماعات."], ["بحجارة من سجّيل", "من طين مطبوخ."], ["كعصف مأكول", "كورق زرع أكلته الدواب وداسته بأرجلها."]], "m": "تضمّنت الآيات الخمس الحديث عن حادث جلل وقع عام ولادة النبي ﷺ، وخلاصته أن أبرهة الأشرم، والي اليمن من قِبل ملك الحبشة، رأى أن يبني بيتاً في صنعاء يدعو العرب إلى حجّه بدل البيت الحرام، والقصد تحويل التجارة والمكاسب من مكة إلى اليمن، فوافقه الملك الحبشي، فلما بنى الكنيسة وسمّاها القُلّيس جاء رجل قرشي فلطّخ جدرانها بالعذرة غضباً منه وذهب، فلما رآها أبرهة استشاط غيظاً، وجهّز جيشاً لغزو مكة وهدم الكعبة، ومعه ثلاثة عشر فيلاً، منها فيل يُدعى محموداً وهو أكبرها، وساروا ما وقف في وجههم حيّ من أحياء العرب إلا قاتلوه وهزموه، حتى انتهوا إلى قرب مكة، وجرت مفاوضات بينهم وبين شيخ مكة عبد المطلب بن هاشم جدّ النبي ﷺ، انتهت بأن يردّ أبرهة إبل عبد المطلب ثم هو وشأنه بالكعبة، وأمر رجال مكة أن يُخلوا البلد ويلتحقوا برؤوس الجبال بنسائهم وأطفالهم. فما هي إلا أن تحرّك جيش أبرهة ووصل إلى وادي محسّر، فإذا بأسراب من الطير فرقة بعد أخرى، ترسل على ذلك الجيش حجارة الواحدة ما بين الحمّصة والعدسة، فما تسقط الحجرة على رجل إلا ذاب وتناثر لحمه، فهلكوا، وفرّ أبرهة ولحمه يتناثر فهلك في الطريق، وكانت هذه نصرة من الله لسكان حرمه وحماة بيته، ومن ثَمّ ما زالت العرب تحترم الكعبة والحرم وسكانه. يخاطب تعالى رسوله مذكّراً إياه بفعله في إهلاك الجبابرة، فأين قوة ظلمة قريش كالعاص بن وائل وعمرو بن هشام والوليد وعقبة من قوة أبرهة، وقد أبادها الله في ساعة؟ فاصبر يا محمد ولا تحمل لهؤلاء الأعداء همّاً، فإن لهم ساعة. ألم يجعل ما كادوه لبيتنا وحرمنا في خسارة وضلال، فلم يجنوا إلا الخزي والدمار؟ وأرسل عليهم طيراً جماعات جماعات، كان يشاهدها رجال مكة المعتصمون بقمم الجبال وهي تمرّ فوقهم، كل طائر يحمل ثلاثة أحجار: واحدة بمنقاره واثنتين بمخلبيه، ترميهم بها فتتفتّت لحومهم، فجعلهم كزرع دخلته ماشية فأكلت ورقه وكسرت قائمه وهشّمته، فكانت آية من آيات الله تعالى.", "h": ["تسلية رسول الله ﷺ عما يلاقيه من ظلم كفار قريش.", "تذكير قريش بفعل الله ﷻ تخويفاً لهم وترهيباً.", "مظاهر قدرة الله تعالى في تدبيره لخلقه، وبطشه بأعدائه."], "k": "«ألم يجعل كيدهم في تضليل»… حين أخاف من كيد أحد، هل أتذكّر أن للبيت رباً يحميه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 459;
