د والأمن التام."], "k": "«الذي أطعمهم من جوع وآمنهم من خوف»… طعامي اليوم وأماني من ربي؛ فهل أعبده شكراً عليهما؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (461, 107, 1, 7, 'سورة الماعون ١ – ٧', 'الماعون: الذين هم عن صلاتهم ساهون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 461) = $j$[{"lbl": "الآيات ١ – ٧", "q": "أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ ﴿١﴾ فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ ﴿٢﴾ وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ﴿٣﴾ فَوَيۡلٞ لِّلۡمُصَلِّينَ ﴿٤﴾ ٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ ﴿٥﴾ ٱلَّذِينَ هُمۡ يُرَآءُونَ ﴿٦﴾ وَيَمۡنَعُونَ ٱلۡمَاعُونَ ﴿٧﴾", "w": [["أرأيت الذي يكذّب بالدين", "هل عرفته؟ والدين ثواب الله وعقابه يوم القيامة."], ["فذلك الذي يدعّ اليتيم", "فهو ذلك الذي يدفع اليتيم عن حقه بعنف."], ["ولا يحضّ على طعام المسكين", "لا يحضّ نفسه ولا غيره على إطعام المساكين."], ["فويل للمصلّين", "العذاب الشديد للمصلّين الساهين عن صلاتهم."], ["عن صلاتهم ساهون", "يؤخّرونها عن أوقاتها."], ["يراءون", "يراءون بصلاتهم وأعمالهم الناس، فلم يخلصوا لله تعالى في ذلك."], ["ويمنعون الماعون", "لا يعطون من سألهم ماعوناً، كالإبرة والقدر والمنجل ونحوه مما يُنتفع به ويُردّ بعينه كسائر الأدوات المنزلية."]], "m": "الآيات الثلاث الأولى نزلت بمكة في العاص بن وائل والوليد بن المغيرة وأضرابهم من عتاة قريش، تعرّض بهم وتندّد بسلوكهم وتتوعّدهم: أرأيت يا رسولنا الذي يكذّب بالجزاء في الآخرة على الحسنات والسيئات؟ فهو ذاك الذي يدفع اليتيم بعنف عن حقه ولا يعطيه إياه احتقاراً له وتكبّراً عليه، ولا يحثّ نفسه ولا غيره على إطعام الفقراء والمساكين، وذلك ناتج عن عدم إيمانه بالحساب والجزاء في الدار الآخرة، وهذه صفة كل ظالم مانع للحق لا يرحم، إذ لو آمن بالجزاء لعمل له بترك الشر وفعل الخير؛ فمن أراد أن يرى مكذّباً بالدين فإنه يراه في الظلمة المعتدين القساة القلوب الذين لا يرحمون ولا يعطون ولا يحسنون. والآيات الأربع الباقية نزلت في بعض منافقي المدينة، فلذا نصف السورة مكي ونصفها مدني: فويل للمصلّين الذين هم عن صلاتهم ساهون، وعيد شديد لهم، إذ الويل وادٍ في جهنم يسيل من صديد أهل النار، ومعنى ساهون أنهم غافلون عنها لا يذكرونها، فكثيراً ما تفوتهم ويخرج وقتها، وأغلب حالهم أنهم لا يصلّونها إلا عند قرب خروج وقتها. ووصف آخر أنهم يراءون بصلاتهم وبكل أعمالهم، يصلّون وينفقون ليراهم المؤمنون فيقولوا إنهم مؤمنون، وبالمراءاة يدرءون عن أنفسهم القتل والسبي. وثالث أنهم يمنعون الماعون، فإذا استعارهم مؤمن ماعوناً لحاجته لا يعيرون ويعتذرون بمعاذير باطلة، فلا يعيرون فأساً ولا منجلاً ولا قدراً، لأنهم يبغضون المؤمنين ولا يريدون أن ينفعوهم بشيء.", "h": ["تقرير عقيدة البعث والجزاء.", "أيّما قلب خلا من عقيدة البعث والجزاء إلا وصاحبه شرّ الخلق، لا خير فيه البتة.", "التنديد بالذين يأكلون أموال اليتامى ويدفعونهم عن حقوقهم استصغاراً لهم واحتقاراً.", "التنديد والوعيد للذين يتهاونون بالصلاة ولا يبالون في أي وقت صلّوها، وهو من علامات النفاق.", "منع الماعون من صفات المنافقين، والمانع لما المسلمون في حاجة إليه ليس منهم، لحديث: «من لم يهتمّ بأمر المسلمين فليس منهم»، فكيف بالذي يمنعهم ما هو فضل عنده وهم في حاجة إليه؟"], "k": "«الذين هم عن صلاتهم ساهون»… هل أؤخّر صلاتي لآخر وقتها بلا عذر؟ فلأبادر بالصلاة القادمة."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 461;
