insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (463, 109, 1, 6, 'سورة الكافرون ١ – ٦', 'الكافرون: لكم دينكم ولي دين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 463) = $j$[{"lbl": "الآيات ١ – ٦", "q": "قُلۡ يَـٰٓأَيُّهَا ٱلۡكَٰفِرُونَ ﴿١﴾ لَآ أَعۡبُدُ مَا تَعۡبُدُونَ ﴿٢﴾ وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ ﴿٣﴾ وَلَآ أَنَا۠ عَابِدٞ مَّا عَبَدتُّمۡ ﴿٤﴾ وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ ﴿٥﴾ لَكُمۡ دِينُكُمۡ وَلِيَ دِينِ ﴿٦﴾", "w": [["قل", "يا رسول الله."], ["يا أيها الكافرون", "المشركون، وهم الوليد والعاص وابن خلف والأسود بن المطلب."], ["لا أعبد ما تعبدون", "من الآلهة الباطلة الآن."], ["ولا أنتم عابدون ما أعبد", "الآن."], ["ولا أنا عابد ما عبدتم", "في المستقبل أبداً."], ["ولا أنتم عابدون ما أعبد", "في المستقبل أبداً، لعلم الله تعالى بذلك."], ["لكم دينكم", "ما أنتم عليه من الوثنية، سوف لا تتركونها أبداً حتى تهلكوا."], ["ولي دين", "الإسلام، فلا أتركه أبداً."]], "m": "نزلت الآيات الست ردّاً على اقتراح تقدّم به بعض المشركين، وهم الوليد بن المغيرة والعاص بن وائل السهمي والأسود بن المطلب وأمية بن خلف، مفاده أن يعبد النبي ﷺ معهم آلهتهم سنة، ويعبدون معه إلهه سنة، مصالحةً بينهم وبينه وإنهاءً للخصومات في نظرهم، ولم يجبهم الرسول ﷺ بشيء حتى نزلت هذه السورة: قل يا رسولنا لهؤلاء المقترحين الباطل: يا أيها الكافرون بالوحي الإلهي وبالتوحيد، المشركون في عبادة الله أصناماً وأوثاناً، لا أعبد ما تعبدون الآن كما اقترحتم، ولا أنتم عابدون الآن ما أعبد لما قضاه الله لكم، ولا أنا عابد ما عبدتم في المستقبل أبداً، ولا أنتم عابدون ما أعبد في المستقبل أبداً، لأن ربي حكم فيكم بالموت على الكفر والشرك لما علم من قلوبكم وأحوالكم وقبح سلوككم وفساد أعمالكم، لكم دينكم لا أتابعكم عليه، ولي دين لا تتابعونني عليه. بهذا أيأس الله رسوله من إيمان هذه الجماعة التي كان النبي ﷺ يطمع في إيمانهم، وأيأس المشركين من الطمع في موافقة الرسول ﷺ على مقترحهم الفاسد، وقد هلك هؤلاء على الكفر فلم يؤمن منهم أحد، فمنهم من هلك في بدر، ومنهم من هلك في مكة على الكفر والشرك، وصدق الله العظيم فيما أخبر به عنهم.", "h": ["تقرير عقيدة القضاء والقدر، وأن الكافر من كفر أزلاً، والمؤمن من آمن أزلاً.", "ولاية الله تعالى لرسوله ﷺ، وعصمته من قبول اقتراح المشركين الباطل.", "تقرير وجود المفاصلة بين أهل الإيمان وأهل الكفر والشرك."], "k": "«لكم دينكم ولي دين»… هل أساوم على شيء من ديني لأرضي الناس؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 463;
insert into public.tdb_cards(topic, i, body) select 463, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "قُلۡ يَـٰٓأَيُّهَا ٱلۡكَٰفِرُونَ ﴿١﴾ لَآ أَعۡبُدُ مَا تَعۡبُدُونَ ﴿٢﴾ وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ ﴿٣﴾ وَلَآ أَنَا۠ عَابِدٞ مَّا عَبَدتُّمۡ ﴿٤﴾ وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ ﴿٥﴾ لَكُمۡ دِينُكُمۡ وَلِيَ دِينِ ﴿٦﴾", "w": [["قل", "يا رسول الله."], ["يا أيها الكافرون", "المشركون، وهم الوليد والعاص وابن خلف والأسود بن المطلب."], ["لا أعبد ما تعبدون", "من الآلهة الباطلة الآن."], ["ولا أنتم عابدون ما أعبد", "الآن."], ["ولا أنا عابد ما عبدتم", "في المستقبل أبداً."], ["ولا أنتم عابدون ما أعبد", "في المستقبل أبداً، لعلم الله تعالى بذلك."], ["لكم دينكم", "ما أنتم عليه من الوثنية، سوف لا تتركونها أبداً حتى تهلكوا."], ["ولي دين", "الإسلام، فلا أتركه أبداً."]], "m": "نزلت الآيات الست ردّاً على اقتراح تقدّم به بعض المشركين، وهم الوليد بن المغيرة والعاص بن وائل السهمي والأسود بن المطلب وأمية بن خلف، مفاده أن يعبد النبي ﷺ معهم آلهتهم سنة، ويعبدون معه إلهه سنة، مصالحةً بينهم وبينه وإنهاءً للخصومات في نظرهم، ولم يجبهم الرسول ﷺ بشيء حتى نزلت هذه السورة: قل يا رسولنا لهؤلاء المقترحين الباطل: يا أيها الكافرون بالوحي الإلهي وبالتوحيد، المشركون في عبادة الله أصناماً وأوثاناً، لا أعبد ما تعبدون الآن كما اقترحتم، ولا أنتم عابدون الآن ما أعبد لما قضاه الله لكم، ولا أنا عابد ما عبدتم في المستقبل أبداً، ولا أنتم عابدون ما أعبد في المستقبل أبداً، لأن ربي حكم فيكم بالموت على الكفر والشرك لما علم من قلوبكم وأحوالكم وقبح سلوككم وفساد أعمالكم، لكم دينكم لا أتابعكم عليه، ولي دين لا تتابعونني عليه. بهذا أيأس الله رسوله من إيمان هذه الجماعة التي كان النبي ﷺ يطمع في إيمانهم، وأيأس المشركين من الطمع في موافقة الرسول ﷺ على مقترحهم الفاسد، وقد هلك هؤلاء على الكفر فلم يؤمن منهم أحد، فمنهم من هلك في بدر، ومنهم من هلك في مكة على الكفر والشرك، وصدق الله العظيم فيما أخبر به عنهم.", "h": ["تقرير عقيدة القضاء والقدر، وأن الكافر من كفر أزلاً، والمؤمن من آمن أزلاً.", "ولاية الله تعالى لرسوله ﷺ، وعصمته من قبول اقتراح المشركين الباطل.", "تقرير وجود المفاصلة بين أهل الإيمان وأهل الكفر والشرك."], "k": "«لكم دينكم ولي دين»… هل أساوم على شيء من ديني لأرضي الناس؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (464, 110, 1, 3, 'سورة النصر ١ – ٣', 'النصر: فسبّح بحمد ربك واستغفره', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 464) = $j$[{"lbl": "الآيات ١ – ٣", "q": "إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ ﴿١﴾ وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا ﴿٢﴾ فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا ﴿٣﴾", "w": [["إذا جاء نصر الله", "نصر الله نبيه محمداً ﷺ على أعدائه المشركين."], ["والفتح", "فتح مكة."], ["في دين الله أفواجاً", "في الإسلام جماعات جماعات."], ["فسبّح بحمد ربك", "نزّهه عن الشريك متلبّساً بحمده."], ["واستغفره", "اطلب منه المغفرة توبةً منك إليه."]], "m": "نزلت الآيات الثلاث المباركات في أُخريات أيام الرسول ﷺ، وهي تحمل علامة للنبي ﷺ على قرب أجله: إذا جاءك نصر الله يا رسولنا، فأصبحت تنتصر على أعدائك في كل معركة تخوضها معهم، وجاءك فتح مكة ففتحها الله عليك، وأصبحت دار إسلام بعد أن كانت دار كفر، ورأيت الناس من سكان اليمن وغيرهم يدخلون في دينك الإسلامي جماعات بعد جماعات، بعد أن كانوا يدخلون فرادى واحداً واحداً وهم خائفون، إذا تمّ هذا ورأيته فسبّح بحمد ربك شكراً له على نعمة النصر والفتح ودخول الناس في دينك وانتهاء دين المشركين الباطل، واستغفره، أي اطلب منه المغفرة لما فرط منك مما هو ذنب في حقك لقربك وكمال علمك، وإن لم يكن في حق غيرك ذنباً يُستغفر منه، إنه تعالى الذي أمرك بالاستغفار كان تواباً على عباده، يقبل توبتهم فيغفر ذنوبهم ويرحمهم.", "h": ["مشروعية نعي الميت إلى أهله، ولكن بدون إعلان وصوت عالٍ.", "وجوب الشكر عند تحقّق النعمة، ومن ذلك سجدة الشكر.", "مشروعية قول: «سبحانك اللهم وبحمدك، اللهم اغفر لي» في الركوع."], "k": "«فسبّح بحمد ربك واستغفره»… بعد كل نجاح، هل أشكر وأستغفر، أم أنسب الفضل لنفسي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 464;
insert into public.tdb_cards(topic, i, body) select 464, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ ﴿١﴾ وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا ﴿٢﴾ فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا ﴿٣﴾", "w": [["إذا جاء نصر الله", "نصر الله نبيه محمداً ﷺ على أعدائه المشركين."], ["والفتح", "فتح مكة."], ["في دين الله أفواجاً", "في الإسلام جماعات جماعات."], ["فسبّح بحمد ربك", "نزّهه عن الشريك متلبّساً بحمده."], ["واستغفره", "اطلب منه المغفرة توبةً منك إليه."]], "m": "نزلت الآيات الثلاث المباركات في أُخريات أيام الرسول ﷺ، وهي تحمل علامة للنبي ﷺ على قرب أجله: إذا جاءك نصر الله يا رسولنا، فأصبحت تنتصر على أعدائك في كل معركة تخوضها معهم، وجاءك فتح مكة ففتحها الله عليك، وأصبحت دار إسلام بعد أن كانت دار كفر، ورأيت الناس من سكان اليمن وغيرهم يدخلون في دينك الإسلامي جماعات بعد جماعات، بعد أن كانوا يدخلون فرادى واحداً واحداً وهم خائفون، إذا تمّ هذا ورأيته فسبّح بحمد ربك شكراً له على نعمة النصر والفتح ودخول الناس في دينك وانتهاء دين المشركين الباطل، واستغفره، أي اطلب منه المغفرة لما فرط منك مما هو ذنب في حقك لقربك وكمال علمك، وإن لم يكن في حق غيرك ذنباً يُستغفر منه، إنه تعالى الذي أمرك بالاستغفار كان تواباً على عباده، يقبل توبتهم فيغفر ذنوبهم ويرحمهم.", "h": ["مشروعية نعي الميت إلى أهله، ولكن بدون إعلان وصوت عالٍ.", "وجوب الشكر عند تحقّق النعمة، ومن ذلك سجدة الشكر.", "مشروعية قول: «سبحانك اللهم وبحمدك، اللهم اغفر لي» في الركوع."], "k": "«فسبّح بحمد ربك واستغفره»… بعد كل نجاح، هل أشكر وأستغفر، أم أنسب الفضل لنفسي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (465, 111, 1, 5, 'سورة المسد ١ – ٥', 'المسد: تبّت يدا أبي لهب', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 465) = $j$[{"lbl": "الآيات ١ – ٥", "q": "تَبَّتۡ يَدَآ أَبِي لَهَبٖ وَتَبَّ ﴿١﴾ مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ ﴿٢﴾ سَيَصۡلَىٰ نَارٗا ذَاتَ لَهَبٖ ﴿٣﴾ وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ ﴿٤﴾ فِي جِيدِهَا حَبۡلٞ مِّن مَّسَدِۭ ﴿٥﴾", "w": [["تبّت يدا أبي لهب", "خسرت يدا أبي لهب بن عبد المطلب، أي خسر عمله."], ["وتبّ", "خسر هو بذاته، إذ هو من أهل النار."], ["ما أغنى عنه ماله", "أي شيء أغنى عنه ماله لما سخط الله تعالى عليه وعذّبه في الدنيا والآخرة؟"], ["وما كسب", "من المال والولد وغيرهما."], ["سيصلى ناراً", "يدخل ناراً يصطلي بحرّها ولفحها."], ["ذات لهب", "توقّد واشتعال."], ["وامرأته", "أم جميل العوراء."], ["حمّالة الحطب", "تحمل شوك السعدان وتلقيه في طريق النبي ﷺ أذيةً له وكرهاً."], ["في جيدها", "في عنقها."]], "m": "نزلت الآيات الخمس المباركات ردّاً على أبي لهب عمّ النبي ﷺ؛ إذ صحّ أنه لما نزلت آية «وأنذر عشيرتك الأقربين» من سورة الشعراء، طلع ﷺ إلى جبل الصفا ونادى: «يا صباحاه، يا صباحاه»، فاجتمع الناس حوله، فقال لهم: «إني لكم نذير بين يدي عذاب شديد»، وقال: «قولوا: لا إله إلا الله، كلمة تملكون بها العرب وتدين لكم بها العجم»، فنطق أبو لهب فقال: تباً لك سائر اليوم، ألهذا جمعتنا؟ فأنزل الله تعالى ردّاً عليه: تبّت يدا أبي لهب، أي خسر أبو لهب وخسر كل شيء له، وهذه جملة دعائية، ولذا هلك بمرض خطير لم يتمكّنوا من غسله فأراقوا عليه الماء فقط. وتبّ، إخبار من الله تعالى بهلاك عبد العزّى أبي لهب. لما سخط الله عليه وأدخله ناره لم يدفع عنه العذاب ماله ولا ولده، سيصلى ناراً ذات توقّد واشتعال، وامرأته أم جميل حمّالة الحطب، حيث كانت تأتي بشوك السعدان وتضعه في طريق النبي ﷺ عند ذهابه إلى صلاة الصبح بالمسجد الحرام، في عنقها حبل من ليف النخل أو من مسد شجر الدوم. بهذا حكم الله تعالى على أعدائه وأعداء رسوله.", "h": ["بيان حكم الله بهلاك أبي لهب، وإبطال كيده الذي كان يكيده لرسول الله ﷺ.", "لا يغني المال ولا الولد عن العبد شيئاً من عذاب الله إذا عمل بمساخطه وترك مراضيه.", "حرمة أذية المؤمنين مطلقاً.", "عدم إغناء القرابة شيئاً مع الشرك والكفر، إذ أبو لهب عمّ النبي ﷺ وهو في النار ذات اللهب."], "k": "«ما أغنى عنه ماله وما كسب»… ما الذي أتّكل عليه غير ربي؟ وهل يغني عني شيئاً يومئذ؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 465;
insert into public.tdb_cards(topic, i, body) select 465, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "تَبَّتۡ يَدَآ أَبِي لَهَبٖ وَتَبَّ ﴿١﴾ مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ ﴿٢﴾ سَيَصۡلَىٰ نَارٗا ذَاتَ لَهَبٖ ﴿٣﴾ وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ ﴿٤﴾ فِي جِيدِهَا حَبۡلٞ مِّن مَّسَدِۭ ﴿٥﴾", "w": [["تبّت يدا أبي لهب", "خسرت يدا أبي لهب بن عبد المطلب، أي خسر عمله."], ["وتبّ", "خسر هو بذاته، إذ هو من أهل النار."], ["ما أغنى عنه ماله", "أي شيء أغنى عنه ماله لما سخط الله تعالى عليه وعذّبه في الدنيا والآخرة؟"], ["وما كسب", "من المال والولد وغيرهما."], ["سيصلى ناراً", "يدخل ناراً يصطلي بحرّها ولفحها."], ["ذات لهب", "توقّد واشتعال."], ["وامرأته", "أم جميل العوراء."], ["حمّالة الحطب", "تحمل شوك السعدان وتلقيه في طريق النبي ﷺ أذيةً له وكرهاً."], ["في جيدها", "في عنقها."]], "m": "نزلت الآيات الخمس المباركات ردّاً على أبي لهب عمّ النبي ﷺ؛ إذ صحّ أنه لما نزلت آية «وأنذر عشيرتك الأقربين» من سورة الشعراء، طلع ﷺ إلى جبل الصفا ونادى: «يا صباحاه، يا صباحاه»، فاجتمع الناس حوله، فقال لهم: «إني لكم نذير بين يدي عذاب شديد»، وقال: «قولوا: لا إله إلا الله، كلمة تملكون بها العرب وتدين لكم بها العجم»، فنطق أبو لهب فقال: تباً لك سائر اليوم، ألهذا جمعتنا؟ فأنزل الله تعالى ردّاً عليه: تبّت يدا أبي لهب، أي خسر أبو لهب وخسر كل شيء له، وهذه جملة دعائية، ولذا هلك بمرض خطير لم يتمكّنوا من غسله فأراقوا عليه الماء فقط. وتبّ، إخبار من الله تعالى بهلاك عبد العزّى أبي لهب. لما سخط الله عليه وأدخله ناره لم يدفع عنه العذاب ماله ولا ولده، سيصلى ناراً ذات توقّد واشتعال، وامرأته أم جميل حمّالة الحطب، حيث كانت تأتي بشوك السعدان وتضعه في طريق النبي ﷺ عند ذهابه إلى صلاة الصبح بالمسجد الحرام، في عنقها حبل من ليف النخل أو من مسد شجر الدوم. بهذا حكم الله تعالى على أعدائه وأعداء رسوله.", "h": ["بيان حكم الله بهلاك أبي لهب، وإبطال كيده الذي كان يكيده لرسول الله ﷺ.", "لا يغني المال ولا الولد عن العبد شيئاً من عذاب الله إذا عمل بمساخطه وترك مراضيه.", "حرمة أذية المؤمنين مطلقاً.", "عدم إغناء القرابة شيئاً مع الشرك والكفر، إذ أبو لهب عمّ النبي ﷺ وهو في النار ذات اللهب."], "k": "«ما أغنى عنه ماله وما كسب»… ما الذي أتّكل عليه غير ربي؟ وهل يغني عني شيئاً يومئذ؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (466, 112, 1, 4, 'سورة الإخلاص ١ – ٤', 'الإخلاص: قل هو الله أحد', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 466) = $j$[{"lbl": "الآيات ١ – ٤", "q": "قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴿١﴾ ٱللَّهُ ٱلصَّمَدُ ﴿٢﴾ لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ ﴿٣﴾ وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ ﴿٤﴾", "w": [["قل هو الله أحد", "قل لمن سألك يا نبينا عن ربك: هو الله أحد."], ["الله الصمد", "الله الذي لا تنبغي العبادة إلا له، والصمد السيد الذي يُصمد إليه في الحوائج، فهو المقصود في قضاء الحوائج على الدوام."], ["لم يلد", "إذ لا شيء يلد إلا وهو فانٍ بائد لا محالة."], ["ولم يولد", "ليس بمحدث بأن لم يكن فكان، فهو كائن أولاً وأبداً."], ["ولم يكن له كفواً أحد", "لم يكن أحد شبيهاً له أو مثيلاً، إذ ليس كمثله شيء."]], "m": "نزلت الآيات الأربع المباركات جواباً لمن قالوا للرسول ﷺ من المشركين: انسب لنا ربك أو صفه لنا، فقال تعالى لرسوله: قل لمن سألوك ذلك: ربي هو الله، أي الإله الذي لا تنبغي الألوهية إلا له، ولا تصلح العبادة إلا له، أحد في ذاته وصفاته وأفعاله، فليس له نظير ولا مثيل في ذلك، إذ هو خالق الكل ومالك الجميع، فلن تكون المحدثات المخلوقات كخالقها ومحدثها. الله، أي المعبود الذي لا معبود بحق إلا هو، الصمد، أي السيد المقصود في قضاء الحوائج، الذي استغنى عن كل خلقه وافتقر الكل إليه. لم يلد، أي لم يكن له ولد، لانتفاء من يجانسه، إذ الولد يجانس والده، والمجانسة منفية عنه تعالى إذ ليس كمثله شيء، ولم يولد لانتفاء الحدوث عنه تعالى، ولم يكن أحد كفواً له ولا مثيلاً ولا نظيراً ولا شبيهاً، إذ ليس كمثله شيء وهو السميع البصير. فلذا هو يُعرف بالأحدية والصمدية: فالأحدية أنه واحد في ذاته وصفاته وأفعاله، لم يكن له كفو ولا شبيه ولا نظير، والصمدية أنه المستغني عن كل ما سواه، والمفتقر إليه في وجوده وبقائه كل ما عداه، كما يُعرف بأسمائه وصفاته وآياته.", "h": ["معرفة الله تعالى بأسمائه وصفاته.", "تقرير التوحيد والنبوة.", "بطلان نسبة الولد إلى الله تعالى.", "وجوب عبادته تعالى وحده، إذ هو ذو الألوهية على خلقه دون سواه."], "k": "«الله الصمد»… إلى من أتّجه أولاً حين تضيق بي حاجة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 466;
