insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (467, 113, 1, 5, 'سورة الفلق ١ – ٥', 'الفلق: قل أعوذ برب الفلق', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 467) = $j$[{"lbl": "الآيات ١ – ٥", "q": "قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ ﴿١﴾ مِن شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِن شَرِّ ٱلنَّفَّـٰثَٰتِ فِي ٱلۡعُقَدِ ﴿٤﴾ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾", "w": [["الفلق", "الصبح."], ["من شر ما خلق", "من حيوان وجماد."], ["غاسق إذا وقب", "الليل إذا أظلم، أو القمر إذا غاب."], ["النفّاثات", "السواحر اللاتي ينفثن."], ["في العقد", "في العقد التي يعقدنها."], ["حاسد إذا حسد", "إذا أظهر حسده وأعمله."]], "m": "لما سحر لبيد بن الأعصم اليهودي بالمدينة النبيَّ ﷺ أنزل تعالى المعوّذتين، فرقاه بهما جبريل فشفاه الله تعالى، ولذا فالسورتان مدنيّتان. قل يا رسولنا: أعوذ، أي أستجير وأتحصّن برب الفلق، وهو الله ﷻ، إذ هو فالق الإصباح وفالق الحب والنوى، ولا يقدر على ذلك إلا هو لعظيم قدرته وسعة علمه، من شر ما خلق تعالى من الكائنات، من حيوان مكلّف كالإنسان، وغير مكلّف كسائر الحيوانات، ومن الجمادات، أي من شر كل ذي شر من سائر المخلوقات. ومن شر الليل إذا أظلم، والقمر إذا غاب، إذ الظلام بدخول الليل أو بغياب القمر يكون مظنّة خروج الحيات السامّة والحيوانات المفترسة والجماعات المتلصّصة للسطو والسرقة وابتغاء الشر والفساد. ومن شر السواحر، وهن النساء اللاتي ينفثن في كل عقدة يرقين عليها ويعقدنها، والنفث إخراج هواء من الفم بدون ريق، ولذا ورد: «من عقد عقدة ثم نفث فيها فقد سحر». ومن شر حاسد من الناس إذا أظهر حسده، فابتغاك بضرّ أو أرادك بشر أو طلبك بسوء بحسده لك، لأن الحسد طلب زوال النعمة عن المحسود، سواء أرادها له أو لم يردها، وهو شرّ الحسد.", "h": ["وجوب التعوّذ بالله والاستعاذة بجنابه تعالى من كل مخوف لا يقدر المرء على دفعه لخفائه أو عدم القدرة عليه.", "تحريم النفث في العقد، إذ هو من السحر، والسحر كفر، وحدّ الساحر ضربة بالسيف.", "تحريم الحسد قطعياً، وهو داء خطير حمل ابن آدم على قتل أخيه، وحمل إخوة يوسف على الكيد له.", "الغبطة ليست من الحسد، لحديث الصحيح: «لا حسد إلا في اثنتين»، إذ المراد به الغبطة."], "k": "«ومن شر حاسد إذا حسد»… أستعيذ من حسد غيري؛ فهل أطهّر قلبي أنا من حسد أحد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 467;
