insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (468, 114, 1, 6, 'سورة الناس ١ – ٦', 'الناس: من شر الوسواس الخناس', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 468) = $j$[{"lbl": "الآيات ١ – ٦", "q": "قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴿١﴾ مَلِكِ ٱلنَّاسِ ﴿٢﴾ إِلَٰهِ ٱلنَّاسِ ﴿٣﴾ مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ ﴿٤﴾ ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ ﴿٥﴾ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ ﴿٦﴾", "w": [["أعوذ", "أتحصّن وأستجير."], ["برب الناس", "خالقهم ومالكهم."], ["ملك الناس", "سيد الناس ومالكهم وحاكمهم."], ["إله الناس", "معبود الناس بحق، إذ لا معبود سواه."], ["من شر الوسواس", "من شر الشيطان، سُمّي بالمصدر لكثرة ملابسته له."], ["الخنّاس", "الذي يخنس ويتأخّر عن القلب عند ذكر الله تعالى."], ["في صدور الناس", "في قلوبهم إذا غفلوا عن ذكر الله تعالى."], ["من الجنة والناس", "من شيطان الجن ومن شيطان الإنس."]], "m": "هذه السورة إحدى المعوّذتين: الأولى الفلق، وقد اشتملت على أربع خصال يُستعاذ منها: من شر كل ذي شر من سائر الخلق، ومن شر ما يحدث في الظلام، ومن شر السواحر النفّاثات في العقد، ومن شر حاسد إذا حسد، وقد اشتملت هذه الأربع على كل ما يُخاف أذاه وضرره. أما سورة الناس فقد اشتملت على شر واحد، إلا أنه أخطر من تلك الأربع لتعلّقه بالقلب، والقلب إذا فسد فسد كل شيء، وإذا صلح صلح كل شيء، ولذا كانت خاصة بالتعوّذ من شر الوسواس الخنّاس. أمر منه تعالى لرسوله، وأمته تابعة له: قل أتحصّن برب الناس، خالقهم ومالكهم وإلههم الذي لا إله لهم سواه، من شر الوسواس، وهو الشيطان الموسوس في صدور الناس بصوت خفي لا يُسمع، فيلقي الشبه في القلب والمخاوف والظنون السيئة، ويزيّن القبيح ويقبّح الحسن، وذلك متى غفل المرء عن ذكر الله. والخنّاس وصف للشيطان من الجن، فإنه إذا ذكر العبد ربه خنس، أي استتر وكأنه غاب ولم يغب، فإذا غفل العبد عن ذكر الله عاد للوسوسة. من الجنة والناس، يعني أن الموسوس للإنسان كما يكون من الجن يكون من الناس، والإنسان يوسوس بمعنى يعمل عمل الشيطان في تزيين الشر وتحسين القبيح، وإلقاء الشبه في النفس، وإثارة الهواجس والخواطر بالكلمات الفاسدة والعبارات المضلّلة، حتى إن ضرر الإنسان على الإنسان أكبر من ضرر الشيطان عليه، إذ الشيطان من الجن يُطرد بالاستعاذة، وشيطان الإنس لا يُطرد بها، وإنما يُصانع ويُدارى للتخلّص منه.", "h": ["وجوب الاستعاذة بالله تعالى من شياطين الإنس والجن.", "تقرير ربوبية الله تعالى وألوهيته ﷻ.", "بيان لفظ الاستعاذة، وهو: أعوذ بالله من الشيطان الرجيم، كما بيّنته السنة الصحيحة، إذ تلاحى رجلان عند النبي ﷺ فقال: «إني لأعلم كلمة لو قالها لذهب عنه ما يجد: أعوذ بالله من الشيطان الرجيم»."], "k": "«الذي يوسوس في صدور الناس»… ما الوسوسة التي تتكرّر عليّ؟ وهل أطردها بذكر الله كلما جاءت؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 468;
